/**
 * A complete conversation pane for either platform: header, the scrolling log with native clusters,
 * tails, date headers and reactions, and the composer. Bring your own data and send handler.
 */
export function Conversation({ platform = "ios", name, initials, messages, typing = false, group = false, now, onSend, onAttach, onBack, onVideoCall, onDetails, onReaction, renderReactions, width, height, className, style, ...props }: ConversationProps) {
  const frame = useRef<HTMLElement>(null);
  const list = useRef<MessageListHandle>(null);
  const ios = platform === "ios";
  const reactions = renderReactions ?? ((message: Message) => message.reactions?.length ? (
    <div className="flex" style={{ gap: 2 }}>
      {message.reactions.map((reaction, index) => (
        <Tapback key={index} reaction={reaction.emoji ? undefined : (reaction.type as TapbackType)} emoji={reaction.emoji} own={reaction.byMe ?? true}
          side={message.direction === "outgoing" ? "left" : "right"} onClick={onReaction ? () => onReaction(message, reaction) : undefined} />
      ))}
    </div>
  ) : undefined);
  const size = { width: width ?? (ios ? 402 : 630), height: height ?? (ios ? 760 : 640) };
  return (
    <PlatformProvider platform={platform}>
      <PaletteStyle platform={platform} />
      <section ref={frame} aria-label={`Conversation with ${name}`} data-slot="conversation" data-im-platform={platform}
        className={cn("relative isolate overflow-hidden font-sans", ios ? "rounded-[24px]" : "rounded-[12px]", className)}
        style={{ ...size, background: "var(--im-bg)", color: "var(--im-incoming-text)", ...style }} {...props}>
        <MessageList ref={list} frameRef={frame} messages={messages} typing={typing ? { sender: name } : false} group={group} now={now}
          anchor={ios ? "top" : "bottom"} insetTop={ios ? 115.5 : macHeaderMetrics.height + 29.3} insetBottom={ios ? 79 : macListBottom} renderReactions={reactions} className="absolute inset-0" />
        {ios ? (
          <>
            <IosNavBar name={name} initials={initials} onBack={onBack} onDetails={onDetails} className="absolute left-0 top-0" />
            {onSend && <IosComposer className="absolute bottom-0 left-0" onSend={onSend} onAttach={onAttach} />}
          </>
        ) : (
          <>
            <MacHeader name={name} initials={initials} onVideoCall={onVideoCall} onOpenDetails={onDetails} className="absolute left-0 top-0 w-full" style={{ height: macHeaderMetrics.height }} />
            {onSend && <MacComposer className="absolute bottom-0 left-0 w-full" onSend={onSend} onAttach={onAttach} />}
          </>
        )}
      </section>
    </PlatformProvider>
  );
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, type ComponentProps, type RefObject } from "react";
import { cn } from "@/lib/utils";
import { bubblePath, tailBox } from "@/components/imessage/bubble-shape";
import { bubbleMetrics } from "@/components/imessage/tokens";
import type { Platform } from "@/components/imessage/platform";

/**
 * Motion engine for the message list. Everything is built on the Web Animations API so a running
 * animation can be paused and scrubbed with `seek(ms)`, which is how the lab captures frames for
 * comparison with the 60 fps native recording (references/ios/motion/).
 *
 * Send timeline, re-measured frame by frame from `references/ios/motion/send-60fps.mp4`. Frames are the
 * 0-based output of `ffmpeg -vsync 0 -start_number 0` (299 frames, 60 fps), so t = (f - 73) / 60 s: f68 to
 * f72 differ by at most 2 in any channel and every one of them paints the blue send button (3321 px with
 * B - R > 80 in an 80 x 65 box over it; f73 has none), so f73 is the first animated frame and t = 0. The
 * contact sheets in that folder are 1-based on the same clip - their "f74" is this file's f73 - and the
 * times this file used to carry were read from f71, two frames (33 ms) early of the first frame that moves.
 * - 0 ms (f73): the text row is *already* a tinted rounded rect, tail and all, over exactly the field's text
 *   box; the send button is already gone and the placeholder is already at full strength (its darkest glyph
 *   luma is 170.5 here and 175.9 once the rect has passed, over backgrounds of 232.6 and 253.0).
 * - 17 to 150 ms: the rect collapses toward the field's right end. Widths, pt: 292 (f73), 294 (f74), 272
 *   (f75), 252, 226, 195, 154 (f79), 123 (f80), 98, 82, 68 (f84). f74 is still full width, so the collapse
 *   starts between 17 and 33 ms. Native keeps shrinking past the bubble's own size to 0.772 at 183 ms; the
 *   clone cannot hold a scale above 1, so the rect carries the shape to 150 ms, where the scale crosses 1.
 * - 33 ms on: the bubble leaves the field on a spring released from rest. Fitted over f84 to f133 with the
 *   amplitude pinned to the geometric travel (127.1 pt), damping 0.73 and 11.9 rad/s reproduces the body's
 *   bottom edge to 0.28 pt rms / 0.77 pt worst over 50 frames; the old 0.8 and 15 rad/s from 103 ms misses
 *   by 9.6 pt rms / 35 pt worst. Scale recovers on a second, slower spring released 10 ms past the minimum.
 * - The bubble overshoots: its tail corner passes 5.0 pt above the slot at 417 ms (f98) and falls back,
 *   inside 0.25 pt of rest at 633 ms (f111) and settled by 690 ms (f114). Scale is done by ~500 ms flat.
 *
 * Measured "Hi there" body tops, recording/this model (402x874 screen, slot top 686.8/687.25): 150 ms
 * 760.8/763.2, 233 ms 717.6/718.0, 317 ms 691.8/692.9, 350 ms 686.9/688.0. f83 duplicates f82, so 167 ms
 * is a repeat. At 1017 ms (f134) "Delivered" moves off the bubble above and the slot rises 15 pt to 671.75.
 */
export const messageMotion = {
  /** Legacy tokens kept for the harness and pressable-message. */
  arrival: 420,
  delivery: 900,
  reaction: 320,
  press: 120,
  longPress: 500,
  send: {
    morph: 17, liftoff: 33, shrink: 150, duration: 690,
    textReveal: 25, textVisible: 70,
    /** The placeholder is already at full strength in f73, so it holds rather than fading in. */
    placeholderIn: 0, tint: 0.55,
    /** In-flight scale: the bubble flies at (1 - squash) of its size and grows back on `growSpring`. */
    squash: 0.228, grow: 193,
    spring: { damping: 0.73, frequency: 11.9 },
    growSpring: { damping: 0.8, frequency: 13.1 },
  },
  receive: { duration: 300, fade: 80, startScale: 0.5, spring: { damping: 0.7, frequency: 30 } },
  reduced: { duration: 200 },
} as const;

export type MotionHandle = {
  duration: number;
  /** Pause every animation and jump to `ms`. */
  seek(ms: number): void;
  play(): void;
  pause(): void;
  /** Stop and remove any helper elements. */
  cancel(): void;
  /** Resolves when the animation finishes (or is cancelled). */
  finished: Promise<void>;
  readonly animations: Animation[];
};

export function prefersReducedMotion(): boolean {
  return typeof window !== "undefined" && typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/**
 * Remaining offset (as a fraction of the start offset) of an underdamped spring released from rest,
 * `t` in seconds. With the send spring's damping 0.73 and 11.9 rad/s the first overshoot is 3.5% of the
 * travel 386 ms after release, 3.8% once `offsetAt` normalises it: 4.9 pt of the send's 127.1 pt travel at
 * 419 ms, which is the 5.0 pt at 417 ms (f98) that the recording overshoots its slot by.
 */
export function springOffset(t: number, damping: number, frequency: number): number {
  if (t <= 0) return 1;
  const root = Math.sqrt(1 - damping * damping);
  const wd = frequency * root;
  return Math.exp(-damping * frequency * t) * (Math.cos(wd * t) + (damping / root) * Math.sin(wd * t));
}

type Rect = { left: number; top: number; width: number; height: number };

function makeHandle(animations: Animation[], duration: number, cleanup: () => void, paused: boolean | undefined, tick?: (ms: number) => void): MotionHandle {
  if (paused) animations.forEach(a => a.pause());
  let done = false;
  let raf = 0;
  const finish = () => { if (done) return; done = true; cancelAnimationFrame(raf); cleanup(); animations.forEach(a => { try { a.cancel(); } catch { /* already gone */ } }); };
  const finished = Promise.all(animations.map(a => a.finished.catch(() => undefined))).then(finish);
  const loop = () => {
    raf = 0;
    if (done || !tick) return;
    const t = Number(animations[0]?.currentTime ?? 0);
    tick(Math.max(0, Math.min(duration, t)));
    if (animations[0]?.playState === "running") raf = requestAnimationFrame(loop);
  };
  if (tick && !paused) raf = requestAnimationFrame(loop);
  return {
    duration,
    animations,
    finished,
    // Once `finish` has run the helper elements are gone, so every control is inert from then on:
    // a late seek or play would otherwise drive animations whose targets are no longer in the page.
    seek(ms) { if (done) return; const t = Math.max(0, Math.min(duration, ms)); animations.forEach(a => { a.pause(); a.currentTime = t; }); tick?.(t); },
    play() { if (done) return; animations.forEach(a => a.play()); if (tick && !raf) raf = requestAnimationFrame(loop); },
    pause() { if (done) return; animations.forEach(a => a.pause()); },
    cancel() { finish(); },
  };
}

function hexToRgb(hex: string): [number, number, number] | null {
  const h = hex.trim().replace("#", "");
  if (h.length === 3) return [parseInt(h[0] + h[0], 16), parseInt(h[1] + h[1], 16), parseInt(h[2] + h[2], 16)];
  if (h.length === 6) return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
  return null;
}

/** Solid color of the bubble's screen-space gradient at screen y `bottom` (px from the frame top). */
function fillAt(body: HTMLElement, bottom: number): string {
  const cs = getComputedStyle(body);
  const top = hexToRgb(cs.getPropertyValue("--im-fill-top"));
  const end = hexToRgb(cs.getPropertyValue("--im-fill-bottom"));
  const screen = parseFloat(cs.getPropertyValue("--im-screen-h")) || 874;
  if (!top || !end) return cs.backgroundColor;
  const k = Math.max(0, Math.min(1, bottom / screen));
  const c = top.map((v, i) => Math.round(v + (end[i] - v) * k));
  return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
}

function visibleText(body: HTMLElement): string {
  return Array.from(body.childNodes).map(node => (node instanceof HTMLElement && node.classList.contains("sr-only") ? "" : node.textContent ?? "")).join("").trim();
}

export type SendAnimationOptions = {
  /** The element that represents the device screen. The transient ghost is appended to it, so it needs `position: relative`. */
  frame: HTMLElement;
  /** The composer text field's rect in viewport coordinates (from getBoundingClientRect). */
  field: Rect;
  /** The new message's `[data-slot="message-bubble"]` element (already laid out in its final slot). */
  bubble: HTMLElement;
  /** Composer placeholder to fade in while the rect shrinks. */
  placeholder?: HTMLElement | null;
  /** Composer send button to hide in the first 17 ms. */
  sendButton?: HTMLElement | null;
  /** Text drawn inside the shrinking rect; defaults to the bubble's text. */
  text?: string;
  /** Corner radius of the composer field; the rect starts as that shape. Defaults to a pill. */
  fieldRadius?: number;
  /**
   * Where the shrinking rect is drawn. Native draws it inside the field, under the placeholder, so pass the
   * field element (a positioned one) to get that layering; it is added as the first child. Defaults to `frame`.
   */
  ghostParent?: HTMLElement | null;
  /** Start paused so the caller can `seek`. */
  paused?: boolean;
  reducedMotion?: boolean;
};

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

export function playSendAnimation(o: SendAnimationOptions): MotionHandle {
  const S = messageMotion.send;
  const reduced = o.reducedMotion ?? prefersReducedMotion();
  if (reduced) {
    const D = messageMotion.reduced.duration;
    const a = o.bubble.animate([{ opacity: 0 }, { opacity: 1 }], { duration: D, fill: "both", easing: "ease-out" });
    const b = o.placeholder ? [o.placeholder.animate([{ opacity: 0 }, { opacity: 1 }], { duration: D, fill: "both" })] : [];
    return makeHandle([a, ...b], D, () => undefined, o.paused);
  }
  const D = S.duration;
  const at = (ms: number) => ms / D;
  const timing: KeyframeAnimationOptions = { duration: D, fill: "both", easing: "linear" };
  const body = o.bubble.querySelector<HTMLElement>('[data-slot="bubble"], [data-slot="emoji"]') ?? o.bubble;
  const platform = (o.bubble.dataset.platform ?? "ios") as Platform;
  const m = bubbleMetrics[platform];
  const side = o.bubble.dataset.direction === "incoming" ? "left" : "right";
  const frameRect = o.frame.getBoundingClientRect();
  const slot = body.getBoundingClientRect();
  const fx = o.field.left - frameRect.left, fy = o.field.top - frameRect.top, fw = o.field.width, fh = o.field.height;
  const bw = slot.width, bh = slot.height;
  const sx = slot.left - frameRect.left, sy = slot.top - frameRect.top;
  const gx = side === "right" ? fx + fw - bw : fx, gy = fy + (fh - bh) / 2;
  const dx = gx - sx, dy = gy - sy;
  const cs = getComputedStyle(body);

  // Two springs, both released from rest and both normalised so they land exactly on the slot at `duration`
  // (without that the last keyframe would step by ~0.5 pt). `offsetAt` is the fraction of the travel still
  // to go; `scaleAt` is the uniform scale, anchored at the bubble's tail corner so that corner flies alone.
  const P = S.spring, G = S.growSpring;
  const kEnd = springOffset((D - S.liftoff) / 1000, P.damping, P.frequency);
  const gEnd = springOffset((D - S.grow) / 1000, G.damping, G.frequency);
  const offsetAt = (ms: number) => (springOffset((ms - S.liftoff) / 1000, P.damping, P.frequency) - kEnd) / (1 - kEnd);
  const scaleAt = (ms: number) => 1 - S.squash * (springOffset((ms - S.grow) / 1000, G.damping, G.frequency) - gEnd) / (1 - gEnd);
  /** Where the flying bubble's box sits at `ms`, in frame coordinates. */
  const flightBox = (ms: number) => {
    const k = offsetAt(ms), scale = scaleAt(ms);
    const width = bw * scale, height = bh * scale;
    const bottom = sy + bh + dy * k;
    const left = side === "right" ? sx + bw + dx * k - width : sx + dx * k;
    return { left, top: bottom - height, width, height, scale };
  };

  // Phase 1: the field's text row becomes a bubble-shaped rect and shrinks toward the field's sending end.
  // It ends exactly on the flying bubble's box at `shrink`, so the hand-over is invisible.
  const ghost = document.createElement("div");
  ghost.dataset.slot = "send-ghost";
  ghost.setAttribute("aria-hidden", "true");
  Object.assign(ghost.style, {
    position: "absolute", left: "0px", top: "0px", boxSizing: "border-box",
    background: fillAt(body, fy + fh), pointerEvents: "none",
    // Inside the field it paints in DOM order, under the placeholder; over the frame it needs to be lifted.
    zIndex: o.ghostParent ? "auto" : "30",
    // A transient element must never become a scroll anchor: scrubbing rebuilds it every frame, and each
    // insert and remove would otherwise let scroll anchoring nudge whatever scroller contains it.
    overflowAnchor: "none",
  } satisfies Partial<CSSStyleDeclaration>);
  const tint = document.createElement("div");
  Object.assign(tint.style, { position: "absolute", inset: "0", background: "#ffffff", opacity: String(S.tint) });
  const label = document.createElement("div");
  label.textContent = o.text ?? visibleText(body);
  Object.assign(label.style, {
    position: "absolute", [side]: "0", top: "0", width: `${bw}px`, height: `${bh}px`, boxSizing: "border-box",
    padding: cs.padding, transformOrigin: `${side} top`,
    font: cs.font, letterSpacing: cs.letterSpacing, lineHeight: cs.lineHeight, color: cs.color, whiteSpace: "nowrap", overflow: "hidden", opacity: "0",
    textAlign: bw <= parseFloat(cs.minWidth || "0") + 0.5 ? "center" : "start",
  });
  ghost.append(tint, label);
  const ghostParent = o.ghostParent ?? o.frame;
  // Under the field's own text, but above whatever paints the field itself (a glass stack, a background).
  const editor = ghostParent.querySelector("textarea, input, [contenteditable]");
  ghostParent.insertBefore(ghost, editor?.parentElement === ghostParent ? editor : ghostParent.firstChild);
  // The keyframes below are in frame coordinates; shift them if the rect lives inside the field instead.
  const ox = ghostParent === o.frame ? 0 : ghostParent.getBoundingClientRect().left - frameRect.left;
  const oy = ghostParent === o.frame ? 0 : ghostParent.getBoundingClientRect().top - frameRect.top;

  const fieldRadius = o.fieldRadius ?? fh / 2;
  const shape: Keyframe[] = [];
  const labelScale: Keyframe[] = [];
  for (let ms = 0; ms <= S.shrink; ms = Math.min(S.shrink, ms + 5)) {
    const p = Math.max(0, Math.min(1, (ms - S.morph) / (S.shrink - S.morph)));
    const b = flightBox(ms);
    const width = lerp(fw, b.width, p), height = lerp(fh, b.height, p);
    const tailScale = m.tailScale * lerp(1, b.scale, p);
    shape.push({
      offset: at(ms), opacity: ms < S.morph ? at(ms) / at(S.morph) : 1,
      left: `${(lerp(fx, b.left, p) - ox).toFixed(2)}px`, top: `${(lerp(fy, b.top, p) - oy).toFixed(2)}px`,
      width: `${width.toFixed(2)}px`, height: `${(height + tailBox.hang * tailScale).toFixed(2)}px`,
      clipPath: `path("${bubblePath(width, height, side, lerp(fieldRadius, m.radius * b.scale, p), tailScale)}")`,
    });
    labelScale.push({ offset: at(ms), transform: `scale(${lerp(1, b.scale, p).toFixed(4)})` });
    if (ms >= S.shrink) break;
  }
  const settled = { ...shape[shape.length - 1], offset: undefined } as Keyframe;
  const animations: Animation[] = [
    ghost.animate([...shape, { ...settled, offset: at(S.shrink) + 0.002, opacity: 0 }, { ...settled, offset: 1, opacity: 0 }], timing),
    tint.animate([{ offset: 0, opacity: S.tint }, { offset: at(S.morph), opacity: S.tint }, { offset: at(S.shrink), opacity: 0 }, { offset: 1, opacity: 0 }], timing),
    label.animate(labelScale.map(frame => ({ ...frame, opacity: labelOpacity(Number(frame.offset) * D, S) })), timing),
  ];

  // Phase 2: the flight is flown by a clone of the bubble in the frame's overlay layer, so it passes over the
  // composer the way the native bubble does (at 133 ms the recording draws its tail across the field's pill);
  // the real bubble stays invisible in its slot until the clone lands.
  const rootRect = o.bubble.getBoundingClientRect();
  const clone = o.bubble.cloneNode(true) as HTMLElement;
  clone.dataset.slot = "send-clone";
  clone.setAttribute("aria-hidden", "true");
  clone.querySelectorAll("[id]").forEach(el => el.removeAttribute("id"));
  Object.assign(clone.style, {
    position: "absolute", left: `${rootRect.left - frameRect.left}px`, top: `${rootRect.top - frameRect.top}px`, width: `${rootRect.width}px`,
    margin: "0", pointerEvents: "none", zIndex: "31", opacity: "0", overflowAnchor: "none",
    // The tail corner is the anchor: it flies alone and the rest of the bubble unfolds from it.
    transformOrigin: `${((side === "right" ? slot.right : slot.left) - rootRect.left).toFixed(2)}px ${(slot.bottom - rootRect.top).toFixed(2)}px`,
  });
  // `cloneNode` copies declarations but not the palette the bubble inherits, so resolve it onto the clone.
  // It then paints the measured gradient wherever it is appended, not only under the element that
  // happens to declare `--im-*` today (both shells append it inside that element; this stops depending on it).
  for (const property of Array.from(cs)) if (property.startsWith("--im-")) clone.style.setProperty(property, cs.getPropertyValue(property));
  const realFrame = o.bubble.querySelector<HTMLElement>('[data-slot="bubble-frame"]');
  const cloneFrame = clone.querySelector<HTMLElement>('[data-slot="bubble-frame"]');
  if (realFrame && cloneFrame) { cloneFrame.style.width = `${realFrame.getBoundingClientRect().width}px`; cloneFrame.style.maxWidth = "none"; }
  o.frame.appendChild(clone);

  const transformAt = (ms: number) => `translate(${(dx * offsetAt(ms)).toFixed(2)}px, ${(dy * offsetAt(ms)).toFixed(2)}px) scale(${scaleAt(ms).toFixed(4)})`;
  const flight: Keyframe[] = [{ offset: 0, transform: transformAt(0) }, { offset: at(S.shrink) - 0.002, transform: transformAt(S.shrink) }];
  for (let ms = S.shrink; ms < D; ms += 5) flight.push({ offset: at(ms), transform: transformAt(ms) });
  flight.push({ offset: 1, transform: "translate(0px, 0px) scale(1)" });
  animations.push(clone.animate(flight, timing));
  // The clone and the real bubble swap places with a step, not a crossfade, so at `duration` (and at
  // progress 1, which never runs `cleanup` because a seeked animation never finishes) exactly one of
  // them is painted and the frame equals the settled layout. A ramp here would let a scrub land on a
  // frame with both of them half opaque, which reads as a lighter, doubled bubble.
  animations.push(clone.animate([{ offset: 0, opacity: 0 }, { offset: at(S.shrink) - 0.002, opacity: 0 }, { offset: at(S.shrink), opacity: 1, easing: "step-end" }, { offset: 1, opacity: 0 }], timing));
  animations.push(o.bubble.animate([{ offset: 0, opacity: 0, easing: "step-end" }, { offset: 1, opacity: 1 }], timing));
  // f73 already draws the placeholder at full strength behind the rect (hence `placeholderIn: 0`), so it is
  // held up for the whole flight rather than faded in; it is animated only so the handle owns its opacity.
  if (o.placeholder) animations.push(o.placeholder.animate([{ offset: 0, opacity: 1 }, { offset: 1, opacity: 1 }], timing));
  if (o.sendButton) animations.push(o.sendButton.animate([{ offset: 0, opacity: 1 }, { offset: at(S.morph), opacity: 0 }, { offset: 1, opacity: 0 }], timing));
  // Keep the clone's screen-space fill honest while it climbs (the body's bottom edge moves through the gradient).
  const tick = (ms: number) => clone.style.setProperty("--bubble-bottom", `${(sy + bh + dy * offsetAt(ms)).toFixed(2)}px`);
  tick(0);
  return makeHandle(animations, D, () => { ghost.remove(); clone.remove(); }, o.paused, tick);
}

/** The message text fades in inside the shrinking rect as it takes the bubble's shape. */
function labelOpacity(ms: number, S: typeof messageMotion.send): number {
  if (ms <= S.textReveal) return 0;
  if (ms >= S.textVisible) return 1;
  return (ms - S.textReveal) / (S.textVisible - S.textReveal);
}

export type ReceiveAnimationOptions = {
  /** The new incoming message's `[data-slot="message-bubble"]` element. */
  bubble: HTMLElement;
  /** Where the bubble pops from (the typing indicator's rect, viewport coordinates). Defaults to just below the slot. */
  from?: Rect | null;
  paused?: boolean;
  reducedMotion?: boolean;
};

export function playReceiveAnimation(o: ReceiveAnimationOptions): MotionHandle {
  const R = messageMotion.receive;
  const reduced = o.reducedMotion ?? prefersReducedMotion();
  if (reduced) {
    const D = messageMotion.reduced.duration;
    return makeHandle([o.bubble.animate([{ opacity: 0 }, { opacity: 1 }], { duration: D, fill: "both", easing: "ease-out" })], D, () => undefined, o.paused);
  }
  const D = R.duration;
  const body = o.bubble.querySelector<HTMLElement>('[data-slot="bubble"], [data-slot="emoji"]') ?? o.bubble;
  const slot = body.getBoundingClientRect();
  const dx = o.from ? o.from.left - slot.left : 0;
  const dy = o.from ? o.from.top + o.from.height - (slot.top + slot.height) : 8;
  // The corner it grows from rides in the keyframes rather than in the element's own style: a seeked
  // animation never finishes, so a cleanup that restored an inline `transform-origin` would never run.
  const transformOrigin = o.bubble.dataset.direction === "outgoing" ? "right bottom" : "left bottom";
  const frames: Keyframe[] = [];
  for (let ms = 0; ms <= D; ms += 5) {
    const k = springOffset(ms / 1000, R.spring.damping, R.spring.frequency);
    const p = 1 - k;
    const scale = R.startScale + (1 - R.startScale) * p;
    frames.push({ offset: ms / D, opacity: Math.min(1, ms / R.fade), transformOrigin, transform: `translate(${(dx * k).toFixed(2)}px, ${(dy * k).toFixed(2)}px) scale(${scale.toFixed(4)})` });
  }
  frames.push({ offset: 1, opacity: 1, transformOrigin, transform: "translate(0px, 0px) scale(1)" });
  const animation = o.bubble.animate(frames, { duration: D, fill: "both", easing: "linear" });
  return makeHandle([animation], D, () => undefined, o.paused);
}

/** Runs the send animation for a freshly rendered outgoing bubble. Cancels on unmount and when a new send starts. */
export function useSendAnimation() {
  const current = useRef<MotionHandle | null>(null);
  useEffect(() => () => current.current?.cancel(), []);
  const play = useCallback((options: SendAnimationOptions) => {
    current.current?.cancel();
    const handle = playSendAnimation(options);
    current.current = handle;
    void handle.finished.then(() => { if (current.current === handle) current.current = null; });
    return handle;
  }, []);
  return { play, current };
}

/** Pops a freshly rendered incoming bubble in from the typing indicator's position. */
export function useReceiveAnimation() {
  const current = useRef<MotionHandle | null>(null);
  useEffect(() => () => current.current?.cancel(), []);
  const play = useCallback((options: ReceiveAnimationOptions) => {
    current.current?.cancel();
    const handle = playReceiveAnimation(options);
    current.current = handle;
    void handle.finished.then(() => { if (current.current === handle) current.current = null; });
    return handle;
  }, []);
  return { play, current };
}

/** One message's arrival: `progress` (0 to 1) seeks the animation instead of playing it. */
export type ArrivalAnimation = { id: string; progress?: number };

export type ArrivalAnimationOptions = {
  /** The device frame (iOS) or window pane (macOS); the flying copy is added to it. */
  frame: RefObject<HTMLElement | null>;
  /** The message that was just sent: the composer's text row becomes that bubble and flies to its slot. */
  send?: ArrivalAnimation | null;
  /** The message that just arrived: it pops in from the typing indicator's position. */
  receive?: ArrivalAnimation | null;
  /** Called when a played (not seeked) send animation finishes. */
  onSendEnd?: () => void;
};

/**
 * Drives the send and receive animations for the app shells: give it the frame and the id of the message
 * that just arrived and it finds the bubble, the composer field and the typing indicator itself.
 */
export function useArrivalAnimation({ frame, send, receive, onSendEnd }: ArrivalAnimationOptions) {
  const running = useRef<MotionHandle | null>(null);
  // Kept in a ref so a fresh inline callback cannot restart a flight that is already in the air.
  const end = useRef(onSendEnd);
  useEffect(() => { end.current = onSendEnd; }, [onSendEnd]);
  const sendId = send?.id ?? null, sendProgress = send?.progress;
  const receiveId = receive?.id ?? null, receiveProgress = receive?.progress;

  useLayoutEffect(() => {
    const root = frame.current;
    if (!root || !sendId) return;
    const bubble = root.querySelector<HTMLElement>(`[data-message-id="${CSS.escape(sendId)}"] [data-slot="message-bubble"]`);
    const field = root.querySelector<HTMLElement>('[data-slot="field"]');
    if (!bubble || !field) return;
    running.current?.cancel();
    const handle = playSendAnimation({
      frame: root, field: field.getBoundingClientRect(), bubble, ghostParent: field,
      sendButton: field.querySelector<HTMLElement>('[data-slot="send"]'),
      fieldRadius: parseFloat(getComputedStyle(field).borderTopLeftRadius) || undefined,
      paused: sendProgress !== undefined,
    });
    running.current = handle;
    if (sendProgress === undefined) void handle.finished.then(() => { if (running.current === handle) { running.current = null; end.current?.(); } });
    else handle.seek(Math.max(0, Math.min(1, sendProgress)) * handle.duration);
    return () => { handle.cancel(); if (running.current === handle) running.current = null; };
  }, [frame, sendId, sendProgress]);

  useLayoutEffect(() => {
    const root = frame.current;
    if (!root || !receiveId) return;
    const bubble = root.querySelector<HTMLElement>(`[data-message-id="${CSS.escape(receiveId)}"] [data-slot="message-bubble"]`);
    if (!bubble) return;
    running.current?.cancel();
    const indicator = root.querySelector<HTMLElement>('[data-slot="typing-indicator"]');
    const handle = playReceiveAnimation({ bubble, from: indicator?.getBoundingClientRect() ?? null, paused: receiveProgress !== undefined });
    running.current = handle;
    if (receiveProgress !== undefined) handle.seek(Math.max(0, Math.min(1, receiveProgress)) * handle.duration);
    return () => { handle.cancel(); if (running.current === handle) running.current = null; };
  }, [frame, receiveId, receiveProgress]);

  useEffect(() => () => running.current?.cancel(), []);
}

/** Progress-driven arrival wrapper kept for the harness: `progress` 0..1 maps onto the receive spring. */
export function MessageMotion({ progress = 1, direction = "incoming", className, style, ...props }: ComponentProps<"div"> & { progress?: number; direction?: "incoming" | "outgoing" }) {
  const t = Math.max(0, Math.min(1, progress));
  const k = springOffset((t * messageMotion.receive.duration) / 1000, messageMotion.receive.spring.damping, messageMotion.receive.spring.frequency);
  const p = t >= 1 ? 1 : 1 - k;
  const scale = messageMotion.receive.startScale + (1 - messageMotion.receive.startScale) * p;
  return <div data-slot="message-motion" data-progress={t.toFixed(3)} className={cn("motion-reduce:!transform-none motion-reduce:!opacity-100", direction === "outgoing" ? "origin-bottom-right" : "origin-bottom-left", className)}
    style={{ opacity: Math.min(1, t * 4), transform: t >= 1 ? undefined : `translateY(${((1 - p) * (direction === "outgoing" ? 30 : 12)).toFixed(2)}px) scale(${scale.toFixed(4)})`, ...style }} {...props} />;
}

"use client";

import type { ComponentProps, CSSProperties } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { fontStack } from "@/components/imessage/tokens";

/**
 * A FaceTime link shared into a conversation, and the call states an app may want to show around it.
 *
 * Messages does not render a live call inline: an active FaceTime call lives in its own window, and
 * call history lives in the Phone and FaceTime apps. What genuinely appears in a transcript is a
 * FaceTime *link* card, which SPEC.md records as "the same gray card as a link preview".
 *
 * **No capture in this repo shows a FaceTime card, in either state.** Nothing below was measured off
 * one. What the card does inherit is the link card's own measured geometry, so that "the same gray
 * card" is true of the pixels and not only of the prose (`references/macos/captures/conversation-pane-light.png`,
 * via `link-preview.tsx`): the fill #e9e9eb light / #3b3b3d dark, the 14 radius, the 10 side padding,
 * and the caption at 10pt on a 12pt pitch in #808084 / #a6a6a9. iOS takes the same parts from the
 * numbers iOS itself measures, exactly as `link-preview.tsx` does: the 19 bubble radius, the 280.5
 * widest bubble, the incoming gray, and the secondary label. Everything else here is invented: the
 * icon, the greens and the red, the button, and every gap. The four states other than `invitation`
 * are app surfaces, not reproductions of a native element. Do not quote any of it as measured.
 */
export type FaceTimeState = "invitation" | "ringing" | "connected" | "ended" | "missed";

type Metrics = { width: number; radius: number; padX: number; padY: number; icon: number; iconRadius: number; title: number; titleLine: number; sub: number; subLine: number; gap: number; button: number; buttonText: number; rowGap: number };

const metrics: Record<Platform, Metrics> = {
  ios: { width: 280.5, radius: 19, padX: 14, padY: 12, icon: 44, iconRadius: 11, title: 17, titleLine: 20, sub: 14, subLine: 17, gap: 11, button: 36, buttonText: 15, rowGap: 12 },
  macos: { width: 240, radius: 14, padX: 10, padY: 10, icon: 34, iconRadius: 8.5, title: 13, titleLine: 16, sub: 10, subLine: 12, gap: 9, button: 28, buttonText: 12, rowGap: 9 },
};

/**
 * The link card's fill and caption colour, copied from `link-preview.tsx` so the two cards match.
 * macOS is measured off the apple.com card; iOS swaps in its own measured incoming gray and secondary
 * label, because #3b3b3d is the macOS gray and reads wrong beside iOS bubbles.
 */
const cardVars: Record<Platform, string> = {
  macos: "[--im-card:#e9e9eb] [--im-card-fg:#808084] [--im-card-title:#000000] dark:[--im-card:#3b3b3d] dark:[--im-card-fg:#a6a6a9] dark:[--im-card-title:#ffffff]",
  ios: "[--im-card:#e9e9eb] [--im-card-fg:#8a8a8e] [--im-card-title:#000000] dark:[--im-card:#262629] dark:[--im-card-fg:#8d8d93] dark:[--im-card-title:#ffffff]",
};

/** Unverified: no capture holds a FaceTime card, so these are the system colours, not measured ones. */
const facetimeGreen = "#30c653";
const missedRed = "#ff453a";

function VideoGlyph({ size }: { size: number }) {
  // SF Symbol "video.fill": a rounded rectangle body with a wedge lens on the trailing side.
  return (
    <svg aria-hidden="true" width={size} height={size} viewBox="0 0 28 28" fill="none">
      <rect x="3" y="8" width="15" height="12" rx="3.6" fill="currentColor" />
      <path d="M19.4 12.6 23.4 9.9c.7-.5 1.6 0 1.6.8v6.6c0 .8-.9 1.3-1.6.8l-4-2.7z" fill="currentColor" />
    </svg>
  );
}

export type FaceTimeCardProps = Omit<ComponentProps<"div">, "children"> & {
  state?: FaceTimeState;
  /** Shown while connected, e.g. "12:04". */
  duration?: string;
  /** Line under the title. Defaults to a sensible label for the state. */
  caption?: string;
  onJoin?: () => void;
  onEnd?: () => void;
  platform?: Platform;
};

export function FaceTimeCard({ state = "invitation", duration = "00:00", caption, onJoin, onEnd, platform: platformProp, className, style, ...props }: FaceTimeCardProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = metrics[platform];
  const active = state === "connected" || state === "ringing";
  const missed = state === "missed";
  const label = caption ?? (state === "invitation" ? "FaceTime Link" : state === "ringing" ? "Calling" : state === "connected" ? duration : missed ? "Missed FaceTime" : "FaceTime ended");
  const action = active ? onEnd : onJoin;
  const actionLabel = active ? "Leave" : state === "invitation" ? "Join" : "Call Back";
  // The button's visible word is one syllable; out of context it needs to say what it calls.
  const actionName = active ? "Leave the FaceTime call" : state === "invitation" ? "Join the FaceTime call" : "Call back on FaceTime";
  const card: CSSProperties = {
    width: m.width, maxWidth: "100%", borderRadius: m.radius, padding: `${m.padY}px ${m.padX}px`,
    background: "var(--im-card)", color: "var(--im-card-title)", fontFamily: fontStack,
  };
  return (
    <div data-slot="facetime-card" data-call-state={state} data-platform={platform} className={cn("select-none", cardVars[platform], className)} style={{ ...card, ...style }} {...props}>
      <div className="flex items-center" style={{ gap: m.gap }}>
        <span aria-hidden="true" className="flex shrink-0 items-center justify-center text-white"
          style={{ width: m.icon, height: m.icon, borderRadius: m.iconRadius, background: missed ? missedRed : facetimeGreen }}>
          <VideoGlyph size={m.icon * 0.62} />
        </span>
        <span className="min-w-0">
          <span className="block truncate" style={{ fontSize: m.title, lineHeight: `${m.titleLine}px`, fontWeight: 600 }}>FaceTime</span>
          {/* A live region only while the call is one: "FaceTime Link" is a caption, not an update. */}
          <span role={state === "invitation" ? undefined : "status"} className="block truncate" style={{ fontSize: m.sub, lineHeight: `${m.subLine}px`, color: "var(--im-card-fg)" }}>{label}</span>
        </span>
      </div>
      {action && (
        <button type="button" onClick={action} aria-label={actionName}
          className="flex w-full items-center justify-center font-semibold text-white transition-[filter] active:brightness-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
          style={{ marginTop: m.rowGap, height: m.button, borderRadius: m.button / 2, fontSize: m.buttonText, background: active ? missedRed : facetimeGreen }}>
          {actionLabel}
        </button>
      )}
    </div>
  );
}

import type { ComponentProps, CSSProperties } from "react";
import { cn } from "@/lib/utils";

/**
 * Contact avatar: initials over the native gray-blue gradient, a photo, or the generic silhouette.
 *
 * **Fill.** A vertical linear gradient across the circle's own box: light #a9c2e1 → #747fb9, dark
 * #575368 → #302649. Fitted to the Ø45 row avatars in `references/ios/captures/list-light.png` and
 * `list-dark.png`, and re-fitted independently to the Ø60 nav-bar avatar in `conv3-light.png`, which
 * returns the same endpoints (max residual 0.7/255 against a straight line). The gradient does not
 * change with the circle's size.
 *
 * **Initials.** White, weight 600, at **7/15 of the diameter** (0.4667). Three diameters in the
 * captures pin that ratio, and Chrome reproduces each one's ink exactly:
 *
 * | Where | Ø | Type | Native ink | Chrome at 3x |
 * |---|---|---|---|---|
 * | List row (`list-light.png`), circle x 26-71 y 188-233 | 45 | 21 | "JA" 24.67 wide, cap 15.00, ink top 15.33 below the circle | 24.67 wide, ink top 15.33 |
 * | Nav bar (`conv3-light.png`), circle x 171-231 y 62-122 | 60 | 28 | "JA" 32.67 wide, cap 19.67, ink top 20.33 below the circle | 33.00 wide, ink top 20.67 |
 * | Details (`details-light.png`), circle x 161-241 y 62-142 | 80 | 37.33 | "JA" 44.00 wide, cap 26.67, ink top 27.00 below the circle | 44.00 wide, ink top 27.00 |
 *
 * Chrome rasterises the caps one to two device px taller than the simulator, so no offset can land both
 * edges. `translateY(0.02em)` puts the ink *top* on native at Ø45 and Ø80 and one device px low at Ø60,
 * which no other offset beats; the ink then hangs a device px below native. Diffed against the captures
 * that hold an avatar, that leaves 0.74% of Ø45 "JA", 0.62% of Ø45 "KB" and 0.50% of Ø80 "JA" mismatched,
 * all of it glyph edges: the circle and the gradient are exact.
 *
 * **Photo.** A plain circular clip, no rim and no shadow: measured on the Ø40 macOS header avatar in
 * `references/macos/captures/conversation-pane-light.png` (x 592-671, y 16-95 at 2x = 40.0 square).
 *
 * **Silhouette: unverified.** No committed capture has a contact without initials or a photo, so the
 * glyph's proportions are drawn from the SF Symbol, not measured. Do not quote them as measured.
 *
 * `ios-nav-bar.tsx`, `ios-conversation-list.tsx` and `ios-details.tsx` each draw their own circle with
 * their own copy of these values instead of importing this component.
 */
export type AvatarSize = 40 | 45 | 60 | 72 | 80 | number;

export type AvatarProps = Omit<ComponentProps<"span">, "children"> & {
  size?: AvatarSize;
  /** One or two letters. Ignored when `src` is set. */
  initials?: string;
  /** Photo variant. */
  src?: string;
  /** Accessible name; falls back to the initials. */
  name?: string;
};

/** Initials type size for a circle of `size`: the measured 7/15 of the diameter (45 → 21, 60 → 28, 80 → 37.33). */
export function avatarFontSize(size: number): number {
  return (size * 7) / 15;
}

/** The literal value of `fontStack` in tokens.ts, inlined so the avatar installs with no dependencies. */
const fontStack = '-apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro", "Helvetica Neue", Helvetica, Arial, sans-serif';

export function Avatar({ size = 40, initials, src, name, className, style, ...props }: AvatarProps) {
  const label = name ?? initials ?? "Contact";
  const vars = { "--av-top": "#a9c2e1", "--av-bottom": "#747fb9" } as CSSProperties;
  return (
    <span
      data-slot="avatar"
      data-size={size}
      role="img"
      aria-label={label}
      className={cn("relative inline-flex shrink-0 select-none items-center justify-center overflow-hidden rounded-full align-middle text-white dark:[--av-bottom:#302649] dark:[--av-top:#575368]", className)}
      style={{
        width: size, height: size, fontSize: avatarFontSize(size), fontWeight: 600, lineHeight: 1, letterSpacing: 0,
        fontFamily: fontStack,
        background: "linear-gradient(var(--av-top), var(--av-bottom))",
        ...vars, ...style,
      }}
      {...props}
    >
      {src ? (
        // eslint-disable-next-line @next/next/no-img-element -- registry components stay framework-neutral
        <img data-slot="avatar-photo" src={src} alt="" className="size-full object-cover" draggable={false} />
      ) : initials ? (
        <span data-slot="avatar-initials" aria-hidden="true" style={{ transform: "translateY(0.02em)" }}>{initials.slice(0, 2)}</span>
      ) : (
        <Silhouette size={size} />
      )}
    </span>
  );
}

/**
 * The generic contact glyph: head above shoulders, white, clipped by the circle.
 * Unverified: no capture in this repo shows a contact without initials or a photo.
 */
function Silhouette({ size }: { size: number }) {
  return (
    <svg data-slot="avatar-silhouette" aria-hidden="true" viewBox="0 0 40 40" width={size} height={size} className="absolute inset-0" fill="#ffffff">
      <circle cx="20" cy="15.5" r="7.5" />
      <path d="M6 40c0-9 5.8-14.5 14-14.5S34 31 34 40Z" />
    </svg>
  );
}

"use client";

import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { cn } from "@/lib/utils";

/**
 * macOS 26 Messages window frame. The pane captures are crops of window x 330–960, so they carry the
 * window's top, right and bottom edges but never its left column. Measured at 2x:
 * - corners: continuous. `conversation-pane-light.png` and `conversation-pane-dark-2.png` are both
 *   shadow-free captures, so their alpha edge is the window's own outline: fitting it with the
 *   exponent Chrome's `superellipse(1.4)` draws (2.639) gives radius 31.67 and 31.81 pt at 0.23 px
 *   rms, and the best plain circle is 25.5 pt at 0.38 px rms (0.9 px worst point). Tracing a Chrome
 *   render of those two values back returns them to 0.06 pt, so the fit reads a radius honestly.
 *   The rim ridge of `conversation-pane-dark.png` reads 0.8 pt larger; that capture sits on the
 *   desktop and its rim is a lit band, so the two alpha outlines are the better evidence.
 * - dark frame: 1 pt #4b4b4b down the sides and along the bottom (two device columns at window
 *   x 959–960 of `conversation-pane-dark.png`). The top edge is brighter and is not painted gray: it
 *   reads #6f6f6f then #5d5d5d over the #1e1e1e pane, and #74787f then #63696f where a blue bubble
 *   sits under the header, which is white at 0.36 and 0.28 over both.
 * - light frame: no side or bottom rim, the pane runs to the edge. The same top highlight is there,
 *   white at 0.70 then 0.40: #fefefe then #fdfdfd over the #fcfcfc header glass, and white over the
 *   plain pane of `conversation-pane-light-partial.png`.
 * - traffic lights: Ø14 centred (25.75, 25.75), (48.75, 25.75), (71.75, 25.75), from SPEC "macOS
 *   Chrome". No committed capture contains them: every pane crop starts at window x 330, so these
 *   come from the full-window frames held outside the repo and cannot be re-measured here. Their
 *   inactive fills are not measured at all, since no capture shows a window that is not key.
 */
export const macWindowMetrics = {
  width: 960,
  height: 640,
  sidebarWidth: 330,
  /** Best circular fit to the window outline. Browsers with `corner-shape` get `continuousRadius`. */
  cornerRadius: 25.5,
  continuousRadius: 31.75,
  trafficLight: { diameter: 14, centers: [25.75, 48.75, 71.75] as const, y: 25.75 },
};

export type MacWindowProps = Omit<ComponentProps<"div">, "children" | "content"> & {
  width?: number;
  height?: number;
  /** Key window: colored traffic lights and the blue sidebar selection. */
  active?: boolean;
  /** The conversation list. Rendered in the left `sidebarWidth` (330 pt) column. */
  sidebar?: ReactNode;
  sidebarWidth?: number;
  /** The conversation pane. */
  content?: ReactNode;
  children?: ReactNode;
};

const lights = [
  { name: "Close", fill: "#ff5f57", rim: "#e0443e" },
  { name: "Minimize", fill: "#febc2e", rim: "#dea123" },
  { name: "Zoom", fill: "#28c840", rim: "#1aab29" },
];

export function MacWindow({ width = macWindowMetrics.width, height = macWindowMetrics.height, active = true, sidebar, sidebarWidth = macWindowMetrics.sidebarWidth, content, children, className, style, ...props }: MacWindowProps) {
  const { diameter, centers, y } = macWindowMetrics.trafficLight;
  return (
    <div
      data-slot="mac-window"
      data-active={active ? "true" : "false"}
      className={cn("mac-window relative isolate overflow-hidden bg-white text-black [--mac-light-inactive-rim:rgba(0,0,0,0.12)] [--mac-light-inactive:#dcdcdc] [--mac-rim-top-1:rgba(255,255,255,0.50)] [--mac-rim-top-2:rgba(255,255,255,0.40)] dark:bg-[#1e1e1e] dark:text-white dark:[--mac-light-inactive-rim:rgba(255,255,255,0.08)] dark:[--mac-light-inactive:#4f4f4f] dark:[--mac-rim-top-1:rgba(255,255,255,0.111)] dark:[--mac-rim-top-2:rgba(255,255,255,0.28)]", className)}
      style={{ width, height, fontFamily: "-apple-system, BlinkMacSystemFont, sans-serif", WebkitFontSmoothing: "antialiased", ...style }}
      {...props}
    >
      <style>{`
        .mac-window { border-radius: ${macWindowMetrics.cornerRadius}px; }
        @supports (corner-shape: superellipse(1.4)) { .mac-window { border-radius: ${macWindowMetrics.continuousRadius}px; corner-shape: superellipse(1.4); } }
      `}</style>
      <div data-slot="mac-window-sidebar" className="absolute inset-y-0 left-0" style={{ width: sidebarWidth }}>{sidebar}</div>
      <div data-slot="mac-window-content" className="absolute inset-y-0 right-0" style={{ left: sidebarWidth }}>{content ?? children}</div>
      <div data-slot="traffic-lights" role="group" aria-label="Window controls" className="absolute left-0 top-0 z-20" style={{ height: y * 2, width: centers[2] + diameter }}>
        {lights.map((light, index) => (
          <span
            key={light.name}
            data-slot="traffic-light"
            role="img"
            aria-label={light.name}
            className="absolute rounded-full"
            style={{
              width: diameter, height: diameter, left: Math.floor(centers[index] - diameter / 2), top: Math.floor(y - diameter / 2),
              // The measured box starts on a quarter point (18.75). A positioned box is snapped to whole
              // device pixels, which would round that away; a fractional transform is not, so it carries
              // the remainder and the light lands where the capture puts it.
              transform: `translate(${((centers[index] - diameter / 2) % 1).toFixed(3)}px, ${((y - diameter / 2) % 1).toFixed(3)}px)`,
              background: active ? light.fill : "var(--mac-light-inactive)",
              boxShadow: `inset 0 0 0 0.5px ${active ? light.rim : "var(--mac-light-inactive-rim)"}`,
            } as CSSProperties}
          />
        ))}
      </div>
      {/* Frame rim, in two parts because native's top edge replaces the side rim rather than sitting on
          top of it: dark draws #4b4b4b down the sides and along the bottom, and both themes draw the
          top edge as white glass, so whatever scrolls under the header shows through it. */}
      <div aria-hidden="true" data-slot="mac-window-rim" className="mac-window pointer-events-none absolute inset-0 z-30 hidden dark:block" style={{ boxShadow: "inset 1px 0 0 #4b4b4b, inset -1px 0 0 #4b4b4b, inset 0 -1px 0 #4b4b4b" }} />
      {/* The top edge is two device rows at 2x: white 0.36 then 0.28 in dark, 0.70 then 0.40 in light.
          The first shadow paints over the second, so `--mac-rim-top-1` carries only the difference. */}
      <div aria-hidden="true" data-slot="mac-window-top-edge" className="mac-window pointer-events-none absolute inset-0 z-30" style={{ boxShadow: "inset 0 0.5px 0 var(--mac-rim-top-1), inset 0 1px 0 var(--mac-rim-top-2)" }} />
    </div>
  );
}

"use client";

import type { ComponentProps, CSSProperties } from "react";
import { cn } from "@/lib/utils";
import { Avatar } from "@/components/imessage/avatar";

/**
 * macOS 26 Messages conversation list. Every number is measured from a native 960×640 window at 2x
 * (see `references/SPEC.md` → macOS Chrome). The sidebar is not a flat 330 pt column: it is a floating
 * panel inset 8 from the window's left, top and bottom, 320 wide (window x 8–328), radius ≈18, with a
 * 1 pt bright rim and a soft shadow onto the pane. Everything inside sits in window coordinates:
 * search field x 18–318 y 52–88 (a 36 tall capsule), pinned Ø73 avatar centered (168, 142.5) with an
 * 11 pt gray label, rows 80.5 tall from y 215 with a Ø40 avatar at x 36–76, a 13 pt semibold name
 * (baseline 28.75 into the row), a 12 pt time on the same baseline ending at x 307.5, a 12 pt preview
 * (baseline 45, 15 pt line pitch, two lines), 1 pt separators from x 82 to 306, a #3478f6 selection
 * (#3a3a3a when the window is not key) and a 49 pt footer bar at the panel's bottom.
 *
 * **Unread** (no capture; read out of ChatKit 26.5 on macOS 26.5, the framework macOS Messages is
 * built on). An unread row draws a dot and nothing else: nothing in the row's layout moves, no label
 * changes weight or colour, and there is no count badge.
 * - Ø **9**, from `-[CKUIBehaviorMac unreadIndicatorImageViewSize]` = `{9, 9}`. The asset behind it,
 *   `-[CKUIBehavior unreadIndicatorTintedImage]`, is a Ø12 circle that fills its box edge to edge, so
 *   the image view's size *is* the dot's diameter.
 * - Fill **#0088ff light / #0091ff dark, opaque**, from `-[CKUIThemeMac unreadIndicatorColor]`.
 *   `__42-[CKUIBehavior unreadIndicatorTintedImage]_block_invoke` is that colour's only consumer:
 *   it bakes it into the circle, and rendering the image under each appearance returns those two.
 * - Placement `-[CKConversationListCellLayout unreadFrame]` = `{4.5, y, 9, 9}` in the same row space
 *   whose avatar is `{18, ·, 40, 40}` and whose name box starts at 64, i.e. exactly this component's.
 *   `-[CKConversationListStandardCell _calculateIndicatorFrameForSize:trailing:displayScale:insets:]`
 *   derives both: x = (`conversationListCellLeftMargin` 18 − 9) / 2 = 4.5, so the dot is centred in the
 *   gutter left of the avatar, and y = (row height − 9) / 2, so it is centred on the row.
 * - **Selected and unread**: the dot turns **white**, opaque. `-[CKUIBehaviorMac
 *   shouldUnreadIndicatorChangeOnSelection]` is `YES` (it is `NO` on `CKUIBehaviorPhone`), and
 *   `-[CKConversationListCell unreadIndicatorImageForVisibility:withMuteState:]` reads
 *   `shouldLabelsBeHighlighted && shouldUnreadIndicatorChangeOnSelection ? unreadIndicatorSelectedImage
 *   : unreadIndicatorTintedImage`. The selected image renders #ffffff in both appearances. It is the
 *   same test that whitens the labels, because the dot sits inside the selection fill, not beside it,
 *   so the dot follows `highlighted` here. `shouldLabelsBeHighlighted` is a bare ivar on the cell with
 *   no notion of a key window, so an inactive window's gray selection is the one case not settled by
 *   the framework: the capture shows its labels staying dark, and the dot stays blue to match.
 * - **No count.** `_TtC7ChatKit32CKConversationListIndicatorsView`, the row's accessory strip, holds
 *   only image views, and `-[CKConversationListCell unreadMessageCount]` is read by nothing that
 *   draws. A number passed here is announced and never painted.
 * - **A pinned conversation** draws the same dot before its title label. `CKPinnedConversationView`
 *   vends `unreadIndicatorSize` {9, 9} and `unreadIndicatorPreferredPadding` trailing **3**, and laying
 *   a 96 × 119 one out (the tile size this component uses) puts the label at x 15.5 w 65.5 y 90 h 19
 *   and the dot at x 3.5 y 95, i.e. the label stays centred in the tile and the dot hangs off its
 *   leading edge 3 away, vertically centred on the label's line. `_unreadIndicatorColor` picks between
 *   three colours and both of its branches are now settled:
 *   `isFilteredByFocus ? conversationListPinnedConversationFilteredByFocusIndicatorColor
 *    : isSelectedWithDarkAppearance ? readSelectedIndicatorColor : unreadIndicatorColor`.
 *   `isFilteredByFocus` is set from `-[CKConversationList updateFilteredByFocusStateForConversations:]`,
 *   the "a Focus is filtering this conversation out" dimming; this kit has no Focus, so it is always NO
 *   and the #000000@25.9% / #ffffff@24.7% colour it would pick is unreachable. `isSelectedWithDarkAppearance`
 *   is written in exactly one place, `-[CKPinnedConversationCollectionViewCell updateConfigurationUsingState:]`,
 *   as `useSelectedAppearanceForConversationCellState:traitCollection: && showsBackgroundViewWhenSelected`,
 *   and `-[CKUIBehaviorMac useSelectedAppearanceForConversationCellState:traitCollection:]` is
 *   `(state.isSelected || state.cellDropState == 2) && traitCollection.activeAppearance.isMainWindowForegroundActive`.
 *   So the name means "selected on the key window, while the tile paints its selected background", and
 *   `readSelectedIndicatorColor` is opaque **#ffffff** in both appearances, the same white the row dot
 *   takes. This component's pinned selection is a ring around the avatar, not the filled radius-8
 *   background view native draws (`conversationListPinnedCellSelectedBackgroundCornerRadius` 8), and
 *   its label does not go white either, so the second term is NO here and the dot always takes
 *   `unreadIndicatorColor`. Give the tile that background and the white branch turns on with it.
 *
 * **Group rows** (`members`). A group conversation's row draws the same `CKAvatarView` the one-to-one
 * row does (`CKConversationListStandardCell._avatarView`), handed every participant instead of one, and
 * `CNAvatarView` lays those out through `ContactsUICore.SnowglobeUIView` as a stack of circles inside
 * the same Ø40 box. See `groupPhotoRecipes` for the measured stack. The preview line is prefixed with
 * `sender`, in the same 12 pt type and the same gray as the rest of the preview: ChatKit does not
 * compose that prefix (`-[CKConversation previewText]` is the message's text alone, and the cell has
 * only a from-label and a summary label), so the wording is the caller's and only the metrics it has to
 * fit are measured.
 */
export type SidebarConversation = {
  id: string;
  name: string;
  initials: string;
  preview: string;
  time: string;
  pinned?: boolean;
  muted?: boolean;
  /**
   * Unread conversation: draws the dot. A number is announced ("3 unread messages") but never
   * painted, because macOS Messages draws no count on a row.
   */
  unread?: boolean | number;
  /** Photo variant of the avatar. */
  photo?: string;
  /**
   * Group conversation: its participants, drawn as the stacked group photo in place of one avatar.
   * Two or more entries make it a group; the stack shows the first seven.
   */
  members?: GroupMember[];
  /**
   * Who sent the last message. A group row prefixes its preview with it ("Sam Rivera: Tuesday…").
   * Ignored on a one-to-one row, which never carries a sender.
   */
  sender?: string;
};

export type GroupMember = {
  /** One or two letters. Ignored when `photo` is set. */
  initials: string;
  /** Accessible name, and the name the group photo announces. */
  name?: string;
  photo?: string;
};

export type MacSidebarProps = Omit<ComponentProps<"nav">, "onSelect"> & {
  conversations: SidebarConversation[];
  selectedId?: string;
  onSelect?: (id: string) => void;
  /** Key window: blue selection. Otherwise the neutral inactive selection. */
  active?: boolean;
  /** Footer line, e.g. "Syncing with iCloud Paused". */
  footer?: string;
  onSearch?: (query: string) => void;
  onOptions?: () => void;
};

export const macSidebarMetrics = {
  /** The column the window reserves. The panel itself is inset inside it. */
  width: 330,
  panel: { left: 8, top: 8, bottom: 8, width: 320, radius: 18 },
  search: { left: 18, top: 52, width: 300, height: 36 },
  pinned: {
    top: 96, avatar: 73, centerX: 168, avatarCenterY: 142.5, height: 119, labelTop: 184.75,
    // CKPinnedConversationView: the dot is the same Ø9, and `unreadIndicatorPreferredPadding` puts 3
    // between it and the title label, which does not move to make room for it.
    unread: 9, unreadGap: 3,
  },
  row: {
    left: 18, width: 300, height: 80.5, radius: 8, avatar: 40, avatarLeft: 18,
    textLeft: 64, textRight: 10.5, separatorRight: 12, nameTop: 15.75, previewTop: 33, previewLine: 15,
    muted: 11.5, mutedTop: 36.3,
    // ChatKit's own unreadFrame: Ø9 centred in the 18 pt gutter left of the avatar, centred on the row.
    unread: 9, unreadLeft: 4.5,
  },
  footer: { height: 49, textTop: 17.75 },
  options: { centerX: 306, centerY: 25.85 },
  /**
   * How long a separator takes to cross when the selection moves. **Unverified**: no capture holds a
   * switch. It is the same 140 ms `macos-messages-app.tsx` gives the travelling highlight
   * (`macTransitions.selection.duration`), copied rather than imported because that file imports this
   * one. The two have to agree: the separators the selection uncovers and covers are the ones it is
   * moving between, so a different number would make them lead or trail the fill.
   */
  selectionFade: 140,
};

/**
 * ChatKit's group photo, measured. A group row's avatar is the same `CKAvatarView` a one-to-one row
 * uses (`CKConversationListStandardCell._avatarView`), handed the conversation's participants through
 * `-[CNAvatarView setContacts:]` instead of one contact. `CNAvatarView` then builds a
 * `ContactsUICore.SnowglobeUIView` holding one `ContactsUICore.AvatarUIView` per person, and the
 * constraint layout it runs is what these numbers are: a probe that swizzles `-[UIDevice
 * userInterfaceIdiom]` to Mac, dlopens ChatKit, builds `CKAvatarView` over N fixture `CNMutableContact`s
 * and calls `layoutIfNeeded` reports each circle's frame.
 *
 * Each row is `[x, y, diameter]` on a **44-unit** box, back to front, and the layout is a pure ratio:
 * asking for 88 doubles every number exactly and asking for 40 divides them by 1.1 exactly, so a
 * circle's frame is its entry times `size / 44`. Every value lands on a quarter unit at 44, which is
 * what says 44 is the grid the recipes were authored on. **The same layout on both platforms**: the
 * probe run with the idiom left as Phone returns the same frames to the last digit, so this is also the
 * iOS group avatar. One contact is the plain full-box circle; two and three have their own recipes;
 * four, five and six add a slot to the three-person stack; seven re-lays the whole stack out, and an
 * eighth participant changes nothing, so seven is the cap.
 *
 * Not reproduced: `SnowglobeUIView` also puts a `UIVisualEffectView` (`UIBlurEffect material=20`) behind
 * the circles, filling the box. Nothing in `references/` shows a group row, so whether that plate is
 * visible against a sidebar row, and what it does over the blue selection, is unmeasured; this draws the
 * circles alone.
 */
export const groupPhotoRecipes: readonly (readonly (readonly [number, number, number])[])[] = [
  [[0, 0, 44]],
  [[4.75, 4.75, 24], [23.75, 23.75, 14]],
  [[5.25, 5.25, 21], [24.75, 17.75, 16], [12.5, 27.25, 13]],
  [[5.25, 5.25, 21], [24.75, 17.75, 16], [12.5, 27.25, 13], [27, 6.75, 10]],
  [[5.25, 5.25, 21], [24.75, 17.75, 16], [12.5, 27.25, 13], [27, 6.75, 10], [4.75, 25.5, 7]],
  [[5.25, 5.25, 21], [24.75, 17.75, 16], [12.5, 27.25, 13], [27, 6.75, 10], [4.75, 25.5, 7], [23.25, 3.25, 5]],
  [[5.25, 5.25, 21], [24.25, 20.25, 15], [27.25, 8.25, 11], [6.5, 26.75, 10], [19.25, 33.25, 7.5], [17.75, 26.75, 5.5], [24, 3.75, 5]],
];

/** The stack, at any diameter. `macos-header.tsx` carries its own copy, the way the iOS chrome does. */
export function GroupPhoto({ size, members, name, className, style, ...props }: Omit<ComponentProps<"span">, "children"> & { size: number; members: GroupMember[]; name?: string }) {
  const people = members.slice(0, groupPhotoRecipes.length);
  const recipe = groupPhotoRecipes[people.length - 1] ?? groupPhotoRecipes[0];
  const unit = size / 44;
  return (
    <span
      data-slot="group-photo"
      role="img"
      aria-label={name ?? people.map(person => person.name ?? person.initials).join(", ")}
      className={cn("relative block shrink-0", className)}
      style={{ width: size, height: size, ...style }}
      {...props}
    >
      {people.map((person, index) => {
        const [x, y, diameter] = recipe[index];
        return (
          <Avatar key={index} aria-hidden="true" size={diameter * unit} initials={person.initials} src={person.photo} name={person.name}
            className="absolute" style={{ left: x * unit, top: y * unit }} />
        );
      })}
    </span>
  );
}

/** Sidebar list options: three centred bars, 16.5 / 12.5 / 9.5 wide, 1.25 thick, 4.1 apart. */
function OptionsIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 16.5 9.45" width="16.5" height="9.45" fill="currentColor">
      <rect x="0" y="0" width="16.5" height="1.25" rx="0.625" />
      <rect x="2" y="4.1" width="12.5" height="1.25" rx="0.625" />
      <rect x="3.5" y="8.2" width="9.5" height="1.25" rx="0.625" />
    </svg>
  );
}

/** Ø10 magnifier with a handle running to the corner: the native ink box is 12.5 square at (32.5, 63.5). */
function SearchIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 12.5 12.5" width="12.5" height="12.5" fill="none" stroke="currentColor">
      <circle cx="5" cy="5" r="4.4" strokeWidth="1.2" />
      <path d="M8.4 8.4 11.9 11.9" strokeWidth="1.4" strokeLinecap="round" />
    </svg>
  );
}

/** bell.slash.fill: a filled bell with the slash separated from it by a background-coloured stroke. */
function MutedIcon({ size, color, halo }: { size: number; color: string; halo: string }) {
  return (
    <svg aria-label="Muted" role="img" viewBox="0 0 10 10" width={size} height={size}>
      <path fill={color} d="M5 0.6a2.6 2.6 0 0 0-2.6 2.6c0 2.2-.6 2.9-1.1 3.4a.5.5 0 0 0 .35.85h6.7a.5.5 0 0 0 .35-.85c-.5-.5-1.1-1.2-1.1-3.4A2.6 2.6 0 0 0 5 .6Zm0 8.8a1.2 1.2 0 0 0 1.15-.9h-2.3A1.2 1.2 0 0 0 5 9.4Z" />
      <path stroke={halo} strokeWidth="1.9" strokeLinecap="round" d="M1.5 1.5 8.5 8.5" />
      <path stroke={color} strokeWidth="0.95" strokeLinecap="round" d="M1.5 1.5 8.5 8.5" />
    </svg>
  );
}

/**
 * What an unread row announces. Nothing in ChatKit builds this string, so the wording is ours; the
 * count comes from the caller because macOS Messages never paints one.
 */
function unreadLabel(unread: boolean | number): string {
  if (unread === true) return "Unread";
  return unread === 1 ? "1 unread message" : `${unread} unread messages`;
}

export function MacSidebar({ conversations, selectedId, onSelect, active = true, footer, onSearch, onOptions, className, style, ...props }: MacSidebarProps) {
  const m = macSidebarMetrics;
  const pinned = conversations.filter(c => c.pinned);
  const rows = conversations.filter(c => !c.pinned);
  const listTop = pinned.length ? m.pinned.top + m.pinned.height : m.pinned.top;
  return (
    <nav
      data-slot="mac-sidebar"
      data-active={active ? "true" : "false"}
      aria-label="Conversations"
      className={cn(
        "mac-sidebar relative h-full select-none overflow-hidden bg-[#f8f8f8] text-black",
        "[--sb-fill:#fafafa] [--sb-rim:#ffffff] [--sb-rim-inner:#fefefe] [--sb-inactive:#e2e2e2] [--sb-name:#000000] [--sb-secondary:#6e6e6d] [--sb-muted:#aeaeae] [--sb-glyph:#232323] [--sb-field:#eeeeee] [--sb-placeholder:#777777] [--sb-separator:#e1e1e1] [--sb-footer-line:#d0d2d7] [--sb-footer-top:#e4e6eb] [--sb-footer-bottom:#eff0f2] [--sb-footer-text:#000000] [--sb-unread:#0088ff]",
        "dark:bg-[#1c1c1c] dark:text-[#f4f4f4]",
        "dark:[--sb-fill:#1b1b1b] dark:[--sb-rim:#424242] dark:[--sb-rim-inner:#323232] dark:[--sb-inactive:#3a3a3a] dark:[--sb-name:#f4f4f4] dark:[--sb-secondary:#a4a4a4] dark:[--sb-muted:#5b5b5b] dark:[--sb-glyph:#dddddd] dark:[--sb-field:#1e1e1e] dark:[--sb-placeholder:#9a9a9a] dark:[--sb-separator:#3a3a3a] dark:[--sb-footer-line:#43454a] dark:[--sb-footer-top:#27292e] dark:[--sb-footer-bottom:#27272a] dark:[--sb-footer-text:#f5f5f5] dark:[--sb-unread:#0091ff]",
        className,
      )}
      style={{ width: m.width, fontFamily: "-apple-system, BlinkMacSystemFont, sans-serif", ...style }}
      {...props}
    >
      {/*
        Native draws continuous corners: a plain circle of radius 18 (panel) / 8 (row selection) is the
        closest circular fit, so browsers with `corner-shape` get the superellipse the capture shows.
      */}
      <style>{`
        .mac-sidebar-panel { border-radius: ${m.panel.radius}px; }
        .mac-sidebar-row { border-radius: ${m.row.radius}px; }
        @supports (corner-shape: superellipse(1.4)) {
          .mac-sidebar-panel { border-radius: 22px; corner-shape: superellipse(1.4); }
          .mac-sidebar-row { border-radius: 10px; corner-shape: superellipse(1.4); }
        }
        .mac-sidebar-separator { transition: opacity ${m.selectionFade}ms linear; }
        @media (prefers-reduced-motion: reduce) { .mac-sidebar-separator { transition: none; } }
      `}</style>
      <div
        aria-hidden="true"
        data-slot="sidebar-panel"
        className="mac-sidebar-panel absolute bg-[var(--sb-fill)]"
        style={{ left: m.panel.left, top: m.panel.top, bottom: m.panel.bottom, width: m.panel.width, // The panel rim is two device pixels and they are not the same colour: #424242 outside,
          // #323232 inside on dark. One 1 pt ring paints both columns the same and reads too bright.
          boxShadow: "0 0 20px rgba(0,0,0,0.05), inset 0 0 0 0.5px var(--sb-rim), inset 0 0 0 1px var(--sb-rim-inner)" }}
      />

      <button type="button" data-slot="sidebar-options" aria-label="Conversation list options" aria-haspopup="menu" onClick={onOptions}
        className="absolute flex size-[26px] items-center justify-center rounded-full text-[var(--sb-glyph)] hover:bg-black/5 dark:hover:bg-white/10"
        style={{ left: m.options.centerX - 13, top: m.options.centerY - 13 }}>
        <OptionsIcon />
      </button>

      <label data-slot="sidebar-search" className="absolute flex items-center bg-[var(--sb-field)] text-[var(--sb-placeholder)]"
        style={{ left: m.search.left, top: m.search.top, width: m.search.width, height: m.search.height, borderRadius: m.search.height / 2 }}>
        <span aria-hidden="true" className="absolute" style={{ left: 32.5 - m.search.left, top: 63.5 - m.search.top }}><SearchIcon /></span>
        <span className="sr-only">Search conversations</span>
        <input type="search" placeholder="Search" onChange={event => onSearch?.(event.target.value)}
          className="absolute bg-transparent text-[13px] leading-[16px] text-[var(--sb-name)] outline-none placeholder:font-medium placeholder:text-[var(--sb-placeholder)] [&::-webkit-search-cancel-button]:hidden [&::-webkit-search-decoration]:hidden"
          style={{ left: 53 - m.search.left, right: 8, top: 61.75 - m.search.top }} />
      </label>

      {pinned.length > 0 && (
        <ul data-slot="sidebar-pinned" aria-label="Pinned" className="absolute flex list-none justify-center gap-[24px] p-0"
          style={{ left: m.panel.left, top: m.pinned.top, width: m.panel.width, height: m.pinned.height }}>
          {pinned.map(c => {
            const selected = c.id === selectedId;
            return (
              <li key={c.id} className="flex w-[96px] flex-col items-center">
                <button type="button" aria-current={selected ? "true" : undefined} onClick={() => onSelect?.(c.id)}
                  className="flex flex-col items-center rounded-[14px] outline-offset-2 focus-visible:outline-2 focus-visible:outline-[#3478f6]"
                  style={{ paddingTop: m.pinned.avatarCenterY - m.pinned.top - m.pinned.avatar / 2 }}>
                  {c.unread ? <span className="sr-only">{unreadLabel(c.unread)}. </span> : null}
                  {c.members && c.members.length > 1
                    ? <GroupPhoto size={m.pinned.avatar} members={c.members} name={c.name}
                        style={selected ? { boxShadow: `0 0 0 2px ${active ? "#3478f6" : "#9a9a9a"}`, borderRadius: "50%" } : undefined} />
                    : <Avatar size={m.pinned.avatar} initials={c.initials} src={c.photo} name={c.name}
                        style={selected ? { boxShadow: `0 0 0 2px ${active ? "#3478f6" : "#9a9a9a"}` } : undefined} />}
                  {/* The tile's label stays centred whether or not there is a dot; the dot hangs off its
                      leading edge, which is what CKPinnedConversationView's own layout does. */}
                  <span className="relative flex max-w-[96px]" style={{ marginTop: m.pinned.labelTop - (m.pinned.avatarCenterY + m.pinned.avatar / 2) }}>
                    {c.unread ? (
                      <span aria-hidden="true" data-slot="pinned-unread" className="absolute rounded-full"
                        style={{ right: "100%", marginRight: m.pinned.unreadGap, top: (13 - m.pinned.unread) / 2, width: m.pinned.unread, height: m.pinned.unread, background: "var(--sb-unread)" }} />
                    ) : null}
                    <span data-slot="pinned-name" className="truncate text-[11px] leading-[13px] text-[var(--sb-secondary)]">{c.name}</span>
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      )}

      <ul data-slot="sidebar-rows" role="list" className="absolute m-0 list-none p-0" style={{ left: m.row.left, top: listTop, width: m.row.width }}>
        {rows.map((c, index) => {
          const selected = c.id === selectedId;
          const nextSelected = rows[index + 1]?.id === selectedId;
          // Inactive windows keep the neutral text colors on the gray selection.
          const highlighted = selected && active;
          const secondary = highlighted ? "#d6e4fd" : "var(--sb-secondary)";
          return (
            <li key={c.id} data-slot="sidebar-row" data-selected={selected ? "true" : "false"} className="relative" style={{ height: m.row.height }}>
              <button type="button" aria-current={selected ? "true" : undefined} onClick={() => onSelect?.(c.id)}
                className="mac-sidebar-row absolute inset-0 text-left outline-none focus-visible:ring-2 focus-visible:ring-[#3478f6]/60"
                style={{ background: selected ? (active ? "#3478f6" : "var(--sb-inactive)") : "transparent" } as CSSProperties}>
                {c.unread ? (
                  <>
                    {/* First in the row so the announcement leads: "Unread, Alex Morgan, Yesterday, ...". */}
                    <span className="sr-only">{unreadLabel(c.unread)}. </span>
                    {/* The dot lies inside the selection fill, so it takes the same white the labels take. */}
                    <span aria-hidden="true" data-slot="row-unread" className="absolute rounded-full"
                      style={{ left: m.row.unreadLeft, top: (m.row.height - m.row.unread) / 2, width: m.row.unread, height: m.row.unread, background: highlighted ? "#ffffff" : "var(--sb-unread)" }} />
                  </>
                ) : null}
                {c.members && c.members.length > 1
                  ? <GroupPhoto size={m.row.avatar} members={c.members} name={c.name} className="absolute" style={{ left: m.row.avatarLeft, top: (m.row.height - m.row.avatar) / 2 }} />
                  : <Avatar size={m.row.avatar} initials={c.initials} src={c.photo} name={c.name} className="absolute" style={{ left: m.row.avatarLeft, top: (m.row.height - m.row.avatar) / 2 }} />}
                <span className="absolute flex items-baseline justify-between gap-2" style={{ left: m.row.textLeft, right: m.row.textRight, top: m.row.nameTop }}>
                  <span data-slot="row-name" className="truncate text-[13px] font-semibold leading-[16px]" style={{ color: highlighted ? "#ffffff" : "var(--sb-name)" }}>{c.name}</span>
                  <span data-slot="row-time" className="shrink-0 text-[12px] leading-[15px]" style={{ color: secondary }}>{c.time}</span>
                </span>
                <span data-slot="row-preview" className="absolute line-clamp-2 text-[12px] leading-[15px]"
                  style={{ left: m.row.textLeft, right: m.row.textRight, top: m.row.previewTop, color: secondary }}>
                  {/* A group row names the sender first. Same type and same gray: it is one run of
                      preview text, wrapping and clamping with the rest of it. */}
                  {c.sender && c.members && c.members.length > 1 ? <span data-slot="row-sender">{c.sender}: </span> : null}
                  {c.preview}
                </span>
                {c.muted && (
                  <span className="absolute" style={{ right: m.row.separatorRight, top: m.row.mutedTop }}>
                    <MutedIcon size={m.row.muted} color={highlighted ? "#d6e4fd" : "var(--sb-muted)"} halo={selected ? (active ? "#3478f6" : "var(--sb-inactive)") : "var(--sb-fill)"} />
                  </span>
                )}
              </button>
              {/* Native draws no separator above or below the selected row. Mounting it always and
                  crossing its opacity is what makes a switch read as one move: the pair the selection
                  is leaving fades up while the pair it is arriving at fades down, over the same span
                  the highlight travels. Mounting it conditionally instead pops one in at the departing
                  row and one out at the arriving row on the click, while the highlight is still in
                  flight. A transition, not a keyframe animation, so a seeked frame carries none of it
                  and `document.getAnimations()` still reaches the live one. */}
              {index < rows.length - 1 && (
                <span aria-hidden="true" data-slot="row-separator" className="mac-sidebar-separator absolute bottom-0 h-px bg-[var(--sb-separator)]"
                  style={{ left: m.row.textLeft, right: m.row.separatorRight, opacity: selected || nextSelected ? 0 : 1 }} />
              )}
            </li>
          );
        })}
      </ul>
      {footer && (
        <div data-slot="sidebar-footer" className="absolute overflow-hidden"
          style={{ left: m.panel.left, bottom: m.panel.bottom, width: m.panel.width, height: m.footer.height, borderRadius: `0 0 ${m.panel.radius}px ${m.panel.radius}px` }}>
          <div aria-hidden="true" className="absolute inset-0" style={{ background: "linear-gradient(to bottom, var(--sb-footer-top), var(--sb-footer-bottom))", boxShadow: "inset 0 1px 0 var(--sb-footer-line)" }} />
          <p className="absolute left-0 m-0 w-full text-center text-[10px] leading-[12px] text-[var(--sb-footer-text)]" style={{ top: m.footer.textTop }}>{footer}</p>
        </div>
      )}
    </nav>
  );
}

"use client";

import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { Avatar } from "@/components/imessage/avatar";

/**
 * macOS 26 Messages conversation header. Measured from `references/macos/captures/conversation-pane-dark.png`
 * and `conversation-pane-light.png` (pane x 330–960 of a 960×640 window, 2x), in pane coordinates:
 * - compose button: Ø36 glass circle, left 6, top 8. Native's pure-white light rim occupies device columns
 *   13–14 and 84–85 and device rows 16–17 and 86–87, i.e. a box of x 6.5–43 by y 8–44 (36.5 × 36). Chrome
 *   snaps a box's paint origin to a whole CSS px, so left 6.5 renders at 7 and drags the glyph with it;
 *   left 6 keeps "square.and.pencil" ink at its measured 17.5–33.5 on both axes and leaves the rim 0.5
 *   left of native. Stroke ≈1.3, #dcdcdc; the rim (peak #373739 over a #1b1c1c fill) sits inside the circle.
 * - avatar: Ø40 at (295, 8), so its center is (315, 28), the pane's horizontal center.
 * - name pill: a 52.6 × 27.1 stadium centred (315, 57.95), i.e. y 44.4–71.5, whose top 3.6 pt hide under
 *   the avatar. Its caps are **circular**, not a squircle: tracing the rim of the dark capture at 2x and
 *   least-squares fitting a superellipse to 34 outline points gives exponent s = 2.01 (a circle) at
 *   0.45 device px rms, while `corner-shape: superellipse(1.4)` (s = 2.639) only reaches 0.93 rms. The
 *   same fit on our own render returns s = 2.64 exactly, so the fit does separate the two shapes.
 *   Fill #1b1b1b under a 0.75pt rgba(255,255,255,0.13) rim (peak #383838 over the fill); 13pt bold
 *   #f4f4f4 text ("Ben" ink 601–646 px, cap top 53.5, baseline 63) starting 11 from the pill edge, then a
 *   3.55 × 9.5 chevron (#5b5b5b, stroke 2, ink 329–332.6) that spans exactly the cap height.
 * - video button: 40×36 stadium (radius 18: the cap fits a circle to 0.2 pt), right inset 8, top 8. Its
 *   "video" glyph is a 13.75 × 12.3 rounded rect (radius 2, stroke 1.15) at (11.05, 11.65) in button
 *   coordinates plus a triangle whose right edge sits at x 30.1; total ink 592.5–612.65 × 18.9–32.5, #dcdddf.
 * - the bar itself is 55 tall (not visible in a capture: the glass has no edge) and translucent: the list
 *   scrolls under it, blurred and washed toward the pane color (light: #fcfcfc wash, bubbles show at ≈15%;
 *   dark: rgba(30,30,30) wash) for the top 50 pt, fading back to full content by ~95 pt.
 * Light theme (conversation-pane-light.png): buttons and pill are #fcfcfc/#fdfdfd discs with a 1 px white
 * rim and a soft downward shadow (−15/255 just below, −8 above), text #000000, chevron #b1b1b1, glyphs #262626.
 *
 * **How the pill grows.** 52.6 × 27.1 is the box for "Ben"; everything around the name is fixed, so the
 * pill is that name's advance plus a constant **28.25** (11 before the text, 4.7 after it, the 3.55
 * chevron box, 9 after that). Chrome renders "Ben" at 13px/700 `-apple-system` in a 24.766 box, which
 * puts the whole pill at 53.0 against the measured 52.6, and the extra 0.4 is that one string's advance,
 * the same 1.5-on-a-bubble difference `SPEC.md` records for "Second of two". The height never moves. The
 * pill is centred under the avatar on the pane's centre, so a longer name grows it by half each way and
 * the chevron keeps its 9 to the pill's right edge: the checked render of a 22-character group name
 * comes out 179.2 wide, still centred on 315, with the chevron's box still ending 9 inside it.
 * **Unverified**: where it stops growing. Nothing in a capture bounds it, so `maxWidthInset` is
 * judgement: the pill stops 8 short of the video button, whose 48 (right inset 8 plus width 40) is the
 * wider of the two ends, and the name truncates. That keeps the growth symmetric about the centre.
 *
 * **Groups** (`members`). A group's header draws the same stacked photo the sidebar row does, in the
 * same Ø40 box, and the pill carries the group's name. `groupPhotoRecipes` below is the same measured
 * table `macos-sidebar.tsx` carries, copied rather than imported the way the iOS chrome files each keep
 * their own copy of the avatar's numbers.
 */
export const macHeaderMetrics = {
  height: 55,
  /** Scroll-edge effect: content under the bar is blurred and washed out at full strength for the top
   *  `fadeStart` pt, then eases back to normal by `fadeEnd`. Measured two ways and they agree: over the
   *  empty pane of conversation-pane-light.png (column x 220, clear of the pill's shadow) the wash darkens
   *  white to 252/255 down to y 50.5, then 253 to 70.5, 254 to 89.5, and 255 from 89.5; over the bubbles of
   *  conversation-pane-dark-2.png the wash alpha solves to ≈0.83 at y 32, 0.15 at y 88 and 0.11 at y 92. */
  fadeStart: 50,
  fadeEnd: 96,
  compose: { left: 6, top: 8, size: 36 },
  avatar: { top: 8, size: 40 },
  pill: { top: 44.4, height: 27.1, textTop: 48, paddingLeft: 11, gap: 4.7, paddingRight: 9, fontSize: 13 },
  video: { right: 8, top: 8, width: 40, height: 36 },
  /** Judgement, not measured: how much of each end the pill leaves for the buttons before it truncates. */
  maxWidthInset: 8 + 40 + 8,
};

/**
 * ChatKit's group photo. `CKAvatarButton._avatarView` is a `CNAvatarView` like the conversation list's,
 * and handed more than one contact it lays the circles out through `ContactsUICore.SnowglobeUIView`.
 * Each row is `[x, y, diameter]` on a 44-unit box, back to front, scaled by `size / 44`; see
 * `macos-sidebar.tsx` for how they were read off the framework and what is deliberately not drawn.
 */
export const groupPhotoRecipes: readonly (readonly (readonly [number, number, number])[])[] = [
  [[0, 0, 44]],
  [[4.75, 4.75, 24], [23.75, 23.75, 14]],
  [[5.25, 5.25, 21], [24.75, 17.75, 16], [12.5, 27.25, 13]],
  [[5.25, 5.25, 21], [24.75, 17.75, 16], [12.5, 27.25, 13], [27, 6.75, 10]],
  [[5.25, 5.25, 21], [24.75, 17.75, 16], [12.5, 27.25, 13], [27, 6.75, 10], [4.75, 25.5, 7]],
  [[5.25, 5.25, 21], [24.75, 17.75, 16], [12.5, 27.25, 13], [27, 6.75, 10], [4.75, 25.5, 7], [23.25, 3.25, 5]],
  [[5.25, 5.25, 21], [24.25, 20.25, 15], [27.25, 8.25, 11], [6.5, 26.75, 10], [19.25, 33.25, 7.5], [17.75, 26.75, 5.5], [24, 3.75, 5]],
];

export type MacHeaderMember = { initials: string; name?: string; photo?: string };

export type MacHeaderProps = Omit<ComponentProps<"header">, "children"> & {
  name: string;
  initials?: string;
  /** Photo URL, or a custom avatar node. */
  photo?: string;
  avatar?: ReactNode;
  /**
   * Group conversation: its participants, drawn as the stacked group photo in place of one avatar.
   * Two or more entries make it a group; the stack shows the first seven. Ignored when `avatar` is set.
   */
  members?: MacHeaderMember[];
  onCompose?: () => void;
  onVideoCall?: () => void;
  /** Clicking the name pill opens the conversation details. */
  onOpenDetails?: () => void;
};

function GroupPhoto({ size, members, name }: { size: number; members: MacHeaderMember[]; name: string }) {
  const people = members.slice(0, groupPhotoRecipes.length);
  const recipe = groupPhotoRecipes[people.length - 1] ?? groupPhotoRecipes[0];
  const unit = size / 44;
  return (
    <span data-slot="group-photo" role="img" aria-label={name} className="relative block shrink-0" style={{ width: size, height: size }}>
      {people.map((person, index) => {
        const [x, y, diameter] = recipe[index];
        return (
          <Avatar key={index} aria-hidden="true" size={diameter * unit} initials={person.initials} src={person.photo} name={person.name}
            className="absolute" style={{ left: x * unit, top: y * unit }} />
        );
      })}
    </span>
  );
}

