export type ContextMenuProps = {
  variant?: "ios" | "macos";
  items: ContextMenuItem[];
  onAction?: (id: string) => void;
  onClose?: () => void;
  /** Rendered above the items (macOS: the two tapback rows). */
  header?: ReactNode;
  /**
   * iOS: a color painted at the top of the menu, fading to the neutral fill. Native gets this from the
   * bubble showing through the glass; pass one when the menu floats over a plain background.
   */
  tint?: string;
  /**
   * iOS: a faint wash of the bubble color over the whole menu (native glass carries a little of the
   * bubble's color far below the blurred edge). Pass the bubble's fill color.
   */
  wash?: string;
  /** macOS: menu width; iOS is fixed at 250. */
  width?: number;
  autoFocus?: boolean;
  /** Flip to false to play the dismissal; `onExited` fires when it is over. */
  open?: boolean;
  onExited?: () => void;
  className?: string;
  style?: CSSProperties;
  "aria-label"?: string;
};

export function ContextMenu({ variant = "ios", items, onAction, onClose, header, tint, wash, width, open = true, onExited, autoFocus = false, className, style, "aria-label": ariaLabel = "Message actions" }: ContextMenuProps) {
  const root = useRef<HTMLDivElement>(null);
  // Native menus fade and settle back rather than vanishing; keep the element mounted for it.
  const exited = useRef(onExited);
  useEffect(() => { exited.current = onExited; }, [onExited]);
  useEffect(() => {
    if (open) return;
    const element = root.current;
    const reduced = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;
    if (!element || reduced) { exited.current?.(); return; }
    const animation = element.animate(
      [{ opacity: 1, transform: "scale(1)" }, { opacity: 0, transform: "scale(0.94)" }],
      { duration: 120, easing: "cubic-bezier(0.4, 0, 1, 1)", fill: "both" },
    );
    animation.finished.then(() => exited.current?.()).catch(() => {});
    return () => { try { animation.cancel(); } catch { /* already gone */ } };
  }, [open]);
  const m = contextMenuMetrics[variant];

  // Opened for the keyboard: focus the first item, and hand focus back to whatever opened the menu
  // when it goes. A layout effect, so the cleanup runs while the menu is still in the DOM.
  useLayoutEffect(() => {
    if (!autoFocus) return;
    const menu = root.current;
    const opener = document.activeElement as HTMLElement | null;
    // The first item of any kind, so a menu whose header is the Tapback row starts on a tapback.
    menu?.querySelector<HTMLButtonElement>('[role="menuitem"]:not([aria-disabled="true"]), [role="menuitemradio"]:not([aria-disabled="true"]), [role="menuitemcheckbox"]:not([aria-disabled="true"])')?.focus({ preventScroll: true });
    return () => {
      const active = document.activeElement;
      const inside = active instanceof Node && menu?.contains(active);
      if (inside && opener?.isConnected) opener.focus({ preventScroll: true });
    };
  }, [autoFocus]);

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === "Escape") { event.preventDefault(); onClose?.(); return; }
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    // The macOS menu carries the Tapback bar in its header, and that bar owns its own arrow, Home and
    // End behaviour. Let a key that started inside it through instead of moving the menu's focus.
    if ((event.target as HTMLElement | null)?.closest?.('[data-slot="tapback-bar"]')) return;
    const buttons = Array.from(root.current?.querySelectorAll<HTMLButtonElement>("[role=menuitem]:not([aria-disabled=true])") ?? []);
    if (!buttons.length) return;
    event.preventDefault();
    const i = buttons.indexOf(document.activeElement as HTMLButtonElement);
    const next = event.key === "Home" ? 0 : event.key === "End" ? buttons.length - 1 : event.key === "ArrowDown" ? (i + 1) % buttons.length : (i - 1 + buttons.length) % buttons.length;
    buttons[next]?.focus();
  }

  // Half of a separator's 11pt block, i.e. the bare gap the row above or below it has to fill.
  const separatorGap = (contextMenuMetrics.macos.separatorBlock - 1) / 2;

  // The highlight is a child rather than the button's own background so it can sit inset the way
  // AppKit draws it. Driving its opacity from CSS keeps it out of React state on every pointer move.
  const highlightStyle = `[data-slot="menu-item"] > [data-slot="menu-highlight"]{opacity:0;transition:opacity 60ms linear}
[data-slot="menu-item"]:hover > [data-slot="menu-highlight"],[data-slot="menu-item"]:focus-visible > [data-slot="menu-highlight"]{opacity:1}
[data-slot="menu-item"][aria-disabled="true"] > [data-slot="menu-highlight"]{opacity:0}`;

  const rows = items.map((item, index) => {
    if ("separator" in item) {
      return <div key={`sep-${index}`} role="separator" data-slot="menu-separator" style={variant === "macos"
        ? { height: 1, marginBlock: separatorGap, marginInline: 16, background: "var(--im-menu-separator, #dfe0e2)" }
        : { height: 0.5, background: "var(--im-menu-separator, rgba(0,0,0,0.12))" }} />;
    }
    const gapTop = 0;
    const gapBottom = 0;
    return (
      <button key={item.id} type="button" role="menuitem" aria-disabled={item.disabled || undefined} tabIndex={item.disabled ? -1 : undefined} data-slot="menu-item" data-id={item.id} onClick={() => !item.disabled && onAction?.(item.id)}
        className={cn("flex w-full cursor-default items-center border-0 bg-transparent text-left outline-none",
          item.destructive ? "text-[var(--im-menu-destructive,#ff3b30)]" : "text-[var(--im-menu-text,#000)]",
          !item.disabled && variant === "macos" && "hover:text-white focus-visible:text-white")}
        style={{ height: m.row + gapTop + gapBottom, boxSizing: "border-box", paddingTop: gapTop || undefined, paddingBottom: gapBottom || undefined, marginTop: gapTop ? -gapTop : undefined, marginBottom: gapBottom ? -gapBottom : undefined,
          paddingLeft: m.textX, position: "relative", fontFamily: fontStack, fontSize: m.fontSize, lineHeight: `${m.row}px`, letterSpacing: 0, opacity: item.disabled ? 0.4 : 1, width: "100%" }}>
        {/* The highlight is inset and rounded on both platforms, never a full-bleed line. iOS uses a
            neutral wash inside the menu's own padding; macOS uses the accent. */}
        <span aria-hidden="true" data-slot="menu-highlight" className="pointer-events-none absolute"
          style={variant === "macos"
            ? { left: 4, right: 4, top: 0, bottom: 0, borderRadius: 6, background: "#3478f6" }
            : { left: m.highlightInset, right: m.highlightInset, top: m.highlightInsetY, bottom: m.highlightInsetY, borderRadius: m.highlightRadius, background: "var(--im-menu-highlight, rgba(0,0,0,0.05))" }} />
        <span aria-hidden="true" data-slot="menu-icon" style={{ position: "absolute", left: m.iconCenter - m.iconBox / 2, top: gapTop, bottom: gapBottom, width: m.iconBox, display: "flex", alignItems: "center", justifyContent: "center" }}>
          {typeof item.icon === "string" ? <MenuIcon name={item.icon as MenuIconName} size={variant === "ios" ? 22 : 16} /> : item.icon}
        </span>
        <span data-slot="menu-label" style={{ whiteSpace: "nowrap", position: "relative" }}>{item.label}</span>
      </button>
    );
  });

  if (variant === "macos") {
    return (
      <div ref={root} role="menu" aria-label={ariaLabel} data-slot="context-menu" data-variant="macos" className={cn("select-none", className)} onKeyDown={onKeyDown}
        style={{ width: width ?? m.width, boxSizing: "border-box", borderRadius: m.radius, overflow: "hidden", position: "relative", paddingTop: m.padding, paddingBottom: contextMenuMetrics.macos.paddingBottom, fontFamily: fontStack, color: "var(--im-menu-text, #242526)",
          background: "var(--im-menu-bg, rgba(247,248,251,0.92))", backdropFilter: "blur(30px) saturate(1.6)", WebkitBackdropFilter: "blur(30px) saturate(1.6)",
          boxShadow: "0 0 0 0.5px var(--im-menu-border, #b1b1b1), 0 8px 24px rgba(0,0,0,0.18), 0 1px 3px rgba(0,0,0,0.12)", ...style }}>
        <style>{highlightStyle}</style>
        {header}
        {rows}
        {/* The bright inner rim rides above the rows so a highlight cannot erase it. */}
        <div aria-hidden="true" data-slot="menu-rim" style={{ position: "absolute", inset: 0, borderRadius: "inherit", pointerEvents: "none", boxShadow: "inset 0 0 0 0.5px var(--im-menu-rim, rgba(255,255,255,0.7))" }} />
      </div>
    );
  }

  const background = tint
    ? `linear-gradient(to bottom, ${tint} 0px, ${tint} 30px, color-mix(in srgb, ${tint} 45%, var(--im-menu-bg, #edeff1)) 47px, color-mix(in srgb, ${tint} 22%, var(--im-menu-bg, #edeff1)) 64px, color-mix(in srgb, ${tint} 8%, var(--im-menu-bg, #edeff1)) 114px, var(--im-menu-bg, #edeff1))`
    : "var(--im-menu-glass, rgba(229,229,231,0.69))";
  const height = iosContextMenuHeight(items);
  const outline = continuousRoundedRectPath(m.width, height, m.radius);
  const shape = `path("${outline}")`;
  // A `backdrop-filter` is clipped to its element's border box and border radius, never to its
  // `clip-path`: the glass's brightened backdrop therefore painted a hard square corner outside the
  // menu's continuous one. Measured on the long-press scene at 3x, 1 device px inside the left edge
  // and 20 below the top: #ffffff against the #cccbd0 the dimmed list continues past the corner, and
  // #d9d7dd against #c7c6cb at the bottom right. A mask of the same path IS respected, so the glass
  // carries the shape twice: the clip for its fill, the mask for the backdrop it filters.
  const maskShape = `url("data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="${m.width}" height="${height}"><path d="${outline}" fill="#000"/></svg>`)}")`;
  return (
    <div ref={root} role="menu" aria-label={ariaLabel} data-slot="context-menu" data-variant="ios" className={cn("select-none", className)} onKeyDown={onKeyDown}
      style={{ width: m.width, height, boxSizing: "border-box", fontFamily: fontStack, position: "relative", ...style }}>
      <style>{highlightStyle}</style>
      <div aria-hidden="true" data-slot="menu-shadow" style={{ position: "absolute", inset: 0, transform: "translateY(7px)", filter: "blur(11px)", pointerEvents: "none" }}>
        <div style={{ position: "absolute", inset: 0, clipPath: shape, background: "var(--im-menu-shadow, rgba(0,0,0,0.16))" }} />
      </div>
      <div aria-hidden="true" data-slot="menu-glass" style={{ position: "absolute", inset: 0, clipPath: shape, background,
        WebkitMaskImage: maskShape, maskImage: maskShape, WebkitMaskRepeat: "no-repeat", maskRepeat: "no-repeat",
        backdropFilter: "var(--im-menu-glass-filter, blur(9px) brightness(1.32) saturate(1.35))", WebkitBackdropFilter: "var(--im-menu-glass-filter, blur(9px) brightness(1.32) saturate(1.35))" }} />
      <svg aria-hidden="true" data-slot="menu-rim" width={m.width} height={height} viewBox={`0 0 ${m.width} ${height}`} style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
        <path d={outline} fill="none" stroke="var(--im-glass-rim, rgba(255,255,255,0.55))" strokeWidth={1} />
      </svg>
      {wash && <div aria-hidden="true" data-slot="menu-wash" style={{ position: "absolute", inset: 0, pointerEvents: "none", clipPath: shape, background: `linear-gradient(to bottom, transparent 34px, color-mix(in srgb, ${wash} 4.5%, transparent) 52px, color-mix(in srgb, ${wash} 2.5%, transparent) 60%, color-mix(in srgb, ${wash} 1%, transparent))` }} />}
      {/* A pressed or focused row paints edge to edge, so it has to be cut by the menu's own corner:
          clip the rows to the same continuous shape the glass uses instead of letting them square it off. */}
      <div style={{ position: "absolute", inset: 0, boxSizing: "border-box", paddingBlock: m.padding, clipPath: shape }}>{header}{rows}</div>
    </div>
  );
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, type CSSProperties, type KeyboardEvent as ReactKeyboardEvent, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { fontStack, type Direction, type Service } from "@/components/imessage/tokens";
import { BalloonTrail, TapbackGlyph, tapbackLabels, type TapbackType } from "@/components/imessage/tapback";
import { TapbackBar, tapbackBarMetrics, type TapbackSelection } from "@/components/imessage/tapback-bar";
import { ContextMenu, contextMenuMetrics, iosContextMenuHeight, iosMessageMenu, type ContextMenuItem } from "@/components/imessage/context-menu";

/**
 * The iOS long-press overlay. Layout measured from `references/ios/captures/longpress-*.png`:
 * the pressed bubble is lifted about its trailing edge by a uniform scale that widens it by 26.07,
 * capped at 1.15. Three pressed bubbles fix that, each measured against its own unpressed copy in
 * `conv3-light.png`: "Ok" 49.62×40.08 → 57.15×45.96 hits the cap, while the wider two-liners take the
 * same 26: "Every detail…" 250.96×60.24 → 277.00×66.43 (1.1037 wide, 1.1027 tall) and "Aaaa…"
 * 280.63×60.24 → 306.74×65.82 (1.0930 / 1.0926). A height-driven rule would miss "Aaaa…" by 2 pt.
 * Each grows about its own centre, which rises 0.18 (0.135 for "Ok", 0.222 for "Aaaa…", and the "Ok"
 * glyph ink agrees at 0.17). The text rides the scale: that glyph ink also grows 1.148 × 1.132, so
 * `textScale` stays 1. The tapback pill sits 5 above the bubble (measured 5.09) and stretches from
 * the screen margin (10.83) to the bubble's trailing edge, the
 * emoji-picker bubble hangs from the pill with its centre 28 beside the bubble, and the 250-wide menu
 * starts 16.1 below the bubble's own bottom edge, tail included (the 6.8 hang scales with the lift).
 * Six frames give 16.07/16.11/16.07/16.09/16.11/16.2, reading each menu's top off its first row's
 * "Copy" ink rather than its washed-out glass edge. If the menu would pass 42 above the frame's
 * bottom (three frames clamp there, all with their menu top at 644.02) or the bar rise above 60, the
 * whole group shifts; incoming bubbles mirror everything (bar 16→391.17, picker to the right, menu
 * left-aligned). `topInset` is the one number here with no capture behind it: nothing in the nine
 * long-press frames pushes the bar high enough to clamp.
 *
 * Motion (60 fps frames in references/ios/motion/): dim from 0 ms; bubble lift + menu unfolding from
 * the bubble's corner over ≈130 ms; the pill expands from the picker circle over ≈200 ms; glyphs fade
 * in left to right with a 17 ms stagger. `progress` (0..1) scrubs the whole timeline.
 */
export const messageActionsTiming = { total: 600, exit: 220, dim: 150, lift: 130, menu: 130, picker: [60, 200], bar: [100, 320], glyphStart: 250, glyphStagger: 17, glyphDuration: 120 } as const;

/**
 * The dim behind the overlay. It covers the whole screen: the status bar and the nav bar go under it
 * with the list, unblurred and not re-drawn above it. Fitted, not guessed — `longpress-ok-light.png`
 * is `conv3-light.png` with one message pressed, so one capture over the other measures the dim
 * directly. Outside the overlay's own furniture (device rows 1356-2349) and the status-bar clock (the
 * two captures are 24 minutes apart) every pixel of that frame is `capture = screen·0.79 +
 * (22,21,42)·0.21`, residual 0.14/255 mean and 0.9 max over the nav bar's full 0-255 range. Three more
 * pairs agree: `incoming-light.png` -> `longpress-incoming-light.png` and `conv2-dark.png` ->
 * `longpress-last-bubble-dark.png` come back at 0.001/255 mean error — exact after rounding — and the
 * same value carries `longpress-two-line-light.png`. It is one dim in both themes, and one alpha over
 * every layer: fitting the bands of the light pair separately gives 0.2103/0.2092/0.2130 over the nav
 * bar, 0.2105/0.2054/0.2129 over the list and 0.2133/0.2118/0.2172 over the composer.
 *
 * The (22,18,44) this used to carry renders white as (206,205,210) where every light capture reads
 * #ceced2 = (206,206,210): the green channel was a level dark everywhere the dim fell.
 *
 * Chrome cannot land both ends of this at once, and the last level is its rounding, not the value.
 * It composites an overlay as `round(src·(1-a₈)) + round(tint·a₈)` with the alpha quantised to
 * 54/255, so the tint's contribution is one rounded triple: over black it is (5,4,9), which fixes
 * white at 201+(5,4,9) = (206,205,210). Native rounds the sum instead and gets (5,4,9) over black and
 * (206,206,210) over white from the same value. (23,22,43) buys the light end (measured over the lab's
 * nav band: interior G +0.2 instead of -0.8) and loses the dark one by the same level (+1.0 instead of
 * 0.0), so this keeps the measured number and wears one level of green over bright grounds.
 *
 * `--im-dim` still wins wherever a palette sets it, and `tapback.tsx` sets it for both themes; it now
 * carries this same value. Two fallbacks elsewhere are still the old one and want correcting:
 * `message-reply.tsx` (the reply-thread dim) and `tapback-details.tsx` (the details scrim).
 *
 * KNOWN WRONG, and not fixable from here: this dim reaches the Dynamic Island, and nothing may. The
 * island is a hardware cutout the OS composites above the app, so it reads #000000 in every capture
 * that has an overlay over it — `longpress-*`, `newmsg-light.png`, `plus-menu-open-light.png`,
 * `details-light.png`, `photo-picker-light.png` — while the status bar around it dims with everything
 * else (#ceced2 under this dim, #cccccc under the sheet's). Under our dim it goes to (5,4,9), a flat
 * +6 over the island's 125.33×36.67 pt, which is 6.4% of the 0 0 402 168 band. The fix belongs where
 * the island is drawn (`ios-status-bar.tsx` plus the app's z-order), not in one overlay: every dim in
 * the app has the same bug.
 */
export const messageActionsDim = "var(--im-dim, rgba(22,21,42,0.21))";

export const messageActionsMetrics = {
  /** The lift widens the bubble by this much, up to `liftMaxScale`; height follows the same factor. */
  liftWidth: 26.07, liftMaxScale: 1.15, liftY: -0.18, barGap: 5, menuGap: 16.1, tailHang: 6.8, pickerBeside: 28, topInset: 60, bottomInset: 42,
} as const;

export type Rect = { x: number; y: number; width: number; height: number };

/** Takes the bubble's unscaled body: the lift is driven by its width, not its height. */
export function liftScale({ width }: Pick<Rect, "width">): number {
  return Math.min(messageActionsMetrics.liftMaxScale, 1 + messageActionsMetrics.liftWidth / width);
}

export type MessageActionsProps = {
  /** The pressed bubble body's rect (unscaled), in the frame's coordinates. */
  rect: Rect;
  frame: { width: number; height: number };
  direction?: Direction;
  service?: Service;
  /** Whether the pressed bubble has a tail (the menu clears it). */
  tail?: boolean;
  /** The bubble to lift; rendered at `rect` inside the overlay. */
  children: ReactNode;
  items?: ContextMenuItem[];
  selected?: TapbackSelection;
  /**
   * The colour the menu's glass picks up from the message above it. Defaults to that message's own
   * bubble fill. Pass null for a message that has no bubble to give it: an emoji-only message is a bare
   * glyph, and a photo, a link card and a file card each carry their own surface instead.
   *
   * UNVERIFIED for those kinds. Every long-press capture in `references/ios/` is of a text bubble, so
   * what native tints the glass with when nothing coloured sits behind it is not measured; plain glass
   * is the conservative reading of "the bubble behind it seen through the glass".
   */
  wash?: string | null;
  recent?: string[];
  /** Who reacted, for the details popover shown when re-opening a message that already has your tapback. */
  details?: { initials: string; name?: string };
  onSelect?: (selection: TapbackSelection) => void;
  onAction?: (id: string) => void;
  onPickEmoji?: () => void;
  onClose?: () => void;
  /** Scrub position 0..1 of the entrance; omit to play it. */
  progress?: number;
  /** Flip to false to play the dismissal; `onExited` fires when it is over. */
  open?: boolean;
  onExited?: () => void;
  /** Move focus into the tapback bar on open (default). */
  autoFocus?: boolean;
  /** Override the lift scale (default: `liftScale(rect)`, uniform). */
  scale?: number | [number, number];
  /** Counter-scale for the text inside the lifted bubble. Native scales it with the bubble, so 1. */
  textScale?: number;
  className?: string;
  style?: CSSProperties;
};

export function layoutMessageActions({ rect, frame, direction, scale, items, tail = false }: { rect: Rect; frame: { width: number; height: number }; direction: Direction; scale: [number, number]; items: ContextMenuItem[]; tail?: boolean }) {
  const m = messageActionsMetrics;
  const outgoing = direction === "outgoing";
  const [sx, sy] = scale;
  // The lift scales the bubble about its trailing edge and nudges it up by `liftY` (0.18, not the
  // 0.55 this once carried; see the header for the three centres that fix it).
  const lifted = { width: rect.width * sx, height: rect.height * sy, left: 0, top: rect.y + rect.height / 2 - (rect.height * sy) / 2 + m.liftY };
  lifted.left = outgoing ? rect.x + rect.width - lifted.width : rect.x;
  const barH = tapbackBarMetrics.ios.height;
  const bar = { left: outgoing ? tapbackBarMetrics.ios.edgeInset : rect.x, right: outgoing ? rect.x + rect.width : frame.width - tapbackBarMetrics.ios.edgeInset, top: lifted.top - m.barGap - barH, height: barH };
  const cm = contextMenuMetrics.ios;
  const menuHeight = iosContextMenuHeight(items);
  // The menu clears the bubble's own bottom edge, so a tail pushes it down by its scaled hang.
  const menu = { left: outgoing ? rect.x + rect.width - cm.width : rect.x, top: lifted.top + lifted.height + m.menuGap + (tail ? m.tailHang * sy : 0), height: menuHeight };
  // Keep the menu above the composer and the bar below the nav bar; the whole group moves together.
  let shift = 0;
  const menuBottom = menu.top + menuHeight;
  if (menuBottom > frame.height - m.bottomInset) shift = frame.height - m.bottomInset - menuBottom;
  if (bar.top + shift < m.topInset) shift = m.topInset - bar.top;
  const pickerCenterX = outgoing ? lifted.left - m.pickerBeside : lifted.left + lifted.width + m.pickerBeside;
  return { outgoing, lifted, bar, menu, shift, bubbleTranslate: shift + m.liftY, pickerX: pickerCenterX - bar.left };
}

export function MessageActions({ rect, frame, direction = "outgoing", service = "imessage", tail = false, children, items = iosMessageMenu, selected, wash, recent, details, onSelect, onAction, onPickEmoji, onClose, progress, open = true, onExited, autoFocus = true, scale: scaleProp, textScale: textScaleProp, className, style }: MessageActionsProps) {
  const root = useRef<HTMLDivElement>(null);
  const scrub = useRef<((time: number | null) => void) | null>(null);
  const id = useId().replace(/:/g, "");
  const s = scaleProp ?? liftScale(rect);
  const scale: [number, number] = typeof s === "number" ? [s, s] : s;
  const textScale = textScaleProp ?? 1;
  const L = layoutMessageActions({ rect, frame, direction, scale, items, tail });
  const side = L.outgoing ? "left" : "right";

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); onClose?.(); } };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [onClose]);

  // The overlay is modal, so the message that was pressed gets focus back when the overlay gives it
  // up (`autoFocus` goes false as the dismissal starts, while the overlay is still mounted).
  // A passive effect, not a layout one: React restores the pre-commit focus at the end of the commit
  // phase, so a layout effect's focus() is undone before the frame is painted.
  const restoreTo = useRef<HTMLElement | null>(null);
  // Captured in a layout effect (before the bar's own autoFocus, which is a passive effect in a
  // child) and never overwritten with something inside the overlay, so a re-run cannot record the
  // glyph the bar just focused as the thing to go back to.
  useLayoutEffect(() => {
    if (!autoFocus) return;
    const active = document.activeElement;
    if (!(active instanceof Node && root.current?.contains(active))) restoreTo.current = active as HTMLElement | null;
  }, [autoFocus]);
  useEffect(() => {
    if (!autoFocus) return;
    const overlay = root.current;
    return () => {
      const previous = restoreTo.current;
      const active = document.activeElement;
      const inside = active instanceof Node && overlay?.contains(active);
      if (inside && previous?.isConnected) previous.focus({ preventScroll: true });
    };
  }, [autoFocus]);

  /** Tab stays inside the overlay while it is open, the way a modal sheet does. */
  function onRootKeyDown(event: ReactKeyboardEvent<HTMLDivElement>) {
    if (event.key !== "Tab") return;
    const el = root.current;
    if (!el) return;
    const stops = Array.from(el.querySelectorAll<HTMLElement>('button:not([disabled]), [tabindex]:not([tabindex="-1"])')).filter(node => node.getClientRects().length > 0);
    if (!stops.length) return;
    const first = stops[0], last = stops[stops.length - 1];
    const active = document.activeElement;
    const inside = active instanceof Node && el.contains(active);
    if (event.shiftKey ? active === first || !inside : active === last || !inside) {
      event.preventDefault();
      (event.shiftKey ? last : first).focus();
    }
  }

  // Build the entrance timeline once with the Web Animations API so it can be played or scrubbed.
  useLayoutEffect(() => {
    const el = root.current;
    if (!el) return;
    const t = messageActionsTiming;
    const q = <T extends Element>(slot: string) => Array.from(el.querySelectorAll<T>(`[data-slot="${slot}"]`));
    const one = (slot: string) => el.querySelector<HTMLElement>(`[data-slot="${slot}"]`);
    const list: Animation[] = [];
    const add = (target: Element | null, keyframes: Keyframe[], options: KeyframeAnimationOptions) => { if (target) list.push(target.animate(keyframes, { fill: "both", ...options })); };
    const spring = "cubic-bezier(0.2, 0.95, 0.3, 1)";
    add(one("backdrop"), [{ opacity: 0 }, { opacity: 1 }], { duration: t.dim, easing: "ease-out" });
    add(one("lifted-bubble"), [{ transform: "translateY(0px) scale(1, 1)" }, { transform: `translateY(${L.bubbleTranslate}px) scale(${scale[0]}, ${scale[1]})` }], { duration: t.lift, easing: spring });
    // The counter-scale rides a registered custom property so a consumer can animate it; at the native
    // default of 1 this keyframe is a no-op and the text simply scales with the bubble.
    try { CSS.registerProperty({ name: "--im-lift-text", syntax: "<number>", inherits: true, initialValue: "1" }); } catch { /* already registered */ }
    add(one("lifted-bubble"), [{ "--im-lift-text": "1" } as Keyframe, { "--im-lift-text": String(textScale) } as Keyframe], { duration: t.lift, easing: spring });
    add(one("context-menu"), [{ opacity: 0, transform: "scale(0.6)" }, { opacity: 1, transform: "scale(1)" }], { duration: t.menu, easing: spring });
    add(one("emoji-picker-bubble"), [{ opacity: 0, transform: "scale(0.35)" }, { opacity: 1, transform: "scale(1)" }], { duration: t.picker[1] - t.picker[0], delay: t.picker[0], easing: spring });
    const pill = one("tapback-pill");
    if (pill) {
      const h = L.bar.height;
      const pickerLeft = L.pickerX - 22, pickerRight = L.bar.right - L.bar.left - (L.pickerX + 22);
      // The pill grows out of the picker circle, so it starts clipped to that circle on either side.
      const start = `inset(${(h - 44) / 2}px ${Math.max(0, pickerRight)}px ${(h - 44) / 2}px ${Math.max(0, pickerLeft)}px round 22px)`;
      add(pill, [{ clipPath: start, opacity: 0.6 }, { clipPath: `inset(0px 0px 0px 0px round ${h / 2}px)`, opacity: 1 }], { duration: t.bar[1] - t.bar[0], delay: t.bar[0], easing: spring });
    }
    q<HTMLElement>("tapback-option").forEach((glyph, i) => add(glyph, [{ opacity: 0, transform: "translateX(6px) scale(0.8)" }, { opacity: 1, transform: "translateX(0) scale(1)" }], { duration: t.glyphDuration, delay: t.glyphStart + i * t.glyphStagger, easing: "ease-out" }));
    add(one("tapback-details"), [{ opacity: 0, transform: "translateY(-8px) scale(0.9)" }, { opacity: 1, transform: "translateY(0) scale(1)" }], { duration: 200, delay: 200, easing: spring });
    // A held (paused or filling) animation on the menu promotes it to its own compositing layer, which
    // cuts the backdrop its glass filters and leaves the panel flat and dark. Every layer's resting
    // style already is the end state, so drop the animations once the timeline is over.
    const settle = (a: Animation) => { try { a.cancel(); } catch { /* already gone */ } };
    scrub.current = time => {
      for (const a of list) {
        if (time === null) { a.play(); a.finished.then(() => settle(a)).catch(() => {}); }
        else if (time >= t.total) settle(a);
        else { a.pause(); a.currentTime = time; }
      }
    };
    return () => { list.forEach(a => a.cancel()); scrub.current = null; };
    // The timeline depends on the final layout only; a new layout remounts via `key` upstream.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const reduced = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (progress !== undefined) scrub.current?.(Math.min(1, Math.max(0, progress)) * messageActionsTiming.total);
    else if (reduced) scrub.current?.(messageActionsTiming.total);
    else scrub.current?.(null);
  }, [progress]);

  // Dismissal. The entrance animations are cancelled once they settle (so the glass keeps its
  // backdrop), so this is a fresh, shorter timeline that folds everything back toward the bubble.
  const exited = useRef(onExited);
  useEffect(() => { exited.current = onExited; }, [onExited]);
  useEffect(() => {
    if (open) return;
    const overlay = root.current;
    const reduced = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (!overlay || reduced) { exited.current?.(); return; }
    const pick = (slot: string) => Array.from(overlay.querySelectorAll<HTMLElement>(`[data-slot="${slot}"]`));
    const shrink = [...pick("context-menu"), ...pick("tapback-pill"), ...pick("emoji-picker-bubble"), ...pick("tapback-details")];
    const D = messageActionsTiming.exit;
    const timing: KeyframeAnimationOptions = { duration: D, easing: "cubic-bezier(0.4, 0, 1, 1)", fill: "both" };
    const running = [
      ...pick("backdrop").map(el => el.animate([{ opacity: 1 }, { opacity: 0 }], timing)),
      ...shrink.map(el => el.animate([{ opacity: 1, transform: "scale(1)" }, { opacity: 0, transform: "scale(0.72)" }], timing)),
      ...pick("lifted-bubble").map(el => el.animate([{ transform: getComputedStyle(el).transform }, { transform: "none" }], { ...timing, easing: "cubic-bezier(0.3, 0, 0.2, 1)" })),
    ];
    let done = false;
    const finish = () => { if (!done) { done = true; exited.current?.(); } };
    if (!running.length) { finish(); return; }
    Promise.allSettled(running.map(a => a.finished)).then(finish);
    return () => running.forEach(a => { try { a.cancel(); } catch { /* already gone */ } });
  }, [open]);

  return (
    // z-20 clears the reaction balloons the list paints at z-10, so they dim and blur with everything else.
    <div ref={root} data-slot="message-actions" data-direction={direction} role="dialog" aria-modal="true" aria-label="Message options"
      onKeyDown={onRootKeyDown} className={cn("absolute inset-0 z-20 select-none outline-none", className)} style={{ fontFamily: fontStack, ...style }}>
      {/* The lift is a transform, so the bubble's own shrink-to-fit measures its line boxes in scaled
          screen pixels and would set a frame that is `scale` too wide. Pin it to the measured body. */}
      <style>{`[data-actions="${id}"] [data-slot="bubble"] > span:last-child { display: inline-block; transform-origin: 50% 50%; transform: scale(var(--im-lift-text, 1)); }
[data-actions="${id}"] [data-slot="bubble-frame"] { max-width: ${rect.width}px !important; }`}</style>
      <div data-slot="backdrop" aria-hidden="true" onClick={onClose} style={{ position: "absolute", inset: 0, background: messageActionsDim }} />
      {/* The lifted bubble casts its own shadow onto the dimmed list. Fitted beside the "Ok" bubble in
          `longpress-ok-light.png`, where nothing else contributes: the dim (#ceced2 over white) reads
          194 at 0.7 pt out, 196 at 4, 198 at 7.3, 201 at 12.3 and 202 at 14, and 188 just under the body.
          One tight layer carries the edge and one wide layer the falloff; both reproduce within 1/255.
          `drop-shadow` rather than `box-shadow` so the tail and the reaction balloon cast it too. */}
      <div data-slot="lifted-bubble" data-actions={id} data-service={service} style={{ position: "absolute", left: rect.x, top: rect.y, width: rect.width, height: rect.height, transformOrigin: L.outgoing ? "100% 50%" : "0% 50%", transform: `translateY(${L.bubbleTranslate}px) scale(${scale[0]}, ${scale[1]})`, filter: "drop-shadow(0 2px 8px rgba(0,0,0,0.07)) drop-shadow(0 6px 24px rgba(0,0,0,0.13))", "--im-lift-text": String(textScale) } as CSSProperties}>
        {children}
      </div>
      <TapbackBar layout="ios" selected={selected} recent={recent} onSelect={onSelect} onPickEmoji={onPickEmoji} autoFocus={autoFocus}
        pickerX={L.pickerX} pickerSide={side} width={L.bar.right - L.bar.left}
        style={{ position: "absolute", left: L.bar.left, top: L.bar.top + L.shift }} />
      <ContextMenu variant="ios" items={items} onAction={onAction}
        wash={wash === undefined ? (service === "sms" ? "var(--im-green-bottom, #31c355)" : L.outgoing ? "var(--im-blue-bottom, #3583f6)" : "var(--im-gray-bottom, #e9e9eb)") : wash ?? undefined}
        style={{ position: "absolute", left: L.menu.left, top: L.menu.top + L.shift, transformOrigin: L.outgoing ? "100% 0%" : "0% 0%" }} />
      {selected && details && <TapbackDetails selection={selected} initials={details.initials} name={details.name} style={{ position: "absolute", left: frame.width / 2 - tapbackDetailsMetrics.width / 2, top: tapbackDetailsMetrics.top }} />}
    </div>
  );
}

/**
 * The "tapback details" popover shown when a message that already carries your reaction is re-opened.
 * Measured on `longpress-ok-selected-light.png` (3x): a 124×121 glass card with continuous corners,
 * centred on the screen at y 66.26. Inside, a Ø49.76 white balloon whose trail points straight DOWN
 * (Ø11.13 at +27.34 and Ø5.18 at +38.0 from its centre) sits with its centre 33.57 below the card's
 * top, and the reactor's Ø30.66 avatar is centred 93.6 below it. The glyph ink is 26.3 wide.
 */
export const tapbackDetailsMetrics = {
  width: 124, height: 121, radius: 30, top: 66.26,
  balloon: { main: 49.76, medium: 11.13, small: 5.18, mediumOffset: [0, 27.34] as [number, number], smallOffset: [0, 38.0] as [number, number], glyph: 26.6, glyphOffsetY: 1.2 },
  balloonCenterY: 33.57, avatar: 30.66, avatarCenterY: 93.6,
} as const;

export function TapbackDetails({ selection, initials, name, style }: { selection: TapbackSelection; initials: string; name?: string; style?: CSSProperties }) {
  const m = tapbackDetailsMetrics;
  const g = m.balloon;
  return (
    <div data-slot="tapback-details" role="group" aria-label={`${name ?? initials} reacted with ${"type" in selection ? tapbackLabels[selection.type] : selection.emoji}`}
      style={{ position: "relative", width: m.width, height: m.height, borderRadius: m.radius, background: "var(--im-glass-solid, #ededef)", boxShadow: "var(--im-glass-shadow, 0 8px 28px rgba(0,0,0,0.10)), inset 0 0 0 0.5px var(--im-glass-rim, rgba(255,255,255,0.55))", ...style }}>
      <div data-slot="details-balloon" style={{ position: "absolute", left: m.width / 2 - g.main / 2, top: m.balloonCenterY - g.main / 2, width: g.main, height: g.main, borderRadius: "50%", background: "var(--im-details-balloon, #ffffff)", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <TapbackGlyph type={"type" in selection ? selection.type : undefined} emoji={"emoji" in selection ? selection.emoji : undefined} size={g.glyph} style={{ marginTop: 2 * g.glyphOffsetY }} />
        <BalloonTrail geometry={g} side="left" color="var(--im-details-balloon, #ffffff)" />
      </div>
      <div aria-hidden="true" data-slot="details-avatar"
        style={{ position: "absolute", left: m.width / 2 - m.avatar / 2, top: m.avatarCenterY - m.avatar / 2, width: m.avatar, height: m.avatar, borderRadius: "50%", background: "linear-gradient(#a8bfe1, #7f8ec1)", color: "#fff", fontSize: 12.5, fontWeight: 600, letterSpacing: 0.2, display: "flex", alignItems: "center", justifyContent: "center" }}>{initials}</div>
    </div>
  );
}

export type { TapbackType };

"use client";

import { useCallback, useEffect, useRef, useState, useSyncExternalStore, type CSSProperties, type KeyboardEvent, type MouseEvent, type PointerEvent } from "react";

const reducedMotionQuery = () => (typeof window === "undefined" ? null : window.matchMedia?.("(prefers-reduced-motion: reduce)") ?? null);
function subscribeReducedMotion(onChange: () => void) {
  const query = reducedMotionQuery();
  query?.addEventListener("change", onChange);
  return () => query?.removeEventListener("change", onChange);
}
/** True when the viewer prefers reduced motion; false during server rendering. */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(subscribeReducedMotion, () => reducedMotionQuery()?.matches ?? false, () => false);
}

/**
 * iOS-style long press (see references/SPEC.md "iOS long-press"): 500 ms hold with the bubble
 * scaling up slightly over the hold, cancelled by 8 px of movement. Right-click, double-click and
 * the keyboard (Enter, Space, Shift+F10, ContextMenu) open the same actions immediately.
 */
export type LongPressOptions = {
  onLongPress: (origin: { x: number; y: number; source: "press" | "contextmenu" | "dblclick" | "keyboard" }) => void;
  onCancel?: () => void;
  /** Hold duration in ms (native ≈ 500). */
  threshold?: number;
  /** Pointer travel that cancels the press, in px (native 8). */
  moveTolerance?: number;
  /** Scale reached at the end of the hold (a subtle 1.03 native). */
  holdScale?: number;
  disabled?: boolean;
};

export function useLongPress({ onLongPress, onCancel, threshold = 500, moveTolerance = 8, holdScale = 1.03, disabled = false }: LongPressOptions) {
  const [holding, setHolding] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const origin = useRef({ x: 0, y: 0 });
  const fired = useRef(false);
  const reduced = useReducedMotion();

  const clear = useCallback(() => { if (timer.current) clearTimeout(timer.current); timer.current = null; }, []);
  const cancel = useCallback(() => { const was = timer.current !== null; clear(); setHolding(false); if (was) onCancel?.(); }, [clear, onCancel]);
  useEffect(() => () => clear(), [clear]);

  const onPointerDown = useCallback((event: PointerEvent<HTMLElement>) => {
    if (disabled || event.button !== 0) return;
    clear(); fired.current = false; origin.current = { x: event.clientX, y: event.clientY };
    setHolding(true);
    timer.current = setTimeout(() => {
      timer.current = null; fired.current = true; setHolding(false);
      onLongPress({ x: origin.current.x, y: origin.current.y, source: "press" });
    }, threshold);
  }, [disabled, clear, threshold, onLongPress]);

  const onPointerMove = useCallback((event: PointerEvent<HTMLElement>) => {
    if (timer.current && Math.hypot(event.clientX - origin.current.x, event.clientY - origin.current.y) > moveTolerance) cancel();
  }, [moveTolerance, cancel]);

  const onPointerUp = useCallback(() => { if (timer.current) cancel(); else setHolding(false); }, [cancel]);
  const onContextMenu = useCallback((event: MouseEvent<HTMLElement>) => {
    if (disabled) return;
    event.preventDefault(); clear(); setHolding(false);
    if (!fired.current) onLongPress({ x: event.clientX, y: event.clientY, source: "contextmenu" });
    fired.current = false;
  }, [disabled, clear, onLongPress]);
  const onDoubleClick = useCallback((event: MouseEvent<HTMLElement>) => {
    if (disabled) return;
    if (!fired.current) onLongPress({ x: event.clientX, y: event.clientY, source: "dblclick" });
    fired.current = false;
  }, [disabled, onLongPress]);
  const onKeyDown = useCallback((event: KeyboardEvent<HTMLElement>) => {
    if (disabled) return;
    if (event.key === "Enter" || event.key === " " || event.key === "ContextMenu" || (event.key === "F10" && event.shiftKey)) {
      event.preventDefault();
      const rect = event.currentTarget.getBoundingClientRect();
      onLongPress({ x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, source: "keyboard" });
    }
  }, [disabled, onLongPress]);

  /** Apply to the pressed element: the slow scale-up over the hold, snapping back on cancel. */
  const holdStyle: CSSProperties = reduced ? {} : {
    transform: holding ? `scale(${holdScale})` : "scale(1)",
    transition: holding ? `transform ${threshold}ms cubic-bezier(0.4, 0, 0.9, 0.6)` : "transform 160ms ease-out",
    willChange: holding ? "transform" : undefined,
  };

  return {
    holding,
    holdStyle,
    cancel,
    handlers: { onPointerDown, onPointerMove, onPointerUp, onPointerCancel: cancel, onPointerLeave: cancel, onContextMenu, onDoubleClick, onKeyDown },
    /** Accessibility attributes for the pressable element. */
    a11y: { role: "button" as const, tabIndex: 0, "aria-haspopup": "menu" as const },
  };
}

"use client";

import { useCallback, useImperativeHandle, useLayoutEffect, useMemo, useRef, useState, type ComponentProps, type CSSProperties, type KeyboardEvent, type MouseEvent, type PointerEvent, type ReactNode, type Ref, type RefObject } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { bubbleMetrics, emojiFontStack, fontStack, type Direction, type Service } from "@/components/imessage/tokens";
import { isEmojiOnly, MessageBubble, reactionOffsets } from "@/components/imessage/message-bubble";
import { DateSeparator, formatClockTime, formatDateLabel, type DateSeparatorVariant } from "@/components/imessage/date-separator";
import { LinkPreview } from "@/components/imessage/link-preview";
import { MessageAttachment } from "@/components/imessage/message-attachment";
import { MessageImages } from "@/components/imessage/message-image";
import { MessageAudio } from "@/components/imessage/message-audio";
import { InvisibleInk } from "@/components/imessage/message-effects";
import { ReplyCount, ReplyStub } from "@/components/imessage/message-reply";
import { FailedSendBadge, NotDelivered } from "@/components/imessage/ios-notices";
import { TypingIndicator } from "@/components/imessage/typing-indicator";
import { useBubbleScreenSpace } from "@/components/imessage/use-screen-space";

/**
 * The scrolling message log: clusters consecutive same-sender messages (60 s window, tail on the last
 * bubble only), applies the measured group gaps and edge insets, inserts date headers after a gap of an
 * hour, places the delivery label under the last outgoing message, renders emoji-only messages as big
 * glyphs, link messages as link cards, group-chat sender names, and the typing indicator at the end.
 * Bubble fills are kept in screen space through `useBubbleScreenSpace`.
 */
export type MessageStatus = "sending" | "sent" | "delivered" | "read" | "failed";
export type MessageReaction = { type: string; byMe?: boolean; emoji?: string };
export type MessageKind = "text" | "link" | "attachment" | "image" | "audio" | "typing";
export type MessageLink = { url: string; title?: string; host?: string; image?: string };
export type MessageAttachmentInfo = { name: string; size?: string; href?: string };

export type Message = {
  id: string;
  text: string;
  direction: Direction;
  service?: Service;
  sentAt: Date | number;
  sender?: string;
  senderInitials?: string;
  status?: MessageStatus;
  readAt?: Date | number;
  edited?: boolean;
  reactions?: MessageReaction[];
  kind?: MessageKind;
  link?: MessageLink;
  attachments?: MessageAttachmentInfo[];
  /** Photos or videos, when `kind` is "image". */
  images?: Array<{ src: string; alt: string; width?: number; height?: number }>;
  /** Voice message, when `kind` is "audio". */
  audio?: { duration: number; peaks?: number[] };
  /** The message this one replies to. */
  replyTo?: { id: string; text: string; direction: Direction; service?: Service; sender?: string };
  /** How many replies hang off this message. */
  replyCount?: number;
  /** Sent with a bubble effect. "invisible-ink" hides the message until it is revealed. */
  effect?: "slam" | "loud" | "gentle" | "invisible-ink";
  /** Force the tail on or off. Native draws it only on the last bubble of a cluster; use this to reproduce captures. */
  tail?: boolean;
  /** Override the gap above this message (px). Only for reproducing captures; the cluster rule decides otherwise. */
  gapBefore?: number;
};

export type MessageListHandle = {
  scrollToBottom(behavior?: ScrollBehavior): void;
  isNearBottom(): boolean;
  /**
   * Scroll a message into view and flash it. Returns false when that message is not in this list, so a
   * shell can fall back to opening the conversation it does live in. `progress` (0..1) seeks the flash
   * instead of playing it.
   */
  jumpTo(id: string, options?: { behavior?: ScrollBehavior; progress?: number }): boolean;
  readonly element: HTMLDivElement | null;
};

export type MessageListMetrics = {
  /** Space above the first row and below the last (the shell adds the chrome's own insets). */
  insetTop: number;
  insetBottom: number;
  /**
   * Emoji-only messages: glyph size, line box, side padding, and how far the glyph sits below where Chrome
   * places it in that box. macOS measured (ink 71.5 x 70.5 = 72pt glyph, 87.3pt line box, ink 4pt from the edge).
   */
  emojiSize: number;
  emojiLineHeight: number;
  emojiPadX: number;
  emojiShift: number;
  /**
   * Extra space a tail adds under its own bubble when the next message still continues the cluster.
   * A tail normally ends a cluster, so this only applies when a caller forces `tail` on a message
   * that is not the last of its group. macOS lets the tail push the next bubble down by its hang;
   * iOS has no capture of a mid-cluster tail, so it stays 0 there.
   */
  tailSpace: number;
  /** Rows closer than this to the bottom keep auto-scrolling as messages arrive. */
  nearBottom: number;
};

export const messageListMetrics: Record<Platform, MessageListMetrics> = {
  ios: { insetTop: 0, insetBottom: 0, emojiSize: 58, emojiLineHeight: 70.3, emojiPadX: 2.4, emojiShift: 0.8, tailSpace: 0, nearBottom: 72 },
  macos: { insetTop: 0, insetBottom: 0, emojiSize: 72, emojiLineHeight: 87.3, emojiPadX: 3, emojiShift: 1, tailSpace: 4.76, nearBottom: 72 },
};

export const clusterWindowMs = 60_000;
export const dateHeaderGapMs = 3_600_000;

/**
 * Threads: opening one from the list, and jumping from a reply's quoted stub back to the message it
 * quotes.
 *
 * UNVERIFIED. Nothing in `references/` captures a thread or a jump, so the flash a jumped-to message
 * runs is built from the documented behaviour (the message pulses once and settles) and its numbers
 * are plausible, not measured. The two gesture thresholds are not invented: 500 ms and 8 px are the
 * measured hold and travel `use-long-press.ts` uses, repeated here because the list must not depend
 * on that file (it is not one of this component's registry dependencies).
 *
 * Precedence on a bubble that carries a thread as well as the press gestures, first rule that fires
 * wins:
 *
 * 1. A control inside the row takes its own click: the reply count, the stub's jump button, a link
 *    card, an attachment link, the Invisible Ink reveal. The row never second-guesses one of those.
 * 2. A press that reaches the 500 ms hold, a right click, or a double click belongs to the message
 *    actions (the shells bind those on the log itself), so the click that ends one opens no thread.
 *    A press that travelled more than 8 px is a scroll or a text drag, not a tap.
 * 3. What is left is a plain tap, and on a message that has replies it opens the thread, the way
 *    native does. Except in click-to-select mode: there a click selects the message (macOS,
 *    measured), and the reply count stays the way in.
 * 4. Keyboard: the log's arrow keys focus a row, and Enter or Space on it opens its thread. When the
 *    shell has claimed those keys for the actions menu (`messageActions`) they stay with the menu and
 *    the reply count button, which is its own tab stop, is the keyboard route into the thread.
 */
export const threadGesture = { hold: 500, moveTolerance: 8 } as const;

/**
 * The flash a message runs when a jump lands on it. Seekable by construction: it is one Web Animations
 * animation on the row, so `document.getAnimations()` reaches it and `flash={{ id, progress }}` pauses
 * and seeks it instead of playing it. UNVERIFIED, see above.
 */
export const messageFlash = { duration: 480, peak: 110, scale: 1.045, dip: 0.4, reducedDuration: 220, reducedDip: 0.6 } as const;

/** Same reading as `message-motion`'s, repeated because that file is not a dependency of this one. */
function prefersReducedMotion(): boolean {
  return typeof window !== "undefined" && typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export type MessageListProps = Omit<ComponentProps<"div">, "children" | "ref"> & {
  messages: Message[];
  /** Show the typing indicator after the last message. Pass the sender's name for the accessible label. */
  typing?: boolean | { sender?: string };
  /** Group conversation: show sender names above incoming clusters. */
  group?: boolean;
  /** Reference time for "Today"/"Yesterday"; defaults to now. */
  now?: Date | number;
  /** The element that represents the device screen (for the screen-space bubble fill). Defaults to the list itself. */
  frameRef?: RefObject<HTMLElement | null>;
  platform?: Platform;
  /** Service line shown above the first date header on iOS. Defaults to "iMessage", or "Text Message" for all-SMS threads. */
  serviceLabel?: ReactNode | null;
  /** Render tapback balloons for a message (see tapback.tsx). */
  renderReactions?: (message: Message) => ReactNode;
  /** Keep the newest message in view when messages arrive while scrolled near the bottom. */
  autoScroll?: boolean;
  /** Show the date header above the first message (native always does; captures of a scrolled list do not). */
  firstDateHeader?: boolean;
  /**
   * The shell opens actions (the long-press overlay, the macOS context menu) on a message. Rows then
   * advertise that popup to assistive technology; the log's arrow keys reach them either way.
   */
  messageActions?: boolean;
  /**
   * Ids of the messages a click has selected. Passing this (even empty) turns the rows into a
   * multi-select listbox and paints the selection overlay on their bubbles. macOS only: iOS has no
   * click-to-select, it has the checkbox select mode in `ios-select-mode.tsx`.
   */
  selectedIds?: readonly string[];
  /**
   * Open a message's thread. The reply count under a message calls it with "reply-count"; a plain tap
   * on a message that has replies calls it with "message" (see `threadGesture` for the precedence
   * against the press gestures). Without it the reply count stays the inert label it renders today.
   */
  onOpenThread?: (id: string, source: ThreadOpenSource) => void;
  /**
   * Jump to the message a reply quotes: activating the stub above a reply calls it. The list scrolls
   * that message into view and flashes it whenever it is in this list; the callback fires either way,
   * so a shell can close a thread or switch conversations first. A caller that answers by driving
   * `flash` itself simply restarts the same flash.
   */
  onJumpToMessage?: (id: string) => void;
  /**
   * The message whose thread is open, if one is. Only the list can tell the reply count that it is
   * expanded, so a shell that owns the thread state passes it back here for the announcement.
   */
  openThreadId?: string | null;
  /**
   * Scroll a message into view and flash it, declaratively. `progress` (0..1) pauses and seeks the
   * flash rather than playing it, which is what makes a scenario checkpoint reproducible.
   */
  flash?: { id: string; progress?: number } | null;
  /** Where a short conversation sits: under the header ("top", native iOS) or against the composer ("bottom"). */
  anchor?: "top" | "bottom";
  insetTop?: number;
  insetBottom?: number;
  ref?: Ref<MessageListHandle>;
};

/** Which affordance opened a thread: the count under a message, or the message itself. */
export type ThreadOpenSource = "reply-count" | "message";

type Row =
  | { kind: "date"; key: string; date: number; service?: ReactNode; variant: DateSeparatorVariant }
  | { kind: "message"; key: string; message: Message; tail: boolean; gap: number; showStatus: boolean; showSender: boolean; emoji: boolean }
  | { kind: "typing"; key: string; gap: number; sender?: string };

const ms = (v: Date | number) => (typeof v === "number" ? v : v.getTime());

function startOfDay(v: number) { const d = new Date(v); return new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime(); }

/** "Delivered", "Read 9:41 AM", "Read Yesterday", "Sent as Text Message". */
export function statusLabel(message: Message, now: number): string | undefined {
  switch (message.status) {
    case "delivered": return "Delivered";
    case "read": {
      if (message.readAt === undefined) return "Read";
      const at = ms(message.readAt);
      if (startOfDay(at) === startOfDay(now)) return `Read ${formatClockTime(at)}`;
      return `Read ${formatDateLabel(at, now).day}`;
    }
    case "sent": return message.service === "sms" ? "Sent as Text Message" : "Sent";
    default: return undefined;
  }
}

export function buildRows(messages: Message[], options: { platform: Platform; now: number; group: boolean; serviceLabel: ReactNode | null; firstDateHeader: boolean; typing?: { sender?: string } | null }): Row[] {
  const m = bubbleMetrics[options.platform];
  const lm = messageListMetrics[options.platform];
  const rows: Row[] = [];
  // A tail hangs below its bubble and, on macOS, takes that space from the next bubble in the cluster.
  // Measured body bottom to next body top: 3.24 / 2.93 / 3.49 / 2.74 with no tail above, 7.74 / 8.10 /
  // 8.11 / 8.23 with one (conversation-pane-dark.png, -light.png, -dark-2.png, -light-partial.png).
  let previousTail = false;
  // The delivery label lives under the newest outgoing message that has one: a message still sending shows
  // nothing, and the previous bubble keeps its "Delivered" until the new one is delivered.
  const lastOutgoing = messages.reduce((found, message, index) => (message.direction === "outgoing" && message.kind !== "link" && message.kind !== "typing" && statusLabel(message, options.now) !== undefined ? index : found), -1);
  for (let i = 0; i < messages.length; i++) {
    const message = messages[i];
    if (message.kind === "typing") continue;
    const previous = i > 0 ? messages[i - 1] : undefined;
    const next = i + 1 < messages.length ? messages[i + 1] : undefined;
    const emoji = message.kind !== "link" && isEmojiOnly(message.text);
    const t = ms(message.sentAt);
    const needsHeader = previous ? t - ms(previous.sentAt) > dateHeaderGapMs : options.firstDateHeader;
    // Only the header that opens the conversation carries the service name and its tight top gap; every
    // later one is a one-line mid-list header with a gap of its own on both sides.
    if (needsHeader) rows.push({ kind: "date", key: `date-${message.id}`, date: t, service: i === 0 ? options.serviceLabel : undefined, variant: i === 0 ? "first" : "mid" });
    const continues = (a: Message | undefined, b: Message) =>
      Boolean(a) && a!.direction === b.direction && (a!.sender ?? "") === (b.sender ?? "") && ms(b.sentAt) - ms(a!.sentAt) <= clusterWindowMs && ms(b.sentAt) - ms(a!.sentAt) >= 0 && !isEmojiOnly(a!.text) && !isEmojiOnly(b.text) && a!.kind !== "typing";
    const inCluster = !needsHeader && continues(previous, message);
    const nextInCluster = Boolean(next) && next!.kind !== "typing" && continues(message, next!) && ms(next!.sentAt) - t <= dateHeaderGapMs;
    const tail = message.tail ?? (!emoji && message.kind !== "link" && !nextInCluster);
    // `previousTail` is only ever true here for a caller-forced tail: a derived tail is exactly
    // `!inCluster` for the row that follows, so the two can never both hold on their own.
    const gap = message.gapBefore ?? (needsHeader || !previous ? 0 : inCluster ? m.gapInGroup + (previousTail ? lm.tailSpace : 0) : m.gapBetweenGroups);
    previousTail = tail;
    rows.push({
      kind: "message", key: message.id, message, tail, gap, emoji,
      showStatus: i === lastOutgoing,
      showSender: options.group && message.direction === "incoming" && Boolean(message.sender) && !inCluster,
    });
  }
  if (options.typing) rows.push({ kind: "typing", key: "typing", gap: rows.length ? m.gapBetweenGroups : 0, sender: options.typing.sender });
  return rows;
}

function EmojiMessage({ message, platform }: { message: Message; platform: Platform }) {
  const lm = messageListMetrics[platform];
  const outgoing = message.direction === "outgoing";
  return (
    <div data-slot="message-bubble" data-direction={message.direction} data-platform={platform} data-emoji-only="true"
      className={cn("flex min-w-0 flex-col", outgoing ? "items-end" : "items-start")} style={{ width: "100%", fontFamily: fontStack }}>
      <div data-slot="emoji" style={{ fontSize: lm.emojiSize, lineHeight: `${lm.emojiLineHeight}px`, fontFamily: emojiFontStack, padding: `0 ${lm.emojiPadX}px`, whiteSpace: "nowrap", position: "relative", top: lm.emojiShift }}>
        <span className="sr-only">{outgoing ? "You: " : `${message.sender ?? "Contact"}: `}</span>{message.text.trim()}
      </div>
    </div>
  );
}

export function MessageList({
  messages, typing = false, group = false, now, frameRef, platform: platformProp, serviceLabel, renderReactions, autoScroll = true,
  firstDateHeader = true, messageActions = false, selectedIds, onOpenThread, onJumpToMessage, openThreadId, flash, anchor = "top", insetTop, insetBottom, ref, className, style, onScroll, onKeyDown, ...props
}: MessageListProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = bubbleMetrics[platform];
  const lm = messageListMetrics[platform];
  const scroller = useRef<HTMLDivElement>(null);
  const nearBottom = useRef(true);
  // "Today"/"Yesterday" need a clock; read it once so rendering stays pure, and never let it fall behind the newest message.
  const [mountedAt] = useState(() => Date.now());
  const nowMs = now === undefined ? messages.reduce((latest, message) => Math.max(latest, ms(message.sentAt)), mountedAt) : ms(now);
  const typingInfo = useMemo(() => (typing === false ? null : typing === true ? {} : typing), [typing]);
  const service = serviceLabel === undefined ? (messages.length && messages.every(message => message.service === "sms") ? "Text Message" : "iMessage") : serviceLabel;
  const rows = useMemo(() => buildRows(messages, { platform, now: nowMs, group, serviceLabel: service, firstDateHeader, typing: typingInfo }), [messages, platform, nowMs, group, service, firstDateHeader, typingInfo]);
  // A listbox of rows only exists once the shell owns a selection; without it the log keeps the plain
  // roles it has always had, so iOS and every uncontrolled consumer are untouched.
  const selectable = selectedIds !== undefined;
  const selection = useMemo(() => new Set(selectedIds ?? []), [selectedIds]);

  useBubbleScreenSpace(scroller, frameRef);

  const scrollToBottom = useCallback((behavior: ScrollBehavior = "auto") => {
    const el = scroller.current;
    if (el) el.scrollTo({ top: el.scrollHeight - el.clientHeight, behavior });
  }, []);

  // One flash at a time: a second jump cancels the first rather than compounding two transforms on
  // two different rows.
  const flashing = useRef<Animation | null>(null);
  const jumpTo = useCallback((id: string, options?: { behavior?: ScrollBehavior; progress?: number }) => {
    const el = scroller.current;
    const row = el?.querySelector<HTMLElement>(`[data-slot="message-row"][data-message-id="${CSS.escape(id)}"]`);
    if (!el || !row) return false;
    const reduced = prefersReducedMotion();
    const listBox = el.getBoundingClientRect();
    const rowBox = row.getBoundingClientRect();
    // Only scroll when the message is not already fully in view: native does not shuffle the log to
    // recentre something the reader can see. Scroll this element rather than `scrollIntoView`, which
    // would also scroll every ancestor, including the page the device frame sits on.
    if (rowBox.top < listBox.top + 8 || rowBox.bottom > listBox.bottom - 8) {
      const centred = el.scrollTop + (rowBox.top - listBox.top) - Math.max(0, (el.clientHeight - rowBox.height) / 2);
      el.scrollTo({
        top: Math.max(0, Math.min(centred, el.scrollHeight - el.clientHeight)),
        // A smooth scroll runs on its own clock, so a seeked (scrubbed) jump lands instantly instead.
        behavior: options?.progress !== undefined || reduced ? "auto" : options?.behavior ?? "smooth",
      });
    }
    flashing.current?.cancel();
    const F = messageFlash;
    const duration = reduced ? F.reducedDuration : F.duration;
    // The pulse grows from the message's own edge, the side the long-press lift grows from. Every
    // keyframe carries the origin: a seeked animation never finishes, so nothing restores it later.
    const transformOrigin = row.dataset.direction === "outgoing" ? "right center" : "left center";
    const frames: Keyframe[] = reduced
      ? [{ offset: 0, opacity: 1 }, { offset: 0.5, opacity: F.reducedDip }, { offset: 1, opacity: 1 }]
      : [
        { offset: 0, opacity: 1, transform: "scale(1)", transformOrigin, easing: "ease-out" },
        { offset: F.peak / F.duration, opacity: F.dip, transform: `scale(${F.scale})`, transformOrigin, easing: "ease-in-out" },
        { offset: 1, opacity: 1, transform: "scale(1)", transformOrigin },
      ];
    const animation = row.animate(frames, { duration, fill: "both", easing: "linear" });
    flashing.current = animation;
    if (options?.progress === undefined) {
      void animation.finished.then(() => { if (flashing.current === animation) { animation.cancel(); flashing.current = null; } }).catch(() => { /* cancelled by the next jump */ });
    } else {
      animation.pause();
      animation.currentTime = Math.max(0, Math.min(1, options.progress)) * duration;
    }
    return true;
  }, []);
  useImperativeHandle(ref, () => ({ scrollToBottom, isNearBottom: () => nearBottom.current, jumpTo, get element() { return scroller.current; } }), [scrollToBottom, jumpTo]);

  /** The stub above a reply: tell the caller, then jump here if the quoted message is in this list. */
  const jump = useCallback((id: string) => { onJumpToMessage?.(id); jumpTo(id); }, [onJumpToMessage, jumpTo]);
  const messageIds = useMemo(() => new Set(messages.map(message => message.id)), [messages]);
  const threadIds = useMemo(() => new Set(messages.filter(message => message.replyCount).map(message => message.id)), [messages]);

  // A press that becomes a hold, a drag, or a second click belongs to the actions gesture, so the
  // click that ends it must not also open a thread. `threadGesture` documents the whole order.
  const press = useRef<{ x: number; y: number; at: number } | null>(null);
  const plainTap = useCallback((event: MouseEvent<HTMLElement>) => {
    const start = press.current;
    press.current = null;
    if (event.defaultPrevented || event.button !== 0 || event.detail > 1) return false;
    if ((event.target as HTMLElement | null)?.closest?.('a, button, input, textarea, select, [role="button"], [role="link"], [contenteditable]')) return false;
    if (start && (Math.hypot(event.clientX - start.x, event.clientY - start.y) > threadGesture.moveTolerance || event.timeStamp - start.at >= threadGesture.hold)) return false;
    const selection = typeof window === "undefined" ? null : window.getSelection();
    if (selection && !selection.isCollapsed && selection.anchorNode && event.currentTarget.contains(selection.anchorNode)) return false;
    return true;
  }, []);

  const lastKey = rows.length ? rows[rows.length - 1].key : "";
  useLayoutEffect(() => {
    if (autoScroll && nearBottom.current) scrollToBottom();
  }, [autoScroll, scrollToBottom, lastKey, rows.length]);

  // Declared after the auto-scroll effect so the jump wins: layout effects run in order, and pinning
  // the log to the bottom first would otherwise undo the scroll this one just made.
  const flashId = flash?.id ?? null;
  const flashProgress = flash?.progress;
  useLayoutEffect(() => {
    if (!flashId) return;
    jumpTo(flashId, { progress: flashProgress });
    return () => { flashing.current?.cancel(); flashing.current = null; };
  }, [flashId, flashProgress, jumpTo]);

  const typingLabel = typingInfo?.sender ? `${typingInfo.sender} is typing` : "Someone is typing";
  const maxWidth = `calc((100% + ${2 * m.edgeInset}px) * ${m.maxWidthRatio})`;

  /**
   * The log is one tab stop and the arrow keys walk the messages inside it, so a keyboard can reach
   * a single message without adding a tab stop per bubble. Reaching one is what makes its actions
   * (the long-press overlay, the macOS context menu) available without a pointer.
   */
  function onListKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    // Enter or Space on a focused message opens its thread. A shell that binds those keys to the
    // actions menu says so with `messageActions`, and then they stay with the menu: the reply count
    // under the message is its own tab stop, so the thread is still reachable without a pointer.
    if (onOpenThread && !selectable && !messageActions && (event.key === "Enter" || event.key === " ")) {
      const row = event.target as HTMLElement | null;
      const id = row?.matches?.('[data-slot="message-row"][data-message-id]') ? row.getAttribute("data-message-id") : null;
      if (id && threadIds.has(id)) { event.preventDefault(); onOpenThread(id, "message"); return; }
    }
    if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
    const target = event.target as HTMLElement | null;
    // Let a field, a slider or a menu inside the log keep its own arrow keys.
    if (target && target !== event.currentTarget && target.closest("input, textarea, [role=slider], [role=menu]")) return;
    const rows = Array.from(scroller.current?.querySelectorAll<HTMLElement>('[data-slot="message-row"][data-message-id]') ?? []);
    if (!rows.length) return;
    event.preventDefault();
    const from = rows.findIndex(row => row === target || row.contains(target));
    const next = event.key === "Home" ? 0
      : event.key === "End" ? rows.length - 1
        : from < 0 ? (event.key === "ArrowDown" ? 0 : rows.length - 1)
          : Math.min(rows.length - 1, Math.max(0, from + (event.key === "ArrowDown" ? 1 : -1)));
    rows[next]?.focus();
  }

  return (
    <div ref={scroller} role="log" aria-live="polite" aria-relevant="additions text" aria-label="Messages" tabIndex={0}
      data-slot="message-list" data-platform={platform} onKeyDown={onListKeyDown}
      className={cn("relative min-h-0 overflow-y-auto overscroll-contain focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[#0088ff]", anchor === "bottom" && "flex flex-col", className)}
      style={{ fontFamily: fontStack, background: "var(--im-bg)", ...style }}
      onScroll={event => {
        const el = event.currentTarget;
        nearBottom.current = el.scrollHeight - el.scrollTop - el.clientHeight < lm.nearBottom;
        onScroll?.(event);
      }} {...props}>
      <div data-slot="message-list-content" className="flex shrink-0 flex-col" role={selectable ? "listbox" : undefined} aria-multiselectable={selectable || undefined} aria-label={selectable ? "Messages" : undefined}
        style={{ padding: `${insetTop ?? lm.insetTop}px ${m.edgeInset}px ${insetBottom ?? lm.insetBottom}px`, marginTop: anchor === "bottom" ? "auto" : undefined }}>
        {rows.map(row => {
          if (row.kind === "date") return <DateSeparator key={row.key} date={row.date} now={nowMs} service={row.service} variant={row.variant} platform={platform} />;
          if (row.kind === "typing") {
            return (
              <div key={row.key} data-slot="message-row" data-typing="true" className="flex items-start" style={{ marginTop: row.gap }}>
                <TypingIndicator label={row.sender ? `${row.sender} is typing` : typingLabel} platform={platform} />
              </div>
            );
          }
          const { message } = row;
          const outgoing = message.direction === "outgoing";
          const rowStyle: CSSProperties = { marginTop: row.gap };
          let content: ReactNode;
          // MessageBubble hangs its own reactions; every other kind needs them hung below.
          let isTextBubble = false;
          if (message.kind === "link" && message.link) {
            const link = message.link;
            content = <LinkPreview href={link.url} title={link.title} host={link.host} image={link.image} platform={platform} />;
          } else if (message.kind === "image" && message.images?.length) {
            content = <MessageImages images={message.images} direction={message.direction} tail={row.tail} platform={platform} />;
          } else if (message.kind === "audio" && message.audio) {
            content = <MessageAudio duration={message.audio.duration} peaks={message.audio.peaks} direction={message.direction} tail={row.tail} platform={platform} />;
          } else if (message.kind === "attachment" && message.attachments?.length) {
            content = (
              <>
                {message.attachments.map((file, index) => (
                  <MessageAttachment key={file.name + index} name={file.name} size={file.size} href={file.href}
                    direction={message.direction} tail={row.tail && index === message.attachments!.length - 1} platform={platform}
                    style={index ? { marginTop: m.gapInGroup } : undefined} />
                ))}
              </>
            );
          } else if (row.emoji) {
            content = <EmojiMessage message={message} platform={platform} />;
          } else {
            isTextBubble = true;
            content = (
              <MessageBubble direction={message.direction} service={message.service ?? "imessage"} tail={row.tail} platform={platform}
                sender={row.showSender ? message.sender : undefined} status={row.showStatus ? statusLabel(message, nowMs) : undefined}
                edited={message.edited} reactions={renderReactions?.(message)} emojiOnly={false} selected={selection.has(message.id)} maxWidth={maxWidth} style={{ width: "100%" }}>
                {message.text}
              </MessageBubble>
            );
          }
          // Only the text branch hands its reactions to MessageBubble. Every other kind draws its own
          // container, so without this a reaction applied to a photo, a link card, an audio row, a
          // file card or a bare emoji is stored and never painted.
          const reactions = renderReactions?.(message);
          if (reactions && !isTextBubble) {
            const offset = reactionOffsets[platform];
            content = (
              <div className="relative" style={{ marginTop: offset.marginTop, display: "flex", flexDirection: "column", alignItems: outgoing ? "flex-end" : "flex-start" }}>
                {content}
                <div data-slot="reactions" className="absolute z-10" style={{ top: offset.top, [outgoing ? "left" : "right"]: offset.side }}>{reactions}</div>
              </div>
            );
          }
          if (message.effect === "invisible-ink") content = <InvisibleInk>{content}</InvisibleInk>;
          if (message.status === "failed") {
            content = (
              <div className="flex items-center" style={{ gap: 8, flexDirection: outgoing ? "row" : "row-reverse" }}>
                <FailedSendBadge platform={platform} />
                {content}
              </div>
            );
          }
          const quote = message.replyTo;
          // The stub only becomes a control when the jump has somewhere to land: the quoted message is
          // in this list, or the caller takes the jump itself. Otherwise it stays the plain quotation
          // it renders today, rather than a button that does nothing.
          const canJump = Boolean(quote) && (Boolean(onJumpToMessage) || messageIds.has(quote!.id));
          // Rule 3 of `threadGesture`: a plain tap opens the thread, but not while a click selects.
          const tapOpensThread = Boolean(onOpenThread) && Boolean(message.replyCount) && !selectable;
          return (
            // `tabIndex -1`: the row is not its own tab stop, the log's arrow keys focus it. That is
            // what lets a keyboard open a message's actions, or its thread, without a pointer.
            <div key={row.key} data-slot="message-row" data-message-id={message.id} data-direction={message.direction} data-kind={message.kind ?? "text"}
              data-selected={selection.has(message.id) ? "true" : undefined} role={selectable ? "option" : undefined} aria-selected={selectable ? selection.has(message.id) : undefined}
              data-has-thread={message.replyCount ? "true" : undefined}
              tabIndex={-1}
              // The row advertises one popup, and the actions menu keeps it when a shell binds one:
              // that is what Enter and Space do there. The reply count under the message carries the
              // thread's own `aria-haspopup="dialog"`, so a thread is announced either way.
              aria-haspopup={messageActions ? "menu" : tapOpensThread ? "dialog" : undefined}
              onPointerDown={tapOpensThread ? (event: PointerEvent<HTMLDivElement>) => { press.current = { x: event.clientX, y: event.clientY, at: event.timeStamp }; } : undefined}
              onClick={tapOpensThread ? (event: MouseEvent<HTMLDivElement>) => { if (plainTap(event)) onOpenThread!(message.id, "message"); } : undefined}
              data-effect={message.effect} className={cn("flex min-w-0 flex-col focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]", outgoing ? "items-end" : "items-start")}
              style={tapOpensThread ? { ...rowStyle, cursor: "pointer" } : rowStyle}>
              {quote && (canJump ? (
                // A button with no box of its own: the stub keeps every measured edge, and the whole
                // quotation is the hit target, the way a quoted stub behaves natively. The copy inside
                // is hidden from assistive technology because this label already reads it out.
                <button type="button" data-slot="reply-jump" data-target-id={quote.id}
                  onClick={event => { event.stopPropagation(); jump(quote.id); }}
                  aria-label={`Replying to ${quote.sender ?? (quote.direction === "outgoing" ? "your message" : "their message")}: ${quote.text}. Go to that message.`}
                  className="flex w-full min-w-0 cursor-pointer flex-col focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
                  style={{ alignItems: "inherit", margin: 0, padding: 0, border: 0, background: "transparent", font: "inherit", color: "inherit", textAlign: "inherit", appearance: "none" }}>
                  <ReplyStub quote={quote} aria-hidden="true" platform={platform} />
                </button>
              ) : <ReplyStub quote={quote} platform={platform} />)}
              {content}
              {message.status === "failed" && <NotDelivered platform={platform} />}
              {message.replyCount ? (onOpenThread ? (
                // `display: contents` keeps the button exactly where it was in the layout while giving
                // the click somewhere to stop: opening a thread should not also run the shell's
                // click-to-select on the message behind it.
                <span data-slot="thread-controls" style={{ display: "contents" }} onClick={event => event.stopPropagation()}>
                  <ReplyCount count={message.replyCount} platform={platform} expanded={openThreadId === undefined ? undefined : openThreadId === message.id}
                    onOpen={() => onOpenThread(message.id, "reply-count")} />
                </span>
              ) : <ReplyCount count={message.replyCount} platform={platform} />) : null}
            </div>
          );
        })}
      </div>
    </div>
  );
}

