"use client";

import { useEffect, useId, useRef, useState, type ComponentProps, type CSSProperties, type RefObject } from "react";
import { cn } from "@/lib/utils";

/**
 * Send-with-effect: the four bubble effects and the invisible-ink reveal.
 *
 * The three scale timelines ARE measured: `references/ios/motion/effects.md` reads the bubble's height
 * over its settled height off 60 fps recordings of the iOS 26 simulator, and every offset below is one
 * of those times divided by the duration. What is still not measured, and is called out where it
 * appears: the rotation on Slam, the sideways jitter on Loud, the handful of steps between two
 * measured frames, and the screen effects. The screen that chooses an effect is measured too, in
 * `ios-effects-picker.tsx`, and so is the look of the Invisible Ink preview it shows.
 */
export type BubbleEffectKind = "slam" | "loud" | "gentle" | "invisible-ink";

export const bubbleEffects: Array<{ kind: BubbleEffectKind; title: string; description: string }> = [
  { kind: "slam", title: "Slam", description: "Drops the bubble onto the conversation and shakes it." },
  { kind: "loud", title: "Loud", description: "Blows the bubble up, then lets it settle." },
  { kind: "gentle", title: "Gentle", description: "Arrives small and grows to size." },
  { kind: "invisible-ink", title: "Invisible Ink", description: "Hides the message until it is revealed." },
];

/**
 * Total duration of each bubble effect, in ms, measured from 60 fps recordings of the iOS 26
 * simulator sending with each effect (`references/ios/motion/effects.md`). Invisible Ink has no
 * motion of its own: the message simply arrives covered.
 *
 * Slam and Gentle are timed from the frame the effects screen leaves, so their first 50 and 200 ms
 * are the send flight and the bubble is not on screen yet. Loud is timed from the first frame the
 * bubble is visible, 117 ms after the screen leaves, so it starts at full opacity and its 1230 ms sit
 * after that flight rather than containing it.
 */
export const bubbleEffectDuration: Record<BubbleEffectKind, number> = { slam: 640, loud: 1230, gentle: 3000, "invisible-ink": 0 };

export function prefersReducedMotion(): boolean {
  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;
}

/**
 * Keyframes traced from those recordings. Each `offset` is the measured time in ms divided by the
 * duration above, to four places, which lands every one within 0.05 ms of its frame; the Slam impact
 * is the one exception and carries its exact fraction, for the reason given there. Each scale is the
 * bubble's measured height over its settled height. `easing: "linear"` keeps the curve between two
 * keyframes a straight line, so seeking to a measured time renders that measured scale, and every
 * measured frame reads back within 0.002 of the table. A step with no frame behind it is interpolated
 * between its neighbours and is called out where it appears.
 */
function keyframes(kind: BubbleEffectKind): Keyframe[] {
  switch (kind) {
    case "slam":
      // Arrives far oversized and shrinking fast, lands squashed at 0.92, rebounds to 1.07, settles.
      // Frames at 50 (7.7, and clipped by the screen, so that is a lower bound), 233, 267, 300, 333,
      // 367, 400, 467, 533 and 633 ms. Two steps are not measured: the scale 8 it starts at, which is
      // off the screen before the bubble is visible at all, and the 2.6 at 288 ms, because the
      // recording jumps 4.67 -> 0.92 between two frames and that is the slam itself.
      return [
        { offset: 0, transform: "scale(8) rotate(-4deg)", opacity: 0 },
        { offset: 0.0521, opacity: 0 },
        { offset: 0.0781, transform: "scale(7.7) rotate(-3.4deg)", opacity: 1 },
        { offset: 0.3641, transform: "scale(5.1) rotate(-1.4deg)" },
        { offset: 0.4172, transform: "scale(4.67) rotate(-1deg)" },
        { offset: 0.45, transform: "scale(2.6) rotate(-0.4deg)" },
        // 300/640 exactly. The impact is falling 0.14 of scale per ms, a hundred times faster than any
        // other stretch of any of these curves, so rounding this one offset to four places would land
        // the 0.92 a thirtieth of a millisecond late and read 0.925 at 300 ms.
        { offset: 0.46875, transform: "scale(0.92) rotate(0deg)" },
        { offset: 0.5203, transform: "scale(0.95)" },
        { offset: 0.5734, transform: "scale(1)" },
        { offset: 0.625, transform: "scale(1.02)" },
        { offset: 0.7297, transform: "scale(1.07)" },
        { offset: 0.8328, transform: "scale(1.05)" },
        { offset: 0.9891, transform: "scale(1)" },
        { offset: 1, transform: "scale(1)" },
      ];
    case "loud":
      // Starts a third of size, blows past twice its size, shakes at the top, then falls back. Frames
      // at 0, 33, 83, 183, 283, 350, 450, 550, 683, 783, 883, 1033 and 1233 ms on a clock that starts
      // where the bubble becomes visible, so it opens at 0.32 with no fade. The sideways jitter is the
      // shake the recording shows on top of the growth, and the 1.05 at 1144 ms is interpolated: the
      // recording has no frame between 1033 and the settle.
      return [
        { offset: 0, transform: "scale(0.32)" },
        { offset: 0.0268, transform: "scale(0.58)" },
        { offset: 0.0675, transform: "scale(1.02)" },
        { offset: 0.1488, transform: "scale(1.75) translateX(-4px)" },
        { offset: 0.2301, transform: "scale(2.12) translateX(4px)" },
        { offset: 0.2846, transform: "scale(2.23) translateX(-3px)" },
        { offset: 0.3659, transform: "scale(2.35) translateX(3px)" },
        { offset: 0.4472, transform: "scale(2.27) translateX(-2px)" },
        { offset: 0.5553, transform: "scale(2.32) translateX(2px)" },
        { offset: 0.6366, transform: "scale(2.2) translateX(0)" },
        { offset: 0.7179, transform: "scale(1.87)" },
        { offset: 0.8398, transform: "scale(1.25)" },
        { offset: 0.93, transform: "scale(1.05)" },
        { offset: 1, transform: "scale(1)" },
      ];
    case "gentle":
      // Arrives at a third of size, overshoots slightly, then takes seconds to relax into place.
      // Frames at 200 (the first one the bubble is on screen), 233, 300, 400, 533, the hold through
      // 1250, then 1983, 2583 and the settle at 3083, which is 83 ms past this duration and lands on
      // the last keyframe instead. The 1.18 at 1650 ms is interpolated: nothing is measured between
      // the end of the hold and 1983.
      return [
        { offset: 0, transform: "scale(0.38)", opacity: 0 },
        { offset: 0.0611, opacity: 0 },
        { offset: 0.0667, transform: "scale(0.38)", opacity: 1 },
        { offset: 0.0777, transform: "scale(0.65)" },
        { offset: 0.1, transform: "scale(0.85)" },
        { offset: 0.1333, transform: "scale(1.13)" },
        { offset: 0.1777, transform: "scale(1.25)" },
        { offset: 0.4167, transform: "scale(1.25)" },
        { offset: 0.55, transform: "scale(1.18)" },
        { offset: 0.661, transform: "scale(1.1)" },
        { offset: 0.861, transform: "scale(1.05)" },
        { offset: 1, transform: "scale(1)" },
      ];
    default:
      return [{ opacity: 1 }, { opacity: 1 }];
  }
}

export type BubbleEffectHandle = { seek(ms: number): void; play(): void; cancel(): void; readonly duration: number };

/**
 * Runs a bubble effect on an element. Pass `progress` (0..1) to scrub instead of play, which is what
 * the harness timeline does. Under reduced motion the element simply appears.
 */
export function playBubbleEffect(element: HTMLElement, kind: BubbleEffectKind, options: { progress?: number; origin?: string } = {}): BubbleEffectHandle {
  const duration = bubbleEffectDuration[kind];
  if (kind === "invisible-ink" || duration === 0 || prefersReducedMotion()) {
    element.style.transform = "";
    return { seek() {}, play() {}, cancel() {}, duration: 0 };
  }
  // The recordings keep the bubble pinned at its trailing bottom corner while everything else about it
  // grows (in the Loud capture the bottom edge stays within 785-793 for the whole 1230 ms), so that
  // corner is the origin: bottom right for an outgoing bubble, bottom left for an incoming one. The
  // direction sits on an ancestor when the effect runs on a bubble frame and on a descendant when a
  // `BubbleEffect` wraps a whole bubble, so look both ways; looking up alone left the wrapper scaling
  // out of its bottom left corner and dragging an outgoing bubble off the screen.
  const direction = element.closest("[data-direction]")?.getAttribute("data-direction")
    ?? element.querySelector("[data-direction]")?.getAttribute("data-direction");
  element.style.transformOrigin = options.origin ?? (direction === "outgoing" ? "100% 100%" : "0% 100%");
  const animation = element.animate(keyframes(kind), { duration, easing: "linear", fill: "both" });
  if (options.progress === undefined) animation.play();
  else { animation.pause(); animation.currentTime = Math.max(0, Math.min(1, options.progress)) * duration; }
  return {
    seek(ms) { animation.pause(); animation.currentTime = Math.max(0, Math.min(duration, ms)); },
    play() { animation.play(); },
    cancel() { animation.cancel(); element.style.transform = ""; },
    duration,
  };
}

/** Declarative wrapper: runs `kind` on its child whenever `kind` or `replay` changes. */
export function BubbleEffect({ kind, progress, replay, children, className, style, ...props }: ComponentProps<"div"> & { kind?: BubbleEffectKind; progress?: number; replay?: number }) {
  const host = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const element = host.current;
    if (!element || !kind) return;
    const handle = playBubbleEffect(element, kind, { progress });
    return () => handle.cancel();
  }, [kind, progress, replay]);
  return <div ref={host} data-slot="bubble-effect" data-effect={kind} className={cn("will-change-transform", className)} style={style} {...props}>{children}</div>;
}

/**
 * Invisible Ink: the message is covered by drifting particles until it is revealed. Native reveals on
 * touch or a pointer pass and hides again after a moment; `revealed` lets an app control that instead.
 */
/**
 * iOS 26 offers eight, in this order. The Screen tab's page dots confirm the count: eight dots, and
 * swiping past Celebration goes nowhere (`references/ios/motion/effects.md`). Shooting Star, which
 * earlier releases had, is gone.
 */
export type ScreenEffectKind = "echo" | "spotlight" | "balloons" | "confetti" | "love" | "lasers" | "fireworks" | "celebration";

export const screenEffects: Array<{ kind: ScreenEffectKind; title: string }> = [
  { kind: "echo", title: "Echo" },
  { kind: "spotlight", title: "Spotlight" },
  { kind: "balloons", title: "Balloons" },
  { kind: "confetti", title: "Confetti" },
  { kind: "love", title: "Love" },
  { kind: "lasers", title: "Lasers" },
  { kind: "fireworks", title: "Fireworks" },
  { kind: "celebration", title: "Celebration" },
];

/**
 * One deterministic 1-bit speckle tile, 64 px square with 15% of its pixels opaque. It is an image
 * rather than an SVG filter so every engine rasterises the same specks and a screenshot stays
 * comparable, and it is a single layer because two composited mask layers do not agree across
 * engines: `mask-composite: intersect` reads as "intersect with nothing" for the first layer in
 * WebKit and masks the text away entirely.
 */
const inkTile = "data:image/png;base64,";

const inkMask: CSSProperties = {
  maskImage: `url(${inkTile})`,
  maskSize: "64px 64px",
  maskRepeat: "repeat",
  WebkitMaskImage: `url(${inkTile})`,
  WebkitMaskSize: "64px 64px",
  WebkitMaskRepeat: "repeat",
  animation: "im-ink-drift 5200ms linear infinite",
};

const inkKeyframes = `
@keyframes im-ink-drift {
  from { mask-position: 0 0; -webkit-mask-position: 0 0; }
  to { mask-position: 64px -64px; -webkit-mask-position: 64px -64px; }
}
/* The drift runs on whatever the mask lands on, which is the text slot rather than the wrapper that
   carries [data-ink-masked], so the reduced-motion rule has to name all three or it stops nothing. */
@media (prefers-reduced-motion: reduce) {
  [data-slot="invisible-ink"] :is([data-ink-masked], [data-slot="text"], [data-slot="ink-target"]) { animation: none !important; }
}
`;

/**
 * Invisible Ink: the message's text dissolves into drifting specks until it is revealed, and the
 * bubble itself stays where it is. Native reveals on touch or a pointer pass and hides again after a
 * moment; `revealed` lets an app control that instead.
 *
 * The mask lands on the bubble's `[data-slot="text"]` (or anything marked `data-slot="ink-target"`),
 * so the fill, the tail and any reactions keep drawing normally. Content with neither gets masked
 * whole, which is the right fallback for a plain string.
 */
export function InvisibleInk({ revealed, onRevealChange, children, className, style, ...props }: Omit<ComponentProps<"div">, "onChange"> & { revealed?: boolean; onRevealChange?: (revealed: boolean) => void }) {
  const [internal, setInternal] = useState(false);
  const open = revealed ?? internal;
  const id = useId();
  const scope = `ink-${id.replace(/[^a-zA-Z0-9]/g, "")}`;
  const set = (next: boolean) => { if (revealed === undefined) setInternal(next); onRevealChange?.(next); };

  const filterId = `${scope}-spread`;
  // Camel case to CSS, keeping the `-webkit-` prefix intact: Safari still needs the prefixed
  // mask properties, and its `mask-composite` takes the legacy keywords.
  const cssName = (key: string) =>
    key.startsWith("Webkit")
      ? `-webkit-${key.slice(6).replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`).replace(/^-/, "")}`
      : key.replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`);
  const declarations = Object.entries(inkMask).map(([key, value]) => `${cssName(key)}:${value}`).join(";");

  return (
    <div data-slot="invisible-ink" data-revealed={open} className={cn("relative", scope, className)} style={style} {...props}>
      {!open && (
        <svg aria-hidden="true" width="0" height="0" className="absolute" focusable="false">
          <filter id={filterId} x="-25%" y="-40%" width="150%" height="180%" colorInterpolationFilters="sRGB">
            {/* Spread each glyph into a cloud, then push the cloud's alpha back up so the specks the
                mask leaves behind are as bright as the text was. Native emits one particle per glyph
                pixel and lets them drift, which is what this approximates. */}
            <feGaussianBlur stdDeviation="1.3" />
            <feComponentTransfer><feFuncA type="linear" slope="3.6" intercept="-0.42" /></feComponentTransfer>
          </filter>
        </svg>
      )}
      {!open && (
        <style>{`${inkKeyframes}
.${scope} :is([data-slot="text"], [data-slot="ink-target"]) { ${declarations};filter:url(#${filterId}) }
.${scope}:not(:has([data-slot="text"], [data-slot="ink-target"])) > div:first-of-type { ${declarations};filter:url(#${filterId}) }`}</style>
      )}
      <div data-ink-masked={open ? undefined : ""}>{children}</div>
      {!open && (
        <button type="button" aria-label="Reveal message sent with Invisible Ink" aria-describedby={`${id}-hint`}
          onClick={() => set(true)} onPointerEnter={() => set(true)} onFocus={() => set(true)}
          className="absolute inset-0 cursor-default focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]">
          <span id={`${id}-hint`} className="sr-only">Hidden with Invisible Ink. Activate to reveal.</span>
        </button>
      )}
    </div>
  );
}

/** Convenience: run a bubble effect on the message row with `data-message-id={id}` inside `frame`. */
export function useBubbleEffectOnMessage(frame: RefObject<HTMLElement | null>, effect: { id: string; kind: BubbleEffectKind; progress?: number } | null | undefined) {
  useEffect(() => {
    if (!effect) return;
    const element = frame.current?.querySelector<HTMLElement>(`[data-message-id="${effect.id}"] [data-slot="bubble-frame"]`);
    if (!element) return;
    const handle = playBubbleEffect(element, effect.kind, { progress: effect.progress });
    return () => handle.cancel();
  }, [frame, effect]);
}

"use client";

import { useEffect, useRef, type CSSProperties } from "react";
import { cn } from "@/lib/utils";
import type { ScreenEffectKind } from "@/components/imessage/message-effects";

/**
 * Full-screen send effects, drawn on a canvas that covers the device frame.
 *
 * NOT MEASURED. No native recording of a screen effect exists in `references/`, so the particle
 * counts, colours and timings follow the well-known look rather than a capture. Re-derive them from a
 * recording before claiming fidelity.
 *
 * Every effect is a pure function of `t` (0..1) and the anchor rect: no wall clock, no `Math.random`,
 * no state carried between frames. The same `t` therefore paints the same pixels on every run and in
 * every engine, which is what makes the harness scrubbable and its screenshots stable.
 */
export const screenEffectDuration: Record<ScreenEffectKind, number> = {
  echo: 2400, spotlight: 2600, balloons: 4200, confetti: 4200, love: 2600,
  lasers: 3000, fireworks: 3600, celebration: 3600,
};

/**
 * The one frame each effect holds under `prefers-reduced-motion`: its fullest, calmest pose. The
 * canvas is painted once and never repainted, so nothing on screen moves.
 */
const stillFrame: Record<ScreenEffectKind, number> = {
  echo: 0.5, spotlight: 0.5, balloons: 0.62, confetti: 0.5, love: 0.55,
  lasers: 0.5, fireworks: 0.45, celebration: 0.5,
};

export type Anchor = { x: number; y: number; width: number; height: number };

type Frame = { context: CanvasRenderingContext2D; width: number; height: number; t: number; anchor: Anchor };

const TAU = Math.PI * 2;

function clamp01(value: number): number {
  return value < 0 ? 0 : value > 1 ? 1 : value;
}

/** 0 → 1 → 0, rising over the first `rise` of the effect and falling over the last `fall`. */
function envelope(t: number, rise: number, fall: number): number {
  return Math.min(1, clamp01(t) / rise) * Math.min(1, (1 - clamp01(t)) / fall);
}

function easeOut(value: number): number {
  const v = 1 - clamp01(value);
  return 1 - v * v * v;
}

/**
 * Deterministic value in [0,1) from an index and a channel. Integer operations only, so every engine
 * returns the same bits. The previous `fract(sin(seed) * 43758.5453)` did not: `Math.sin` is only
 * implementation-approximated, and measured across 600 seeds Chromium and WebKit disagreed on 15 of
 * them (worst delta 7.3e-12), which is enough to flip a `> 0.5` branch. `channel` keeps each stream
 * independent; the old code reused one seed with different offsets, so streams overlapped (fireworks'
 * angle jitter equalled its own spark reach on the first burst, which visibly clumped it).
 */
function hash(index: number, channel: number): number {
  let h = Math.imul(index ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(channel + 0x27d4eb2f, 0xc2b2ae35);
  h = Math.imul(h ^ (h >>> 15), 0x2c1b3c6d);
  h = Math.imul(h ^ (h >>> 12), 0x297a2d39);
  return ((h ^ (h >>> 15)) >>> 0) / 4294967296;
}

/** `roundRect` is recent in WebKit; `arcTo` draws the same path everywhere. */
function roundedRect(context: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {
  const radius = Math.min(r, w / 2, h / 2);
  context.beginPath();
  context.moveTo(x + radius, y);
  context.arcTo(x + w, y, x + w, y + h, radius);
  context.arcTo(x + w, y + h, x, y + h, radius);
  context.arcTo(x, y + h, x, y, radius);
  context.arcTo(x, y, x + w, y, radius);
  context.closePath();
}

/** Effects that happen against a night sky: the screen dims under them, as it does natively. */
const dims: Partial<Record<ScreenEffectKind, number>> = { fireworks: 0.82, lasers: 0.78 };

function drawBackdrop(kind: ScreenEffectKind, { context, width, height, t }: Frame) {
  const peak = dims[kind];
  if (!peak) return;
  // Holds until the last particle is gone, then lifts, rather than fading out from 83% while
  // fireworks are still bursting.
  const fade = envelope(t, 1 / 6, 0.08);
  context.fillStyle = `rgba(4,6,18,${(peak * fade).toFixed(3)})`;
  context.fillRect(0, 0, width, height);
}

const confettiColors = ["#ff3b30", "#ff9500", "#ffcc00", "#34c759", "#0088ff", "#af52de", "#ff2d55"];
const balloonColors = ["#ff3b30", "#ff9500", "#ffcc00", "#34c759", "#0088ff", "#af52de"];
const laserColors: ReadonlyArray<readonly [number, number, number]> = [
  [255, 45, 85], [255, 149, 0], [255, 214, 10], [52, 199, 89], [0, 199, 255], [0, 136, 255], [175, 82, 222],
];

/** `hsl()` rounds to bytes differently between engines; laser beams mix their own rgba instead. */
function rgba(color: readonly [number, number, number], alpha: number): string {
  return `rgba(${color[0]},${color[1]},${color[2]},${alpha.toFixed(3)})`;
}

function drawConfetti({ context, width, height, t }: Frame) {
  const count = 160;
  for (let i = 0; i < count; i++) {
    const local = t - hash(i, 1) * 0.35;
    if (local <= 0) continue;
    const x = hash(i, 2) * width + Math.sin((local * 3 + i) * 1.6) * 22;
    const y = -30 + local * (height + 160) * (0.75 + hash(i, 3) * 0.55);
    if (y > height + 30) continue;
    const size = 5 + hash(i, 4) * 5;
    context.save();
    context.translate(x, y);
    context.rotate((local * 6 + hash(i, 5) * 6) * (hash(i, 6) < 0.5 ? -1 : 1));
    context.globalAlpha = clamp01((1 - local) * 3);
    context.fillStyle = confettiColors[i % confettiColors.length];
    context.fillRect(-size / 2, -size / 4, size, size / 2);
    context.restore();
  }
}

function drawBalloons({ context, width, height, t }: Frame) {
  const count = 22;
  for (let i = 0; i < count; i++) {
    const local = t - hash(i, 11) * 0.3;
    if (local <= 0) continue;
    const x = 20 + hash(i, 12) * (width - 40) + Math.sin((local * 2 + i) * 1.2) * 14;
    const y = height + 80 - local * (height + 220) * (0.8 + hash(i, 13) * 0.5);
    if (y < -120) continue;
    const w = 26 + hash(i, 14) * 16;
    const h = w * 1.22;
    context.save();
    context.globalAlpha = Math.min(1, local * 6) * Math.min(1, (1 - local) * 4);
    context.fillStyle = balloonColors[i % balloonColors.length];
    context.beginPath();
    context.ellipse(x, y, w / 2, h / 2, 0, 0, TAU);
    context.fill();
    context.globalAlpha *= 0.22;
    context.fillStyle = "#ffffff";
    context.beginPath();
    context.ellipse(x - w * 0.17, y - h * 0.2, w * 0.16, h * 0.2, -0.4, 0, TAU);
    context.fill();
    context.restore();
    context.save();
    context.globalAlpha = Math.min(1, local * 6) * Math.min(1, (1 - local) * 4);
    context.beginPath();
    context.moveTo(x, y + h / 2);
    context.quadraticCurveTo(x + 5, y + h / 2 + 22, x, y + h / 2 + 44);
    context.strokeStyle = "rgba(0,0,0,0.25)";
    context.lineWidth = 1;
    context.stroke();
    context.restore();
  }
}

function heartPath(context: CanvasRenderingContext2D, x: number, y: number, size: number) {
  const s = size / 32;
  context.beginPath();
  context.moveTo(x, y + 10 * s);
  context.bezierCurveTo(x - 18 * s, y - 6 * s, x - 8 * s, y - 22 * s, x, y - 10 * s);
  context.bezierCurveTo(x + 8 * s, y - 22 * s, x + 18 * s, y - 6 * s, x, y + 10 * s);
  context.closePath();
}

function drawLove({ context, width, height, t, anchor }: Frame) {
  const originX = anchor.x + anchor.width / 2;
  const originY = anchor.y + anchor.height / 2;
  const size = 26 + easeOut(t / 0.42) * 210;
  // The heart grows out of the bubble and lifts, but it settles at a point that keeps it framed: the
  // old rise carried it off the top of the screen well before the effect ended.
  const lift = easeOut((t - 0.28) / 0.46);
  const centerX = originX + (width / 2 - originX) * lift;
  const centerY = originY + (Math.max(size * 0.55, height * 0.34) - originY) * lift;
  const out = clamp01((t - 0.78) / 0.22);
  // Continuous: the old beat switched off at t = 0.5 mid-swing and popped.
  const beat = 1 + Math.sin(t * 26) * 0.035 * (1 - clamp01(t / 0.7));
  const scale = beat * (1 + out * 0.18);
  context.save();
  context.globalAlpha = 1 - out;
  context.translate(centerX, centerY);
  context.scale(scale, scale);
  heartPath(context, 0, 0, size);
  context.fillStyle = "#ff2d55";
  context.fill();
  context.restore();
}

function drawFireworks({ context, width, height, t }: Frame) {
  const bursts = 8;
  for (let b = 0; b < bursts; b++) {
    // The last burst now closes at t = 0.999, so the sky is busy until the dim lifts and empty after.
    const local = (t - b * 0.0885) / 0.38;
    if (local <= 0 || local >= 1) continue;
    // Stratified by the golden ratio, then jittered: six raw hashes clumped in the upper left.
    const cx = width * (0.15 + (((b * 0.618034 + 0.18) % 1) * 0.7 + (hash(b, 21) - 0.5) * 0.05));
    const cy = height * (0.12 + (((b * 0.381966 + 0.4) % 1) * 0.44 + (hash(b, 22) - 0.5) * 0.05));
    const color = confettiColors[b % confettiColors.length];
    if (local < 0.2) {
      // The shell, before the sparks separate. White read as a gray smudge over the dim, so it burns
      // in the burst's own colour.
      const flash = 1 - local / 0.2;
      const glow = context.createRadialGradient(cx, cy, 0, cx, cy, 26 * (0.4 + local * 3));
      glow.addColorStop(0, `rgba(255,255,255,${(0.7 * flash).toFixed(3)})`);
      glow.addColorStop(0.45, `${color}${Math.round(0.55 * flash * 255).toString(16).padStart(2, "0")}`);
      glow.addColorStop(1, `${color}00`);
      context.globalAlpha = 1;
      context.fillStyle = glow;
      context.fillRect(cx - 90, cy - 90, 180, 180);
    }
    const sparks = 40;
    for (let i = 0; i < sparks; i++) {
      const seed = b * 128 + i;
      const angle = (i / sparks) * TAU + hash(seed, 23) * 0.14;
      const reach = (70 + hash(seed, 24) * 92) * easeOut(local);
      const x = cx + Math.cos(angle) * reach;
      const y = cy + Math.sin(angle) * reach + local * local * 48;
      context.globalAlpha = Math.pow(1 - local, 0.7);
      context.fillStyle = color;
      context.beginPath();
      context.arc(x, y, 2.7, 0, TAU);
      context.fill();
    }
  }
  context.globalAlpha = 1;
}

function drawCelebration({ context, width, height, t }: Frame) {
  const streams = 3;
  for (let s = 0; s < streams; s++) {
    const originX = width * (0.22 + s * 0.28);
    for (let i = 0; i < 64; i++) {
      const seed = s * 128 + i;
      const local = t - (s * 0.07 + hash(seed, 31) * 0.34);
      if (local <= 0) continue;
      // Split into horizontal and vertical speed: the old single speed with a shallow gravity term
      // peaked around 200 px, so every stream stayed inside the bottom quarter of the screen.
      const vx = (hash(seed, 32) - 0.5) * 420;
      const vy = 1750 + hash(seed, 33) * 1250;
      const x = originX + vx * local;
      const y = height + 12 - vy * local + 2600 * local * local;
      if (y > height + 40 || y < -40 || x < -40 || x > width + 40) continue;
      context.globalAlpha = clamp01((1 - local) * 2.4);
      context.fillStyle = i % 3 === 0 ? "#ffd60a" : confettiColors[i % confettiColors.length];
      context.beginPath();
      context.arc(x, y, 2.1 + hash(seed, 34) * 1.4, 0, TAU);
      context.fill();
    }
  }
  context.globalAlpha = 1;
}

function drawLasers({ context, width, height, t, anchor }: Frame) {
  // Anchored: the beams leave the message and sweep out to the edges of the screen.
  const cx = anchor.x + anchor.width / 2;
  const cy = anchor.y + anchor.height / 2;
  const reach = Math.hypot(width, height);
  const beams = 12;
  const fade = envelope(t, 0.12, 0.14);
  if (fade <= 0) return;
  context.save();
  context.globalCompositeOperation = "lighter";
  // Beams leave the edge of the bubble rather than its centre, so the message stays readable.
  const inset = Math.max(anchor.width, anchor.height) * 0.42;
  for (let i = 0; i < beams; i++) {
    const side = i % 2 === 0 ? 1 : -1;
    const lane = Math.floor(i / 2) / (beams / 2 - 1) - 0.5;
    const angle = lane * 0.92 + Math.sin((t * 1.7 + i / beams) * TAU) * 0.34 * side;
    const dirX = Math.cos(angle) * side;
    const dirY = Math.sin(angle) * side;
    const startX = cx + dirX * inset;
    const startY = cy + dirY * inset;
    const endX = cx + dirX * reach;
    const endY = cy + dirY * reach;
    const color = laserColors[i % laserColors.length];
    const gradient = context.createLinearGradient(startX, startY, endX, endY);
    gradient.addColorStop(0, rgba(color, 0.9 * fade));
    gradient.addColorStop(0.55, rgba(color, 0.5 * fade));
    gradient.addColorStop(1, rgba(color, 0));
    context.strokeStyle = gradient;
    context.lineCap = "round";
    context.lineWidth = 9;
    context.globalAlpha = 0.3;
    context.beginPath();
    context.moveTo(startX, startY);
    context.lineTo(endX, endY);
    context.stroke();
    context.lineWidth = 2.2;
    context.globalAlpha = 1;
    context.stroke();
  }
  const halo = context.createRadialGradient(cx, cy, inset * 0.5, cx, cy, inset + 70);
  halo.addColorStop(0, `rgba(255,255,255,${(0.16 * fade).toFixed(3)})`);
  halo.addColorStop(1, "rgba(255,255,255,0)");
  context.globalAlpha = 1;
  context.fillStyle = halo;
  context.fillRect(cx - inset - 80, cy - inset - 80, (inset + 80) * 2, (inset + 80) * 2);
  context.restore();
}

function drawSpotlight({ context, width, height, t, anchor }: Frame) {
  const fade = envelope(t, 0.25, 0.25);
  if (fade <= 0) return;
  const cx = anchor.x + anchor.width / 2;
  const cy = anchor.y + anchor.height / 2;
  // The beam opens wide and closes onto the bubble.
  const radius = (Math.max(anchor.width, anchor.height) * 0.75 + 90) * (1.45 - 0.45 * easeOut(t / 0.45));
  context.save();
  context.fillStyle = `rgba(0,0,0,${(0.72 * fade).toFixed(3)})`;
  context.fillRect(0, 0, width, height);
  // Punched at full alpha. Sharing the dim's alpha here left the middle of the beam 20% black, so the
  // message under the spotlight came out darker than the rest of the conversation.
  context.globalCompositeOperation = "destination-out";
  const beam = context.createRadialGradient(cx, cy, radius * 0.34, cx, cy, radius);
  beam.addColorStop(0, "rgba(0,0,0,1)");
  beam.addColorStop(1, "rgba(0,0,0,0)");
  context.fillStyle = beam;
  context.beginPath();
  context.arc(cx, cy, radius, 0, TAU);
  context.fill();
  context.restore();
}

function drawEcho({ context, width, height, t, anchor }: Frame) {
  const copies = 18;
  const spread = Math.hypot(width, height) * 0.46;
  const w = anchor.width;
  const h = anchor.height;
  const radius = Math.min(19, h / 2);
  for (let i = 0; i < copies; i++) {
    const local = (t - i * 0.021) / 0.62;
    if (local <= 0 || local >= 1) continue;
    // Golden angle: random angles clumped the copies on one side of the bubble.
    const angle = i * 2.39996 + hash(i, 51) * 0.6;
    const drift = easeOut(local) * spread * (0.5 + hash(i, 52) * 0.7);
    // Each copy keeps its own size and grows a little, so they still read as bubbles; scaling to 2.4x
    // turned the late ones into bars wider than the screen.
    const scale = (0.6 + hash(i, 54) * 0.5) * (0.85 + local * 0.75);
    context.save();
    context.globalAlpha = Math.min(1, local * 6) * (1 - local) * 0.6;
    context.translate(anchor.x + w / 2 + Math.cos(angle) * drift, anchor.y + h / 2 + Math.sin(angle) * drift);
    context.rotate((hash(i, 53) - 0.5) * 0.3);
    context.scale(scale, scale);
    context.fillStyle = "#0088ff";
    roundedRect(context, -w / 2, -h / 2, w, h, radius);
    context.fill();
    context.restore();
  }
}

const painters: Record<ScreenEffectKind, (frame: Frame) => void> = {
  confetti: drawConfetti, balloons: drawBalloons, love: drawLove, fireworks: drawFireworks,
  celebration: drawCelebration, lasers: drawLasers,
  spotlight: drawSpotlight, echo: drawEcho,
};

export type ScreenEffectProps = {
  kind: ScreenEffectKind;
  /** Scrub position 0..1. Omit to play once. */
  progress?: number;
  /** Bump to replay. */
  replay?: number;
  /**
   * The bubble the effect radiates from, in frame coordinates. Echo, spotlight, lasers and love use
   * it. Without one the bubble named by `anchorMessageId` is measured, then the last outgoing bubble
   * in the frame, then a point above the composer.
   */
  anchor?: Anchor;
  /** The message the effect was sent with, when the host would rather name it than measure it. */
  anchorMessageId?: string;
  onDone?: () => void;
  className?: string;
  style?: CSSProperties;
};

/** Absolutely positioned canvas; put it inside the device frame with `inset-0`. */
export function ScreenEffect({ kind, progress, replay, anchor, anchorMessageId, onDone, className, style }: ScreenEffectProps) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const done = useRef(onDone);
  const anchorRef = useRef(anchor);
  // The clock lives outside the effect so a re-render (a new `anchor` object, a parent state change)
  // re-syncs the canvas without restarting the animation from zero.
  const startedAt = useRef(0);
  const finished = useRef(false);

  // Declared first, so both are current before the painting effect below re-runs.
  useEffect(() => { done.current = onDone; anchorRef.current = anchor; });
  useEffect(() => { startedAt.current = 0; finished.current = false; }, [kind, replay]);

  const anchorKey = anchor ? `${anchor.x},${anchor.y},${anchor.width},${anchor.height}` : "";
  useEffect(() => {
    const element = canvas.current;
    const parent = element?.parentElement;
    if (!element || !parent) return;
    const context = element.getContext("2d");
    if (!context) return;
    const reduced = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;
    let raf = 0;
    let width = 0, height = 0;
    let fallback: Anchor = { x: 0, y: 0, width: 120, height: 40 };

    /** Where the effect radiates from when the host passes no anchor. */
    const measureAnchor = (frameRect: DOMRect): Anchor => {
      const named = anchorMessageId
        ? parent.querySelector<HTMLElement>(`[data-message-id="${CSS.escape(anchorMessageId)}"] [data-slot="bubble"]`)
        : null;
      const outgoing = parent.querySelectorAll<HTMLElement>('[data-slot="message-bubble"][data-direction="outgoing"] [data-slot="bubble"]');
      const rect = (named ?? outgoing[outgoing.length - 1])?.getBoundingClientRect();
      if (rect && rect.width > 0 && rect.height > 0) {
        return { x: rect.left - frameRect.left, y: rect.top - frameRect.top, width: rect.width, height: rect.height };
      }
      return { x: width * 0.5 - 60, y: height * 0.62, width: 120, height: 40 };
    };

    const size = () => {
      // The frame, not the canvas: a canvas is a replaced element, so `inset-0` alone leaves it at its
      // intrinsic size. The explicit CSS size below is what stretches it over the frame.
      const rect = parent.getBoundingClientRect();
      const dpr = Math.min(3, window.devicePixelRatio || 1);
      width = Math.max(1, Math.round(rect.width));
      height = Math.max(1, Math.round(rect.height));
      const backingWidth = Math.round(width * dpr);
      const backingHeight = Math.round(height * dpr);
      // Assigning `width` resets the bitmap even when the value is unchanged, which would blank the
      // canvas for a frame every time this effect re-runs.
      if (element.width !== backingWidth || element.height !== backingHeight) {
        element.width = backingWidth;
        element.height = backingHeight;
      }
      element.style.width = `${width}px`;
      element.style.height = `${height}px`;
      context.setTransform(dpr, 0, 0, dpr, 0, 0);
      fallback = measureAnchor(rect);
    };

    const paint = (value: number) => {
      context.clearRect(0, 0, width, height);
      const frame: Frame = { context, width, height, t: clamp01(value), anchor: anchorRef.current ?? fallback };
      context.save();
      drawBackdrop(kind, frame);
      painters[kind](frame);
      context.restore();
    };

    size();
    // Scrubbed by the harness: one frame, no clock, no callback.
    if (progress !== undefined) { paint(progress); return; }

    const duration = screenEffectDuration[kind];
    if (reduced) {
      // Static and calm: one representative frame, held. A single timer still retires the effect so
      // the host clears the overlay, and it is cleared on unmount.
      paint(stillFrame[kind]);
      if (finished.current) return;
      if (!startedAt.current) startedAt.current = performance.now();
      const remaining = Math.max(0, duration - (performance.now() - startedAt.current));
      const timer = window.setTimeout(() => { finished.current = true; done.current?.(); }, remaining);
      return () => window.clearTimeout(timer);
    }
    if (finished.current) { paint(1); return; }

    const step = (now: number) => {
      if (!startedAt.current) startedAt.current = now;
      const t = (now - startedAt.current) / duration;
      paint(t);
      if (t < 1) { raf = requestAnimationFrame(step); return; }
      finished.current = true;
      done.current?.();
    };
    // Repaint the frame the clock is already on, so a re-run never shows an empty canvas.
    if (startedAt.current) paint((performance.now() - startedAt.current) / duration);
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [kind, progress, replay, anchorKey, anchorMessageId]);

  return <canvas ref={canvas} aria-hidden="true" data-slot="screen-effect" data-effect={kind} className={cn("pointer-events-none absolute inset-0", className)} style={style} />;
}

"use client";

import { useEffect, useRef, useState, type ComponentProps, type CSSProperties, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { fontStack } from "@/components/imessage/tokens";
import { InvisibleInk, bubbleEffects, screenEffects, type BubbleEffectKind, type ScreenEffectKind } from "@/components/imessage/message-effects";

/**
 * "Send with effect", the screen iOS shows when you press and hold the send button.
 *
 * Measured from `references/ios/captures/effects-picker-light.png` (nothing chosen),
 * `effects-slam-light.png` (a bubble effect chosen) and `effects-screen-light.png` (the Screen tab),
 * all iOS 26 on a 402x874 pt screen captured at 3x.
 *
 * The layout is not a list. The conversation freezes and blurs behind; the message being sent is
 * previewed as a real bubble; the four bubble effects live in a white vertical rail on the trailing
 * edge, each row a right-aligned label plus a dot. Choosing one turns that row's dot into the send
 * button, moves the preview up alongside it, replaces that row's label with "SEND WITH <NAME>" above
 * the bubble, and dims the labels of the rows that were not chosen. The Screen tab drops the rail
 * entirely and stacks the send button above the close button.
 */
export const effectsPickerMetrics = {
  /** Everything below is in points on the 402x874 screen the numbers were measured from. */
  frame: { width: 402, height: 874 },
  title: { capTop: 96, baseline: 112, fontSize: 22, centerX: 201 },
  segment: { left: 81, top: 132, width: 240, height: 32, radius: 16, inset: 2, fontSize: 13, labelCapTop: 143, selectedWeight: 600, weight: 400 },
  rail: { left: 321.75, top: 572, width: 53.75, height: 214.67, radius: 23, rowPitch: 57, firstRowCenter: 593.67 },
  dot: { size: 9, centerX: 348.5 },
  /** The chosen row's dot becomes a send button the same size as the close button. */
  send: { width: 38, height: 28, centerX: 348.5, screenCenterY: 765.83 },
  close: { width: 38, height: 28, centerX: 348.5, centerY: 825.83 },
  /** Row labels and the caption share one type style and one right ink edge. */
  label: { rightInk: 298.33, bearing: 1.2, fontSize: 11.33, weight: 400, capHeight: 8.33, tracking: 0, dimOpacity: 0.44 },
  /**
   * The caption sits above the preview. The Screen tab really does set it a third of a point smaller
   * and 3.33 pt further left: three different Screen captions measure a right ink edge of 294.67 and
   * an 11 pt body, against 298.33 and 11.33 for every Bubble one.
   */
  caption: { rightInk: 298.33, gapAboveBubble: 8.67, screenRightInk: 294.67, screenFontSize: 11, screenGapAboveBubble: 7 },
  /**
   * The preview bubble. It rests low on the screen until an effect is chosen, then rises to the
   * chosen row and slides 14.33 pt toward the rail. Both right edges are measured, not derived.
   */
  preview: {
    restingTop: 792,
    restingRight: 301.33,
    chosenRight: 315.67,
    chosenTopFromRowCenter: -17.33,
    screenTop: 731,
    screenRight: 301.33,
    maxWidth: 280.5,
    /**
     * The preview never drops below this. Fitted from the Invisible Ink capture, where the fourth
     * row would otherwise put the bubble's bottom at 834.34 and it sits at 827.33 instead.
     */
    maxBottom: 827.33,
  },
  /**
   * The preview bubble is a flat #0088ff, not the conversation's screen-space gradient: the same
   * bubble measures (0, 136, 255) at y 578 and again at y 871 across the four captures.
   */
  previewFill: "#0088ff",
  /**
   * The Screen tab pages through its effects and shows a dot per effect under the preview. There are
   * eight dots in iOS 26, and the eighth is the last: swiping past Celebration goes nowhere.
   */
  pageDots: { size: 7.67, pitch: 17.62, firstCenterX: 139.17, centerY: 807 },
  /** Time the whole screen takes to appear and to leave. */
  timing: { enter: 260, exit: 200, move: 320 },
} as const;

/**
 * Where the cap top falls inside a `line-height: 1` box, as a fraction of the font size.
 * The captures record positions as cap tops, so every text offset here goes through this.
 * The ratio is calibrated by rendering, not taken from font tables: browsers snap a baseline to a
 * device pixel, so the best single ratio lands every label within one device pixel at 3x.
 */
function capTopInset(fontSize: number) {
  return fontSize * 0.1145;
}

/**
 * Apple's continuous corner, the same profile the composer and nav bar use. A circular corner is up
 * to 0.9 pt too tight along the flank of a rail this wide. Browsers without `corner-shape` fall back
 * to a plain round corner.
 */
const continuous = { cornerShape: "superellipse(1.14)" } as CSSProperties;

/**
 * Light values are measured off the three captures; the dark set follows the same iOS system colours
 * the rest of the kit uses. They are custom properties so a `.dark` ancestor flips the whole screen
 * without the caller passing anything.
 */
const vars =
  "[--ios-fx-backdrop:rgba(233,236,242,0.86)] [--ios-fx-title:rgba(60,60,67,0.66)] [--ios-fx-track:rgba(120,120,128,0.16)] [--ios-fx-pill:#ffffff] [--ios-fx-tab:#000000] [--ios-fx-rail:#ffffff] [--ios-fx-dot:#999999] [--ios-fx-label:rgba(60,60,67,0.75)] [--ios-fx-close:#808080] [--ios-fx-send:#0088ff] [--ios-fx-glyph:#ffffff] " +
  "dark:[--ios-fx-backdrop:rgba(10,10,12,0.9)] dark:[--ios-fx-title:rgba(255,255,255,0.8)] dark:[--ios-fx-track:rgba(120,120,128,0.24)] dark:[--ios-fx-pill:#636366] dark:[--ios-fx-tab:#ffffff] dark:[--ios-fx-rail:rgba(255,255,255,0.14)] dark:[--ios-fx-dot:rgba(255,255,255,0.24)] dark:[--ios-fx-label:rgba(255,255,255,0.8)]";

const c = {
  backdrop: "var(--ios-fx-backdrop)",
  title: "var(--ios-fx-title)",
  segmentTrack: "var(--ios-fx-track)",
  segmentPill: "var(--ios-fx-pill)",
  segmentLabel: "var(--ios-fx-tab)",
  rail: "var(--ios-fx-rail)",
  dot: "var(--ios-fx-dot)",
  label: "var(--ios-fx-label)",
  close: "var(--ios-fx-close)",
  send: "var(--ios-fx-send)",
  glyph: "var(--ios-fx-glyph)",
};

export type EffectsPickerSelection = { bubble: BubbleEffectKind } | { screen: ScreenEffectKind } | null;

export type IosEffectsPickerProps = Omit<ComponentProps<"div">, "onSelect" | "children"> & {
  tab?: "bubble" | "screen";
  onTabChange?: (tab: "bubble" | "screen") => void;
  selection?: EffectsPickerSelection;
  onSelect?: (selection: EffectsPickerSelection) => void;
  /** Fires when the chosen effect's send control is activated. */
  onSend?: (selection: EffectsPickerSelection) => void;
  onClose?: () => void;
  /** False plays the exit timeline and then calls `onExited`. */
  open?: boolean;
  onExited?: () => void;
  /** Seek the entrance to this fraction (0..1) instead of playing it, which is what the harness does. */
  progress?: number;
  /** The message being sent, rendered as the preview bubble. */
  preview: ReactNode;
};

function UpArrow() {
  // 13 x 15.67 pt of ink, 2 pt stroke, measured off the send button in effects-slam-light.png.
  return (
    <svg aria-hidden="true" width="13" height="15.67" viewBox="0 0 13 15.67" fill="none">
      <path d="M6.5 14.67V1M1.2 5.7 6.5 1l5.3 4.7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function Cross() {
  // 13.67 pt square of ink, 2 pt stroke.
  return (
    <svg aria-hidden="true" width="13.67" height="13.67" viewBox="0 0 13.67 13.67" fill="none">
      <path d="M1 1l11.67 11.67M12.67 1 1 12.67" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
    </svg>
  );
}

/** A label or caption placed by its cap top and its right ink edge, the way the captures measure it. */
function InkLabel({ rightInk, capTop, fontSize, dim, style, children, ...props }: ComponentProps<"span"> & { rightInk: number; capTop: number; fontSize: number; dim?: boolean }) {
  const m = effectsPickerMetrics;
  return (
    <span
      {...props}
      style={{
        position: "absolute",
        right: m.frame.width - rightInk - m.label.bearing,
        top: capTop - capTopInset(fontSize),
        fontSize,
        lineHeight: 1,
        fontWeight: m.label.weight,
        letterSpacing: m.label.tracking,
        whiteSpace: "nowrap",
        textAlign: "right",
        opacity: dim ? m.label.dimOpacity : 1,
        transition: "opacity 220ms ease",
        ...style,
      }}
    >
      {children}
    </span>
  );
}

export function IosEffectsPicker({
  tab: tabProp,
  onTabChange,
  selection = null,
  onSelect,
  onSend,
  onClose,
  open = true,
  onExited,
  progress,
  preview,
  className,
  style,
  ...props
}: IosEffectsPickerProps) {
  const [internalTab, setInternalTab] = useState<"bubble" | "screen">("bubble");
  const tab = tabProp ?? internalTab;
  const setTab = (next: "bubble" | "screen") => {
    if (tabProp === undefined) setInternalTab(next);
    onTabChange?.(next);
  };
  const m = effectsPickerMetrics;
  const root = useRef<HTMLDivElement>(null);
  const rail = useRef<HTMLDivElement>(null);
  const previewBox = useRef<HTMLDivElement>(null);
  const exited = useRef(false);

  useEffect(() => {
    exited.current = false;
  }, []);

  /**
   * The screen is modal, so it takes focus when it opens (a scrubbed entrance does not: the harness
   * seeks frames and must not move the caret) and gives Escape back wherever focus happens to be.
   * The root carries `outline-none`: it is a focus holder, not a control, and must paint nothing.
   */
  useEffect(() => {
    if (!open || progress !== undefined) return;
    root.current?.focus({ preventScroll: true });
  }, [open, progress]);
  useEffect(() => {
    if (!open || !onClose) return;
    const onKey = (event: globalThis.KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); onClose(); } };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  useEffect(() => {
    const node = root.current;
    if (!node) return;
    if (open) {
      const entrance = node.animate([{ opacity: 0 }, { opacity: 1 }], { duration: m.timing.enter, easing: "cubic-bezier(0.32, 0.72, 0, 1)", fill: "both" });
      if (progress === undefined) return;
      // Seeked, not played: a scrubbed checkpoint has to land on the same frame every run.
      entrance.pause();
      entrance.currentTime = Math.max(0, Math.min(1, progress)) * m.timing.enter;
      return () => entrance.cancel();
    }
    const animation = node.animate([{ opacity: 1 }, { opacity: 0 }], { duration: m.timing.exit, easing: "ease-out", fill: "forwards" });
    const finish = () => {
      if (exited.current) return;
      exited.current = true;
      onExited?.();
    };
    animation.addEventListener("finish", finish);
    return () => animation.removeEventListener("finish", finish);
  }, [open, progress, m.timing.enter, m.timing.exit, onExited]);

  const chosenBubble = selection && "bubble" in selection ? selection.bubble : null;
  const chosenScreen = selection && "screen" in selection ? selection.screen : null;
  const chosenIndex = chosenBubble ? bubbleEffects.findIndex(effect => effect.kind === chosenBubble) : -1;
  const chosenTitle = chosenBubble
    ? bubbleEffects.find(effect => effect.kind === chosenBubble)?.title
    : chosenScreen
      ? screenEffects.find(effect => effect.kind === chosenScreen)?.title
      : null;
  const caption = chosenTitle ? `SEND WITH ${chosenTitle.toUpperCase()}` : null;

  const onScreenTab = tab === "screen";
  const [previewHeight, setPreviewHeight] = useState(0);
  const rowTop = chosenIndex >= 0 ? m.rail.firstRowCenter + chosenIndex * m.rail.rowPitch + m.preview.chosenTopFromRowCenter : 0;
  const previewTop = chosenIndex >= 0
    ? (previewHeight > 0 ? Math.min(rowTop, m.preview.maxBottom - previewHeight) : rowTop)
    : onScreenTab
      ? m.preview.screenTop
      : m.preview.restingTop;
  const previewRight = chosenIndex >= 0 ? m.preview.chosenRight : onScreenTab ? m.preview.screenRight : m.preview.restingRight;
  const captionGap = onScreenTab ? m.caption.screenGapAboveBubble : m.caption.gapAboveBubble;
  const captionFontSize = onScreenTab ? m.caption.screenFontSize : m.label.fontSize;
  const captionRightInk = onScreenTab ? m.caption.screenRightInk : m.caption.rightInk;

  // The bubble fill is a screen-space gradient, so the preview has to say where it sits on the
  // screen. The picker fills the frame, which makes that its own offset plus its measured height.
  useEffect(() => {
    const node = previewBox.current;
    if (!node) return;
    const sync = () => {
      setPreviewHeight(node.offsetHeight);
      node.style.setProperty("--bubble-bottom", `${previewTop + node.offsetHeight}px`);
    };
    sync();
    const observer = new ResizeObserver(sync);
    observer.observe(node);
    return () => observer.disconnect();
  }, [previewTop, preview]);

  return (
    <div
      ref={root}
      data-slot="ios-effects-picker"
      role="dialog"
      aria-modal="true"
      aria-label="Send with effect"
      tabIndex={-1}
      className={cn("absolute inset-0 select-none outline-none", vars, className)}
      style={{
        fontFamily: fontStack,
        background: c.backdrop,
        backdropFilter: "blur(45px) saturate(1.6)",
        WebkitBackdropFilter: "blur(45px) saturate(1.6)",
        ...style,
      }}
      {...props}
    >
      <div
        data-slot="effects-title"
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: m.title.capTop - capTopInset(m.title.fontSize),
          textAlign: "center",
          fontSize: m.title.fontSize,
          lineHeight: 1,
          color: c.title,
        }}
      >
        Send with effect
      </div>

      <div
        data-slot="effects-tabs"
        role="tablist"
        aria-label="Effect kind"
        onKeyDown={event => {
          if (event.key !== "ArrowLeft" && event.key !== "ArrowRight" && event.key !== "Home" && event.key !== "End") return;
          event.preventDefault();
          const next = event.key === "Home" ? "bubble" : event.key === "End" ? "screen" : event.key === "ArrowRight" ? "screen" : "bubble";
          if (next !== tab) setTab(next);
          event.currentTarget.querySelector<HTMLButtonElement>(`[data-tab="${next}"]`)?.focus();
        }}
        style={{
          position: "absolute",
          left: m.segment.left,
          top: m.segment.top,
          width: m.segment.width,
          height: m.segment.height,
          borderRadius: m.segment.radius,
          background: c.segmentTrack,
        }}
      >
        <span
          aria-hidden="true"
          data-slot="effects-tab-pill"
          style={{
            position: "absolute",
            top: m.segment.inset,
            left: onScreenTab ? m.segment.width / 2 + m.segment.inset : m.segment.inset,
            width: m.segment.width / 2 - m.segment.inset * 2,
            height: m.segment.height - m.segment.inset * 2,
            borderRadius: (m.segment.height - m.segment.inset * 2) / 2,
            background: c.segmentPill,
            boxShadow: "0 3px 8px rgba(0, 0, 0, 0.12), 0 3px 1px rgba(0, 0, 0, 0.04)",
            transition: "left 220ms cubic-bezier(0.32, 0.72, 0, 1)",
          }}
        />
        {(["bubble", "screen"] as const).map((value, index) => (
          <button
            key={value}
            type="button"
            role="tab"
            aria-selected={tab === value}
            data-tab={value}
            tabIndex={tab === value ? 0 : -1}
            onClick={() => setTab(value)}
            style={{
              position: "absolute",
              top: 0,
              left: index * (m.segment.width / 2),
              width: m.segment.width / 2,
              height: m.segment.height,
              background: "transparent",
              border: 0,
              padding: 0,
              fontFamily: "inherit",
              fontSize: m.segment.fontSize,
              fontWeight: tab === value ? m.segment.selectedWeight : m.segment.weight,
              color: c.segmentLabel,
              cursor: "default",
            }}
          >
            <span
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top: m.segment.labelCapTop - m.segment.top - capTopInset(m.segment.fontSize),
                lineHeight: 1,
              }}
            >
              {value === "bubble" ? "Bubble" : "Screen"}
            </span>
          </button>
        ))}
      </div>

      {caption && (
        <InkLabel
          data-slot="effects-caption"
          rightInk={captionRightInk}
          capTop={previewTop - captionGap - m.label.capHeight}
          fontSize={captionFontSize}
          style={{ color: c.label, transition: "top 320ms cubic-bezier(0.32, 0.72, 0, 1)" }}
        >
          {caption}
        </InkLabel>
      )}

      {/* Labels sit outside the rail so the rail's own bounds never clip them. */}
      {!onScreenTab &&
        bubbleEffects.map((effect, index) => {
          const chosen = chosenBubble === effect.kind;
          if (chosen) return null;
          const centerY = m.rail.firstRowCenter + index * m.rail.rowPitch;
          return (
            <InkLabel
              key={effect.kind}
              aria-hidden="true"
              data-slot="effects-row-label"
              rightInk={m.label.rightInk}
              capTop={centerY - m.label.capHeight / 2}
              fontSize={m.label.fontSize}
              dim={chosenIndex >= 0}
              style={{ color: c.label }}
            >
              {effect.title.toUpperCase()}
            </InkLabel>
          );
        })}

      <div
        ref={previewBox}
        data-slot="effects-preview"
        style={{
          position: "absolute",
          right: m.frame.width - previewRight,
          top: previewTop,
          width: m.preview.maxWidth,
          display: "flex",
          justifyContent: "flex-end",
          transition: `top ${m.timing.move}ms cubic-bezier(0.32, 0.72, 0, 1), right ${m.timing.move}ms cubic-bezier(0.32, 0.72, 0, 1)`,
          ["--im-blue-top" as string]: m.previewFill,
          ["--im-blue-bottom" as string]: m.previewFill,
        }}
      >
        {chosenBubble === "invisible-ink" ? <InvisibleInk revealed={false}>{preview}</InvisibleInk> : preview}
      </div>

      {!onScreenTab && (
        <div
          ref={rail}
          data-slot="effects-rail"
          role="radiogroup"
          aria-label="Bubble effects"
          onKeyDown={event => {
            const keys = ["ArrowDown", "ArrowRight", "ArrowUp", "ArrowLeft", "Home", "End"];
            if (!keys.includes(event.key)) return;
            event.preventDefault();
            const radios = Array.from(rail.current?.querySelectorAll<HTMLButtonElement>('[role="radio"]') ?? []);
            if (!radios.length) return;
            const from = radios.indexOf(document.activeElement as HTMLButtonElement);
            const current = from < 0 ? Math.max(0, chosenIndex) : from;
            const next = event.key === "Home" ? 0
              : event.key === "End" ? radios.length - 1
                : event.key === "ArrowDown" || event.key === "ArrowRight" ? (current + 1) % radios.length
                  : (current - 1 + radios.length) % radios.length;
            // A radio group moves and chooses together, which is also what the rail's preview does.
            radios[next]?.focus();
            onSelect?.({ bubble: bubbleEffects[next].kind });
          }}
          style={{
            position: "absolute",
            left: m.rail.left,
            top: m.rail.top,
            width: m.rail.width,
            height: m.rail.height,
            borderRadius: m.rail.radius,
            ...continuous,
            background: c.rail,
          }}
        >
          {bubbleEffects.map((effect, index) => {
            const centerY = m.rail.firstRowCenter - m.rail.top + index * m.rail.rowPitch;
            const chosen = chosenBubble === effect.kind;
            return (
              <button
                key={effect.kind}
                type="button"
                role="radio"
                aria-checked={chosen}
                aria-label={chosen ? `Send with ${effect.title}` : effect.title}
                tabIndex={chosen || (chosenIndex < 0 && index === 0) ? 0 : -1}
                onClick={() => (chosen ? onSend?.({ bubble: effect.kind }) : onSelect?.({ bubble: effect.kind }))}
                style={{
                  position: "absolute",
                  left: (m.rail.width - (chosen ? m.send.width : m.dot.size)) / 2,
                  top: centerY - (chosen ? m.send.height : m.dot.size) / 2,
                  width: chosen ? m.send.width : m.dot.size,
                  height: chosen ? m.send.height : m.dot.size,
                  borderRadius: chosen ? m.send.height / 2 : m.dot.size / 2,
                  background: chosen ? c.send : c.dot,
                  color: c.glyph,
                  border: 0,
                  padding: 0,
                  cursor: "default",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  transition: "width 220ms cubic-bezier(0.32, 0.72, 0, 1), height 220ms cubic-bezier(0.32, 0.72, 0, 1), left 220ms cubic-bezier(0.32, 0.72, 0, 1), top 220ms cubic-bezier(0.32, 0.72, 0, 1), background-color 220ms ease",
                }}
              >
                {chosen && <UpArrow />}
              </button>
            );
          })}
        </div>
      )}

      {onScreenTab && (
        <div data-slot="effects-pages" aria-hidden="true" style={{ position: "absolute", left: 0, top: m.pageDots.centerY - m.pageDots.size / 2, height: m.pageDots.size }}>
          {screenEffects.map((effect, index) => (
            <span
              key={effect.kind}
              style={{
                position: "absolute",
                left: m.pageDots.firstCenterX + index * m.pageDots.pitch - m.pageDots.size / 2,
                width: m.pageDots.size,
                height: m.pageDots.size,
                borderRadius: m.pageDots.size / 2,
                background: c.label,
                opacity: chosenScreen === effect.kind ? 1 : m.label.dimOpacity,
                transition: "opacity 220ms ease",
              }}
            />
          ))}
        </div>
      )}

      {onScreenTab && (
        <button
          type="button"
          data-slot="effects-send"
          aria-label={chosenTitle ? `Send with ${chosenTitle}` : "Send"}
          onClick={() => onSend?.(selection)}
          style={{
            position: "absolute",
            left: m.send.centerX - m.send.width / 2,
            top: m.send.screenCenterY - m.send.height / 2,
            width: m.send.width,
            height: m.send.height,
            borderRadius: m.send.height / 2,
            background: c.send,
            color: c.glyph,
            border: 0,
            padding: 0,
            cursor: "default",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <UpArrow />
        </button>
      )}

      <button
        type="button"
        data-slot="effects-close"
        aria-label="Cancel"
        onClick={onClose}
        style={{
          position: "absolute",
          left: m.close.centerX - m.close.width / 2,
          top: m.close.centerY - m.close.height / 2,
          width: m.close.width,
          height: m.close.height,
          borderRadius: m.close.height / 2,
          background: c.close,
          color: c.glyph,
          border: 0,
          padding: 0,
          cursor: "default",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <Cross />
      </button>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type ComponentProps, type CSSProperties, type KeyboardEvent as ReactKeyboardEvent, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { bodyClipPath, tailBox, tailPath, tailSeamOverlap } from "@/components/imessage/bubble-shape";
import { bubbleMetrics, fontStack, type Direction, type Service } from "@/components/imessage/tokens";
import { MessageBubble } from "@/components/imessage/message-bubble";

/**
 * Inline replies: the quoted stub above a reply, the "N replies" affordance under a message that has
 * a thread, and the focused thread view.
 *
 * PARTLY MEASURED. No native capture of a reply thread exists in `references/`, so the two numbers
 * that describe the stub itself stay provisional: it is drawn at `stubScale` (0.76) of the quoted
 * bubble and at `stubOpacity` (55%). What the stub is built from is measured, and is derived here
 * rather than guessed:
 *
 * - Type, padding, radius, minimum width, tail and maximum width are the platform's measured bubble
 *   metrics multiplied by `stubScale`, so the stub is a real bubble at 76% rather than a picture of
 *   one. It is laid out at that size (no `transform: scale`), which matters for three measured
 *   behaviours: the stub's own edge lands exactly on the reply bubble's measured edge inset, its
 *   screen-space gradient stays in screen coordinates, and `MessageBubble`'s shrink-to-fit still
 *   measures line boxes in unscaled px (under a transform, `getClientRects` returns scaled px and the
 *   bubble sets a frame `scale` too narrow; `message-actions.tsx` documents the same trap).
 * - The gap under the stub is the measured cluster gap (4.33 iOS / 3 macOS), body bottom to body top,
 *   or the measured between-cluster gap (10.33 / 11.5) when the stub carries a tail, that being the
 *   one measured gap a tail is known to hang into. Tails take no layout space, as measured.
 * - A long quote is clamped to `stubMaxLines` with an ellipsis instead of wrapping without limit. Two
 *   lines is what the measured conversation-list preview uses on both platforms and the stub is the
 *   same kind of quotation, but nothing has been measured on the stub itself.
 * - The stub's tail is off by default. The measured rule ("only the last bubble of a cluster has a
 *   tail") would give a lone quoted copy one, but no capture shows the stub, so it stays a prop. When
 *   it is on, the tail is drawn outside the body and nothing on the stub clips it.
 *
 * The reply count reuses the measured secondary label ("Delivered": 11pt / 10pt semibold, its
 * tracking, its gap under the bubble, and #8a8a8e / #808080) rather than a size and colour of its own.
 *
 * NOTHING ABOUT THE THREAD SURFACE IS MEASURED. No capture in `references/` shows a reply thread, and
 * none shows the transition into or out of one, so the count's hit target, the thread's chrome and
 * every timing in `replyThreadMotion` are plausible values rather than readings. They are kept in the
 * family of the two motions that were measured: the long-press overlay (dim 150 ms, entrance 600,
 * dismissal 220) and the "Send with effect" screen (entrance 260, exit 200). The only positions
 * borrowed from a capture are the iOS back control's measured Ø44 box centred (38, 84) and the
 * measured edge insets and cluster gaps the messages inside the thread already use.
 */
export type ReplyQuote = {
  id: string;
  text: string;
  direction: Direction;
  service?: Service;
  sender?: string;
};

/**
 * Provisional stub numbers. `stubScale` and `stubOpacity` are the two values SPEC.md carries for
 * replies; `stubMaxLines` follows the measured 2-line conversation-list preview.
 */
export const replyMetrics: Record<Platform, { stubScale: number; stubOpacity: number; stubMaxLines: number }> = {
  ios: { stubScale: 0.76, stubOpacity: 0.55, stubMaxLines: 2 },
  macos: { stubScale: 0.78, stubOpacity: 0.55, stubMaxLines: 2 },
};

/** The stub's geometry: the platform's measured bubble metrics scaled by `stubScale`. */
export function replyStubMetrics(platform: Platform) {
  const m = bubbleMetrics[platform];
  const scale = replyMetrics[platform].stubScale;
  return {
    scale,
    fontSize: m.fontSize * scale,
    lineHeight: m.lineHeight * scale,
    paddingX: m.paddingX * scale,
    paddingY: m.paddingY * scale,
    radius: m.radius * scale,
    minWidth: m.minWidth * scale,
    letterSpacing: m.letterSpacing * scale,
    tailScale: m.tailScale * scale,
    /** How far the tail hangs below the body. It is drawn outside the body and takes no space. */
    hang: tailBox.hang * m.tailScale * scale,
    /** Stub body bottom to the reply body's top, without and with a tail. */
    gap: m.gapInGroup,
    gapWithTail: m.gapBetweenGroups,
    /**
     * A bubble's own rule (fixed px on iOS, a share of the pane on macOS), scaled. The macOS share is
     * of the pane, and a row is inset from it on both sides, so add the insets back the way
     * `message-list` does before taking the share.
     */
    maxWidth: platform === "ios"
      ? `min(${(m.maxWidth * scale).toFixed(2)}px, 100%)`
      : `min(calc((100% + ${2 * m.edgeInset}px) * ${(m.maxWidthRatio * scale).toFixed(5)}), 100%)`,
  };
}

/** Height of a stub body of `lines` lines. The tail hang and the gap below it are extra. */
export function replyStubHeight(platform: Platform, lines = 1): number {
  const s = replyStubMetrics(platform);
  return s.lineHeight * lines + s.paddingY * 2;
}

/**
 * A bubble hugs its longest wrapped line instead of stretching to its maximum width (measured), and
 * CSS shrink-to-fit cannot express that, so the laid-out line boxes are measured and the frame's width
 * set from them. `MessageBubble` does the same for real bubbles; the stub cannot borrow that hook
 * because it lays out at `stubScale`, and the copy is small enough to keep the loop simple: clamped
 * lines are still laid out, so they take part in the measurement, and the widest one can only be the
 * width already available, which leaves the frame where it is.
 */
function useStubTextFit(paddingX: number, deps: unknown[]) {
  const frame = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const frameEl = frame.current;
    const textEl = frameEl?.querySelector<HTMLElement>('[data-slot="text"]');
    if (!frameEl || !textEl) return;
    const container = frameEl.parentElement;
    let raf = 0;
    const measure = () => {
      frameEl.style.width = "";
      const range = document.createRange();
      range.selectNodeContents(textEl);
      const lines: Array<{ top: number; left: number; right: number }> = [];
      for (const rect of Array.from(range.getClientRects())) {
        if (rect.width === 0 && rect.height === 0) continue;
        const line = lines.find(l => Math.abs(l.top - rect.top) < 1);
        if (line) { line.left = Math.min(line.left, rect.left); line.right = Math.max(line.right, rect.right); }
        else lines.push({ top: rect.top, left: rect.left, right: rect.right });
      }
      if (lines.length < 2) return;
      const longest = Math.max(...lines.map(l => l.right - l.left));
      const hug = Math.ceil((longest + 2 * paddingX) * 100) / 100 + 0.05;
      if (hug < frameEl.getBoundingClientRect().width - 0.1) frameEl.style.width = `${hug}px`;
    };
    measure();
    const observer = new ResizeObserver(() => { cancelAnimationFrame(raf); raf = requestAnimationFrame(measure); });
    if (container) observer.observe(container);
    document.fonts?.ready.then(() => measure()).catch(() => {});
    return () => { observer.disconnect(); cancelAnimationFrame(raf); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [paddingX, ...deps]);
  return frame;
}

/** The stub above a reply: the quoted message, smaller and dimmer, on the reply's own edge. */
export function ReplyStub({ quote, tail = false, maxLines, platform: platformProp, className, style, ...props }: Omit<ComponentProps<"div">, "children"> & {
  quote: ReplyQuote; tail?: boolean; maxLines?: number; platform?: Platform;
}) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const s = replyStubMetrics(platform);
  const lines = maxLines ?? replyMetrics[platform].stubMaxLines;
  const outgoing = quote.direction === "outgoing";
  const side = outgoing ? "right" : "left";
  const service = quote.service ?? "imessage";
  const key = outgoing ? (service === "sms" ? "green" : "blue") : "gray";
  const frame = useStubTextFit(s.paddingX, [quote.text, platform, lines, tail]);

  // The same screen-space fill a bubble uses: one gradient the height of the screen, anchored to this
  // body's bottom edge. `use-screen-space.ts` keeps `--bubble-bottom` current while the list scrolls.
  const bottomVar = "var(--bubble-bottom, calc(var(--im-screen-h) * 0.55))";
  const fill: CSSProperties = {
    backgroundImage: "linear-gradient(var(--im-fill-top), var(--im-fill-bottom))",
    backgroundSize: "100% var(--im-screen-h)",
    backgroundRepeat: "no-repeat",
    backgroundColor: "var(--im-fill-bottom)",
  };

  return (
    // The row is a flex column aligned to the reply's own side; `align-items: inherit` hands that
    // alignment to the copy. Shrink-to-fit alone would not: a quote long enough to reach the stub's
    // maximum width makes this box fill the row, and the copy inside it would sit on the far edge.
    <div data-slot="reply-stub" data-direction={quote.direction} data-platform={platform}
      className={cn("pointer-events-none flex w-full flex-col select-none", className)}
      style={{ fontFamily: fontStack, alignItems: "inherit", opacity: replyMetrics[platform].stubOpacity, marginBottom: tail ? s.gapWithTail : s.gap, ...style }} {...props}>
      <span className="sr-only">{`Replying to ${quote.sender ?? (outgoing ? "your message" : "their message")}: ${quote.text}`}</span>
      {/* The copy itself is decorative: the sentence above already reads the quote out. */}
      <div ref={frame} aria-hidden="true" data-slot="message-bubble" data-stub="true" data-direction={quote.direction} data-service={service} data-platform={platform}
        className="relative"
        style={{ maxWidth: s.maxWidth, "--im-fill-top": `var(--im-${key}-top)`, "--im-fill-bottom": `var(--im-${key}-bottom)` } as CSSProperties}>
        <div data-slot="bubble" className="relative" style={{
          fontSize: s.fontSize, lineHeight: `${s.lineHeight}px`, letterSpacing: s.letterSpacing,
          padding: `${s.paddingY}px ${s.paddingX}px`, minWidth: s.minWidth, textAlign: "start",
          color: outgoing ? "var(--im-outgoing-text)" : "var(--im-incoming-text)",
        }}>
          {/* The fill sits behind the text, so clipping the tail corner never clips glyphs. */}
          <div data-slot="fill" className="pointer-events-none absolute inset-0" style={{
            borderRadius: s.radius, clipPath: tail ? bodyClipPath(side, s.tailScale, tailSeamOverlap[platform]) : `inset(0 round ${s.radius}px)`,
            ...fill, backgroundPosition: `0 calc(100% + (var(--im-screen-h) - ${bottomVar}))`,
          }} />
          {tail && <div data-slot="tail" className="pointer-events-none absolute" style={{
            [side]: 0, bottom: -s.hang, width: tailBox.width * s.tailScale, height: tailBox.height * s.tailScale + s.hang,
            clipPath: `path("${tailPath(side, s.tailScale)}")`,
            ...fill, backgroundPosition: `0 calc(100% + (var(--im-screen-h) - ${bottomVar} - ${s.hang}px))`,
          }} />}
          {/* `fit-content` centres a quote too short to fill the minimum width and leaves a wrapped one
              flush; the clamp lives here so the body never puts the tail inside an `overflow: hidden`. */}
          <span data-slot="text" className="relative" style={{
            display: "-webkit-box", WebkitBoxOrient: "vertical", WebkitLineClamp: lines, overflow: "hidden",
            width: "fit-content", marginInline: "auto", whiteSpace: "pre-wrap", overflowWrap: "anywhere",
          }}>{quote.text}</span>
        </div>
      </div>
    </div>
  );
}

/** A reply: the quoted stub, then the reply bubble itself, both on the reply's own edge. */
export function ReplyMessage({ quote, direction = "outgoing", service, tail = false, status, stubTail = false, stubMaxLines, children, platform: platformProp, className, style, ...props }: Omit<ComponentProps<"div">, "children"> & {
  quote: ReplyQuote; direction?: Direction; service?: Service; tail?: boolean; status?: ReactNode;
  stubTail?: boolean; stubMaxLines?: number; children: ReactNode; platform?: Platform;
}) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = bubbleMetrics[platform];
  // macOS caps a bubble at a share of the *pane*, and `MessageBubble` resolves that percentage against
  // its own box. Left to shrink-wrap inside this row the box is only as wide as the text, so the cap
  // collapses onto it and the bubble is squeezed to a few characters. Fill the row and hand the bubble
  // the same maximum `message-list` does, insets added back.
  const maxWidth = platform === "ios" ? undefined : `calc((100% + ${2 * m.edgeInset}px) * ${m.maxWidthRatio})`;
  return (
    <div data-slot="reply-message" data-direction={direction} className={cn("flex w-full min-w-0 flex-col", direction === "outgoing" ? "items-end" : "items-start", className)} style={style} {...props}>
      <ReplyStub quote={quote} tail={stubTail} maxLines={stubMaxLines} platform={platform} />
      <MessageBubble direction={direction} service={service} tail={tail} status={status} platform={platform}
        maxWidth={maxWidth} style={{ width: "100%" }}>{children}</MessageBubble>
    </div>
  );
}

/**
 * How far the reply count's hit target reaches past its ink. UNMEASURED. The label is the measured
 * secondary label, 13 pt of line box on iOS and 11 on macOS, which is far under a comfortable target,
 * so the button hangs an invisible box off the ink instead of taking padding: padding would move the
 * label off the measured `statusGap`. It reaches further down than up because up is that gap and then
 * the bubble, which keeps its own long-press and right-click gestures.
 */
export const replyCountHit: Record<Platform, { x: number; top: number; bottom: number }> = {
  ios: { x: 10, top: 4, bottom: 13 },
  macos: { x: 8, top: 3, bottom: 8 },
};

/**
 * "1 reply" under a message that started a thread, set in the measured secondary label.
 *
 * It is a real control: a button (so Enter and Space open the thread), an accessible name that says
 * how many replies it opens and that it opens a dialog, hover and focus feedback, and a hit target
 * larger than the ink. `expanded` reflects whether the thread it opens is on screen.
 *
 * The feedback is a web affordance, not a reading: no capture shows this label being pointed at, and
 * SPEC.md records that macOS Messages paints no hover state on its rows or bubbles at all. It costs no
 * fidelity because it only exists while the pointer or the focus ring is on the control: at rest the
 * button paints exactly the measured label, verified pixel for pixel against the `reply` baseline.
 */
export function ReplyCount({ count, onOpen, expanded, platform: platformProp, className, style, ...props }: Omit<ComponentProps<"button">, "children" | "onClick"> & { count: number; onOpen?: () => void; expanded?: boolean; platform?: Platform }) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = bubbleMetrics[platform];
  const hit = replyCountHit[platform];
  return (
    // `aria-haspopup` only when something is wired to it: an unwired count opens nothing and should
    // not say that it does.
    <button type="button" data-slot="reply-count" data-count={count} data-platform={platform} onClick={onOpen}
      aria-haspopup={onOpen ? "dialog" : undefined} aria-expanded={expanded} aria-label={count === 1 ? "Show 1 reply" : `Show ${count} replies`}
      className={cn("relative underline-offset-2 transition-opacity duration-150 hover:underline active:opacity-60 focus-visible:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff] motion-reduce:transition-none", className)}
      style={{
        fontFamily: fontStack, fontSize: m.statusFontSize, lineHeight: `${m.statusLineHeight}px`, fontWeight: 600,
        letterSpacing: m.statusLetterSpacing, marginTop: m.statusGap, color: "var(--im-secondary)", ...style,
      }} {...props}>
      {/* Inside the button, so a press on it is a press on the control; absolute, so it adds no ink. */}
      <span aria-hidden="true" data-slot="hit-area" className="absolute" style={{ left: -hit.x, right: -hit.x, top: -hit.top, bottom: -hit.bottom }} />
      {count === 1 ? "1 reply" : `${count} replies`}
    </button>
  );
}

/**
 * The thread's motion. UNMEASURED, see the note at the top of this file: plausible durations in the
 * family of the measured ones, not readings off a frame.
 */
export const replyThreadMotion = {
  /** The whole surface arriving, and leaving. The measured effects screen uses 260 and 200. */
  enter: 260,
  exit: 200,
  /** The dim and the backdrop's blur ramp together, over the measured long-press dim. */
  dim: 150,
  /** iOS: the panel grows into place from this scale, this far below it. macOS slides its pane in. */
  panelScale: 0.94,
  panelRise: 10,
  /** The thread's root message grows a little further than the panel around it. */
  rootScale: 0.92,
  /** The iOS sheet curve the rest of the kit uses, and a plain accelerate for the way out. */
  ease: "cubic-bezier(0.32, 0.72, 0, 1)",
  exitEase: "cubic-bezier(0.4, 0, 1, 1)",
} as const;

/**
 * The thread's chrome, per platform. UNMEASURED apart from the iOS close control, which sits in the
 * nav bar's measured Ø44 box centred (38, 84), and the insets and gaps inside the thread, which are
 * the platform's measured bubble metrics.
 *
 * iOS presents the thread full screen over the blurred conversation, so `paneWidth` is 0 and the
 * panel fills the frame. macOS presents it as a pane on the trailing edge with the conversation still
 * legible beside it, so it takes a width, paints its own background, and does not blur what is behind.
 */
export const replyThreadMetrics: Record<Platform, {
  topInset: number; headerHeight: number; titleSize: number; closeSize: number; closeInset: number; blur: number; paneWidth: number;
}> = {
  ios: { topInset: 62, headerHeight: 44, titleSize: 17, closeSize: 44, closeInset: 16, blur: 9, paneWidth: 0 },
  macos: { topInset: 0, headerHeight: 38, titleSize: 13, closeSize: 22, closeInset: 12, blur: 0, paneWidth: 420 },
};

/** The close control's glyph: the nav bar's back chevron on iOS, a cross on the macOS pane. */
function ThreadCloseGlyph({ platform }: { platform: Platform }) {
  if (platform === "ios") {
    // The measured back chevron, in its measured 44 pt box (`ios-details.tsx` draws the same path).
    return (
      <svg aria-hidden="true" width="44" height="44" viewBox="0 0 44 44" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
        <path d="M24.8 13.87 16.2 22.17 24.8 30.47" />
      </svg>
    );
  }
  return (
    <svg aria-hidden="true" width="11" height="11" viewBox="0 0 11 11" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round">
      <path d="M1 1 10 10M10 1 1 10" />
    </svg>
  );
}

/**
 * The focused thread: the rest of the conversation dims and blurs behind it and only the thread stays
 * lit. Render inside the device frame with `inset-0`.
 *
 * Pass the conversation as `backdrop` and it is blurred with a real `filter`, the way `ios-details`
 * does it. `backdrop-filter` samples whatever the host happens to have painted behind the overlay and
 * Chromium picks its own radius on a composited layer, so the same markup screenshots differently in
 * different hosts; with a `backdrop` the blur is ours and the frame is reproducible. Without one it
 * falls back to `backdrop-filter`, which is fine live and unreliable in a capture.
 *
 * The dim is the measured long-press value, shared with `message-actions` through `--im-dim`.
 *
 * Motion: the dim and the blur come up over `dim` ms while the panel grows into place (iOS) or slides
 * in from the trailing edge (macOS) over `enter`, the root message growing a little further than the
 * panel around it. `open={false}` reverses that over `exit` and calls `onExited` at the end, so the
 * parent can keep the thread mounted until the dismissal has actually been seen:
 *
 *     const openId = thread?.rootId ?? null;
 *     const [seen, setSeen] = useState(openId);
 *     const [closing, setClosing] = useState<string | null>(null);
 *     if (seen !== openId) { setSeen(openId); setClosing(openId ? null : seen); }   // during render
 *     {(openId ?? closing) && <ReplyThread open={openId !== null} onExited={() => setClosing(null)} …>}
 *
 * That `if` has to run during render, not in an effect: an effect would leave one committed frame
 * with the thread already unmounted and the dismissal would never run. `ios-messages-app.tsx` does
 * the same for the long-press overlay and the effects screen.
 *
 * The entrance is built with the Web Animations API, so `progress` (0..1) pauses and seeks it instead
 * of playing it, and `document.getAnimations()` can reach every part of it.
 */
export function ReplyThread({
  title = "Replies", root: rootMessage, onClose, closeLabel, backdrop, blur, open = true, onExited, progress,
  platform: platformProp, children, className, style, ...props
}: Omit<ComponentProps<"div">, "title"> & {
  title?: string;
  /** The message the thread hangs off. Drawn above the replies, and it grows ahead of them. */
  root?: ReactNode;
  onClose?: () => void;
  closeLabel?: string;
  backdrop?: ReactNode;
  blur?: number;
  /** Flip to false to play the dismissal; `onExited` fires when it is over. */
  open?: boolean;
  onExited?: () => void;
  /** Seek the entrance to this fraction (0..1) instead of playing it, which is what the harness does. */
  progress?: number;
  platform?: Platform;
}) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = bubbleMetrics[platform];
  const t = replyThreadMetrics[platform];
  const ios = platform === "ios";
  const blurPx = blur ?? t.blur;
  const panelFrom = ios ? `translateY(${replyThreadMotion.panelRise}px) scale(${replyThreadMotion.panelScale})` : "translateX(100%)";
  const surface = useRef<HTMLDivElement>(null);
  const scrub = useRef<((time: number | null) => void) | null>(null);
  const titleId = useId();

  // Derived DURING RENDER, not in an effect. Two things depend on it: the dismissal has to start on
  // the frame `open` goes false (an effect leaves one committed frame with nothing left to animate),
  // and `onExited` must not fire for a thread that mounted closed and never opened.
  const [seenOpen, setSeenOpen] = useState(open);
  const [closing, setClosing] = useState(false);
  if (seenOpen !== open) {
    setSeenOpen(open);
    setClosing(!open);
  }

  // The thread is modal, so it takes focus on open (a scrubbed entrance does not: the harness seeks
  // frames and must not move the caret) and Escape closes it from anywhere, not only while focus
  // happens to sit inside. The surface paints no focus ring: it is a holder, not a control.
  useEffect(() => {
    if (!open || closing || progress !== undefined) return;
    surface.current?.focus({ preventScroll: true });
  }, [open, closing, progress]);
  useEffect(() => {
    if (!onClose || closing) return;
    const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); onClose(); } };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [onClose, closing]);

  // The control that opened the thread gets focus back when the thread gives it up, so a keyboard
  // lands back on the reply count it came from rather than at the top of the document.
  const restoreTo = useRef<HTMLElement | null>(null);
  useLayoutEffect(() => {
    const active = document.activeElement;
    if (!(active instanceof Node && surface.current?.contains(active))) restoreTo.current = active as HTMLElement | null;
  }, []);
  // Called when the dismissal finishes rather than only from an unmount cleanup: React runs a passive
  // cleanup after the node is already detached, by which time focus has fallen to the body and the
  // "was it still inside?" test can no longer be answered. The unmount keeps it as a backstop for a
  // parent that drops the thread without playing the dismissal.
  const restoreFocus = useCallback(() => {
    const previous = restoreTo.current;
    if (!previous?.isConnected) return;
    const el = surface.current;
    const active = document.activeElement;
    const gone = !active || active === document.body;
    if (!gone && !(el && active instanceof Node && el.contains(active))) return;
    restoreTo.current = null;
    previous.focus({ preventScroll: true });
  }, []);
  useEffect(() => restoreFocus, [restoreFocus]);

  /** Tab stays inside while the thread is up, the way a modal sheet does. */
  function onSurfaceKeyDown(event: ReactKeyboardEvent<HTMLDivElement>) {
    if (event.key !== "Tab") return;
    const el = surface.current;
    if (!el) return;
    const stops = Array.from(el.querySelectorAll<HTMLElement>('button:not([disabled]), [href], [tabindex]:not([tabindex="-1"])')).filter(node => node.getClientRects().length > 0);
    if (!stops.length) return;
    const first = stops[0], last = stops[stops.length - 1];
    const active = document.activeElement;
    const inside = active instanceof Node && el.contains(active);
    if (event.shiftKey ? active === first || !inside : active === last || !inside) {
      event.preventDefault();
      (event.shiftKey ? last : first).focus();
    }
  }

  // The entrance, built with the Web Animations API so it can be played or seeked. Every layer's
  // resting style already is the end of its keyframes, so settling the timeline is just cancelling
  // it, which also releases the composited layer a held animation would otherwise pin (a held layer
  // cuts `backdrop-filter` off from what it samples; `message-actions.tsx` documents the same trap).
  // Settling empties the list, so a seek back below the end rebuilds it rather than losing it.
  useLayoutEffect(() => {
    const el = surface.current;
    if (!el) return;
    const T = replyThreadMotion;
    const one = (slot: string) => el.querySelector<HTMLElement>(`[data-slot="${slot}"]`);
    let list: Animation[] = [];
    const build = () => {
      const made: Animation[] = [];
      const add = (target: Element | null, keyframes: Keyframe[], options: KeyframeAnimationOptions) => { if (target) made.push(target.animate(keyframes, { fill: "both", ...options })); };
      add(one("dim"), [{ opacity: 0 }, { opacity: 1 }], { duration: T.dim, easing: "ease-out" });
      add(one("backdrop-blur"), [{ opacity: 0 }, { opacity: 1 }], { duration: T.dim, easing: "ease-out" });
      add(one("backdrop-content"), [{ filter: "blur(0px)" }, { filter: `blur(${blurPx}px)` }], { duration: T.dim, easing: "ease-out" });
      add(one("thread-panel"), ios
        ? [{ opacity: 0, transform: panelFrom }, { opacity: 1, transform: "none" }]
        : [{ transform: panelFrom }, { transform: "none" }], { duration: T.enter, easing: T.ease });
      add(one("thread-root"), [{ transform: `scale(${T.rootScale})` }, { transform: "none" }], { duration: T.enter, easing: T.ease });
      return made;
    };
    const drop = (a: Animation) => { try { a.cancel(); } catch { /* already gone */ } };
    const settle = () => { for (const a of list) drop(a); list = []; };
    scrub.current = time => {
      if (time !== null && time >= T.enter) { settle(); return; }
      if (!list.length) list = build();
      if (time === null) {
        // Each leg is released as it ends, not when the first one does: the dim is over at 150 ms and
        // the panel at 260, and settling them together would cut the panel's last 110 ms. Its `finished`
        // is captured before the cancel, which replaces the promise with a fresh pending one.
        const playing = list;
        const ends = playing.map(a => { a.play(); return a.finished; });
        ends.forEach((end, i) => end.then(() => drop(playing[i])).catch(() => {}));
        Promise.allSettled(ends).then(() => { if (list === playing) list = []; });
        return;
      }
      for (const a of list) { a.pause(); a.currentTime = time; }
    };
    return () => { settle(); scrub.current = null; };
  }, [blurPx, ios, panelFrom]);

  useEffect(() => {
    if (!open || closing) return;
    const reduced = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (progress !== undefined) scrub.current?.(Math.min(1, Math.max(0, progress)) * replyThreadMotion.enter);
    else if (reduced) scrub.current?.(replyThreadMotion.enter);
    else scrub.current?.(null);
  }, [open, closing, progress]);

  // The dismissal: the entrance is settled first, so this runs from the settled, open frame.
  const exited = useRef(onExited);
  useEffect(() => { exited.current = onExited; }, [onExited]);
  useEffect(() => {
    if (!closing) return;
    const el = surface.current;
    const reduced = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    scrub.current?.(replyThreadMotion.enter);
    let done = false;
    const finish = () => { if (done) return; done = true; restoreFocus(); exited.current?.(); };
    if (!el || reduced) { finish(); return; }
    const one = (slot: string) => el.querySelector<HTMLElement>(`[data-slot="${slot}"]`);
    const timing: KeyframeAnimationOptions = { duration: replyThreadMotion.exit, easing: replyThreadMotion.exitEase, fill: "both" };
    const running: Animation[] = [];
    const add = (target: Element | null, keyframes: Keyframe[]) => { if (target) running.push(target.animate(keyframes, timing)); };
    add(one("dim"), [{ opacity: 1 }, { opacity: 0 }]);
    add(one("backdrop-blur"), [{ opacity: 1 }, { opacity: 0 }]);
    add(one("backdrop-content"), [{ filter: `blur(${blurPx}px)` }, { filter: "blur(0px)" }]);
    add(one("thread-panel"), ios
      ? [{ opacity: 1, transform: "none" }, { opacity: 0, transform: panelFrom }]
      : [{ transform: "none" }, { transform: panelFrom }]);
    add(one("thread-root"), [{ transform: "none" }, { transform: `scale(${replyThreadMotion.rootScale})` }]);
    if (!running.length) { finish(); return; }
    Promise.allSettled(running.map(a => a.finished)).then(finish);
    return () => running.forEach(a => { try { a.cancel(); } catch { /* already gone */ } });
  }, [closing, blurPx, ios, panelFrom, restoreFocus]);

  const dismiss = closing ? undefined : onClose;
  const panelStyle: CSSProperties = ios
    ? { inset: 0, transformOrigin: "50% 100%" }
    : {
      top: 0, bottom: 0, right: 0, width: `min(100%, ${t.paneWidth}px)`, background: "var(--im-bg)",
      borderInlineStart: "1px solid var(--im-separator)", boxShadow: "-8px 0 26px rgba(0,0,0,0.12)",
    };

  return (
    <div ref={surface} data-slot="reply-thread" data-platform={platform} data-state={closing ? "closing" : "open"}
      role="dialog" aria-modal="true" aria-labelledby={titleId} tabIndex={-1} onKeyDown={onSurfaceKeyDown}
      className={cn("absolute inset-0 z-30 outline-none", className)}
      style={{ fontFamily: fontStack, ...style }} {...props}>
      {backdrop !== undefined ? (
        <div aria-hidden="true" data-slot="backdrop" className="absolute inset-0 -z-10 overflow-hidden">
          {/* Blurring a box larger than the screen keeps the filter's own edge falloff off-screen. */}
          <div data-slot="backdrop-content" className="absolute" style={{ inset: -60, background: "var(--im-bg)", filter: `blur(${blurPx}px)` }}>
            <div className="absolute" style={{ inset: 60 }}>{backdrop}</div>
          </div>
        </div>
      ) : blurPx > 0 ? (
        // The fallback blur is its own layer rather than a filter on the surface: the entrance fades
        // it in, and fading the surface itself would take the thread with it.
        <div aria-hidden="true" data-slot="backdrop-blur" className="absolute inset-0 -z-10"
          style={{ backdropFilter: `blur(${blurPx}px)`, WebkitBackdropFilter: `blur(${blurPx}px)` }} />
      ) : null}
      {/* The dim, then a scrim over it: Escape does the same job for the keyboard, so the scrim stays
          out of the a11y tree. The scrim goes inert while the thread is leaving, so a second click
          cannot ask for a dismissal that is already running. */}
      <div aria-hidden="true" data-slot="dim" className="absolute inset-0" style={{ background: "var(--im-dim, rgba(22,18,44,0.21))" }} />
      <div aria-hidden="true" data-slot="scrim" onClick={dismiss} className="absolute inset-0 cursor-default" />
      {/* iOS fills the frame, so the panel lets clicks through to the scrim and only its own content
          takes them back. The macOS pane is opaque and takes everything inside its own width. */}
      <div data-slot="thread-panel" className={cn("absolute flex flex-col", ios && "pointer-events-none")} style={panelStyle}>
        <div data-slot="thread-header" className="pointer-events-auto relative flex shrink-0 items-center"
          style={{ height: t.headerHeight, marginTop: t.topInset, paddingInline: m.edgeInset, justifyContent: ios ? "center" : "space-between" }}>
          <span id={titleId} data-slot="thread-title" style={{ fontSize: t.titleSize, lineHeight: 1, fontWeight: 600, color: "var(--im-incoming-text)" }}>{title}</span>
          {onClose && (
            <button type="button" data-slot="thread-close" onClick={dismiss} aria-label={closeLabel ?? (ios ? "Back to the conversation" : "Close replies")}
              className="flex items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
              style={ios
                ? { position: "absolute", left: t.closeInset, top: (t.headerHeight - t.closeSize) / 2, width: t.closeSize, height: t.closeSize, color: "var(--im-incoming-text)" }
                : { width: t.closeSize, height: t.closeSize, color: "var(--im-secondary)" }}>
              <ThreadCloseGlyph platform={platform} />
            </button>
          )}
        </div>
        <div data-slot="thread-messages" className="pointer-events-auto relative mt-auto flex flex-col" style={{ gap: m.gapBetweenGroups, padding: m.edgeInset }}>
          {rootMessage !== undefined && (
            <div data-slot="thread-root" className="flex w-full flex-col" style={{ transformOrigin: "50% 100%" }}>{rootMessage}</div>
          )}
          {children}
        </div>
      </div>
    </div>
  );
}

/** Shape an app can store alongside a message to describe its thread. */
export type ThreadInfo = { rootId: string; replyCount: number };

export type ReplyStyle = CSSProperties;

"use client";

import { useCallback, useLayoutEffect, useMemo, useRef, useState, type ComponentProps, type CSSProperties, type MouseEvent, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { bubbleMetrics, fontStack, type Direction } from "@/components/imessage/tokens";
import { bodyClipPath, tailBox, tailPath, tailSeamOverlap } from "@/components/imessage/bubble-shape";

/**
 * Photos and videos sent in a conversation. A photo takes the bubble's shape, tail included, so the
 * same traced outline in `bubble-shape.ts` clips the image instead of filling it.
 *
 * NOT MEASURED against a native photo message: the corner radius and tail come from the measured text
 * bubble, and the multi-photo grid follows the documented layout. The tile gap is provisional.
 *
 * The single photo's box, on the other hand, is now read out of ChatKit rather than guessed: see
 * `photoBox` below. So are the accessible names: ChatKit's own accessibility bundle
 * (`/System/iOSSupport/System/Library/AccessibilityBundles/ChatKitFramework.axbundle`,
 * `Accessibility.loctable`) calls one attachment `photo.attachment` = "Photo", counts them with
 * `attachment.count` = "%d attachments" and positions each one with
 * `messages.attachment.stack.view.format` = "attachment %1$d of %2$d".
 *
 * A photo sent together with text is NOT one balloon with a caption under the photo. ChatKit splits a
 * message into parts (`-[CKMessagePartChatItem messagePartRange]`, `CKTextMessagePartChatItem` vs
 * `CKAttachmentMessagePartChatItem`), and each part is its own balloon chat item, so native draws the
 * photo balloon and the text balloon as two bubbles of one cluster. "Caption" exists nowhere in the
 * image balloon; in ChatKit it belongs to Business Chat rich cards
 * (`-[CKBalloonView didTapTruncatedCaptionForRichCard:]`). The message list therefore renders the two,
 * passing `tail` to whichever comes last; this component stays a photo group.
 */
export type MessageImage = { src: string; alt: string; width?: number; height?: number };

export type MessageImagesProps = Omit<ComponentProps<"div">, "children"> & {
  images: MessageImage[];
  direction?: Direction;
  tail?: boolean;
  /** Longest edge of the group, in px. Defaults to the platform's maximum bubble width. */
  maxWidth?: number;
  /** Tallest the group may grow, in px. Defaults to the native cap (see `photoBox`). */
  maxHeight?: number;
  /** The transfer has not arrived yet: hold every tile on the placeholder. */
  loading?: boolean;
  /**
   * Open the full-screen viewer at `index`. The second argument is the tile's own box in viewport
   * coordinates, so the viewer can zoom out of the tile the way native does instead of fading in.
   */
  onOpenImage?: (index: number, rect: DOMRect) => void;
  /** @deprecated Use `onOpenImage`, which also hands over the tile's box. */
  onOpen?: (index: number) => void;
  /** Tapback balloons; positioned on the group's top corner away from the screen edge. */
  reactions?: ReactNode;
  platform?: Platform;
};

/** Native shows at most four tiles and counts the rest. */
const MAX_TILES = 4;

/** Gap between tiles. Provisional: no native capture of a multi-photo message exists. */
const TILE_GAP = 2;

/**
 * How big one photo's balloon is, read out of ChatKit instead of a screenshot.
 * `-[CKUIBehaviorPhone thumbnailFillSizeForWidth:imageSize:]`, swept over widths 100…600 against
 * extreme image sizes, fills the balloon width and then clamps the shape: anything wider than 16:9
 * comes back at `width x 0.5625` and anything taller than 3:4 at `width x 1.3333`, in both cases
 * cropped, since the answer is a *fill* size (its sibling `unconstrainedAspectFillSizeForWidth:`
 * returns the unclamped fit). It never returns a height over 500; past that the width shrinks to hold
 * the ratio (w 400, a 1:4 photo → 375 x 500).
 *
 * `-[CKUIBehaviorMac thumbnailFillSizeForWidth:imageSize:]` overrides it and applies no shape clamp at
 * all: it returns the true aspect fit, capped at the same height of 500 (a 1:6 photo → 83.5 x 500).
 * Native rounds each result to the device pixel grid (it answers 158.0 where 280.5 x 0.5625 is
 * 157.78); the fractions are kept here for the same reason `tileSize` keeps its own.
 */
export const photoBox: Record<Platform, { minRatio: number; maxRatio: number; maxHeight: number }> = {
  ios: { minRatio: 0.5625, maxRatio: 4 / 3, maxHeight: 500 },
  macos: { minRatio: 0, maxRatio: Number.POSITIVE_INFINITY, maxHeight: 500 },
};

/**
 * Where a tapback balloon sits against the group's top corner. Measured on text bubbles and carried
 * over: a photo group takes a tapback like any other balloon, and native anchors it to the balloon's
 * frame, which is what this box is. Numbers from `tapback.tsx`'s `balloonSlot` (the corrected pair),
 * not from `message-bubble.tsx`'s older copy. A photo has no measured slot of its own; ChatKit does
 * carry `-[CKUIBehavior messageAcknowledgmentPhotoGridXOffsetScalar]` = 0 / `…YOffsetScalar` = 0.2 on
 * iPhone and 0.35 / 0.35 on Mac, but those are fractions of a frame this component does not build (a
 * photo *grid* view), so they are recorded rather than used.
 */
const reactionSlot: Record<Platform, { marginTop: number; top: number; side: number }> = {
  ios: { marginTop: 28, top: -27.39, side: -13.85 },
  macos: { marginTop: 27.4, top: -22.05, side: -11.79 },
};

/**
 * What native offers on an attachment it has not fetched: ChatKit's `TAP_TO_DOWNLOAD` = "Tap to
 * Download" and `CLICK_TO_DOWNLOAD` = "Click to Download" (`ChatKit.framework/Resources/ChatKit.loctable`).
 * The tile keeps the same copy when the fetch fails, and activating it asks for the photo again.
 */
const downloadLabel: Record<Platform, string> = { ios: "Tap to Download", macos: "Click to Download" };

/**
 * Aspect ratios already learned this session, so a photo that has been seen once never opens at the
 * 4:3 placeholder again. A remount (the viewer closing, a list re-render) would otherwise lay the
 * bubble out at the wrong height and snap when the image decodes. Empty during hydration, because
 * nothing can have loaded by then, so the first client render still matches the server's.
 */
const aspectMemo = new Map<string, number>();

type Phase = "ready" | "failed";

/**
 * Average colour of the corner of `image` that the tail meets, so the tail reads as a continuation of
 * the photo rather than a gray stub. The tile is `object-cover`, so the visible corner is not the
 * source's own corner: map the tail's footprint back through the cover crop before reading it.
 * Returns null when the image has not loaded, is not laid out, or taints the canvas (a cross-origin
 * photo), and the caller keeps its fallback fill.
 */
function sampleCorner(image: HTMLImageElement, side: "left" | "right", boxWidth: number, boxHeight: number): string | null {
  const naturalWidth = image.naturalWidth;
  const naturalHeight = image.naturalHeight;
  if (!image.complete || !naturalWidth || !naturalHeight) return null;
  const rect = image.getBoundingClientRect();
  if (!rect.width || !rect.height) return null;
  const cover = Math.max(rect.width / naturalWidth, rect.height / naturalHeight);
  const visibleWidth = Math.min(naturalWidth, rect.width / cover);
  const visibleHeight = Math.min(naturalHeight, rect.height / cover);
  const patchWidth = Math.max(1, Math.min(visibleWidth, boxWidth / cover));
  const patchHeight = Math.max(1, Math.min(visibleHeight, boxHeight / cover));
  const left = (naturalWidth - visibleWidth) / 2;
  const sx = side === "right" ? left + visibleWidth - patchWidth : left;
  const sy = (naturalHeight - visibleHeight) / 2 + visibleHeight - patchHeight;
  try {
    const canvas = document.createElement("canvas");
    canvas.width = 8;
    canvas.height = 8;
    const context = canvas.getContext("2d", { willReadFrequently: true });
    if (!context) return null;
    context.drawImage(image, sx, sy, patchWidth, patchHeight, 0, 0, 8, 8);
    const data = context.getImageData(0, 0, 8, 8).data;
    let r = 0, g = 0, b = 0;
    for (let i = 0; i < data.length; i += 4) { r += data[i]; g += data[i + 1]; b += data[i + 2]; }
    const pixels = data.length / 4;
    return `rgb(${Math.round(r / pixels)}, ${Math.round(g / pixels)}, ${Math.round(b / pixels)})`;
  } catch {
    return null; // a cross-origin photo taints the canvas
  }
}

export function MessageImages({
  images, direction = "outgoing", tail = false, maxWidth, maxHeight, loading = false,
  onOpenImage, onOpen, reactions, platform: platformProp, className, style, ...props
}: MessageImagesProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = bubbleMetrics[platform];
  const side = direction === "outgoing" ? "right" : "left";
  const width = maxWidth ?? m.maxWidth;
  const tiles = images.slice(0, MAX_TILES);
  const overflow = images.length - tiles.length;
  const single = tiles.length === 1;
  const groupKey = tiles.map(image => image.src).join("|");

  // Tiles are square, so one number sets both axes: half the group, less the gap. Keep the fraction
  // instead of rounding it, or they stop being square: 280.5 halves to 139.25, and two of those plus
  // the gap is the group's 280.5 again.
  const tileSize = (width - TILE_GAP) / 2;

  // One photo keeps its aspect ratio: the caller's dimensions when it gave any, otherwise the image's
  // own once it has loaded. 4:3 is only the placeholder until then, and only for a photo whose size
  // this session has never seen; declaring `width`/`height` is what keeps the bubble from resizing at
  // all on a cold load.
  const [measured, setMeasured] = useState<{ src: string; aspect: number } | null>(null);
  const first: MessageImage | undefined = tiles[0];
  const firstSrc = first?.src ?? "";
  const declaredAspect = single && first?.width && first.height ? first.width / first.height : null;
  const learnedAspect = single ? (measured?.src === firstSrc ? measured.aspect : aspectMemo.get(firstSrc)) : undefined;
  const aspect = declaredAspect ?? learnedAspect ?? 4 / 3;

  // The clamp is the native one, so a very tall photo stops at 4:3 of its width and a very wide one at
  // 16:9, both cropped by `object-cover`; the group never grows past `maxHeight`, and when the clamped
  // shape would, the width comes in with it rather than the photo stretching.
  const box = photoBox[platform];
  const ceiling = maxHeight ?? box.maxHeight;
  const ratio = Math.min(Math.max(1 / aspect, box.minRatio), box.maxRatio);
  const groupWidth = single ? Math.min(width, ceiling / ratio) : width;
  const height = single ? groupWidth * ratio : tiles.length === 2 ? tileSize : tileSize * 2 + TILE_GAP;

  const grid = useMemo<CSSProperties>(() => {
    if (single) return { display: "block" };
    return { display: "grid", gridTemplateColumns: "1fr 1fr", gridTemplateRows: tiles.length === 2 ? "1fr" : "1fr 1fr", gap: TILE_GAP };
  }, [single, tiles.length]);

  const hang = tailBox.hang * m.tailScale;
  // The tail continues the photo, so it is filled from the tile that touches it: the bottom tile on
  // the tail's side. Three photos put a full-height tile first, so on an incoming message that first
  // tile is the one the tail meets; the 2x2 grid meets tile 3 on the left and tile 4 on the right.
  const tailIndex = side === "right" ? tiles.length - 1 : tiles.length === MAX_TILES ? 2 : 0;
  const [tailFill, setTailFill] = useState<{ key: string; color: string } | null>(null);
  // A tile is on the placeholder until its own <img> says otherwise, so the bubble is never a hole.
  const [phase, setPhase] = useState<Record<string, Phase>>({});
  const [attempt, setAttempt] = useState<Record<string, number>>({});
  const gridRef = useRef<HTMLDivElement>(null);

  // Runs on mount as well as on load: a server-rendered <img> is normally already complete by the
  // time React attaches its handlers, and then `onLoad` never fires at all, the tail stays gray and
  // every tile looks unloaded. It is a layout effect so a photo the browser already has is laid out
  // at its real shape in the same frame, instead of painting 4:3 once and resizing.
  const measure = useCallback(() => {
    const element = gridRef.current;
    if (!element) return;
    const rendered = element.querySelectorAll("img");
    // By tile index, not by position in the list: a tile that failed renders no <img> at all, and
    // counting elements would then sample the wrong photo for the tail.
    const edge = element.querySelector<HTMLImageElement>(`img[data-tile="${tailIndex}"]`);
    // Only ever replace a real colour with a real colour: a half-decoded image reads as null, and
    // dropping back to gray for a frame would flash the tail.
    const sampled = tail && edge ? sampleCorner(edge, side, tailBox.width * m.tailScale, tailBox.height * m.tailScale) : null;
    if (sampled) setTailFill(previous => (previous?.key === groupKey && previous.color === sampled ? previous : { key: groupKey, color: sampled }));
    setPhase(previous => {
      let next = previous;
      rendered.forEach(image => {
        if (!image.complete) return;
        const src = image.getAttribute("data-src") ?? image.src;
        const value: Phase = image.naturalWidth > 0 ? "ready" : "failed";
        if (previous[src] === value) return;
        if (next === previous) next = { ...previous };
        next[src] = value;
      });
      return next;
    });
    const photo = element.querySelector<HTMLImageElement>('img[data-tile="0"]');
    if (single && photo?.naturalWidth && photo.naturalHeight) {
      const value = photo.naturalWidth / photo.naturalHeight;
      aspectMemo.set(firstSrc, value);
      setMeasured(previous => (previous?.src === firstSrc && previous.aspect === value ? previous : { src: firstSrc, aspect: value }));
    }
  }, [single, tail, tailIndex, side, m.tailScale, groupKey, firstSrc, setMeasured, setPhase, setTailFill]);
  useLayoutEffect(() => { measure(); }, [measure]);

  const retry = useCallback((src: string) => {
    setPhase(previous => { const next = { ...previous }; delete next[src]; return next; });
    setAttempt(previous => ({ ...previous, [src]: (previous[src] ?? 0) + 1 }));
  }, []);

  const open = onOpenImage ?? (onOpen ? (index: number) => onOpen(index) : undefined);
  const busy = loading || tiles.some(image => phase[image.src] === undefined);
  const slot = reactionSlot[platform];
  // No photos is not an empty balloon: without this the group would paint a bare gray square the size
  // of a four-tile grid.
  if (!tiles.length) return null;

  return (
    <div data-slot="message-images" data-direction={direction} data-count={images.length}
      // ChatKit's `attachment.count` reads "%d attachments"; the group is named with the photo noun
      // its own `PHOTO_ATTACHMENT_STATUS_PHOTOS_TITLE_FORMAT` ("%tu Photos") uses. One photo needs no
      // group at all: the tile's own name already says everything.
      role={images.length > 1 ? "group" : undefined}
      aria-label={images.length > 1 ? `${images.length} Photos` : undefined}
      aria-busy={busy || undefined}
      className={cn("relative", className)}
      style={{ width: groupWidth, fontFamily: fontStack, marginTop: reactions ? slot.marginTop : undefined, ...style }} {...props}>
      <div ref={gridRef} data-slot="image-grid" style={{ ...grid, width: groupWidth, height, borderRadius: m.radius, overflow: "hidden", clipPath: tail ? bodyClipPath(side, m.tailScale, tailSeamOverlap[platform]) : undefined, background: "var(--im-gray-top)" }}>
        {tiles.map((image, index) => {
          const spanFirst = tiles.length === 3 && index === 0;
          const state = phase[image.src];
          const failed = state === "failed";
          const last = index === MAX_TILES - 1 && overflow > 0;
          const name = image.alt?.trim() || "Photo";
          // "Photo, 2 of 5" follows ChatKit's own `messages.attachment.stack.view.format`
          // ("attachment %1$d of %2$d"); the counted tile has to say what its "+N" opens.
          const position = images.length > 1 ? `${name}, ${index + 1} of ${images.length}` : name;
          // ChatKit's `attachment.count` carries a real plural rule ("%d attachment" / "%d attachments"),
          // so the counted tile gets one too rather than reading "1 more photos".
          const more = `Show ${overflow} more photo${overflow === 1 ? "" : "s"}.`;
          const label = failed ? `${position}. ${downloadLabel[platform]}.` : last ? `${position}. ${more}` : position;
          // A tile that cannot be fetched offers the fetch again, the way native's undownloaded
          // attachment does. Otherwise it opens the viewer, handing over its own box so the viewer can
          // grow out of this tile.
          const activate: ((event: MouseEvent<HTMLButtonElement>) => void) | undefined = failed
            ? () => retry(image.src)
            : open
              ? event => open(index, event.currentTarget.getBoundingClientRect())
              : undefined;
          // A button is a control for the pointer and the keyboard both, for free. With nothing to
          // open it would be a dead tab stop that reads out "dimmed", so the tile becomes a named
          // image instead: the photo keeps its accessible name either way.
          const shell = {
            "data-slot": "photo-tile", "data-index": index,
            "data-state": failed ? "failed" : state === "ready" ? "ready" : "loading",
            "aria-label": label,
            className: "relative block h-full w-full overflow-hidden p-0 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[#0088ff]",
            style: spanFirst ? { gridRow: "span 2" } : undefined,
          } as const;
          const inner = (
            <>
              {failed ? (
                // The placeholder the grid already paints, plus native's own copy for a photo it does
                // not have. Type size is not measured.
                <span data-slot="photo-failed" aria-hidden="true"
                  className="absolute inset-0 flex items-center justify-center px-[8px] text-center font-medium"
                  style={{ fontSize: platform === "ios" ? 15 : 13, lineHeight: 1.2, color: "var(--im-incoming-text)" }}>
                  {downloadLabel[platform]}
                </span>
              ) : (
                /* eslint-disable-next-line @next/next/no-img-element */
                <img key={attempt[image.src] ?? 0} src={image.src} data-src={image.src} data-tile={index} alt="" loading="lazy" decoding="async"
                  onLoad={measure} onError={measure}
                  className="h-full w-full object-cover" style={{ opacity: loading ? 0 : 1 }} />
              )}
              {last && (
                <span aria-hidden="true" className="absolute inset-0 flex items-center justify-center font-semibold text-white"
                  style={{ background: "rgba(0,0,0,0.42)", fontSize: platform === "ios" ? 22 : 17 }}>+{overflow}</span>
              )}
            </>
          );
          return activate
            ? <button key={image.src + index} type="button" onClick={activate} {...shell}>{inner}</button>
            : <div key={image.src + index} role="img" {...shell}>{inner}</div>;
        })}
      </div>
      {tail && (
        <div aria-hidden="true" data-slot="tail" className="pointer-events-none absolute"
          style={{ [side]: 0, bottom: -hang, width: tailBox.width * m.tailScale, height: tailBox.height * m.tailScale + hang, clipPath: `path("${tailPath(side, m.tailScale)}")`, background: tailFill?.key === groupKey ? tailFill.color : "var(--im-gray-bottom)" }} />
      )}
      {/* Outside the grid on purpose: the grid clips to the balloon's outline, and a balloon that laps
          the photo's rounded corner would lose its own edge to that clip. */}
      {reactions && (
        <div data-slot="reactions" className="absolute z-10" style={{ top: slot.top, [direction === "outgoing" ? "left" : "right"]: slot.side }}>{reactions}</div>
      )}
    </div>
  );
}

/** Override the sampled tail colour, e.g. when the image is cross-origin and cannot be read back. */
export function photoTailFill(color: string): CSSProperties {
  return { ["--im-gray-bottom" as string]: color } as CSSProperties;
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
  type CSSProperties,
  type KeyboardEvent as ReactKeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { bubbleMetrics, fontStack } from "@/components/imessage/tokens";
import { IosStatusBar } from "@/components/imessage/ios-status-bar";
import { Tapback, TapbackGlyph, balloonGeometry, balloonSlot, pickerBalloonGeometry, tapbackVars } from "@/components/imessage/tapback";
import { SmileyIcon, TapbackBar, tapbackBarMetrics, type TapbackSelection } from "@/components/imessage/tapback-bar";

/**
 * The full-screen photo viewer: what a photo in a bubble opens into.
 *
 * THIS SURFACE IS NOW CAPTURED. Messages does not draw a photo browser of its own — it presents
 * QuickLook, and `ChatKit.CKQLPreviewController` is the `QLPreviewController` subclass it presents.
 * That subclass can be instantiated outside Messages, so the screen was reproduced and shot:
 *
 *   1. A throwaway iOS app (`clang -target arm64-apple-ios18.0-simulator`) with a `QLPreviewItem`
 *      data source over five generated JPEGs, installed on a private iPhone 17 Pro / iOS 26.0
 *      (23A343) simulator with `xcrun simctl install`.
 *   2. `dlopen("/System/Library/PrivateFrameworks/ChatKit.framework/ChatKit")` inside that app,
 *      `objc_getClass("CKQLPreviewController")`, present it full screen.
 *   3. `xcrun simctl io <udid> screenshot` at 402x874 @3x, and a walk of the live view hierarchy
 *      logging every frame in window coordinates — so the bar geometry is read off the runtime, not
 *      guessed from pixels, and the screenshot only confirms it.
 *
 * Captures: `references/ios/captures/image-viewer-chrome-dark.png` (chrome up over the black ground)
 * and `image-viewer-fit-dark.png` (a 3:4 photo fitted, chrome auto-hidden). Written up in
 * `references/image-viewer.md` and `references/SPEC.md`.
 *
 * WHAT THE CAPTURE OVERTURNED. The chrome is not two opaque bars with a scrim and a centred title.
 * On iOS 26 it is three Liquid Glass circles floating over the photo: a close X top right, and a
 * bottom row of reply (left) and share (right). There is no "Done" text button, no title text and no
 * thumbnail tray. `-[CKQLPreviewController updateBarButtonItems]` disassembles to a single `ret`, so
 * ChatKit builds no bars at all: `loadView` only sets `navigationBar.barStyle`, and QuickLook lays
 * the buttons out itself (`-tapbackButtonFrameForFullScreenBalloonViewController:` forwards to
 * `-frameForAdditionalButtonWithActionName:`, QuickLook's own additional-button slot).
 *
 * FRAMEWORK values are read out of the binaries on this Mac (macOS 26.5.2, Messages 26.0) from a
 * macCatalyst process that dlopens the iOSSupport frameworks. `PUOneUpSettings` is idiom-dependent
 * and its singleton latches the idiom at first `+sharedInstance`, so every read below was taken in a
 * fresh process with `-[UIDevice userInterfaceIdiom]` swizzled to 0 (phone) BEFORE the first access.
 * That is the difference between `interpageSpacing` 40 (phone and mac) and 100 (pad); a plain
 * Catalyst process reports pad. Method bodies come from `lldb ... -o "disassemble -n '-[Class sel]'"`
 * against the loaded image, because the on-disk binaries are shared-cache stubs.
 *
 * The accessible names are ChatKit's own, from
 * `AccessibilityBundles/ChatKitFramework.axbundle/Contents/Resources/Accessibility.loctable`:
 * `photo.attachment` = "Photo", `messages.attachment.stack.view.format` = "attachment %1$d of %2$d",
 * `save.photo.button` = "Save photo", `balloon.message.reply` = "Reply". The live bar buttons carry
 * `accessibilityLabel` "close", "reply" and "Share".
 *
 * JUDGEMENT, with no framework symbol and no capture behind it — each one says so again where it
 * lives, and they are listed in SPEC's "what is not measured": the thresholds that commit a swipe or
 * a dismissal, the scale the photo shrinks to while it is being flung away, where an applied tapback
 * balloon sits on a full-screen photo, the save and tapback buttons' glyphs and their slot in the
 * bar, and the whole macOS presentation.
 *
 * SEEKABLE. The entrance and the exit are one Web Animations timeline per layer, so
 * `document.getAnimations()` reaches them and `progress` pauses and seeks instead of playing. With
 * `progress` set, every CSS transition in the tree is switched off and the chrome's auto-hide timer
 * never arms, so a checkpoint renders the same frame every run.
 */
export const imageViewerMetrics = {
  /**
   * The viewer's ground. `PUBlackOneUpInterfaceTheme -photoBrowserChromeVisibleBackgroundColor` and
   * `-photoBrowserChromeHiddenBackgroundColor` both resolve to opaque black in the light AND the dark
   * trait collection, so the viewer does not follow the theme: it is black either way. Confirmed in
   * `image-viewer-fit-dark.png`, where every pixel outside the fitted photo is exactly (0,0,0).
   */
  ground: "#000000",
  /**
   * The Liquid Glass disc every chrome button is drawn on, MEASURED off
   * `image-viewer-chrome-dark.png` over the viewer's own black ground: the disc's interior reads
   * #131313 (19/255), i.e. white at 7.45% over black, and its outer edge peaks at 52/255, i.e. a rim
   * of white at 14% on top of that fill. The glyph ink reads #f3f3f3, not pure white. A disabled
   * glyph (the capture's reply button, which had no delegate to enable it) peaks at 90/255, which is
   * 0.32 of the enabled ink over the same disc.
   *
   * `blur` is the one number here that a capture cannot give back: the ground behind the discs is
   * flat black, so no radius is recoverable from it. UNMEASURED.
   */
  glass: {
    fill: "rgba(255,255,255,0.0745)",
    rim: "rgba(255,255,255,0.14)",
    ink: "#f3f3f3",
    disabledInk: 0.32,
    blur: 20,
  },
  /**
   * Where the chrome sits. iOS is MEASURED from the live view hierarchy of `CKQLPreviewController`
   * on an iPhone 17 Pro at 402x874:
   *   - `UIWindow.safeAreaInsets` = {62, 0, 34, 0}. Note this is NOT the 54 the status bar's ink
   *     occupies (SPEC's "status bar 0-54"): the layout inset is 62, and there is a 34pt home
   *     indicator inset the conversation captures never showed.
   *   - `UINavigationBar` frame {0, 62, 402, 54}, i.e. it begins exactly at the safe-area top; its
   *     `_UIBarBackground` spans {0, 0, 402, 116}, which is the bar plus `barsOutset`.
   *   - The nav bar's `_UINavigationBarPlatterView`s are 44x44 at (16, 62) and (342, 62), so 16 in
   *     from each edge. ChatKit's build has only the right one (`accessibilityLabel` "close").
   *   - The floating bottom bar is {0, 798, 402, 76}; its button row is {28, 798, 346, 48} and its
   *     `UIPlatformGlassInteractionView`s are 48x48 at (28, 798) and (326, 798).
   * Both slots reproduce numbers SPEC already carries for other screens: the conversation's back
   * button is "a 44pt circle centered (38, 84)" = (16, 62, 44, 44), and the list's compose button is
   * "Ø48 centered (350, 822)" = (326, 798, 48, 48). Same slots, independently measured twice.
   *
   * macOS is UNMEASURED. Messages on macOS is the same Catalyst binary presenting the same
   * QuickLook, so the disc sizes and the horizontal insets are carried over unchanged and only
   * `header.top` is invented — a window has no safe area to hang the bar off.
   */
  chrome: {
    ios: {
      // The header's top IS the safe-area top: `UINavigationBar.frame.origin.y` and
      // `safeAreaInsets.top` are both 62, measured in the same hierarchy dump.
      safeArea: { top: 62, bottom: 34 },
      header: { size: 44, inset: 16 },
      footer: { size: 48, inset: 28, bottom: 28 },
    },
    macos: {
      // A window has no safe area, so `top` here is the inset the chrome keeps instead. UNMEASURED;
      // everything else is carried over from iOS, which is the same Catalyst binary.
      safeArea: { top: 16, bottom: 0 },
      header: { size: 44, inset: 16 },
      footer: { size: 48, inset: 28, bottom: 28 },
    },
  },
  /**
   * Glyph ink boxes, MEASURED. The reply and share sizes are the `UIImage` symbol sizes logged off
   * the live `_UIModernBarButton`s (`arrowshape.turn.up.left` 21.333 x 17.333,
   * `square.and.arrow.up` 19 x 22); the close X is the ink box traced in the capture, 17 x 17
   * centred on the disc.
   *
   * `save` and `tapback` are UNMEASURED: ChatKit has `-saveTapped:` and `-tapbackTapped:` and the
   * axbundle has "Save photo", but neither button appears in the bar unless a
   * `ckQLPreviewControllerDelegate` supplies a chat item, which a probe outside Messages cannot do.
   * Their glyphs and their slot in the bar are drawn to match the two that were measured.
   */
  glyph: {
    close: 17,
    reply: { width: 21.67, height: 19.67, offsetX: -1.17, offsetY: 0.17 },
    share: { width: 18.67, height: 24 },
    save: { width: 18.67, height: 24 },
    tapback: 21,
  },
  /**
   * `PUOneUpSettings -barsAreaVerticalOutset` = 10: how far the bars' AREA runs past the bars
   * themselves. It checks out against the capture — the nav bar's background is 116 tall and the bar
   * itself ends at 62 + 44 = 106.
   */
  barsOutset: 10,
  /**
   * `PUOneUpSettings -interpageSpacing`. 40 under idiom 0 (phone) and idiom 5 (mac), 100 under idiom
   * 1 (pad). This file used to carry the pad value, which put 60pt too much black between photos on
   * every swipe and threw the parallax off with it. The gap is the viewer's ground, so it reads as
   * black.
   */
  interpageSpacing: 40,
  /** `PUOneUpSettings -doubleTapZoomFactor` = 2.5. */
  doubleTapZoom: 2.5,
  /** `PUOneUpSettings -defaultZoomInFactor` = 6, the pinch ceiling. */
  maxZoom: 6,
  /** `PUOneUpSettings -allowDoubleTapZoom`, `-allowChromeHiding` and `-allowUserTransform` are all 1. */
  allowDoubleTapZoom: true,
  allowChromeHiding: true,
  /**
   * `-doubleTapZoomAreaExcludesBackground` = 1 and `-doubleTapZoomAreaExcludesBars` = 1: a double tap
   * on the letterboxed black, or inside the bars' area, does not zoom. `doubleTapTarget` below is
   * where it does.
   */
  doubleTapExcludesBackground: true,
  doubleTapExcludesBars: true,
  /**
   * `PUOneUpSettings -parallaxFactor` = 12.5 with `-allowParallax` = 1 and `-parallaxModel` = 1:
   * while a page moves, its photo lags by 1/12.5 of that page's offset, so the strip does not slide
   * as one sheet.
   */
  parallaxFactor: 12.5,
  /**
   * `PUOneUpSettings -chromeAutoHideDelay` = 3 s with `-allowChromeHiding` = 1 and
   * `-persistChromeVisibility` = 0. This is not theoretical: in the capture run the chrome was up at
   * 1.4 s and gone by 2.6 s without any input, so the viewer really does drop its chrome on a timer.
   */
  chromeAutoHideDelay: 3000,
  /**
   * `PUOneUpSettings -chromeAutoHideBehaviorOnZoom` = 2. The raw value is measured; what the enum's
   * cases mean is not, so this component takes the only reading that is consistent with the other
   * two `chromeAutoHideBehavior*` settings and hides the chrome when the photo leaves fit.
   */
  hideChromeOnZoom: true,
  /**
   * `PUOneUpSettings -userNavigationMaximumDistance` = 2: how far ahead of the current item the pager
   * keeps content ready. Used as the mount window, so a twenty-photo message mounts five pages, not
   * twenty.
   */
  pageWindow: 2,
  /**
   * Rubber band. UIScrollView's documented resistance constant, which every Apple scroll view uses
   * and the one-up pager is one. NOT read out of PhotosUI: platform default, not a measurement.
   */
  rubberBand: 0.55,
  /**
   * Committing a swipe. JUDGEMENT, no framework value: the page flips when the drag passes a third of
   * the frame or the flick is faster than 500 pt/s. (`-pagingFrictionAdjustment` = 2 and
   * `-pagingSpringPullAdjustment` = 0 are the only paging numbers PhotosUI exposes and neither is a
   * threshold.)
   */
  pageCommit: { distance: 1 / 3, velocity: 500 },
  /**
   * Committing a drag-to-dismiss, and how far the photo shrinks on the way down. JUDGEMENT:
   * `PUOneUpSettings` carries no dismissal threshold. 120 pt of travel or a 700 pt/s flick, with the
   * photo scaling to 0.6 across that travel.
   */
  dismiss: { distance: 120, velocity: 700, minScale: 0.6 },
  /**
   * How far the ground dims under an interactive dismissal.
   * `PUTilingViewSettings -interactiveTransitionBackgroundDimming` = 0.5, so the black goes to 50%
   * across the drag and the conversation shows through behind it — it does not fade away entirely.
   */
  dismissDimming: 0.5,
  /** How far a pointer has to move before a drag stops being a tap. JUDGEMENT. */
  slop: 6,
  /** How long a second tap counts as a double tap, and how far it may land from the first. JUDGEMENT. */
  doubleTap: { window: 300, slop: 24 },
  timing: {
    /** `PUTilingViewSettings -springAnimationDuration` = 0.3, with `-useSpringAnimations` = 1. The open zoom, the exit that reverses it, and every settle of the photo's own transform. */
    zoom: 300,
    /** `PUTilingViewSettings -transitionDuration` = 0.2: the ground coming up behind the zoom. */
    backdrop: 200,
    /** `PUOneUpSettings -chromeDefaultAnimationDuration` = 0.2. */
    chrome: 200,
    /** `PUTilingViewSettings -transitionChromeDelay` = 0: the chrome arrives with the zoom, not after it. */
    chromeDelay: 0,
    /** `PUOneUpSettings -finalFadeOutDuration` = 0.2. Used when there is no tile to zoom out of. */
    fade: 200,
    /**
     * `PUOneUpSettings -bounceDuration` = 0.5 with `-bounceSpringDamping` = 1 (critically damped, no
     * overshoot) and `-bounceDelay` = 0. This is the snap back from an OVERSCROLLED pan and nothing
     * else. A double tap, a pinch settle and a page settle all take `zoom` (0.3); this file used to
     * route every one of them through 0.5.
     */
    bounce: 500,
    /** Paging under its own steam, e.g. an arrow key. `PUTilingViewSettings -springAnimationDuration`. */
    page: 300,
    /** `ChatKit.CKUIBehaviorPhone -tapbackDismissalDuration` = 0.5: how long the picker takes to leave. */
    tapbackDismiss: 500,
  },
  /**
   * The easing on the zoom. `PUTilingViewSettings` says spring, overshoot allowed
   * (`-useOvershootingSpringAnimations` = 1), but carries no stiffness or damping to read, so this is
   * the standard curve the rest of the kit uses. JUDGEMENT.
   */
  ease: "cubic-bezier(0.32, 0.72, 0, 1)",
} as const;

export type ImageViewerRect = { x: number; y: number; width: number; height: number };
export type ImageViewerPhoto = { src: string; alt?: string; width?: number; height?: number };
export type ImageViewerSize = { width: number; height: number };

export type ImageViewerProps = Omit<ComponentProps<"div">, "children" | "onSelect"> & {
  /** The photos of the message that was tapped. Paging runs over exactly these. */
  photos: ImageViewerPhoto[];
  /** Which one is showing. Controlled when given, otherwise the viewer keeps its own. */
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
  /**
   * The tapped tile's box in the viewer's OWN coordinates, i.e. relative to the element this viewer
   * fills. A caller holding a viewport `DOMRect` (which is what `MessageImages onOpenImage` hands
   * over) subtracts the viewer host's own `getBoundingClientRect()` first. The open zoom starts here;
   * null falls back to a fade, which is what a viewer opened from a keyboard or a deep link should
   * do.
   */
  sourceRect?: ImageViewerRect | null;
  /**
   * Where each photo's tile is, so the EXIT lands on the photo that is actually showing. Native
   * returns the current item to its own tile and fades when that tile is off-screen; a viewer given
   * only `sourceRect` flies photo 4 back into photo 1's thumbnail. Return null for a tile that is not
   * on screen and the exit fades instead.
   */
  rectForIndex?: (index: number) => ImageViewerRect | null;
  /** The tile's corner radius, so the zoom starts with the bubble's corner and squares off on the way out. */
  sourceRadius?: number;
  /** False plays the exit and then calls `onExited`. Derive it during render, never in an effect. */
  open?: boolean;
  onExited?: () => void;
  onClose?: () => void;
  /** Seek the entrance to this fraction (0..1) instead of playing it, and freeze every transition. */
  progress?: number;
  /**
   * Header lines. OFF by default and rendered only when given, because the measured iOS 26 chrome has
   * none: `CKQLPreviewController` sets `navigationItem.title` to the preview item's title, but the
   * bar draws no title view and the capture shows no text anywhere in the chrome.
   */
  title?: string;
  subtitle?: string;
  /** Show "2 of 5" beside the subtitle. Off by default: neither `PUOneUpSettings` nor QuickLook has a page indicator. */
  pageIndicator?: boolean;
  /** Header and footer visibility. Controlled when given; tapping the photo toggles it either way. */
  chrome?: boolean;
  onChromeChange?: (visible: boolean) => void;
  /**
   * Drop the chrome after `chromeAutoHideDelay` with no input, the way the capture run showed the
   * real viewer doing. Never arms while `progress` is set, so a scrubbed checkpoint is stable.
   */
  autoHideChrome?: boolean;
  /**
   * Drive the drag-to-dismiss pose from outside: 0 at rest, 1 at the commit threshold. Given, it
   * replaces the finger's own travel, so a harness checkpoint or a lab scene can hold the pose the
   * gesture passes through instead of having to synthesise a drag.
   */
  dismissProgress?: number;
  /** Fit is 1. Controlled when given. */
  zoom?: number;
  onZoomChange?: (zoom: number) => void;
  /**
   * The reaction on the photo that is showing, and the picker over it. Reacting from inside the
   * viewer is real: `CKQLPreviewController` has `-tapbackTapped:`, `-tapbackButton`,
   * `-_sendTapback:targetChatItem:isRemoval:` and a full `CKFullScreenBalloonViewController` delegate
   * surface, and `-shouldShowTapbackPickerForFullScreenBalloonViewController:` asks the chat
   * controller per item.
   */
  reaction?: TapbackSelection | null;
  onReact?: (selection: TapbackSelection) => void;
  tapbackOpen?: boolean;
  onTapbackOpenChange?: (open: boolean) => void;
  recent?: string[];
  /**
   * Who reacted, shown beside the balloon.
   * `-shouldShowTapbackAttributionForFullScreenBalloonViewController:` is delegated per chat item, so
   * the real surface can show it. Its placement here is UNMEASURED.
   */
  reactionAttribution?: string;
  /** QuickLook's own share button, `_actionButtonTapped:`. Always in the bar. */
  onShare?: () => void;
  /** ChatKit's `-replyTapped:`. The button is always in the bar and is DISABLED when this is absent, which is what `-shouldShowReplyButtonForMediaObject:previewController:` does to it natively. */
  onReply?: () => void;
  /** ChatKit's `-saveTapped:`, gated natively on `-canCurrentPreviewItemQuickSave`. Omit and no save button is drawn. */
  onSave?: () => void;
  /** `-currentPreviewItemIsSaved`: the save button reports the item is already in the library. */
  saved?: boolean;
  /** Insets the chrome stays inside. Defaults to the platform's measured ones. */
  safeArea?: { top?: number; bottom?: number };
  /** Draw the status bar. `PUOneUpSettings -allowStatusBar` = 1 and the capture shows it, in white over the black ground. */
  statusBar?: boolean;
  /** Clock text for that status bar. */
  time?: string;
  /** The viewer's own size before it can measure itself, e.g. during a server render. */
  frame?: ImageViewerSize;
  platform?: Platform;
};

/** The largest box of `aspect` that fits inside `frame`, centred. Native fits a photo, it does not fill. */
export function fitPhotoRect(aspect: number, frame: ImageViewerSize): ImageViewerRect {
  const width = Math.min(frame.width, frame.height * aspect);
  const height = width / aspect;
  return { x: (frame.width - width) / 2, y: (frame.height - height) / 2, width, height };
}

/**
 * UIScrollView's resistance: the first point of overscroll moves almost one for one and the curve
 * flattens from there, never passing `c * dimension`.
 */
export function rubberBand(distance: number, dimension: number, c: number = imageViewerMetrics.rubberBand): number {
  if (!dimension) return 0;
  const magnitude = Math.abs(distance);
  return Math.sign(distance) * (1 - 1 / (magnitude / (c * dimension) + 1)) * c * dimension;
}

function clamp(value: number, low: number, high: number) {
  return Math.min(high, Math.max(low, value));
}

function prefersReducedMotion() {
  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;
}

/**
 * The two poses of the open zoom, in the zoom layer's own coordinates with `transform-origin: 0 0`.
 * The end pose is the identity, because the photo is already fitted in the frame. The start pose
 * scales the whole frame down until the fitted photo covers `source` exactly, clips away everything
 * outside it, and divides the tile's corner radius by the same scale so it lands at `radius` on
 * screen. Both poses are `inset()` clips of the same shape, which is what makes the pair animatable.
 */
export function zoomPose(source: ImageViewerRect | null, fit: ImageViewerRect, frame: ImageViewerSize, radius: number) {
  const settled = { transform: "translate(0px, 0px) scale(1)", clipPath: "inset(0px 0px 0px 0px round 0px)", opacity: 1 };
  if (!source || !fit.width || !fit.height) {
    return { start: { transform: "translate(0px, 0px) scale(0.94)", clipPath: settled.clipPath, opacity: 0 }, end: settled };
  }
  const scale = Math.max(source.width / fit.width, source.height / fit.height);
  const tx = source.x + source.width / 2 - scale * (fit.x + fit.width / 2);
  const ty = source.y + source.height / 2 - scale * (fit.y + fit.height / 2);
  const left = (source.x - tx) / scale;
  const top = (source.y - ty) / scale;
  const width = source.width / scale;
  const height = source.height / scale;
  return {
    start: {
      transform: `translate(${tx}px, ${ty}px) scale(${scale})`,
      clipPath: `inset(${top}px ${frame.width - left - width}px ${frame.height - top - height}px ${left}px round ${radius / scale}px)`,
      opacity: 1,
    },
    end: settled,
  };
}

/**
 * Where a double tap is allowed to zoom, from `-doubleTapZoomAreaExcludesBackground` = 1 and
 * `-doubleTapZoomAreaExcludesBars` = 1: inside the fitted photo, and outside the bars' areas — which
 * are each bar's band grown by `barsAreaVerticalOutset`.
 */
export function doubleTapTarget(point: { x: number; y: number }, fit: ImageViewerRect, frame: ImageViewerSize, bars: { top: number; bottom: number }): boolean {
  const m = imageViewerMetrics;
  if (m.doubleTapExcludesBackground) {
    const inside = point.x >= fit.x && point.x <= fit.x + fit.width && point.y >= fit.y && point.y <= fit.y + fit.height;
    if (!inside) return false;
  }
  if (m.doubleTapExcludesBars) {
    if (point.y < bars.top || point.y > frame.height - bars.bottom) return false;
  }
  return true;
}

/**
 * Which pages are mounted. `PUOneUpSettings -userNavigationMaximumDistance` = 2, so the pager keeps
 * two items either side ready and everything past that is not in the tree at all.
 */
export function pageWindow(index: number, count: number, distance: number = imageViewerMetrics.pageWindow): number[] {
  const pages: number[] = [];
  for (let i = Math.max(0, index - distance); i <= Math.min(count - 1, index + distance); i++) pages.push(i);
  return pages;
}

