type Point = { x: number; y: number };

type Gesture = {
  pointers: Map<number, Point>;
  mode: "none" | "undecided" | "page" | "dismiss" | "pan" | "pinch";
  start: Point;
  startPan: Point;
  startZoom: number;
  startSpread: number;
  startMid: Point;
  last: Point;
  lastTime: number;
  velocity: Point;
  tapTime: number;
  tapPoint: Point;
};

function spreadOf(points: Point[]) {
  return Math.hypot(points[0].x - points[1].x, points[0].y - points[1].y);
}

function midpointOf(points: Point[]): Point {
  return { x: (points[0].x + points[1].x) / 2, y: (points[0].y + points[1].y) / 2 };
}

/** How long the photo's own transform takes to settle, per the thing that started it moving. */
type Motion = "none" | "settle" | "bounce" | "page";

export function ImageViewer({
  photos,
  index: indexProp,
  defaultIndex = 0,
  onIndexChange,
  sourceRect = null,
  rectForIndex,
  sourceRadius,
  open = true,
  onExited,
  onClose,
  progress,
  title,
  subtitle,
  pageIndicator = false,
  chrome: chromeProp,
  onChromeChange,
  autoHideChrome = true,
  dismissProgress,
  zoom: zoomProp,
  onZoomChange,
  reaction = null,
  onReact,
  tapbackOpen: tapbackOpenProp,
  onTapbackOpenChange,
  recent,
  reactionAttribution,
  onShare,
  onReply,
  onSave,
  saved = false,
  safeArea,
  statusBar,
  time,
  frame: frameProp,
  platform: platformProp,
  className,
  style,
  ...props
}: ImageViewerProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = imageViewerMetrics;
  const chromeBox = m.chrome[platform];
  const inset = { ...chromeBox.safeArea, ...safeArea };
  const radius = sourceRadius ?? bubbleMetrics[platform].radius;
  const scrubbed = progress !== undefined;
  const count = photos.length;
  const showStatusBar = statusBar ?? platform === "ios";

  const root = useRef<HTMLDivElement>(null);
  const backdrop = useRef<HTMLDivElement>(null);
  const zoomLayer = useRef<HTMLDivElement>(null);
  const chromeLayer = useRef<HTMLDivElement>(null);
  const tapbackButton = useRef<HTMLButtonElement>(null);
  const exited = useRef(false);
  const tapTimer = useRef<number | undefined>(undefined);
  const motionTimer = useRef<number | undefined>(undefined);

  // The viewer lays out in its own coordinates, so it has to know its own box before it can fit a
  // photo or read `sourceRect`. `frame` covers the render before the observer has fired.
  const [measuredFrame, setMeasuredFrame] = useState<ImageViewerSize | null>(null);
  const frame = useMemo(
    () => measuredFrame ?? frameProp ?? (platform === "ios" ? { width: 402, height: 874 } : { width: 960, height: 640 }),
    [measuredFrame, frameProp, platform],
  );
  useLayoutEffect(() => {
    const node = root.current;
    if (!node) return;
    const sync = () => setMeasuredFrame({ width: node.clientWidth, height: node.clientHeight });
    sync();
    const observer = new ResizeObserver(sync);
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  const [internalIndex, setInternalIndex] = useState(defaultIndex);
  const index = clamp(indexProp ?? internalIndex, 0, Math.max(0, count - 1));
  const setIndex = useCallback(
    (next: number) => {
      const bounded = clamp(next, 0, Math.max(0, count - 1));
      if (indexProp === undefined) setInternalIndex(bounded);
      onIndexChange?.(bounded);
    },
    [indexProp, onIndexChange, count],
  );

  const [internalChrome, setInternalChrome] = useState(true);
  const chromeVisible = chromeProp ?? internalChrome;
  const setChrome = useCallback(
    (next: boolean) => {
      if (chromeProp === undefined) setInternalChrome(next);
      onChromeChange?.(next);
    },
    [chromeProp, onChromeChange],
  );
  // Callers pass `onChromeChange` inline, so `setChrome` is a new function every parent render. The
  // auto-hide timer reads it through a ref instead, or a render would restart the countdown.
  const setChromeRef = useRef(setChrome);
  useLayoutEffect(() => {
    setChromeRef.current = setChrome;
  });

  const [internalZoom, setInternalZoom] = useState(1);
  const zoom = clamp(zoomProp ?? internalZoom, 1, m.maxZoom);
  const setZoom = useCallback(
    (next: number) => {
      const bounded = clamp(next, 1, m.maxZoom);
      if (zoomProp === undefined) setInternalZoom(bounded);
      onZoomChange?.(bounded);
    },
    [zoomProp, onZoomChange, m.maxZoom],
  );

  const [internalTapback, setInternalTapback] = useState(false);
  const tapbackOpen = tapbackOpenProp ?? internalTapback;
  const setTapbackOpen = useCallback(
    (next: boolean) => {
      if (tapbackOpenProp === undefined) setInternalTapback(next);
      onTapbackOpenChange?.(next);
    },
    [tapbackOpenProp, onTapbackOpenChange],
  );
  // The same derive-during-render rule the shells use for the long-press overlay: the picker has to
  // outlive the flag that opened it, because an effect would leave one committed frame with it
  // already gone and its dismissal would never be seen.
  const [seenTapbackOpen, setSeenTapbackOpen] = useState(tapbackOpen);
  const [tapbackClosing, setTapbackClosing] = useState(false);
  if (seenTapbackOpen !== tapbackOpen) {
    setSeenTapbackOpen(tapbackOpen);
    setTapbackClosing(!tapbackOpen && seenTapbackOpen);
  }

  // Where the footer's tapback button actually sits, so the picker's thought bubble points at it
  // rather than at the middle of the bar: how many controls the footer holds depends on which
  // handlers the caller wired.
  const [tapbackCentre, setTapbackCentre] = useState<number | null>(null);
  useLayoutEffect(() => {
    const node = tapbackButton.current;
    const host = root.current;
    if (!node || !host) return;
    // Against the viewer's own box, not `offsetLeft`: the footer is an inset positioned element, so
    // `offsetLeft` is measured from ITS left edge and lands the picker's tail 28 pt off.
    const sync = () => {
      const button = node.getBoundingClientRect();
      const box = host.getBoundingClientRect();
      setTapbackCentre(button.left - box.left + button.width / 2);
    };
    sync();
    const observer = new ResizeObserver(sync);
    observer.observe(node);
    observer.observe(host);
    return () => observer.disconnect();
  }, [frame.width, onSave, onReply]);

  const [pan, setPan] = useState<Point>({ x: 0, y: 0 });
  const [dragX, setDragX] = useState(0);
  const [drop, setDrop] = useState<Point>({ x: 0, y: 0 });
  const [motion, setMotionState] = useState<Motion>("none");
  const [aspects, setAspects] = useState<Record<string, number>>({});

  // `motion` used to be a boolean that only `onPointerDown` ever cleared, so any keyboard action left
  // the settle transition armed for good. It now clears itself after the animation it describes.
  const beginMotion = useCallback((kind: Exclude<Motion, "none">) => {
    setMotionState(kind);
    window.clearTimeout(motionTimer.current);
    const duration = kind === "bounce" ? imageViewerMetrics.timing.bounce : kind === "page" ? imageViewerMetrics.timing.page : imageViewerMetrics.timing.zoom;
    motionTimer.current = window.setTimeout(() => setMotionState("none"), duration);
  }, []);
  const endMotion = useCallback(() => {
    window.clearTimeout(motionTimer.current);
    setMotionState("none");
  }, []);

  const aspectOf = useCallback(
    (photo: ImageViewerPhoto | undefined) => (photo && photo.width && photo.height ? photo.width / photo.height : (photo && aspects[photo.src]) || 4 / 3),
    [aspects],
  );
  const fit = useMemo(() => fitPhotoRect(aspectOf(photos[index]), frame), [aspectOf, photos, index, frame]);

  const pitch = frame.width + m.interpageSpacing;
  const trackX = -index * pitch + dragX;

  /* ------------------------------------------------------------------ chrome geometry */

  // The bars' areas, which the double-tap zoom is not allowed into and which the picker has to clear.
  const headerBand = inset.top + chromeBox.header.size + m.barsOutset;
  const footerBand = chromeBox.footer.bottom + chromeBox.footer.size + m.barsOutset;
  // How far the whole thought bubble hangs below the pill. `TapbackBar` puts the blob's centre
  // `pickerDrop` below the pill's bottom, and the two trailing circles hang further still: the small
  // one's bottom lands `pickerDrop + smallOffset[1] + small / 2` = 49.37 down. Measuring only to the
  // blob (36.67) drove the trail 12.7 pt into the button it is meant to be pointing at.
  const pickerLift = tapbackBarMetrics.ios.pickerDrop + pickerBalloonGeometry.smallOffset[1] + pickerBalloonGeometry.small / 2;
  // The pill floats far enough above the footer that the thought bubble's lowest dot lands exactly on
  // the tapback button's top edge. Derived from the measured footer and the measured bubble geometry
  // — not itself a measured gap.
  const pickerBottom = chromeBox.footer.bottom + chromeBox.footer.size + pickerLift;
  const pickerInset = tapbackBarMetrics.ios.edgeInset;
  const pickerWidth = frame.width - pickerInset * 2;
  // Where the thought bubble's blob goes, in the pill's own coordinates. `TapbackBar` hangs the blob
  // at `pickerX` and its trailing circles down and to the LEFT of it, the small one landing on the
  // blob's own centre line minus `smallOffset[0]`. Over a bubble that trail points at the bubble, so
  // over a photo it points at the button the picker belongs to: the blob is offset by that much so
  // the small circle, not the blob, lands on the tapback button. Derived from the measured balloon
  // geometry; nothing measures the placement itself.
  const pickerAim = (tapbackCentre ?? frame.width / 2) - pickerInset - pickerBalloonGeometry.smallOffset[0];
  const pickerX = clamp(pickerAim, pickerBalloonGeometry.main / 2, Math.max(pickerBalloonGeometry.main / 2, pickerWidth - pickerBalloonGeometry.main / 2));

  // How far the drag has carried the dismissal: 0 at rest, 1 where it commits. Only DOWNWARD travel
  // counts — dragging up used to shrink the photo, fade the ground and hide the chrome before
  // snapping back, because this read `Math.abs(drop.y)` while the commit test read `drop.y`.
  const shift = dismissProgress === undefined ? drop : { x: 0, y: clamp(dismissProgress, 0, 1) * m.dismiss.distance };
  const dropProgress = clamp(Math.max(0, shift.y) / m.dismiss.distance, 0, 1);
  const dropScale = 1 - (1 - m.dismiss.minScale) * dropProgress;

  /* ------------------------------------------------------------------ entrance and exit */

  // Which item the viewer opened on. The entrance keys off THIS one, so paging cannot restart it,
  // while the pose below tracks whichever photo is showing so the exit lands on its own tile.
  // State, not a ref, because it is read during render: a lazy initial value that never changes.
  const [openIndex] = useState(index);
  const openRect = rectForIndex ? rectForIndex(openIndex) : sourceRect;
  const exitRect = rectForIndex ? rectForIndex(index) : index === openIndex ? sourceRect : null;

  const pose = useMemo(() => zoomPose(exitRect, fit, frame, radius), [exitRect, fit, frame, radius]);
  // The keyframes are read from a ref inside the timeline effect, so a re-render that only moves the
  // page or the pan cannot restart the entrance mid-flight.
  const poseRef = useRef(pose);
  const durationRef = useRef(0);
  // Written in a layout effect rather than in render: layout effects all run before the passive
  // effect below, so the timeline still reads the pose this render computed.
  useLayoutEffect(() => {
    poseRef.current = pose;
    durationRef.current = exitRect ? m.timing.zoom : m.timing.fade;
  });
  // `sourceRect` is a fresh object on every parent render, so the timeline keys off its values.
  const sourceKey = openRect ? `${openRect.x},${openRect.y},${openRect.width},${openRect.height}` : "";

  // Callers normally pass `onExited` inline, and it must not be an effect dependency: a parent
  // re-render mid-exit would cancel the exit and start it again, and it would never finish.
  const onExitedRef = useRef(onExited);
  useLayoutEffect(() => {
    onExitedRef.current = onExited;
  });

  useEffect(() => {
    exited.current = false;
    return () => {
      window.clearTimeout(tapTimer.current);
      window.clearTimeout(motionTimer.current);
    };
  }, []);

  useEffect(() => {
    const stage = zoomLayer.current;
    const ground = backdrop.current;
    const chromeNode = chromeLayer.current;
    if (!stage || !ground) return;
    const reduced = prefersReducedMotion();
    const duration = durationRef.current || (sourceKey ? m.timing.zoom : m.timing.fade);
    const { start, end } = poseRef.current;

    const finish = () => {
      if (exited.current) return;
      exited.current = true;
      onExitedRef.current?.();
    };

    if (open) {
      if (reduced && !scrubbed) return;
      const running = [
        stage.animate([start, end], { duration, easing: m.ease, fill: "both" }),
        ground.animate([{ opacity: 0 }, { opacity: 1 }], { duration: m.timing.backdrop, easing: "linear", fill: "both" }),
        chromeNode?.animate([{ opacity: 0 }, { opacity: 1 }], { duration, delay: m.timing.chromeDelay, easing: "linear", fill: "both" }),
      ].filter(Boolean) as Animation[];
      if (scrubbed) {
        // Seeked, not played: a scrubbed checkpoint has to land on the same frame every run.
        const at = clamp(progress ?? 0, 0, 1) * duration;
        for (const animation of running) {
          animation.pause();
          animation.currentTime = Math.min(at, Number(animation.effect?.getTiming().duration ?? duration));
        }
      }
      return () => running.forEach(animation => animation.cancel());
    }

    if (reduced) {
      // `finish` is the parent's `onExited`, i.e. a setState in another component. Calling it in the
      // effect body is the exact thing the lint rule forbids one boundary further in, so it goes out
      // on a task of its own.
      const id = window.setTimeout(finish, 0);
      return () => window.clearTimeout(id);
    }
    // The exit reverses the entrance: back down into the tile the CURRENT photo came out of, with the
    // ground fading out under it.
    const running = [
      stage.animate([end, start], { duration, easing: m.ease, fill: "forwards" }),
      ground.animate([{ opacity: 1 }, { opacity: 0 }], { duration, easing: "linear", fill: "forwards" }),
      chromeNode?.animate([{ opacity: 1 }, { opacity: 0 }], { duration: m.timing.chrome, easing: "linear", fill: "forwards" }),
    ].filter(Boolean) as Animation[];
    running[0].addEventListener("finish", finish);
    return () => {
      running[0].removeEventListener("finish", finish);
      running.forEach(animation => animation.cancel());
    };
  }, [open, scrubbed, progress, sourceKey, m.ease, m.timing.zoom, m.timing.fade, m.timing.backdrop, m.timing.chrome, m.timing.chromeDelay]);

  // Modal, so it takes focus when it opens. A scrubbed entrance does not: the harness seeks frames
  // and must not move the caret.
  useEffect(() => {
    if (!open || scrubbed) return;
    root.current?.focus({ preventScroll: true });
  }, [open, scrubbed]);

  // `-chromeAutoHideDelay` = 3 s: the chrome drops on its own. Never while scrubbing, never while the
  // picker is up, and never while a reaction is being chosen.
  useEffect(() => {
    if (!autoHideChrome || !m.allowChromeHiding || scrubbed || !open) return;
    if (!chromeVisible || tapbackOpen) return;
    const id = window.setTimeout(() => setChromeRef.current(false), m.chromeAutoHideDelay);
    return () => window.clearTimeout(id);
  }, [autoHideChrome, scrubbed, open, chromeVisible, tapbackOpen, index, zoom, m.allowChromeHiding, m.chromeAutoHideDelay]);

  /* ------------------------------------------------------------------ zoom, pan and paging */

  const panLimit = useCallback(
    (currentZoom: number) => ({
      x: Math.max(0, (fit.width * currentZoom - frame.width) / 2),
      y: Math.max(0, (fit.height * currentZoom - frame.height) / 2),
    }),
    [fit.width, fit.height, frame.width, frame.height],
  );

  const settle = useCallback(
    (nextZoom: number, nextPan: Point, kind: Exclude<Motion, "none"> = "settle") => {
      const limit = panLimit(nextZoom);
      beginMotion(kind);
      setZoom(nextZoom);
      setPan({ x: clamp(nextPan.x, -limit.x, limit.x), y: clamp(nextPan.y, -limit.y, limit.y) });
      // `-chromeAutoHideBehaviorOnZoom` = 2: leaving fit takes the chrome with it.
      if (m.hideChromeOnZoom && nextZoom > 1) setChrome(false);
    },
    [panLimit, setZoom, beginMotion, setChrome, m.hideChromeOnZoom],
  );

  const zoomAbout = useCallback(
    (nextZoom: number, point: Point) => {
      // Keep whatever is under the finger under the finger: the photo's centre moves by the change in
      // scale taken about that point.
      const centre = { x: frame.width / 2, y: frame.height / 2 };
      const ratio = nextZoom / zoom;
      const next = {
        x: point.x - centre.x - ratio * (point.x - centre.x - pan.x),
        y: point.y - centre.y - ratio * (point.y - centre.y - pan.y),
      };
      settle(nextZoom, nextZoom <= 1 ? { x: 0, y: 0 } : next);
    },
    [frame.width, frame.height, pan.x, pan.y, zoom, settle],
  );

  const page = useCallback(
    (delta: number) => {
      const next = index + delta;
      if (next < 0 || next > count - 1) return;
      beginMotion("page");
      setDragX(0);
      setPan({ x: 0, y: 0 });
      setZoom(1);
      setIndex(next);
    },
    [index, count, setIndex, setZoom, beginMotion],
  );

  /* ------------------------------------------------------------------ gestures */

  const gesture = useRef<Gesture>({
    pointers: new Map(),
    mode: "none",
    start: { x: 0, y: 0 },
    startPan: { x: 0, y: 0 },
    startZoom: 1,
    startSpread: 0,
    startMid: { x: 0, y: 0 },
    last: { x: 0, y: 0 },
    lastTime: 0,
    velocity: { x: 0, y: 0 },
    tapTime: 0,
    tapPoint: { x: 0, y: 0 },
  });

  const localPoint = useCallback((clientX: number, clientY: number): Point => {
    const box = root.current?.getBoundingClientRect();
    return { x: clientX - (box?.left ?? 0), y: clientY - (box?.top ?? 0) };
  }, []);

  /** Start a one-finger drag from `point`, whether it is the first finger down or the last one left. */
  function armDrag(g: Gesture, point: Point, time: number) {
    g.mode = "undecided";
    g.start = point;
    g.startPan = { ...pan };
    g.last = point;
    g.lastTime = time;
    g.velocity = { x: 0, y: 0 };
  }

  function onPointerDown(event: ReactPointerEvent<HTMLDivElement>) {
    if (event.pointerType === "mouse" && event.button !== 0) return;
    const g = gesture.current;
    const point = localPoint(event.clientX, event.clientY);
    g.pointers.set(event.pointerId, point);
    event.currentTarget.setPointerCapture(event.pointerId);
    endMotion();
    if (g.pointers.size === 2) {
      const points = [...g.pointers.values()];
      g.mode = "pinch";
      g.startSpread = spreadOf(points) || 1;
      g.startMid = midpointOf(points);
      g.startZoom = zoom;
      g.startPan = { ...pan };
      return;
    }
    if (g.pointers.size > 2) return;
    // Always undecided to begin with, even zoomed in: a tap on a zoomed photo still has to reach the
    // double-tap and chrome paths, so the pan only starts once the pointer has moved past the slop.
    armDrag(g, point, event.timeStamp);
  }

  function onPointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    const g = gesture.current;
    if (!g.pointers.has(event.pointerId)) return;
    const point = localPoint(event.clientX, event.clientY);
    g.pointers.set(event.pointerId, point);

    if (g.mode === "pinch") {
      const points = [...g.pointers.values()].slice(0, 2);
      if (points.length < 2) return;
      const next = clamp((spreadOf(points) / g.startSpread) * g.startZoom, 1, m.maxZoom);
      const mid = midpointOf(points);
      const centre = { x: frame.width / 2, y: frame.height / 2 };
      const ratio = next / g.startZoom;
      const limit = panLimit(next);
      const wanted = {
        x: mid.x - centre.x - ratio * (g.startMid.x - centre.x - g.startPan.x),
        y: mid.y - centre.y - ratio * (g.startMid.y - centre.y - g.startPan.y),
      };
      setZoom(next);
      // Banded, not free: a mid-pinch pan used to be written straight through, so the photo could be
      // shoved arbitrarily far off-centre and only came back on release.
      setPan({ x: band(wanted.x, limit.x, frame.width), y: band(wanted.y, limit.y, frame.height) });
      return;
    }

    const dx = point.x - g.start.x;
    const dy = point.y - g.start.y;
    const dt = Math.max(1, event.timeStamp - g.lastTime);
    g.velocity = { x: ((point.x - g.last.x) / dt) * 1000, y: ((point.y - g.last.y) / dt) * 1000 };
    g.last = point;
    g.lastTime = event.timeStamp;

    if (g.mode === "undecided") {
      if (Math.hypot(dx, dy) < m.slop) return;
      // A zoomed photo pans in both axes; at fit, sideways is paging and downwards is a dismissal.
      // Upwards is neither: it bands like an overscroll and springs back.
      g.mode = zoom > 1 ? "pan" : Math.abs(dx) > Math.abs(dy) ? "page" : "dismiss";
    }

    if (g.mode === "page") {
      // Rubber band at the two ends, where there is no page to bring on.
      const atStart = index === 0 && dx > 0;
      const atEnd = index === count - 1 && dx < 0;
      setDragX(atStart || atEnd ? rubberBand(dx, frame.width) : dx);
      return;
    }

    if (g.mode === "dismiss") {
      setDrop({ x: dx, y: dy > 0 ? dy : rubberBand(dy, frame.height) });
      return;
    }

    if (g.mode === "pan") {
      const limit = panLimit(zoom);
      const wanted = { x: g.startPan.x + dx, y: g.startPan.y + dy };
      setPan({ x: band(wanted.x, limit.x, frame.width), y: band(wanted.y, limit.y, frame.height) });
    }
  }

  function endGesture(event: ReactPointerEvent<HTMLDivElement>) {
    const g = gesture.current;
    const point = g.pointers.get(event.pointerId);
    if (!point) return;
    g.pointers.delete(event.pointerId);
    if (event.currentTarget.hasPointerCapture(event.pointerId)) event.currentTarget.releasePointerCapture(event.pointerId);

    if (g.mode === "pinch") {
      if (g.pointers.size >= 2) return;
      const collapsed = zoom < 1.05;
      settle(collapsed ? 1 : zoom, collapsed ? { x: 0, y: 0 } : pan);
      // The remaining finger keeps its capture and becomes a drag. Clearing the map here — which is
      // what this used to do — threw that pointer's id away, so its own pointerup bailed out before
      // `releasePointerCapture` and the capture was never given back.
      const rest = [...g.pointers.entries()][0];
      if (rest) armDrag(g, rest[1], event.timeStamp);
      else g.mode = "none";
      return;
    }

    const mode = g.mode;
    g.mode = "none";

    if (mode === "page") {
      const flick = Math.abs(g.velocity.x) > m.pageCommit.velocity;
      const dragged = Math.abs(dragX) > frame.width * m.pageCommit.distance;
      // Direction follows whichever test fired. Taking it from `dragX` alone paged FORWARD on a drag
      // 8px left followed by a hard flick right.
      const direction = flick ? (g.velocity.x < 0 ? 1 : -1) : dragX < 0 ? 1 : -1;
      // Armed before the branch, because `page` refuses to run past either end and the track still
      // has to slide back to centre from wherever the finger left it.
      beginMotion("page");
      setDragX(0);
      if (flick || dragged) page(direction);
      return;
    }

    if (mode === "dismiss") {
      if (drop.y > m.dismiss.distance || g.velocity.y > m.dismiss.velocity) {
        // Reset the drop as well as closing. Leaving it committed pinned `dropProgress` at its
        // release value, so the chrome stayed hidden, the ground stayed dimmed and the exit reversed
        // out of the dropped pose instead of the fitted one — and an uncontrolled viewer, whose
        // `open` never goes false, was stuck mid-drop for good.
        setDrop({ x: 0, y: 0 });
        beginMotion("settle");
        onClose?.();
        return;
      }
      beginMotion("bounce");
      setDrop({ x: 0, y: 0 });
      return;
    }

    if (mode === "pan") {
      const limit = panLimit(zoom);
      const outside = Math.abs(pan.x) > limit.x || Math.abs(pan.y) > limit.y;
      settle(zoom, pan, outside ? "bounce" : "settle");
      return;
    }

    if (mode !== "undecided") return;

    // A tap. Two in a row toggle the zoom; one on its own toggles the chrome, after waiting out the
    // window in which a second tap could still arrive.
    const doubled = event.timeStamp - g.tapTime < m.doubleTap.window && Math.hypot(point.x - g.tapPoint.x, point.y - g.tapPoint.y) < m.doubleTap.slop;
    g.tapTime = doubled ? 0 : event.timeStamp;
    g.tapPoint = point;
    window.clearTimeout(tapTimer.current);
    if (doubled) {
      // `-doubleTapZoomAreaExcludesBackground` and `-doubleTapZoomAreaExcludesBars`: the letterbox
      // and the bars' areas are not zoom targets. This used to zoom on a double tap anywhere.
      if (m.allowDoubleTapZoom && doubleTapTarget(point, fit, frame, { top: headerBand, bottom: footerBand })) {
        zoomAbout(zoom > 1 ? 1 : m.doubleTapZoom, point);
      }
      return;
    }
    if (!m.allowChromeHiding) return;
    const stamp = event.timeStamp;
    tapTimer.current = window.setTimeout(() => {
      if (gesture.current.tapTime === stamp) setChrome(!chromeVisible);
    }, m.doubleTap.window);
  }

  // A trackpad pinch arrives as a ctrl-wheel, which is how a photo zooms on macOS. React attaches
  // `wheel` passively, so preventing the page from zooming needs a listener of our own.
  useEffect(() => {
    const node = zoomLayer.current;
    if (!node) return;
    const onWheel = (event: WheelEvent) => {
      if (!event.ctrlKey) return;
      event.preventDefault();
      zoomAbout(clamp(zoom * (1 - event.deltaY / 100), 1, m.maxZoom), localPoint(event.clientX, event.clientY));
    };
    node.addEventListener("wheel", onWheel, { passive: false });
    return () => node.removeEventListener("wheel", onWheel);
  }, [zoom, zoomAbout, localPoint, m.maxZoom]);

  function onKeyDown(event: ReactKeyboardEvent<HTMLDivElement>) {
    if (event.key === "Tab") {
      // `aria-modal` promises the rest of the page is inert, so Tab has to stay inside. Without this
      // the first Tab walked straight out into the conversation behind the viewer.
      const focusable = Array.from(root.current?.querySelectorAll<HTMLElement>('button:not([disabled]), [href], [tabindex]:not([tabindex="-1"])') ?? []).filter(
        node => node.offsetParent !== null,
      );
      if (focusable.length === 0) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      const active = document.activeElement;
      if (event.shiftKey && (active === first || active === root.current)) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
      return;
    }
    if (event.key === "Escape") {
      event.preventDefault();
      if (tapbackOpen) {
        setTapbackOpen(false);
        root.current?.focus({ preventScroll: true });
      } else onClose?.();
      return;
    }
    if ((event.key === "ArrowRight" || event.key === "ArrowLeft") && zoom === 1) {
      event.preventDefault();
      page(event.key === "ArrowRight" ? 1 : -1);
      return;
    }
    if (event.key === "+" || event.key === "=") {
      event.preventDefault();
      zoomAbout(clamp(zoom * 1.5, 1, m.maxZoom), { x: frame.width / 2, y: frame.height / 2 });
      return;
    }
    if (event.key === "-" || event.key === "_") {
      event.preventDefault();
      zoomAbout(clamp(zoom / 1.5, 1, m.maxZoom), { x: frame.width / 2, y: frame.height / 2 });
      return;
    }
    if (event.key === "0") {
      event.preventDefault();
      settle(1, { x: 0, y: 0 });
    }
  }

  /* ------------------------------------------------------------------ painting */

  // The balloon's measured slot hangs it outside the bubble's trailing edge, which works over a
  // bubble and does not over a photo whose trailing edge can be the screen's. Keep the slot, then
  // pull it back inside the frame by the same edge inset a bubble keeps, and below the header.
  const balloon = balloonSlot[platform];
  const balloonSize = balloonGeometry[platform].main;
  const balloonLeft = Math.min(fit.x + fit.width + balloon.side, frame.width - balloonSize - bubbleMetrics[platform].edgeInset);
  const balloonTop = Math.max(headerBand, fit.y + balloon.top);

  const chromeAlpha = chromeVisible && dropProgress === 0 ? 1 : 0;
  const barTransition = scrubbed ? "none" : `opacity ${m.timing.chrome}ms linear`;
  const trackTransition = scrubbed || motion === "none" ? "none" : `transform ${m.timing.page}ms ${m.ease}`;
  const photoDuration = motion === "bounce" ? m.timing.bounce : m.timing.zoom;
  const photoTransition = scrubbed || motion === "none" ? "none" : `transform ${photoDuration}ms ${m.ease}`;

  // The ground under the chrome is measured black in both themes, so the picker's glass takes the
  // dark tokens whatever the page's theme is.
  const vars = tapbackVars("dark", platform) as CSSProperties;

  const photo = photos[index];
  const position = count > 1 ? `attachment ${index + 1} of ${count}` : "";
  const visible = pageWindow(index, count);

  const glass: CSSProperties = {
    background: m.glass.fill,
    backdropFilter: `blur(${m.glass.blur}px)`,
    WebkitBackdropFilter: `blur(${m.glass.blur}px)`,
    boxShadow: `inset 0 0 0 0.5px ${m.glass.rim}`,
  };

  const discButton = (size: number): CSSProperties => ({
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    width: size,
    height: size,
    borderRadius: "50%",
    border: 0,
    padding: 0,
    color: m.glass.ink,
    fontFamily: "inherit",
    cursor: "default",
    ...glass,
  });

  return (
    <div
      ref={root}
      data-slot="image-viewer"
      data-platform={platform}
      role="dialog"
      aria-modal="true"
      aria-label={title ?? "Photo"}
      tabIndex={-1}
      onKeyDown={onKeyDown}
      className={cn("absolute inset-0 select-none overflow-hidden outline-none", className)}
      style={{ fontFamily: fontStack, touchAction: "none", ...vars, ...style }}
      {...props}
    >
      {/* The ground: measured black in both themes, so it does not follow the palette.
          `-interactiveTransitionBackgroundDimming` = 0.5 is how far it dims under a drag — it does
          not clear away entirely, so the conversation shows through at half strength. */}
      <div
        ref={backdrop}
        aria-hidden="true"
        data-slot="viewer-ground"
        style={{ position: "absolute", inset: 0, background: m.ground, opacity: 1 - m.dismissDimming * dropProgress }}
      />

      <div ref={zoomLayer} data-slot="viewer-zoom" style={{ position: "absolute", inset: 0, transformOrigin: "0 0" }}>
        <div
          data-slot="viewer-stage"
          role="group"
          aria-label={["Photo", position].filter(Boolean).join(", ")}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={endGesture}
          onPointerCancel={endGesture}
          style={{ position: "absolute", inset: 0 }}
        >
          <div
            data-slot="viewer-track"
            style={{ position: "absolute", inset: 0, transform: `translateX(${trackX}px)`, transition: trackTransition, willChange: "transform" }}
          >
            {/* Only `-userNavigationMaximumDistance` items either side are in the tree: a twenty-photo
                message used to mount twenty full-resolution images at once. */}
            {visible.map(i => {
              const item = photos[i];
              const active = i === index;
              // Every page's photo lags its own page by 1/parallaxFactor of that page's offset, so a
              // swipe does not slide the whole strip as one sheet. At rest the active page's is 0.
              const parallax = -(trackX + i * pitch) / m.parallaxFactor;
              const box = fitPhotoRect(aspectOf(item), frame);
              const offset = active
                ? { x: pan.x + shift.x + parallax, y: pan.y + shift.y, scale: zoom * dropScale }
                : { x: parallax, y: 0, scale: 1 };
              return (
                <div key={`${item.src}-${i}`} data-slot="viewer-page" data-index={i} style={{ position: "absolute", left: i * pitch, top: 0, width: frame.width, height: frame.height }}>
                  <div
                    data-slot="viewer-photo"
                    style={{
                      position: "absolute",
                      left: box.x,
                      top: box.y,
                      width: box.width,
                      height: box.height,
                      transform: `translate(${offset.x}px, ${offset.y}px) scale(${offset.scale})`,
                      transformOrigin: "center center",
                      transition: active ? photoTransition : "none",
                      willChange: "transform",
                    }}
                  >
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img
                      src={item.src}
                      alt={item.alt ?? "Photo"}
                      draggable={false}
                      decoding="async"
                      loading={Math.abs(i - index) <= 1 ? "eager" : "lazy"}
                      onLoad={event => {
                        const image = event.currentTarget;
                        if (!image.naturalWidth || !image.naturalHeight) return;
                        setAspects(known => (known[item.src] ? known : { ...known, [item.src]: image.naturalWidth / image.naturalHeight }));
                      }}
                      style={{ width: "100%", height: "100%", objectFit: "contain", display: "block", pointerEvents: "none" }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      <div ref={chromeLayer} data-slot="viewer-chrome" style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
        {/* A reaction on the photo: the same balloon a bubble carries, on the photo's top trailing
            corner and clamped so it never rides under the header or off the frame. The slot is the
            measured bubble one, because no capture shows a balloon on a full-screen photo, so its
            placement here is JUDGEMENT. It lives in the chrome layer so it fades up with the rest of
            the overlay instead of hanging in the air while the photo is still zooming. */}
        {reaction && (
          <div data-slot="viewer-reaction" style={{ position: "absolute", left: balloonLeft, top: balloonTop, opacity: 1 - dropProgress }}>
            <Tapback
              platform={platform}
              side="left"
              own
              reaction={"type" in reaction ? reaction.type : undefined}
              emoji={"emoji" in reaction ? reaction.emoji : undefined}
            />
            {reactionAttribution && (
              <span
                data-slot="viewer-reaction-attribution"
                style={{ position: "absolute", top: balloonSize + 4, right: 0, whiteSpace: "nowrap", fontSize: 11, lineHeight: 1.2, color: m.glass.ink, opacity: 0.72 }}
              >
                {reactionAttribution}
              </span>
            )}
          </div>
        )}

        {/* `-allowStatusBar` = 1, and the capture shows it: white ink over the black ground, drawn
            with the same component the conversation uses, forced to its dark values. */}
        {showStatusBar && (
          <div
            data-slot="viewer-status-bar"
            aria-hidden="true"
            style={{ position: "absolute", left: 0, right: 0, top: 0, opacity: chromeAlpha, transition: barTransition }}
          >
            <IosStatusBar
              time={time}
              style={
                {
                  "--ios-sb-label": "#ffffff",
                  "--ios-sb-dot": "#333333",
                  "--ios-sb-battery": "#666666",
                  "--ios-sb-nub": "#808080",
                } as CSSProperties
              }
            />
          </div>
        )}

        {/* Header. One glass disc on the trailing side, `accessibilityLabel` "close" — there is no
            "Done" text button and no title view in the measured chrome. `title`/`subtitle` render
            only when a caller asks for them. */}
        <div
          data-slot="viewer-header"
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: inset.top,
            height: chromeBox.header.size,
            paddingInline: chromeBox.header.inset,
            display: "flex",
            alignItems: "center",
            justifyContent: "flex-end",
            opacity: chromeAlpha,
            transition: barTransition,
            pointerEvents: chromeAlpha ? "auto" : "none",
          }}
        >
          {(title || subtitle || (pageIndicator && count > 1)) && (
            <div
              data-slot="viewer-title"
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top: 0,
                height: chromeBox.header.size,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                pointerEvents: "none",
                color: m.glass.ink,
              }}
            >
              {title && <span style={{ fontSize: 15, lineHeight: 1.2 }}>{title}</span>}
              {(subtitle || (pageIndicator && count > 1)) && (
                <span style={{ display: "flex", gap: 6, fontSize: 11, lineHeight: 1.2, opacity: 0.72 }}>
                  {subtitle && <span>{subtitle}</span>}
                  {pageIndicator && count > 1 && <span>{`${index + 1} of ${count}`}</span>}
                </span>
              )}
            </div>
          )}
          <button type="button" data-slot="viewer-close" aria-label="close" onClick={onClose} style={discButton(chromeBox.header.size)}>
            <CloseIcon size={m.glyph.close} />
          </button>
        </div>

        {/* Footer. MEASURED: reply on the leading edge, share on the trailing edge, both Ø48 discs
            28 in from their own edge and 28 up from the bottom. The reply button is always drawn and
            is disabled without a handler, the way `-shouldShowReplyButtonForMediaObject:` disables
            it natively. Save and tapback are UNMEASURED additions in the trailing group. */}
        <div
          data-slot="viewer-footer"
          style={{
            position: "absolute",
            left: chromeBox.footer.inset,
            right: chromeBox.footer.inset,
            bottom: chromeBox.footer.bottom,
            height: chromeBox.footer.size,
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            opacity: chromeAlpha,
            transition: barTransition,
            pointerEvents: chromeAlpha ? "auto" : "none",
          }}
        >
          <button
            type="button"
            data-slot="viewer-reply"
            aria-label="reply"
            disabled={!onReply}
            onClick={onReply}
            style={{ ...discButton(chromeBox.footer.size), opacity: onReply ? 1 : undefined, color: onReply ? m.glass.ink : `rgba(243,243,243,${m.glass.disabledInk})` }}
          >
            {/* The reply symbol does not sit centred in its button: its ink centre measures 1.17 left
                and 0.17 below the disc's, which is the symbol's own content insets showing through. */}
            <span style={{ display: "inline-flex", transform: `translate(${m.glyph.reply.offsetX}px, ${m.glyph.reply.offsetY}px)` }}>
              <ReplyIcon width={m.glyph.reply.width} height={m.glyph.reply.height} />
            </span>
          </button>
          {/* Gap between the trailing controls: UNMEASURED, no capture shows more than one button on
              this side. */}
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {onReact && (
              <button
                type="button"
                ref={tapbackButton}
                data-slot="viewer-tapback"
                aria-label={reaction ? "Change reaction" : "Add a reaction"}
                aria-expanded={tapbackOpen}
                onClick={() => setTapbackOpen(!tapbackOpen)}
                style={discButton(chromeBox.footer.size)}
              >
                {reaction ? (
                  <TapbackGlyph type={"type" in reaction ? reaction.type : undefined} emoji={"emoji" in reaction ? reaction.emoji : undefined} size={m.glyph.tapback} />
                ) : (
                  <SmileyIcon size={m.glyph.tapback} color={m.glass.ink} strokeWidth={1.6} />
                )}
              </button>
            )}
            {onSave && (
              <button type="button" data-slot="viewer-save" aria-label="Save photo" aria-pressed={saved} onClick={onSave} style={discButton(chromeBox.footer.size)}>
                <SaveIcon width={m.glyph.save.width} height={m.glyph.save.height} saved={saved} />
              </button>
            )}
            <button type="button" data-slot="viewer-share" aria-label="Share" onClick={onShare} style={discButton(chromeBox.footer.size)}>
              <ShareIcon width={m.glyph.share.width} height={m.glyph.share.height} />
            </button>
          </div>
        </div>

        {(tapbackOpen || tapbackClosing) && (
          <ViewerTapbackPicker
            platform={platform}
            open={tapbackOpen}
            scrubbed={scrubbed}
            selected={reaction ?? undefined}
            recent={recent}
            width={pickerWidth}
            bottom={pickerBottom}
            left={pickerInset}
            pickerX={pickerX}
            onSelect={selection => {
              onReact?.(selection);
              setTapbackOpen(false);
              root.current?.focus({ preventScroll: true });
            }}
            onClose={() => {
              setTapbackOpen(false);
              root.current?.focus({ preventScroll: true });
            }}
            onExited={() => setTapbackClosing(false)}
          />
        )}
      </div>

      {/* One string per item, so it announces on an index change and stays silent on every other
          render: identical text written back into a live region is not re-announced. */}
      <span aria-live="polite" className="sr-only">{[photo?.alt || "Photo", position].filter(Boolean).join(", ")}</span>
    </div>
  );
}

/** Rubber-banded past `edge`, one-for-one inside it. */
function band(value: number, edge: number, dimension: number) {
  return Math.abs(value) > edge ? Math.sign(value) * edge + rubberBand(value - Math.sign(value) * edge, dimension) : value;
}

/**
 * The reaction picker over a full-screen photo: the same `TapbackBar` a bubble gets, floated above
 * the footer instead of above a balloon, because a full-screen photo has no bubble to hang off.
 * `CKQLPreviewController -tapbackButtonFrameForFullScreenBalloonViewController:` anchors it on the
 * toolbar's tapback button.
 *
 * Its thought bubble points DOWN at that button.
 * `-fullScreenBalloonViewControllerPickerViewUsesBottomTail:` is not a constant, though the docblock
 * here used to say so: it disassembles to `CGRectGetMinY(tapbackButtonFrame)` compared against
 * `CGRectGetMaxY(navigationBar.frame)` and returns 1 only when the button sits at or below the nav
 * bar's bottom (and when the frame is empty). The tapback button is in the FOOTER, always below the
 * header (footer button top = height - 76, header bottom = 106 on a 402x874 frame), so this layout
 * always takes the bottom-tail branch — but it takes it because the geometry says so, not because
 * the method is a constant.
 *
 * Its dismissal takes `CKUIBehaviorPhone -tapbackDismissalDuration`, 0.5 s. Its entrance has no
 * framework value: JUDGEMENT, the same 0.2 s the chrome fades in over.
 */
function ViewerTapbackPicker({
  platform,
  open,
  scrubbed,
  selected,
  recent,
  width,
  bottom,
  left,
  pickerX,
  onSelect,
  onClose,
  onExited,
}: {
  platform: Platform;
  open: boolean;
  scrubbed: boolean;
  selected?: TapbackSelection;
  recent?: string[];
  width: number;
  bottom: number;
  left: number;
  pickerX: number;
  onSelect: (selection: TapbackSelection) => void;
  onClose: () => void;
  onExited: () => void;
}) {
  const host = useRef<HTMLDivElement>(null);
  const done = useRef(false);
  const m = imageViewerMetrics;
  // Same reason as the viewer's own exit: an inline `onExited` must not restart the dismissal.
  const onExitedRef = useRef(onExited);
  useLayoutEffect(() => {
    onExitedRef.current = onExited;
  });

  useEffect(() => {
    const node = host.current;
    if (!node) return;
    const reduced = prefersReducedMotion();
    if (open) {
      done.current = false;
      if (reduced || scrubbed) return;
      const animation = node.animate(
        [
          { opacity: 0, transform: "translateY(8px) scale(0.92)" },
          { opacity: 1, transform: "translateY(0px) scale(1)" },
        ],
        { duration: m.timing.chrome, easing: m.ease, fill: "both" },
      );
      return () => animation.cancel();
    }
    const finish = () => {
      if (done.current) return;
      done.current = true;
      onExitedRef.current();
    };
    if (reduced) {
      const id = window.setTimeout(finish, 0);
      return () => window.clearTimeout(id);
    }
    const animation = node.animate(
      [
        { opacity: 1, transform: "translateY(0px) scale(1)" },
        { opacity: 0, transform: "translateY(8px) scale(0.92)" },
      ],
      { duration: m.timing.tapbackDismiss, easing: m.ease, fill: "forwards" },
    );
    animation.addEventListener("finish", finish);
    return () => {
      animation.removeEventListener("finish", finish);
      animation.cancel();
    };
  }, [open, scrubbed, m.timing.chrome, m.timing.tapbackDismiss, m.ease]);

  // The pill's recents run past its trailing edge and are reached by scrolling, which is what the
  // capture of the bar over a bubble shows too. The viewer's root sets `touch-action: none` so its
  // own gestures work, which left that scroll unreachable on a touch device; the picker takes it back.
  const scrollable: CSSProperties = { touchAction: "pan-x" };

  if (platform === "macos") {
    // UNVERIFIED, like the rest of the macOS presentation: the two-row picker lives in a context menu
    // natively, so over a photo it is given the menu's own surface as a floating panel, centred on
    // the same tapback button the iOS pill points at. The panel keeps its own centring transform and
    // the host carries the entrance, because one element cannot hold both: an animated `transform`
    // replaces the inline one outright.
    return (
      <div
        ref={host}
        data-slot="viewer-tapback-picker"
        style={{ position: "absolute", bottom, left: 0, right: 0, height: 0, pointerEvents: "none", transformOrigin: `${left + pickerX}px 100%`, ...scrollable }}
      >
        <div
          data-slot="viewer-tapback-panel"
          style={{
            position: "absolute",
            bottom: 0,
            left: left + pickerX,
            transform: "translateX(-50%)",
            borderRadius: 12,
            background: "var(--im-menu-bg, rgba(30,34,39,0.92))",
            boxShadow: "0 12px 40px rgba(0,0,0,0.5), inset 0 0 0 0.5px var(--im-menu-rim, rgba(255,255,255,0.28))",
            backdropFilter: "blur(30px) saturate(1.6)",
            WebkitBackdropFilter: "blur(30px) saturate(1.6)",
            color: "var(--im-menu-text, #dcddde)",
            pointerEvents: "auto",
          }}
        >
          <TapbackBar layout="macos" selected={selected} recent={recent} onSelect={onSelect} onClose={onClose} autoFocus={!scrubbed} />
        </div>
      </div>
    );
  }

  return (
    <div
      ref={host}
      data-slot="viewer-tapback-picker"
      style={{ position: "absolute", bottom, left, width, pointerEvents: "auto", transformOrigin: `${pickerX}px 100%`, ...scrollable }}
    >
      <TapbackBar layout="ios" selected={selected} recent={recent} onSelect={onSelect} onClose={onClose} autoFocus={!scrubbed} pickerX={pickerX} pickerSide="left" width={width} />
    </div>
  );
}

/**
 * The two bars' AREAS, i.e. each bar's band grown by `barsAreaVerticalOutset`. This is what
 * `doubleTapTarget` excludes, so anything testing or reusing that needs the same derivation.
 */
export type ImageViewerChrome = { header: number; footer: number };
export function imageViewerChromeBands(platform: Platform, safeArea?: { top?: number; bottom?: number }): ImageViewerChrome {
  const box = imageViewerMetrics.chrome[platform];
  const inset = { ...box.safeArea, ...safeArea };
  return {
    header: inset.top + box.header.size + imageViewerMetrics.barsOutset,
    footer: box.footer.bottom + box.footer.size + imageViewerMetrics.barsOutset,
  };
}

"use client";

import { useEffect, useMemo, useRef, useState, type ComponentProps } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { bubbleMetrics, fontStack, type Direction } from "@/components/imessage/tokens";
import { MessageBubble } from "@/components/imessage/message-bubble";

/**
 * An audio message: a waveform, a play control, and the remaining time, inside a normal bubble.
 *
 * NOT MEASURED. No native capture of an audio message exists in `references/`, so the waveform's bar
 * width and spacing follow the documented look rather than a measurement, and the bar count is only
 * how many of those fit.
 *
 * What is not guessed:
 * - The bubble, its padding (iOS 10/13.85, macOS 7.08/12.5), radius and tail are the measured ones,
 *   because this renders inside `MessageBubble`.
 * - The row height and the play button's diameter are one number, not two: the button is the circle
 *   that fills the row exactly. The number itself is provisional.
 * - The duration label reuses a type size measured on its own platform: iOS 13pt (the "Send with
 *   effect" segmented-control label, the one measured step between the 11pt secondary label and the
 *   17pt body) and macOS 11pt (the attachment card's "Text Document / 275 bytes" line).
 * - The row's width is the sum of its parts, so the bubble hugs it the way a text bubble hugs its
 *   longest line. `maxWidth` is passed in px: the platform default is a percentage of the bubble's
 *   own shrink-to-fit box, which collapses for content that is not text.
 * - The bubble's line-hugging fit measures the laid-out line boxes, so the row has to be the widest
 *   of them. It is: one inline box holding everything, with no loose text beside it. The duration
 *   still contributes a second, narrower rect of its own, which the fit ignores.
 */
export type MessageAudioProps = Omit<ComponentProps<"div">, "children"> & {
  /** Bar heights, 0..1, oldest first. Pass real peaks, or leave it out for a deterministic stand-in. */
  peaks?: number[];
  /** Total length in seconds. */
  duration: number;
  direction?: Direction;
  tail?: boolean;
  /** Controlled playback position in seconds. */
  position?: number;
  playing?: boolean;
  onPlayChange?: (playing: boolean) => void;
  onSeek?: (seconds: number) => void;
  /** Widest the bubble may grow, in px. Defaults to the platform's maximum bubble width. */
  maxWidth?: number;
  platform?: Platform;
};

function fallbackPeaks(count: number): number[] {
  // Deterministic, so screenshots are stable and no Math.random leaks into a render.
  return Array.from({ length: count }, (_, i) => {
    const a = Math.sin(i * 0.7) * 0.5 + 0.5;
    const b = Math.sin(i * 1.9 + 1.1) * 0.5 + 0.5;
    return 0.18 + Math.min(1, a * 0.6 + b * 0.55) * 0.82;
  });
}

function clock(seconds: number): string {
  const whole = Math.max(0, Math.round(seconds));
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

export function MessageAudio({ peaks, duration, direction = "outgoing", tail = false, position = 0, playing = false, onPlayChange, onSeek, maxWidth, platform: platformProp, className, style, ...props }: MessageAudioProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const ios = platform === "ios";
  // UNVERIFIED: the bar count, width and spacing have no capture behind them. The count is the most
  // bars that fit inside the measured maximum bubble width at that width and spacing, so the row
  // never has to break the measured 13.85 padding: iOS 280.5 - 27.7 padding - 28 button - 20 gaps -
  // 28.13 for a "0:17" label leaves 176.67, and 32 bars at 3 with 2.6 between them are 176.6 of it.
  const barCount = ios ? 32 : 28;
  const bars = useMemo(() => (peaks?.length ? peaks : fallbackPeaks(barCount)), [peaks, barCount]);
  const barWidth = ios ? 3 : 2.5;
  const barGap = ios ? 2.6 : 2;
  /** The row's height, which is also the play button's diameter and the waveform's full-scale peak. */
  const rowHeight = ios ? 28 : 22;
  const played = duration > 0 ? Math.max(0, Math.min(1, position / duration)) : 0;
  const track = useRef<HTMLSpanElement>(null);
  const outgoing = direction === "outgoing";
  const ink = outgoing ? "#ffffff" : "var(--im-incoming-text)";

  const seek = (clientX: number) => {
    const element = track.current;
    if (!element || !onSeek) return;
    const rect = element.getBoundingClientRect();
    onSeek(Math.max(0, Math.min(1, (clientX - rect.left) / rect.width)) * duration);
  };

  return (
    <MessageBubble data-slot="message-audio" direction={direction} tail={tail} platform={platform}
      maxWidth={maxWidth ?? bubbleMetrics[platform].maxWidth}
      className={cn(className)} style={{ fontFamily: fontStack, ...style }} {...props}>
      {/* One inline-flex box, so the bubble's text fit sees the whole row as the widest line and hugs
          it. The name is an aria-label rather than visually hidden text: text inside the bubble lays
          out its own line box, which the fit would then measure instead of this row. `max-width` is
          what keeps an inline box, which otherwise overflows rather than wrapping, inside the
          measured padding; a long duration then narrows the bars instead. */}
      <span role="group" aria-label={`Audio message, ${clock(duration)}`}
        className="inline-flex items-center align-middle" style={{ gap: ios ? 10 : 8, maxWidth: "100%", whiteSpace: "nowrap" }}>
        <button type="button" aria-label={playing ? "Pause audio message" : "Play audio message"} aria-pressed={playing}
          onClick={() => onPlayChange?.(!playing)}
          className="flex shrink-0 items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
          style={{ width: rowHeight, height: rowHeight, background: outgoing ? "rgba(255,255,255,0.22)" : "rgba(0,0,0,0.08)", color: ink }}>
          {playing ? (
            <svg aria-hidden="true" width={ios ? 11 : 9} height={ios ? 12 : 10} viewBox="0 0 11 12"><rect x="0" y="0" width="4" height="12" rx="1.2" fill="currentColor" /><rect x="7" y="0" width="4" height="12" rx="1.2" fill="currentColor" /></svg>
          ) : (
            <svg aria-hidden="true" width={ios ? 11 : 9} height={ios ? 12 : 10} viewBox="0 0 11 12"><path d="M1 1.1c0-.8.9-1.3 1.6-.9l7 4.9c.6.4.6 1.4 0 1.8l-7 4.9c-.7.4-1.6-.1-1.6-.9z" fill="currentColor" /></svg>
          )}
        </button>
        <span ref={track} data-slot="waveform" role="slider" tabIndex={0}
          aria-label="Playback position" aria-valuemin={0} aria-valuemax={Math.round(duration)} aria-valuenow={Math.round(position)} aria-valuetext={clock(position)}
          onPointerDown={event => { event.currentTarget.setPointerCapture(event.pointerId); seek(event.clientX); }}
          onPointerMove={event => { if (event.buttons === 1) seek(event.clientX); }}
          onKeyDown={event => {
            if (!onSeek) return;
            if (event.key === "ArrowRight") { event.preventDefault(); onSeek(Math.min(duration, position + 1)); }
            if (event.key === "ArrowLeft") { event.preventDefault(); onSeek(Math.max(0, position - 1)); }
          }}
          className="inline-flex flex-1 cursor-default items-center focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
          style={{ height: rowHeight, gap: barGap }}>
          {bars.map((peak, index) => {
            const reached = index / bars.length <= played;
            return (
              <span key={index} aria-hidden="true" style={{
                width: barWidth, height: Math.max(3, peak * rowHeight), borderRadius: barWidth / 2,
                background: ink, opacity: reached ? 1 : outgoing ? 0.45 : 0.28,
              }} />
            );
          })}
        </span>
        <span aria-hidden="true" style={{ fontSize: ios ? 13 : 11, color: ink, opacity: 0.75, fontVariantNumeric: "tabular-nums" }}>
          {clock(playing || position > 0 ? duration - position : duration)}
        </span>
      </span>
    </MessageBubble>
  );
}

/** Drives `position` while `playing`, without pulling in an audio element. */
export function useAudioProgress(duration: number, playing: boolean) {
  const [position, setPosition] = useState(0);
  const started = useRef(0);
  useEffect(() => {
    if (!playing) return;
    let raf = 0;
    const base = position;
    const step = (now: number) => {
      if (!started.current) started.current = now;
      const next = base + (now - started.current) / 1000;
      setPosition(next >= duration ? duration : next);
      if (next < duration) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => { cancelAnimationFrame(raf); started.current = 0; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [playing, duration]);
  return [position, setPosition] as const;
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, type ComponentProps, type CSSProperties } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { bubbleMetrics, fontStack, type Direction, type Service } from "@/components/imessage/tokens";
import { bodyClipPath, tailBox, tailPath, tailSeamOverlap } from "@/components/imessage/bubble-shape";

/**
 * Edit a sent message in place, and undo sending one.
 *
 * MEASURED, and only this: the macOS context menu's **Edit** row, traced off
 * `references/macos/captures/ctxmenu-with-edit-light-2x.png` (2x; the menu's top border is device row
 * 9 and its trailing border device column 604, so the menu is 302.5 wide and every number below is in
 * points from its top-left). The row is its own separated block between "Attach Sticker…" and
 * "Forward…": separator lines at 158.75 and 193.75, an 11 pt separator block each, so the row spans
 * 164.25 to 188.25 and its centre is 176.25 down, on the menu's own 24 pt row pitch. Label "Edit",
 * no ellipsis, 13 pt, ink left edge 41.75 in from the leading edge like every other row. Icon is
 * SF Symbol `pencil`: ink 8.5 x 8.5, centred 25.5 in from the leading edge and on the row's centre
 * (device box x 42-58, y 354-370). Cross-checked against the same capture's other rows, which land on
 * the same model: Attach Sticker… centre 141.25, Forward… 211.25, both within 0.25 of their ink.
 *
 * That row is data in `context-menu.tsx` (`macosMessageMenu`, `MenuIconName`), which does not carry it
 * yet. `canEdit` below is the gate for showing it.
 *
 * NOT MEASURED: everything else in this file. No capture shows the editor, a caret or a selection
 * inside a balloon, or the undo-send removal. So the editable bubble is the measured bubble (same
 * metrics, clip, seam overlap and screen-space fill as `message-bubble.tsx`), the "Edited" label is
 * the measured status label in the measured edited blue, and the behaviour follows Apple's documented
 * rules: 15 minutes and five edits, an "Edited" label with its history, Undo Send for two minutes.
 */
export const editWindowMs = 15 * 60 * 1000;
export const undoSendWindowMs = 2 * 60 * 1000;
export const maxEdits = 5;

export function canEdit(sentAt: Date | number, edits = 0, now: Date | number = Date.now()): boolean {
  return edits < maxEdits && +now - +sentAt <= editWindowMs;
}
export function canUndoSend(sentAt: Date | number, now: Date | number = Date.now()): boolean {
  return +now - +sentAt <= undoSendWindowMs;
}

/**
 * Text selection inside the field. UNVERIFIED: no capture shows a selection in a balloon. These are
 * the measured colours Messages paints over a *selected balloon* (SPEC "Selected outgoing bubble
 * (flat)", "Selected incoming bubble (flat)", "Selected SMS green bubble"), the only measured
 * selection colours that sit on a bubble. The values repeat `selectionOverlayClass` in
 * `message-bubble.tsx` instead of importing it because message-edit does not depend on message-bubble
 * in the registry; if one moves, move both.
 */
export const editSelectionClass =
  "[--im-edit-sel-blue:#1b60d8] [--im-edit-sel-gray:#c6c6c7] [--im-edit-sel-green:#0a0a7833] " +
  "dark:[--im-edit-sel-blue:#0b50c8] dark:[--im-edit-sel-gray:#55555c]";

export type EditableBubbleProps = Omit<ComponentProps<"div">, "onSubmit" | "children"> & {
  value: string;
  onChange?: (value: string) => void;
  onSubmit?: (value: string) => void;
  onCancel?: () => void;
  direction?: Direction;
  service?: Service;
  tail?: boolean;
  /**
   * Screen-space y of the body's bottom edge, in px, for the measured position-dependent fill. The
   * shared sweep in `use-screen-space.ts` only visits `[data-slot="message-bubble"]`, so a bubble
   * being edited inside a scrolling list has to be given this.
   */
  screenBottom?: number;
  /** Widest the bubble may grow. Defaults to the same native rule `MessageBubble` uses. */
  maxWidth?: number | string;
  platform?: Platform;
  autoFocus?: boolean;
};

/**
 * The bubble turned into a field. Return commits, Escape cancels, and the bubble keeps the measured
 * shape, padding, line box and fill while editing so nothing shifts.
 */
export function EditableBubble({
  value, onChange, onSubmit, onCancel, direction = "outgoing", service = "imessage", tail = false,
  screenBottom, maxWidth, platform: platformProp, autoFocus = true, className, style, onKeyDown, ...props
}: EditableBubbleProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = bubbleMetrics[platform];
  const outgoing = direction === "outgoing";
  const side = outgoing ? "right" : "left";
  const field = useRef<HTMLTextAreaElement>(null);
  const frame = useRef<HTMLDivElement>(null);
  const sizer = useRef<HTMLSpanElement>(null);
  const composing = useRef(false);
  const hintId = useId();
  const hang = tailBox.hang * m.tailScale;
  const key = direction === "incoming" ? "gray" : service === "sms" ? "green" : "blue";
  const ink = outgoing ? "var(--im-outgoing-text)" : "var(--im-incoming-text)";

  // One gradient in screen coordinates, anchored to the body's bottom, exactly as MessageBubble does
  // it: the tail hangs `hang` lower, so it needs its own background-position or its fill steps out of
  // register with the body's.
  const bottomVar = screenBottom === undefined ? "var(--bubble-bottom, calc(var(--im-screen-h) * 0.55))" : `${screenBottom}px`;
  const fill: CSSProperties = {
    backgroundImage: "linear-gradient(var(--im-fill-top), var(--im-fill-bottom))",
    backgroundSize: "100% var(--im-screen-h)",
    backgroundRepeat: "no-repeat",
    backgroundColor: "var(--im-fill-bottom)",
  };
  const bodyFill: CSSProperties = { ...fill, backgroundPosition: `0 calc(100% + (var(--im-screen-h) - ${bottomVar}))` };
  const tailFill: CSSProperties = { ...fill, backgroundPosition: `0 calc(100% + (var(--im-screen-h) - ${bottomVar} - ${hang}px))` };

  useEffect(() => {
    if (!autoFocus) return;
    const element = field.current;
    if (!element) return;
    element.focus();
    element.setSelectionRange(element.value.length, element.value.length);
  }, [autoFocus]);

  // MessageBubble's `useNativeTextFit`, run against a hidden mirror of the value: native hugs the
  // longest wrapped line, a textarea has no text node to range over, and `field-sizing: content`
  // stretches to the wrap width instead. Without it an iOS bubble jumped from 250.73 to 280.5 the
  // moment it became editable (measured on /lab/reply, "Every detail, down to the last bubble.").
  useLayoutEffect(() => {
    const frameEl = frame.current, textEl = sizer.current, fieldEl = field.current;
    if (!frameEl || !textEl || !fieldEl) return;
    const container = frameEl.parentElement;
    let raf = 0;
    const measure = () => {
      frameEl.style.width = "";
      const range = document.createRange();
      range.selectNodeContents(textEl);
      const lines: Array<{ top: number; left: number; right: number }> = [];
      for (const rect of Array.from(range.getClientRects())) {
        if (rect.width === 0 && rect.height === 0) continue;
        const line = lines.find(l => Math.abs(l.top - rect.top) < 1);
        if (line) { line.left = Math.min(line.left, rect.left); line.right = Math.max(line.right, rect.right); }
        else lines.push({ top: rect.top, left: rect.left, right: rect.right });
      }
      if (!lines.length) return;
      const longest = Math.max(...lines.map(l => l.right - l.left));
      fieldEl.style.textAlign = lines.length === 1 && longest < m.minWidth - 2 * m.paddingX ? "center" : "";
      const hug = Math.ceil((longest + 2 * m.paddingX) * 100) / 100 + 0.05;
      if (lines.length > 1 && hug < frameEl.getBoundingClientRect().width - 0.1) frameEl.style.width = `${hug}px`;
    };
    measure();
    const observer = new ResizeObserver(() => { cancelAnimationFrame(raf); raf = requestAnimationFrame(measure); });
    if (container) observer.observe(container);
    document.fonts?.ready.then(() => measure()).catch(() => {});
    return () => { observer.disconnect(); cancelAnimationFrame(raf); };
  }, [value, m.paddingX, m.minWidth, platform, maxWidth]);

  return (
    // Escape is handled on the root, not the field, so it still cancels while focus is on Cancel or
    // Done. Return stays on the field: on a button it means "press this button".
    <div data-slot="editable-bubble" data-direction={direction} role="group" aria-label="Edit message"
      className={cn("flex w-full min-w-0 flex-col", editSelectionClass, outgoing ? "items-end" : "items-start", className)}
      style={{
        fontFamily: fontStack,
        ...(screenBottom === undefined ? {} : { ["--bubble-bottom" as string]: `${screenBottom}px` }),
        ["--im-fill-top" as string]: `var(--im-${key}-top)`,
        ["--im-fill-bottom" as string]: `var(--im-${key}-bottom)`,
        ["--im-edit-sel" as string]: `var(--im-edit-sel-${key})`,
        ...style,
      } as CSSProperties}
      onKeyDown={event => {
        if (event.key === "Escape" && onCancel) { event.preventDefault(); event.stopPropagation(); onCancel(); }
        onKeyDown?.(event);
      }}
      {...props}>
      <div ref={frame} data-slot="bubble-frame" className="relative max-w-full" style={{ maxWidth: maxWidth ?? (platform === "ios" ? m.maxWidth : `${m.maxWidthRatio * 100}%`) }}>
        <div data-slot="bubble" className="relative" style={{ padding: `${m.paddingY}px ${m.paddingX}px`, minWidth: m.minWidth }}>
          {/* The fill lives behind the text so clipping the tail corner never clips glyphs. */}
          <div aria-hidden="true" data-slot="fill" className="pointer-events-none absolute inset-0"
            style={{ borderRadius: m.radius, clipPath: tail ? bodyClipPath(side, m.tailScale, tailSeamOverlap[platform]) : undefined, ...bodyFill }} />
          {tail && <div aria-hidden="true" data-slot="tail" className="pointer-events-none absolute" style={{
            [side]: 0, bottom: -hang, width: tailBox.width * m.tailScale, height: tailBox.height * m.tailScale + hang,
            clipPath: `path("${tailPath(side, m.tailScale)}")`, ...tailFill,
          }} />}
          <textarea ref={field} data-slot="edit-field" aria-label="Message" aria-describedby={hintId} value={value} rows={1}
            onChange={event => onChange?.(event.target.value)}
            onCompositionStart={() => { composing.current = true; }}
            onCompositionEnd={() => { composing.current = false; }}
            onKeyDown={event => {
              if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing && !composing.current) {
                event.preventDefault();
                onSubmit?.(value.trim());
              }
            }}
            className="relative block w-full resize-none border-0 bg-transparent outline-none [field-sizing:content] [overflow-wrap:anywhere] selection:bg-[var(--im-edit-sel)]"
            style={{
              margin: 0, padding: 0, boxSizing: "border-box", fontFamily: "inherit",
              fontSize: m.fontSize, lineHeight: `${m.lineHeight}px`, letterSpacing: m.letterSpacing,
              // UNVERIFIED: no capture shows the caret in a balloon. It takes the bubble's measured
              // text colour, which is the only ink colour measured inside a bubble.
              color: ink, caretColor: ink,
            }} />
          {/* Laid out at the field's own content width, never painted; only the hug measures it. */}
          <span ref={sizer} aria-hidden="true" data-slot="edit-sizer"
            className="pointer-events-none invisible absolute whitespace-pre-wrap [overflow-wrap:anywhere]"
            style={{ top: m.paddingY, left: m.paddingX, right: m.paddingX, fontSize: m.fontSize, lineHeight: `${m.lineHeight}px`, letterSpacing: m.letterSpacing }}>{value}</span>
          <span id={hintId} className="sr-only">Return saves the edit. Escape cancels it.</span>
        </div>
      </div>
      {/*
        UNVERIFIED: native shows no Cancel/Done pair, so the row is sized and placed from the measured
        status label (same type, same gap under the body, same inset) rather than from a new number.
      */}
      <div className="flex items-center gap-3" style={{
        fontSize: m.statusFontSize, lineHeight: `${m.statusLineHeight}px`, letterSpacing: m.statusLetterSpacing,
        fontWeight: 600, marginTop: m.statusGap,
        paddingInlineEnd: outgoing ? m.statusInset : 0, paddingInlineStart: outgoing ? 0 : m.statusInset,
      }}>
        <button type="button" data-slot="edit-cancel" aria-label="Cancel editing" onClick={onCancel} style={{ color: "var(--im-secondary)" }}>Cancel</button>
        <button type="button" data-slot="edit-done" aria-label="Done editing" onClick={() => onSubmit?.(value.trim())} style={{ color: "var(--im-edited)" }}>Done</button>
      </div>
    </div>
  );
}

/**
 * "Edited" under a message, and the edit history an app can show when it is tapped.
 *
 * The label's own geometry is not captured, so it reuses the measured status label ("Delivered"):
 * 11/13 semibold at a 4.65 gap and a 19.3 inset on iOS, 9/11 semibold at 4 and 15.9 on macOS, in the
 * measured `--im-edited` blue. `MessageBubble`'s own inline `edited` span still hardcodes the iOS
 * 11/13 and a 14 inset on both platforms; the two disagree on macOS.
 */
export function EditedLabel({ onShowHistory, direction = "outgoing", platform: platformProp, className, style, ...props }: Omit<ComponentProps<"button">, "children"> & { onShowHistory?: () => void; direction?: Direction; platform?: Platform }) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const m = bubbleMetrics[platform];
  const outgoing = direction === "outgoing";
  return (
    // Without a history handler the label is text, so it is disabled rather than an empty tab stop.
    <button type="button" data-slot="edited" onClick={onShowHistory} disabled={!onShowHistory}
      aria-label={onShowHistory ? "Edited. Show edit history." : undefined}
      className={cn("underline-offset-2", onShowHistory && "hover:underline", className)}
      style={{
        fontFamily: fontStack,
        fontSize: m.statusFontSize, lineHeight: `${m.statusLineHeight}px`, letterSpacing: m.statusLetterSpacing,
        fontWeight: 600, marginTop: m.statusGap,
        paddingInlineEnd: outgoing ? m.statusInset : 0, paddingInlineStart: outgoing ? 0 : m.statusInset,
        color: "var(--im-edited)",
        ...style,
      }} {...props}>
      Edited
    </button>
  );
}

/**
 * Undo Send timing. UNVERIFIED: nothing here is read off a capture, so it is one named table the
 * harness and the tests can seek rather than numbers spread through the keyframes.
 */
export const undoSendPoof = {
  duration: 420,
  /** prefers-reduced-motion: the same removal as a plain cross fade, no scale and no blur. */
  reducedDuration: 180,
  /** The bubble swells before it collapses. `offset` is a fraction of the timeline, so `progress` hits it. */
  swell: { offset: 0.35, scale: 1.06, opacity: 0.9 },
  endScale: 0.2,
  blur: 6,
  /** Per-segment, not on the effect: see the keyframes below. */
  easing: "cubic-bezier(0.4, 0, 0.2, 1)",
} as const;

function prefersReducedMotion(): boolean {
  return typeof window !== "undefined" && typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export type UndoSendPoofProps = ComponentProps<"div"> & {
  running?: boolean;
  /** 0..1: pause the poof and seek it to that fraction instead of playing it. */
  progress?: number;
  /** Fires when the bubble is gone, which is when the app should drop the message. */
  onDone?: () => void;
};

/**
 * Undo Send: the bubble swells, collapses and blurs away. Built on the Web Animations API with one
 * animation on one element, so `document.getAnimations()` reaches it and `progress` seeks it to the
 * same frame every run. A seeked poof never reports the message as gone: only a played one calls
 * `onDone`, and it calls it once.
 */
export function UndoSendPoof({ children, running = true, progress, onDone, className, style, ...props }: UndoSendPoofProps) {
  const host = useRef<HTMLDivElement>(null);
  const finished = useRef(onDone);
  useEffect(() => { finished.current = onDone; }, [onDone]);
  useEffect(() => {
    const element = host.current;
    if (!element || !running) return;
    const reduced = prefersReducedMotion();
    const duration = reduced ? undoSendPoof.reducedDuration : undoSendPoof.duration;
    // The easing sits on the keyframes, not on the effect: an effect-level easing warps the whole
    // iteration, so `swell.offset` would no longer be the fraction of the timeline the swell happens
    // at and `progress` would not map linearly onto it. Measured at 0.35 with the easing on the
    // effect, the frame was already past the swell (scale 0.862); on the keyframes it is scale 1.06.
    const frames: Keyframe[] = reduced
      ? [{ opacity: 1 }, { opacity: 0 }]
      : [
        { offset: 0, transform: "scale(1)", opacity: 1, filter: "blur(0px)", easing: undoSendPoof.easing },
        { offset: undoSendPoof.swell.offset, transform: `scale(${undoSendPoof.swell.scale})`, opacity: undoSendPoof.swell.opacity, filter: "blur(0px)", easing: undoSendPoof.easing },
        { offset: 1, transform: `scale(${undoSendPoof.endScale})`, opacity: 0, filter: `blur(${undoSendPoof.blur}px)` },
      ];
    const animation = element.animate(frames, { duration, easing: "linear", fill: "both" });
    if (progress !== undefined) {
      // Seeked, not played: a scrubbed checkpoint has to land on the same frame every run.
      animation.pause();
      animation.currentTime = Math.max(0, Math.min(1, progress)) * duration;
      return () => animation.cancel();
    }
    // `finish` rather than the `finished` promise: it fires once, it never fires on a cancel, and the
    // cleanup below takes the animation's fill off the element on the way out.
    const done = () => finished.current?.();
    animation.addEventListener("finish", done);
    return () => { animation.removeEventListener("finish", done); animation.cancel(); };
  }, [running, progress]);
  return (
    <div ref={host} data-slot="undo-send"
      data-state={running ? (progress === undefined ? "running" : "seeking") : "idle"}
      data-progress={progress === undefined ? undefined : Math.max(0, Math.min(1, progress)).toFixed(3)}
      className={cn("origin-center", running && "pointer-events-none", className)} style={style} {...props}>
      {children}
    </div>
  );
}

/** Countdown an app can show while Undo Send is still possible. */
export function undoSendRemaining(sentAt: Date | number, now: Date | number = Date.now()): number {
  return Math.max(0, undoSendWindowMs - (+now - +sentAt));
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type ComponentProps, type CSSProperties, type PointerEvent as ReactPointerEvent, type ReactNode, type UIEvent as ReactUIEvent } from "react";
import { cn } from "@/lib/utils";

/**
 * iOS 26 conversation details screen, measured from `references/ios/captures/details-light.png`
 * and `details-dark.png` (402×874 @3x). Every number below is a point value read off those frames:
 *
 * - Back button Ø44 glass circle centred (38, 84); avatar Ø80 centred (201, 102).
 * - Avatar initials: ink 44.00 wide by 26.67 cap, x 178.67–222.33, y 89.00–115.33. Chrome needs
 *   37.5pt at weight 650 to land there; 34pt semibold is 4.33 too narrow and 2.33 too short.
 * - Name 26pt bold centred on x 201, ink y 152.33–177.67.
 * - Three Ø54 glass action circles centred y 222.67 at x 127 / 201 / 275 (74 pitch). Glyphs are
 *   22pt SF Symbols: available ones use the label colour, unavailable ones tertiary label (30%).
 * - Grouped cells span x 16–386, radius 26 with a continuous corner, 20 between groups: phone
 *   269.67–340.33 (70.67 tall), links 360.33–464.33 (two 52 rows, 1pt separator at 411.33 inset to
 *   x 32–370), Hide Alerts 484.33–536.33, Block Contact 556.33–608.33. Row text starts at x 32.
 * - Cell and button fills are translucent: 6% black in light, 12% white in dark (over pure white
 *   that measures #efeff0, over black #1c1c1f — both read off the captures).
 * - Switch: 63×28 track (radius 14) with a 37×24 knob (radius 12) inset 2, trailing edge at x 372.
 *   Re-measured 2026-09-08 on the Hide Alerts row of both captures: track x 309.00–372.00,
 *   y 496.333–524.333; knob x 311.00–348.00, y 498.333–522.333. Both captures show it **off**; no
 *   capture in this repo holds an on switch, so the on colour comes from the framework instead
 *   (`+[UIColor systemGreenColor]` resolved under each `UIUserInterfaceStyle` in a Mac Catalyst
 *   process with the idiom swizzled to phone: #34c759 light, #30d158 dark). `-[UISwitch
 *   intrinsicContentSize]` there is 61×28, which corroborates the measured 28 track height.
 *   The off track darkens the cell fill by 21% in light and lightens it by 28% in dark (sampled
 *   beside the knob against the bare cell on the same row).
 * - RECENT tag: 41×11.33 pill, radius 3.5, #c7c7cc in both themes, 8.5pt bold label (cap 6).
 *
 * The screen sits over the conversation, which is blurred (σ≈18) and washed out by a 49% white /
 * 59% black scrim; pass that conversation as `backdrop`.
 *
 * The presentation is a separate matter, and its timings are UNMEASURED: no capture in this repo
 * records this screen in motion, so nothing below is a reading off a frame. See `iosDetailsMotion`.
 *
 * ## What the capture does not show
 *
 * `details-light.png` is one scroll position of a conversation with no shared content: the cell
 * stack ends at Block Contact and nothing follows it. Three groups are therefore built from the
 * measured *style* rather than from a frame, and are **UNMEASURED**: the shared photos grid, the
 * shared links list and the shared attachments list (`photos`, `sharedLinks`, `attachments`). They
 * sit between Hide Alerts and Block Contact, which is where they push the destructive row down, and
 * with all three absent the stack reproduces the capture point for point. What they reuse:
 *
 * - The cell geometry, the 20 between groups, the 52 row, the 70.67 two-line cell, the 16 row inset
 *   and the 1pt separator inset to x 32–370 are all measured on this screen.
 * - A two-line item row keeps the measured phone cell's three gaps (16.875 above, 1.5 between,
 *   14.29 below) with its 17pt and 13pt lines swapped, so it is 70.67 tall like the measured one.
 * - The grid is 3 across with a 4 gap, from `+[CKUIBehavior sharedBehaviors]` under the phone
 *   idiom: `attachmentBrowserGridInterItemSpacing` and `attachmentBrowserGridMinimumLineSpacing`
 *   are both 4. Inside the 370 cell at the measured 16 inset that makes a 110 tile. The tile radius
 *   12 is the measured Photos-picker tile radius (SPEC, `photo-picker-light.png`).
 * - The chevron on a row that navigates is the nav bar's measured chevron: 4.67 × 12.67 ink, 2.6
 *   round stroke, #bdbdbd / #5d5d5d (`ios-nav-bar.tsx`).
 *
 * ChatKit 26 actually files shared content under tabs, not under more cells on the info list
 * (`DetailsPhotosTab`, `DetailsLinksTab`, `DetailsAttachmentsTab`, `CKDetailsSegmentedControlCell`).
 * Nothing in `references/` shows that surface, so this file stays with the grouped cells.
 *
 * ## Scrolling
 *
 * Also UNMEASURED, and it cannot be measured from a still. The cells scroll; the header collapses
 * into the conversation's nav bar, which is the exact inverse of the pose the presentation grows
 * out of, so the two ends of the collapse are measured even though the travel between them is not.
 * See `iosDetailsCollapse`. It is seekable: `scroll` (in points) drives paused Web Animations, so
 * `document.getAnimations()` reaches every layer and a checkpoint renders the same twice.
 */

const font = "-apple-system, BlinkMacSystemFont, sans-serif";

/** Light/dark values live in CSS variables so a `.dark` ancestor flips the whole screen. */
const vars =
  "[--ios-dt-label:#000000] [--ios-dt-secondary:#848488] [--ios-dt-blue:#0088ff] [--ios-dt-red:#ff383c] " +
  "[--ios-dt-fill:rgba(0,0,0,0.06)] [--ios-dt-separator:#dadadb] [--ios-dt-glyph:#000000] [--ios-dt-glyph-off:rgba(0,0,0,0.26)] [--ios-dt-glyph-blend:normal] [--ios-dt-av-top:#a9c2e1] [--ios-dt-av-bottom:#747fb9] " +
  "[--ios-dt-tag:#c7c7cc] [--ios-dt-tag-label:#ffffff] [--ios-dt-track:rgba(0,0,0,0.21)] [--ios-dt-knob:#ffffff] " +
  "[--ios-dt-chevron:#bdbdbd] [--ios-dt-av-shadow:rgba(0,0,0,0.12)] [--ios-dt-glass:rgba(255,255,255,0.9)] [--ios-dt-glass-rim:inset_0_0_0_0_rgba(0,0,0,0)] [--ios-dt-glass-shadow:0_6px_36px_4px_rgba(0,0,0,0.065)] " +
  "[--ios-dt-scrim:rgba(255,255,255,0.573)] [--ios-dt-saturate:1] [--ios-dt-page:#ffffff] " +
  "dark:[--ios-dt-label:#ffffff] dark:[--ios-dt-secondary:#98989f] dark:[--ios-dt-blue:#0091ff] dark:[--ios-dt-red:#ff4245] " +
  "dark:[--ios-dt-fill:rgba(235,235,245,0.12)] dark:[--ios-dt-separator:#3a3a3c] dark:[--ios-dt-glyph:#ffffff] dark:[--ios-dt-glyph-off:rgba(255,255,255,0.26)] dark:[--ios-dt-glyph-blend:plus-lighter] dark:[--ios-dt-av-top:#575368] dark:[--ios-dt-av-bottom:#302649] " +
  "dark:[--ios-dt-track:rgba(255,255,255,0.28)] dark:[--ios-dt-chevron:#5d5d5d] dark:[--ios-dt-av-shadow:rgba(0,0,0,0.3)] " +
  "dark:[--ios-dt-glass:rgba(28,28,28,0.9)] dark:[--ios-dt-glass-rim:inset_0_0_0_0.3333px_rgba(255,255,255,0.0385),inset_0_0_0_0.6667px_rgba(255,255,255,0.032),inset_0_0_0_1px_rgba(255,255,255,0.061)] dark:[--ios-dt-glass-shadow:0_0_0_0_rgba(0,0,0,0)] " +
  "dark:[--ios-dt-scrim:rgba(0,0,0,0.587)] dark:[--ios-dt-saturate:1.05] dark:[--ios-dt-page:#000000]";

/** Apple's continuous corner. Browsers without `corner-shape` fall back to a plain round corner. */
const continuous = { cornerShape: "superellipse(1.14)" } as CSSProperties;

/**
 * The grouped-cell geometry, all of it measured off the captures (see the header). `top` is the
 * first cell's top; every later group starts `gap` below the one before it, which reproduces the
 * measured 269.67 / 360.33 / 484.33 / 556.33 stack exactly and lets an unmeasured group in without
 * moving anything above it.
 */
const cell = {
  left: 16,
  width: 370,
  radius: 26,
  gap: 20,
  top: 269.6667,
  /** Row text starts at x 32, i.e. 16 inside the cell. */
  inset: 16,
  /** One-line row (Hide Alerts, Block Contact, the blue link rows). */
  row: 52,
  /** Two-line cell (the phone row). */
  twoLine: 70.6667,
} as const;

/** The measured two-line cell's three gaps, with its 17pt and 13pt lines swapped. UNMEASURED. */
const twoLineRow = { title: 16.875, detail: 40.375 } as const;

/** 3 across, 4 apart (CKUIBehavior, phone idiom), inside the measured 16 inset: a 110 tile. */
const grid = { columns: 3, gap: 4, radius: 12 } as const;
const tile = (cell.width - cell.inset * 2 - grid.gap * (grid.columns - 1)) / grid.columns;

export type IosDetailsAction = {
  id: string;
  label: string;
  icon: "phone" | "video" | "mail";
  /** Unavailable actions keep the glass circle but drop the glyph to tertiary label (measured). */
  disabled?: boolean;
  onPress?: () => void;
};

/** One tile of the shared photos grid. Pass `node` for a next/image, `src` for a plain one. */
export type IosDetailsPhoto = { id: string; src?: string; alt?: string; node?: ReactNode; onPress?: () => void };
/** One row of the shared links or shared attachments list. */
export type IosDetailsItem = { id: string; title: string; detail?: string; onPress?: () => void };
/** A shared-content group: a header row that navigates, then its items. */
export type IosDetailsSection<T> = { title?: string; count?: number | string; items: T[]; onOpen?: () => void };

export type IosDetailsProps = Omit<ComponentProps<"div">, "children" | "onChange"> & {
  name: string;
  initials?: string;
  /** Replaces the initials avatar (an <img>, say). */
  avatar?: ReactNode;
  /** First cell: a small label ("phone") over its value, with an optional tag ("RECENT"). */
  phoneLabel?: string;
  phone?: string;
  tag?: string;
  actions?: IosDetailsAction[];
  /** Blue link rows in the second cell. */
  links?: Array<{ id: string; label: string; onPress?: () => void }>;
  hideAlerts?: boolean;
  onHideAlertsChange?: (next: boolean) => void;
  hideAlertsLabel?: string;
  /** Shared content, below the capture's fold and UNMEASURED. Each one is a grouped cell. */
  photos?: IosDetailsSection<IosDetailsPhoto>;
  sharedLinks?: IosDetailsSection<IosDetailsItem>;
  attachments?: IosDetailsSection<IosDetailsItem>;
  blockLabel?: string;
  onBlock?: () => void;
  onBack?: () => void;
  /** The conversation behind the screen; rendered blurred and washed out. */
  backdrop?: ReactNode;
  /**
   * Seek the presentation to this fraction instead of playing it, which is what the harness does:
   * while `open`, 0 is dismissed and 1 is settled; while it is closing, 0 is settled and 1 is gone.
   * Leave it unset for the real thing.
   */
  progress?: number;
  /**
   * Seek the scroll position, in points, instead of letting the surface scroll: the header collapse
   * follows it exactly the way it follows a finger. Leave it unset for the real thing.
   */
  scroll?: number;
  /** False plays the dismissal; `onExited` fires when it is over, and the consumer unmounts then. */
  open?: boolean;
  onExited?: () => void;
};

/**
 * The presentation's timings. UNMEASURED, and they cannot be measured from anything in this repo:
 * no capture records this screen in motion. They sit in the family of the ones that were measured:
 *
 * - The rise takes 320 ms on `cubic-bezier(0.32, 0.72, 0, 1)`, the curve the measured effects screen
 *   (`ios-effects-picker.tsx`, 260 ms), this file's own Hide Alerts switch (220 ms) and the app
 *   shell's screen transitions (`iosScreenTransition`, 400 ms present) all already use.
 * - The scrim and the shared chrome fade over 220 ms, a little ahead of the rise, the way the
 *   long-press overlay's measured dim (150 of its 600 ms) leads its menu.
 * - The way out is 260 ms on the long-press menu's exit curve, between that menu's own 220 ms exit
 *   and the shell's 280 ms dismiss.
 *
 * What IS measured is the pose at each end. The settled pose is `details-light.png`, unchanged: the
 * timeline is cancelled once it lands, so the screen at rest carries no transform at all. The start
 * pose is the conversation's own nav bar, so the screen grows out of the control that opened it:
 * `ios-nav-bar.tsx` puts the avatar Ø60 centred (201, 92) and the name pill's 17pt text centred on
 * y 133.5 (status bar 54 + pill top 63, 32.33 tall, its span nudged 0.33 down); this screen puts the
 * avatar Ø80 centred (201, 102) and the 28pt name centred on y 162.65. So the avatar grows 60 → 80
 * (scale 0.75) across 10 pt of centre, which is the same thing as growing downward from a top edge
 * both screens put on y 62; the name grows 17 → 28 (scale 0.6071) across 29.15; and the back button
 * does not move at all, being Ø44 at (16, 62) on both. The avatar's 37.5pt initials land on 28.1pt
 * at that scale, a third of a point off the nav bar's own 28.
 *
 * The one number here that touches the capture is `backdropScale`. A sheet pushes what it covers
 * back; under σ18 of blur and a 57% scrim the capture cannot tell whether it did. Diffed against
 * `details-light.png` over 0 60 402 560 the settled screen misses 1713 px of 2,026,080 unscaled and
 * 1642 px at 0.96 (both 0.08%; dark is 3136 / 3068, both 0.15%), so the frame does not decide it and
 * this is a presentation choice, not a measurement. The blur is divided by the scale so that what
 * lands on screen is still σ18.
 */
/** The control points behind `iosDetailsMotion.ease`; the drag inverts the curve through them. */
const sheetCurve = [0.32, 0.72, 0, 1] as const;

export const iosDetailsMotion = {
  /** The whole entrance, and the sheet's own rise inside it. */
  enter: 360,
  sheet: 320,
  /** The scrim, and the chrome both screens share. */
  dim: 220,
  exit: 260,
  ease: `cubic-bezier(${sheetCurve.join(", ")})`,
  exitEase: "cubic-bezier(0.4, 0, 1, 1)",
  /** The conversation behind: its blur, and how far the sheet pushes it back. */
  blur: 18,
  backdropScale: 0.96,
  /** The three glass buttons, then the grouped cells, settle after the header in a short stagger. */
  actionStart: 60, actionStagger: 22, actionRise: 14, actionDuration: 200,
  cellStart: 80, cellStagger: 24, cellRise: 22, cellDuration: 200,
  /** The stagger stops at the measured stack's four cells, so a longer stack still lands by `enter`. */
  cellStaggerMax: 3,
  /** A drag past this far, or released faster than this (px/ms), dismisses. */
  dragCommit: 120, dragVelocity: 0.6,
} as const;

/** Where the header comes from: the nav bar's own avatar and name pill, both measured (see above). */
export const iosDetailsMorph = {
  avatar: { dy: -10, scale: 60 / 80 },
  name: { dy: -29.15, scale: 17 / 28 },
} as const;

/**
 * The header collapse. UNMEASURED — no capture holds this screen scrolled — but both ends of it are:
 * it runs the presentation's morph backwards, so a fully collapsed header is the conversation's own
 * measured nav bar (avatar Ø60 centred (201, 92) under its measured shadow, the name 17pt centred on
 * y 133.5 inside the measured glass pill, the back button Ø44 at (16, 62), which never moves).
 *
 * `travel` is derived rather than chosen: 120.3333 is the scroll that carries the first cell's
 * measured top (269.6667) onto the nav bar pill's measured bottom edge (149.3333), so the collapse
 * finishes exactly as the content reaches the bar it is passing under, and never overlaps it.
 * `actionFade` is derived the same way: the three glass circles are gone by the scroll (74) that
 * brings the first cell's top onto their measured top (195.6667).
 *
 * The pill's own box is the nav bar's measured padding (12.9531 leading, 10.7188 trailing) around
 * the name at the collapsed scale, so a longer or shorter name gets the pill that name would have.
 */
export const iosDetailsCollapse = {
  travel: 120.3333,
  actionFade: 74,
  pill: { top: 117, height: 32.3333, radius: 16.1667, padLeft: 12.9531, padRight: 10.7188, centre: 201 },
  /** Rendering the collapsed pill's 24 blur (measured on the nav bar) through the collapsed scale. */
  blur: 24,
} as const;

type Pose = Record<string, string>;
type Layer = { el: HTMLElement; from: Pose; to: Pose; duration: number; delay: number; easing: string };

function prefersReducedMotion() {
  return typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
}
function clamp01(value: number) { return Math.max(0, Math.min(1, value)); }
function stop(animation: Animation) { try { animation.cancel(); } catch { /* already gone */ } }
function seekTo(list: Animation[], time: number) {
  list.forEach(animation => { animation.pause(); try { animation.currentTime = time; } catch { /* no timeline yet */ } });
}

/**
 * Where in the rise the sheet stands `covered` of the way up: the entrance curve read backwards.
 * A drag scrubs the timeline, and `cubic-bezier(0.32, 0.72, 0, 1)` spends most of its travel in the
 * first fifth of it, so scrubbing it linearly would leave the screen nearly still under a finger
 * that has already moved 200 pt. Bisect the curve's y for its parameter, then read its x.
 */
function riseSeek(covered: number): number {
  const [x1, y1, x2, y2] = sheetCurve;
  const at = (a: number, b: number, t: number) => 3 * (1 - t) * (1 - t) * t * a + 3 * (1 - t) * t * t * b + t * t * t;
  let low = 0, high = 1, t = 0.5;
  for (let step = 0; step < 24; step++) { t = (low + high) / 2; if (at(y1, y2, t) < covered) low = t; else high = t; }
  return at(x1, x2, t);
}

/** What an element is holding right now, so a dismissal can start from a half-played entrance or a drag. */
function poseNow(el: HTMLElement, shape: Pose): Pose {
  const style = getComputedStyle(el);
  const pose: Pose = {};
  for (const key of Object.keys(shape)) pose[key] = style.getPropertyValue(key.replace(/[A-Z]/g, char => `-${char.toLowerCase()}`)) || shape[key];
  return pose;
}

/**
 * Every layer of the presentation, as the pose it holds while dismissed and the pose it settles on.
 * The settled pose is what the element already carries at rest, so cancelling the timeline when it
 * lands leaves the measured screen with no animation, no transform and its glass intact (a held
 * animation would promote each layer and cut the glass circles off from the backdrop they blur).
 *
 * `translate` and `scale` are used rather than `transform`, so a layer whose measured position is
 * already carried by a fractional `transform` (the action circles, via `subpixel`) keeps it — and so
 * that the collapse, which owns `transform`, composes with this instead of replacing it.
 */
function detailsLayers(content: HTMLElement, blur: HTMLElement | null, scrim: HTMLElement | null, height: number, saturate: string): Layer[] {
  const m = iosDetailsMotion;
  const layers: Layer[] = [];
  const add = (el: HTMLElement | null, from: Pose, to: Pose, duration: number, delay = 0, easing: string = m.ease) => {
    if (el) layers.push({ el, from, to, duration, delay, easing });
  };
  const own = (slot: string) => content.querySelector<HTMLElement>(`:scope > [data-slot="${slot}"]`);
  const each = (slot: string) => Array.from(content.querySelectorAll<HTMLElement>(`:scope > [data-slot="${slot}"]`));
  const cells = () => Array.from(content.querySelectorAll<HTMLElement>(`:scope > [data-slot="details-scroll"] [data-slot="cell"]`));
  // The chrome that both screens share is already on screen, in the same place: it cancels the
  // sheet's rise exactly (same duration, same easing) and morphs out of the nav bar instead.
  const stay = (dy: number) => `0px ${(dy - height).toFixed(3)}px`;

  add(blur,
    { filter: `blur(0px) saturate(${saturate})`, scale: "1" },
    { filter: `blur(${(m.blur / m.backdropScale).toFixed(3)}px) saturate(${saturate})`, scale: String(m.backdropScale) },
    m.sheet);
  add(scrim, { opacity: "0" }, { opacity: "1" }, m.dim, 0, "ease-out");
  add(content, { translate: `0px ${height}px` }, { translate: "0px 0px" }, m.sheet);
  add(own("back"), { translate: stay(0) }, { translate: "0px 0px" }, m.sheet);
  add(own("back"), { opacity: "0" }, { opacity: "1" }, m.dim, 0, "ease-out");
  add(own("avatar"), { translate: stay(iosDetailsMorph.avatar.dy), scale: String(iosDetailsMorph.avatar.scale) }, { translate: "0px 0px", scale: "1" }, m.sheet);
  add(own("name"), { translate: stay(iosDetailsMorph.name.dy), scale: String(iosDetailsMorph.name.scale) }, { translate: "0px 0px", scale: "1" }, m.sheet);
  each("action").forEach((el, index) => add(el, { translate: `0px ${m.actionRise}px` }, { translate: "0px 0px" }, m.actionDuration, m.actionStart + index * m.actionStagger));
  cells().forEach((el, index) => add(el, { translate: `0px ${m.cellRise}px` }, { translate: "0px 0px" }, m.cellDuration, m.cellStart + Math.min(index, m.cellStaggerMax) * m.cellStagger));
  return layers;
}

/** Web Animations, not a rAF loop or a transition, so `document.getAnimations()` can seek a frame. */
function runLayers(layers: Layer[], phase: "enter" | "exit"): Animation[] {
  const m = iosDetailsMotion;
  return layers.map(({ el, from, to, duration, delay, easing }) => phase === "enter"
    ? el.animate([from, to], { duration, delay, easing, fill: "both" })
    // One flat span on the way out, so the shared chrome's counter-translate still cancels the
    // sheet's exactly, and it starts from wherever the layer is now (settled, or mid-drag).
    : el.animate([poseNow(el, from), from], { duration: m.exit, easing: m.exitEase, fill: "both" }));
}

/**
 * The collapse, as paused animations whose clock is the scroll offset in points: one millisecond of
 * timeline per point scrolled, so seeking is `currentTime = scrollTop`. They own `transform` and
 * `opacity`, which composes with the presentation's `translate` / `scale` rather than replacing it,
 * and they exist only while the surface is scrolled — at the top the timeline is cancelled and the
 * measured screen carries no transform at all, exactly as it does with no collapse in the file.
 */
function collapseLayers(content: HTMLElement, pillWidth: number): Layer[] {
  const c = iosDetailsCollapse;
  const layers: Layer[] = [];
  const add = (el: HTMLElement | null, from: Pose, to: Pose, duration: number = c.travel) => {
    if (el) layers.push({ el, from, to, duration, delay: 0, easing: "linear" });
  };
  const own = (slot: string) => content.querySelector<HTMLElement>(`:scope > [data-slot="${slot}"]`);
  const avatar = own("avatar");
  const shadow = avatar ? getComputedStyle(avatar).getPropertyValue("--ios-dt-av-shadow").trim() || "rgba(0,0,0,0.12)" : "";
  add(avatar,
    { transform: "translateY(0px) scale(1)", boxShadow: "0 2px 4px rgba(0,0,0,0)" },
    { transform: `translateY(${iosDetailsMorph.avatar.dy}px) scale(${iosDetailsMorph.avatar.scale})`, boxShadow: `0 2px 4px ${shadow}` });
  add(own("name"),
    { transform: "translateY(0px) scale(1)" },
    { transform: `translateY(${iosDetailsMorph.name.dy}px) scale(${iosDetailsMorph.name.scale})` });
  const pill = own("collapsed-pill");
  if (pill) {
    pill.style.width = `${pillWidth.toFixed(4)}px`;
    pill.style.left = `${(c.pill.centre - pillWidth / 2).toFixed(4)}px`;
    add(pill, { opacity: "0" }, { opacity: "1" });
  }
  Array.from(content.querySelectorAll<HTMLElement>(`:scope > [data-slot="action"]`))
    .forEach(el => add(el, { opacity: "1" }, { opacity: "0" }, c.actionFade));
  return layers;
}

/** Swallows the click a drag would otherwise leave behind on whatever control it started on. */
function swallowClick(node: HTMLElement | null) {
  if (!node) return;
  const swallow = (event: Event) => { event.stopPropagation(); event.preventDefault(); };
  node.addEventListener("click", swallow, { capture: true, once: true });
  setTimeout(() => node.removeEventListener("click", swallow, true), 0);
}

type GlassCircleProps = ComponentProps<"button"> & { size: number; "data-slot"?: string; "data-action"?: string };

function GlassCircle({ size, className, style, children, ...rest }: GlassCircleProps) {
  return (
    <button type="button"
      className={cn("absolute flex items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]", className)}
      style={{ width: size, height: size, background: "var(--ios-dt-fill)", backdropFilter: "blur(24px)", WebkitBackdropFilter: "blur(24px)", ...style }}
      {...rest}>
      {children}
    </button>
  );
}

/**
 * SF Symbol stand-ins, drawn at the ink sizes measured inside the Ø54 circles. Ink boxes read off
 * `details-light.png` (mean-intensity edges, so they are good to about a third of a point):
 * phone x 118.0–136.0 y 213.67–231.33, video x 190.0–213.11 y 215.02–230.33, mail x 263.67–286.33
 * y 214.67–230.67. Blink snaps each `<svg>` box to a whole CSS pixel, so glyphs whose centred
 * position lands on a half point carry the remainder in a transform, the way `subpixel` does.
 */
function ActionGlyph({ icon }: { icon: IosDetailsAction["icon"] }) {
  const id = useId();
  if (icon === "phone") {
    // 18.36 wide, not 17: at 17 the ink measures 16.67 across against the capture's 18.0.
    return (
      <svg aria-hidden="true" width="18.36" height="17.3333" viewBox="1.72 1.25 13.5 13.5" fill="currentColor">
        <path d="M3.654 1.328a.678.678 0 0 0-1.015-.063L1.605 2.3c-.483.484-.661 1.169-.45 1.77a17.6 17.6 0 0 0 4.168 6.608 17.6 17.6 0 0 0 6.608 4.168c.601.211 1.286.033 1.77-.45l1.034-1.034a.678.678 0 0 0-.063-1.015l-2.307-1.794a.68.68 0 0 0-.58-.122l-2.19.547a1.75 1.75 0 0 1-1.657-.459L5.482 8.062a1.75 1.75 0 0 1-.46-1.657l.548-2.19a.68.68 0 0 0-.122-.58z" />
      </svg>
    );
  }
  if (icon === "video") {
    // Body 16.33 wide (capture x 190.0–206.33), a 1.17 gap, then the lens wedge: its neck stands on
    // x 17.5 running y 4.60–10.70 and its outer edge on the ink's right, y 1.22–14.08. Both slanted
    // edges measure 0.615 of rise per point across, checked at x 208.0 and x 212.33 top and bottom.
    // The half-point centring is snapped away by Blink, so the third of a point comes back here.
    return (
      <svg aria-hidden="true" width="23" height="15.3333" viewBox="0 0 23 15.3333" fill="currentColor" style={{ transform: "translateY(0.3333px)" }}>
        <rect x="0" y="0" width="16.3333" height="15.3333" rx="3.6" />
        <path d="M17.969 4.312 22.531 1.508Q23 1.22 23 1.77V13.53Q23 14.08 22.531 13.792L17.969 10.988Q17.5 10.7 17.5 10.15V5.15Q17.5 4.6 17.969 4.312Z" />
      </svg>
    );
  }
  // The envelope is a 22.67 × 16 rounded rect crossed by four 0.9 wide creases, read off
  // `details-light.png`: the flap runs corner to corner through (11.33, 10.4), and a short seam
  // rises from each bottom corner to meet the flap's arm at (8.3, 7.7) / (14.37, 7.7).
  return (
    // Centred on 275 a 22.67 wide box starts on 263.667, and Blink snaps both edges inward: the
    // envelope then renders 22.0 across instead of the capture's 263.67–286.33. A whole 23 wide box
    // survives the snap (263.5 rounds to 264), the viewBox insets the 22.67 of artwork inside it,
    // and half a point of transform carries the pair onto the measured edges.
    <svg aria-hidden="true" width="23" height="16" viewBox="-0.1667 0 23 16" style={{ transform: "translateX(-0.5px)" }}>
      <mask id={id} maskUnits="userSpaceOnUse" x="0" y="0" width="22.6667" height="16">
        <rect width="22.6667" height="16" rx="2.6" fill="#ffffff" />
        <path d="M-0.7 0 11.3333 10.4 23.37 0M0 16 8.3 7.7M22.6667 16 14.3667 7.7" fill="none" stroke="#000000" strokeWidth="0.9" />
      </mask>
      <rect width="22.6667" height="16" rx="2.6" fill="currentColor" mask={`url(#${id})`} />
    </svg>
  );
}

/**
 * The disclosure chevron on a row that navigates. The nav bar's measured one: 4.67 × 12.67 of ink
 * on a 2.6 round stroke, in the measured chevron gray (`ios-nav-bar.tsx`). Its box is centred on the
 * row and its ink sits `cell.inset` in from the cell's trailing edge.
 */
function Chevron() {
  return (
    <svg aria-hidden="true" className="absolute" width="8.6667" height="16.6667" viewBox="-2 -2 8.6667 16.6667" fill="none"
      stroke="var(--ios-dt-chevron)" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"
      style={{ right: cell.inset - 2, top: "50%", transform: "translateY(-50%)" }}>
      <path d="M1.3 1.3 3.37 6.3333 1.3 11.37" />
    </svg>
  );
}

export type IosSwitchProps = Omit<ComponentProps<"button">, "onChange"> & {
  checked?: boolean;
  onChange?: (next: boolean) => void;
  label?: string;
};

/**
 * iOS 26 switch: 63×28 track, 37×24 knob inset 2, so the knob travels 22 (measured on the Hide
 * Alerts row of both captures, which show it off).
 *
 * The on colour is not in any capture and is not a guess either: `+[UIColor systemGreenColor]`,
 * resolved for each `UIUserInterfaceStyle` in a Mac Catalyst process with `-[UIDevice
 * userInterfaceIdiom]` swizzled to phone, is #34c759 light and #30d158 dark.
 *
 * Off, the track is the measured composite over this screen's cell fill (`--ios-dt-track`). Away
 * from that cell there is nothing measured to composite against, so it falls back to the framework's
 * `+[UIColor secondarySystemFillColor]` (#787880 at 16% light, 32% dark).
 */
export function IosSwitch({ checked = false, onChange, label, className, style, ...rest }: IosSwitchProps) {
  return (
    <button type="button" data-slot="ios-switch" role="switch" aria-checked={checked} aria-label={label} onClick={() => onChange?.(!checked)}
      className={cn(
        "relative shrink-0 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff] motion-reduce:!transition-none",
        "[--ios-sw-on:#34c759] [--ios-sw-off:rgba(120,120,128,0.16)] dark:[--ios-sw-on:#30d158] dark:[--ios-sw-off:rgba(120,120,128,0.32)]",
        className,
      )}
      style={{ width: 63, height: 28, borderRadius: 14, overflow: "hidden", background: checked ? "var(--ios-sw-on)" : "var(--ios-dt-track, var(--ios-sw-off))", transition: "background 200ms ease", ...style }}
      {...rest}>
      {/*
        The capture shows no shadow outside the switch at all: one pixel past the track the pixels
        are already the surrounding gradient, and inside the track the knob only darkens it by ~3/255.
        The track therefore clips the knob's shadow, and that shadow is barely there.
      */}
      <span aria-hidden="true" className="absolute block motion-reduce:!transition-none" style={{
        left: 2, top: 2, width: 37, height: 24, borderRadius: 12, background: "var(--ios-dt-knob, #ffffff)",
        boxShadow: "0 1px 3px rgba(0,0,0,0.10)",
        transform: `translateX(${checked ? 22 : 0}px)`, transition: "transform 220ms cubic-bezier(0.32,0.72,0,1)",
      }} />
    </button>
  );
}

/**
 * Blink snaps a painted box to whole CSS px, so a fill placed straight on a third-of-a-point edge
 * lands a device pixel off at 3x. The fill therefore sits on an integer box and a transform carries
 * the fraction; transforms are composited without snapping. `subpixel` does the same for any element
 * whose measured position is not a whole point.
 */
export function subpixel(top: number): CSSProperties {
  const whole = Math.floor(top);
  return { top: whole, transform: `translateY(${(top - whole).toFixed(4)}px)` };
}

function Cell({ top, height, children }: { top: number; height: number; children: ReactNode }) {
  const whole = Math.floor(top);
  const boxHeight = Math.max(1, Math.round(height));
  return (
    <div data-slot="cell" className="absolute" style={{ left: cell.left, top, width: cell.width, height }}>
      <span aria-hidden="true" data-slot="cell-fill" className="absolute" style={{
        left: 0, top: whole - top, width: cell.width, height: boxHeight, borderRadius: cell.radius,
        background: "var(--ios-dt-fill)", transformOrigin: "0 0",
        transform: `translateY(${(top - whole).toFixed(4)}px) scaleY(${(height / boxHeight).toFixed(5)})`,
        ...continuous,
      }} />
      {children}
    </div>
  );
}

/** The measured hairline: 1pt at a row boundary, inset to x 32–370. */
function Separator({ top }: { top: number }) {
  return (
    <span aria-hidden="true" data-slot="separator" className="absolute"
      style={{ left: cell.inset, right: cell.inset, top: top - 1.3333, transform: "translateY(0.3333px)", height: 1, background: "var(--ios-dt-separator)" }} />
  );
}

const rowFocus = "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-[#0088ff]";
/** Row text is 17pt (measured); a second line is 13pt (measured, the phone cell's small label). */
const titleType: CSSProperties = { fontSize: 17, lineHeight: "22px", color: "var(--ios-dt-label)" };
const detailType: CSSProperties = { fontSize: 13, lineHeight: "16px", color: "var(--ios-dt-secondary)" };
const clip: CSSProperties = { overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" };

/**
 * A shared group's header row: the section's name, how many it holds, and a chevron. The whole 52pt
 * row is the hit target when it navigates, and it is a plain heading when it does not. UNMEASURED.
 */
function SectionHeader({ title, count, onOpen }: { title: string; count?: number | string; onOpen?: () => void }) {
  const body = (
    <>
      <span style={{ ...titleType, ...clip }}>{title}</span>
      {count !== undefined && (
        <span data-slot="section-count" style={{ ...titleType, color: "var(--ios-dt-secondary)", marginLeft: "auto", marginRight: onOpen ? 8 : 0 }}>{count}</span>
      )}
      {onOpen && <Chevron />}
    </>
  );
  const style: CSSProperties = { paddingLeft: cell.inset, paddingRight: cell.inset + (onOpen ? 14 : 0), transform: "translateY(0.6667px)" };
  return (
    <div className="absolute" style={{ left: 0, right: 0, top: 0, height: cell.row }}>
      {onOpen
        ? <button type="button" data-slot="section-header" onClick={onOpen} className={cn("absolute inset-0 flex items-center text-left", rowFocus)} style={style}>{body}</button>
        : <h2 data-slot="section-header" className="absolute inset-0 m-0 flex items-center font-normal" style={style}>{body}</h2>}
    </div>
  );
}

/**
 * One row of a shared links or shared attachments list. Two lines keep the measured phone cell's
 * three gaps with its 17pt and 13pt lines swapped, so the row is the measured 70.67 tall; a row with
 * no second line is the measured 52. UNMEASURED.
 */
function ItemRow({ item, top, height }: { item: IosDetailsItem; top: number; height: number }) {
  const twoLine = item.detail !== undefined;
  const pad = cell.inset + (item.onPress ? 14 : 0);
  const body = twoLine ? (
    <>
      <span className="absolute" style={{ left: cell.inset, right: pad, top: twoLineRow.title, ...titleType, ...clip }}>{item.title}</span>
      <span className="absolute" style={{ left: cell.inset, right: pad, top: twoLineRow.detail, ...detailType, ...clip }}>{item.detail}</span>
      {item.onPress && <Chevron />}
    </>
  ) : (
    <>
      <span style={{ ...titleType, ...clip }}>{item.title}</span>
      {item.onPress && <Chevron />}
    </>
  );
  const style: CSSProperties = twoLine
    ? { transform: "translateY(0.6667px)" }
    : { paddingLeft: cell.inset, paddingRight: pad, transform: "translateY(0.6667px)" };
  return (
    <div className="absolute" style={{ left: 0, right: 0, top, height }}>
      {/* Every item row sits under a row: the header above the first one, an item above the rest. */}
      <Separator top={0} />
      {item.onPress
        ? <button type="button" data-slot="detail-row" onClick={item.onPress} className={cn("absolute inset-0 text-left", !twoLine && "flex items-center", rowFocus)} style={style}>{body}</button>
        : <div data-slot="detail-row" className={cn("absolute inset-0", !twoLine && "flex items-center")} style={style}>{body}</div>}
    </div>
  );
}

/** How tall a shared group's cell is, given what it holds. UNMEASURED; see the header. */
function photosHeight(section: IosDetailsSection<IosDetailsPhoto>) {
  const rows = Math.max(1, Math.ceil(section.items.length / grid.columns));
  return cell.row + cell.inset + rows * tile + (rows - 1) * grid.gap + cell.inset;
}
function listHeight(section: IosDetailsSection<IosDetailsItem>) {
  return cell.row + section.items.reduce((total, item) => total + (item.detail === undefined ? cell.row : cell.twoLine), 0);
}

function PhotosCell({ section, top }: { section: IosDetailsSection<IosDetailsPhoto>; top: number }) {
  return (
    <Cell top={top} height={photosHeight(section)}>
      <SectionHeader title={section.title ?? "Photos"} count={section.count ?? section.items.length} onOpen={section.onOpen} />
      <Separator top={cell.row} />
      {section.items.map((photo, index) => {
        const column = index % grid.columns;
        const row = Math.floor(index / grid.columns);
        const box: CSSProperties = {
          left: cell.inset + column * (tile + grid.gap),
          top: cell.row + cell.inset + row * (tile + grid.gap),
          width: tile, height: tile, borderRadius: grid.radius, background: "var(--ios-dt-fill)",
        };
        const label = photo.alt ?? `Photo ${index + 1}`;
        const media = photo.node ?? (photo.src
          // eslint-disable-next-line @next/next/no-img-element -- registry components stay framework-neutral
          ? <img src={photo.src} alt="" className="size-full object-cover" draggable={false} />
          : null);
        return photo.onPress
          ? (
            <button key={photo.id} type="button" data-slot="photo" aria-label={label} onClick={photo.onPress}
              className={cn("absolute overflow-hidden", "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]")} style={box}>
              {media}
            </button>
          )
          : (
            <span key={photo.id} data-slot="photo" role="img" aria-label={label} className="absolute block overflow-hidden" style={box}>
              {media}
            </span>
          );
      })}
    </Cell>
  );
}

function ListCell({ section, title, top }: { section: IosDetailsSection<IosDetailsItem>; title: string; top: number }) {
  // The rows stack under the header, each one as tall as it needs: 52 with one line, 70.67 with two.
  const rows: Array<{ item: IosDetailsItem; top: number; height: number }> = [];
  section.items.reduce<number>((cursor, item) => {
    const height = item.detail === undefined ? cell.row : cell.twoLine;
    rows.push({ item, top: cursor, height });
    return cursor + height;
  }, cell.row);
  return (
    <Cell top={top} height={listHeight(section)}>
      <SectionHeader title={section.title ?? title} count={section.count ?? section.items.length} onOpen={section.onOpen} />
      {rows.map(row => <ItemRow key={row.item.id} item={row.item} top={row.top} height={row.height} />)}
    </Cell>
  );
}

export function IosDetails({
  name, initials, avatar, phoneLabel = "phone", phone, tag, actions = [], links = [],
  hideAlerts = false, onHideAlertsChange, hideAlertsLabel = "Hide Alerts", blockLabel = "Block Contact", onBlock,
  photos, sharedLinks, attachments,
  onBack, backdrop, progress, scroll, open = true, onExited, className, style, ...props
}: IosDetailsProps) {
  const letters = initials ?? name.trim().split(/\s+/).slice(0, 2).map(p => p[0] ?? "").join("").toUpperCase();
  const titleId = useId();
  const root = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const scroller = useRef<HTMLDivElement>(null);
  const nameInk = useRef<HTMLSpanElement>(null);
  const blur = useRef<HTMLDivElement>(null);
  const scrim = useRef<HTMLDivElement>(null);
  const timeline = useRef<Animation[] | null>(null);
  const collapse = useRef<Animation[] | null>(null);
  const scrolled = useRef(0);
  const landed = useRef(false);
  const exited = useRef(onExited);
  useEffect(() => { exited.current = onExited; }, [onExited]);

  // The dismissal is derived during render, not in an effect: an effect leaves one committed frame
  // with the screen already gone, and the exit never runs. `closing` also separates a screen that is
  // leaving (fire `onExited`, stop taking clicks) from one mounted closed, which just sits dismissed.
  const [seenOpen, setSeenOpen] = useState(open);
  const [closing, setClosing] = useState(false);
  if (seenOpen !== open) { setSeenOpen(open); setClosing(!open); }

  // Whether the surface is off the top, derived during render for a seeked scroll and kept in state
  // for a live one. The collapsed pill only exists while it is true, so the screen at rest is the
  // measured one with nothing extra painted over it.
  const [liveCollapsing, setLiveCollapsing] = useState(false);
  const collapsing = scroll !== undefined ? scroll > 0 : liveCollapsing;

  const build = (phase: "enter" | "exit"): Animation[] | null => {
    const node = content.current;
    const box = root.current;
    if (!node || !box) return null;
    const height = box.getBoundingClientRect().height;
    if (!height) return null;
    const saturate = getComputedStyle(box).getPropertyValue("--ios-dt-saturate").trim() || "1";
    return runLayers(detailsLayers(node, blur.current, scrim.current, height, saturate), phase);
  };
  const land = (list: Animation[]) => {
    if (timeline.current !== list) return;
    list.forEach(stop);
    timeline.current = null;
    landed.current = true;
  };

  /**
   * The collapse follows the scroll offset with no animation of its own: build the layers if the
   * surface has left the top, then seek them to the offset. Back at the top the timeline is dropped,
   * which is what keeps the measured screen free of a composited transform.
   */
  const seekCollapse = (top: number) => {
    scrolled.current = top;
    const node = content.current;
    if (!node) return;
    if (top <= 0) { collapse.current?.forEach(stop); collapse.current = null; return; }
    let list = collapse.current;
    if (!list) {
      const back = node.querySelector<HTMLElement>(`:scope > [data-slot="back"]`);
      const title = node.querySelector<HTMLElement>(`:scope > [data-slot="name"]`);
      const ink = nameInk.current;
      // The back button is Ø44 on both screens and the collapse never scales it, so its box is the
      // ruler that turns whatever scale an embedding applies back into points. The name's own scale
      // comes off its computed style, because a half-played entrance is still holding one.
      const unit = back ? back.getBoundingClientRect().width / 44 : 1;
      const nameScale = (title && parseFloat(getComputedStyle(title).scale)) || 1;
      const inkWidth = ink && unit ? ink.getBoundingClientRect().width / unit / nameScale : 0;
      const c = iosDetailsCollapse;
      list = collapseLayers(node, inkWidth * iosDetailsMorph.name.scale + c.pill.padLeft + c.pill.padRight)
        .map(({ el, from, to, duration, easing }) => el.animate([from, to], { duration, easing, fill: "both" }));
      collapse.current = list;
    }
    seekTo(list, Math.min(top, iosDetailsCollapse.travel));
  };

  // Only unmount cancels the timeline. The two phases hand over to each other without one, so a
  // dismissal can read the pose the entrance, or a drag, is still holding.
  useEffect(() => () => {
    timeline.current?.forEach(stop); timeline.current = null;
    collapse.current?.forEach(stop); collapse.current = null;
  }, []);

  useLayoutEffect(() => {
    if (prefersReducedMotion()) { landed.current = true; return; }
    const previous = timeline.current;
    const next = build(open ? "enter" : "exit");
    previous?.forEach(stop);
    timeline.current = next;
    landed.current = false;
    // One rebuild per phase, and `build` only reads refs.
  }, [open]);

  useLayoutEffect(() => {
    // Reduced motion: the screen is simply there, and leaves at once. Its resting styles are the
    // settled pose, so there is nothing to undo.
    if (prefersReducedMotion()) { if (!open && closing) exited.current?.(); return; }
    const list = timeline.current ?? build(open ? "enter" : "exit");
    if (!list) return;
    timeline.current = list;
    const total = open ? iosDetailsMotion.enter : iosDetailsMotion.exit;
    if (progress !== undefined) {
      const time = clamp01(progress) * total;
      seekTo(list, time);
      // A settled checkpoint is screenshotted, so drop the timeline there and let the glass breathe.
      if (open && time >= total) land(list);
      return;
    }
    // Mounted closed rather than closing: hold the dismissed pose instead of playing a dismissal.
    if (!open && !closing) { seekTo(list, total); return; }
    let dropped = false;
    list.forEach(animation => animation.play());
    Promise.allSettled(list.map(animation => animation.finished)).then(() => {
      if (dropped) return;
      if (open) land(list);
      else if (closing && timeline.current === list) exited.current?.();
    });
    return () => { dropped = true; };
  }, [open, progress, closing]);

  // The collapse is rebuilt whenever the pill comes or goes, and re-seeked whenever the offset is
  // handed in rather than scrolled. Both paths end in the same paused, seeked timeline.
  useLayoutEffect(() => {
    collapse.current?.forEach(stop);
    collapse.current = null;
    if (scroll !== undefined && scroller.current) scroller.current.scrollTop = scroll;
    seekCollapse(scroll ?? scrolled.current);
    // `seekCollapse` only reads refs; the offset and the pill's presence are the whole input.
  }, [collapsing, scroll]);

  const onScroll = (event: ReactUIEvent<HTMLDivElement>) => {
    if (scroll !== undefined) return;
    const top = event.currentTarget.scrollTop;
    seekCollapse(top);
    if (top > 0 !== liveCollapsing) setLiveCollapsing(top > 0);
  };

  // The screen covers the conversation, so Escape backs out of it the way the back button does.
  useEffect(() => {
    if (!open || !onBack) return;
    const onKey = (event: KeyboardEvent) => { if (event.key === "Escape") { event.preventDefault(); onBack(); } };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onBack]);

  /**
   * Drag down to dismiss. It seeks the entrance backwards rather than writing its own styles, so a
   * half-dragged screen is the same pose as a half-played entrance: the blur, the scrim, the sheet
   * and the header morph all follow the finger together. Released short of the threshold, it plays
   * the rest of the entrance forward from where it is. It only starts at the top of the list, so a
   * drag anywhere below that scrolls instead, the way it does natively.
   */
  const drag = useRef<{ id: number; from: number; last: number; at: number; velocity: number; live: boolean } | null>(null);
  const playIn = () => {
    const list = timeline.current;
    if (!list) return;
    list.forEach(animation => animation.play());
    Promise.allSettled(list.map(animation => animation.finished)).then(() => land(list));
  };
  const onPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!open || closing || progress !== undefined || !onBack || !landed.current || prefersReducedMotion()) return;
    if (event.pointerType === "mouse" && event.button !== 0) return;
    if ((scroller.current?.scrollTop ?? 0) > 0) return;
    drag.current = { id: event.pointerId, from: event.clientY, last: event.clientY, at: event.timeStamp, velocity: 0, live: false };
  };
  const onPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    const state = drag.current;
    if (!state || event.pointerId !== state.id) return;
    const dy = event.clientY - state.from;
    if (!state.live) {
      // A tap, or a drag back up, leaves the controls alone.
      if (dy < 8) return;
      state.live = true;
      event.currentTarget.setPointerCapture(state.id);
      const list = timeline.current ?? build("enter");
      if (list) { timeline.current = list; seekTo(list, iosDetailsMotion.enter); }
    }
    const elapsed = event.timeStamp - state.at;
    if (elapsed > 0) state.velocity = (event.clientY - state.last) / elapsed;
    state.last = event.clientY;
    state.at = event.timeStamp;
    // The sheet rises by the frame's own height, so tracking the finger means seeking to wherever
    // the rise stands `1 - dy / height` of the way up.
    const height = root.current?.getBoundingClientRect().height || 1;
    const back = riseSeek(clamp01(1 - dy / height)) * iosDetailsMotion.sheet;
    if (timeline.current) seekTo(timeline.current, back);
  };
  const onPointerEnd = (event: ReactPointerEvent<HTMLDivElement>) => {
    const state = drag.current;
    if (!state || event.pointerId !== state.id) return;
    drag.current = null;
    if (!state.live) return;
    swallowClick(root.current);
    const dy = event.clientY - state.from;
    // Ask for the dismissal first: the exit builds from the pose this drag is holding. Then play the
    // entrance back in, which springs the screen home if the consumer does not take the dismissal.
    if (dy > iosDetailsMotion.dragCommit || state.velocity > iosDetailsMotion.dragVelocity) onBack?.();
    playIn();
  };

  // The stack, in order. With no shared content it is the four measured cells on their measured
  // tops; each group that is present pushes the ones under it down by its height plus the measured
  // 20, and Block Contact stays last.
  const groups: ReactNode[] = [];
  let cursor = cell.top;
  const place = (height: number, render: (top: number) => ReactNode) => {
    groups.push(render(cursor));
    cursor += height + cell.gap;
  };
  if (phone !== undefined) {
    place(cell.twoLine, top => (
      <Cell key="phone" top={top} height={cell.twoLine}>
        <span data-slot="phone-label" className="absolute" style={{ left: cell.inset, top: 16.875, fontSize: 13, lineHeight: "16px", transform: "translateY(-0.6667px)", color: "var(--ios-dt-secondary)" }}>{phoneLabel}</span>
        <span data-slot="phone-value" className="absolute" style={{ left: cell.inset, top: 34.375, fontSize: 17, lineHeight: "22px", color: "var(--ios-dt-label)" }}>{phone}</span>
        {tag && (
          <span data-slot="tag" className="absolute flex items-center justify-center"
            style={{ left: 312.3333, top: 19.3333, transform: "translateY(0.3333px)", width: 41, height: 11.3333, borderRadius: 3.5, background: "var(--ios-dt-tag)", color: "var(--ios-dt-tag-label)", fontSize: 8.5, lineHeight: 1, fontWeight: 700, letterSpacing: 0 }}>
            {tag}
          </span>
        )}
      </Cell>
    ));
  }
  if (links.length > 0) {
    place(links.length * cell.row, top => (
      <Cell key="links" top={top} height={links.length * cell.row}>
        {links.map((link, index) => (
          <div key={link.id} className="absolute" style={{ left: 0, right: 0, top: index * cell.row, height: cell.row }}>
            {index > 0 && <Separator top={0} />}
            <button type="button" data-slot="link" onClick={link.onPress}
              className={cn("absolute inset-0 flex items-center text-left", rowFocus)}
              style={{ paddingLeft: cell.inset, fontSize: 17, lineHeight: "22px", transform: "translateY(0.6667px)", color: "var(--ios-dt-blue)" }}>
              {link.label}
            </button>
          </div>
        ))}
      </Cell>
    ));
  }
  place(cell.row, top => (
    <Cell key="hide-alerts" top={top} height={cell.row}>
      <div className="absolute inset-0 flex items-center justify-between" style={{ paddingLeft: cell.inset, paddingRight: 14 }}>
        <span data-slot="hide-alerts-label" style={{ ...titleType, transform: "translateY(0.6667px)" }}>{hideAlertsLabel}</span>
        <IosSwitch checked={hideAlerts} onChange={onHideAlertsChange} label={hideAlertsLabel} style={{ transform: "translateY(0.3333px)" }} />
      </div>
    </Cell>
  ));
  if (photos && photos.items.length > 0) place(photosHeight(photos), top => <PhotosCell key="photos" section={photos} top={top} />);
  if (sharedLinks && sharedLinks.items.length > 0) place(listHeight(sharedLinks), top => <ListCell key="shared-links" section={sharedLinks} title="Links" top={top} />);
  if (attachments && attachments.items.length > 0) place(listHeight(attachments), top => <ListCell key="attachments" section={attachments} title="Attachments" top={top} />);
  place(cell.row, top => (
    <Cell key="block" top={top} height={cell.row}>
      <button type="button" data-slot="block" onClick={onBlock}
        className={cn("absolute inset-0 flex items-center text-left", rowFocus)}
        style={{ paddingLeft: cell.inset, fontSize: 17, lineHeight: "22px", transform: "translateY(0.6667px)", color: "var(--ios-dt-red)" }}>
        {blockLabel}
      </button>
    </Cell>
  ));
  // The page ends 20 below the last group: the measured gap, used as the bottom inset.
  const pageHeight = cursor;

  return (
    <div ref={root} data-slot="ios-details" data-state={open ? "open" : "closing"}
      data-progress={progress === undefined ? undefined : clamp01(progress).toFixed(3)}
      role="dialog" aria-modal="true" aria-labelledby={titleId}
      onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerEnd} onPointerCancel={onPointerEnd}
      className={cn("relative isolate size-full select-none overflow-hidden", vars, className)}
      style={{ fontFamily: font, ...style }} {...props}>
      {backdrop !== undefined && (
        <div aria-hidden="true" data-slot="backdrop" className="absolute inset-0 -z-10 overflow-hidden">
          {/*
            Blurring a box larger than the screen keeps the filter's own edge falloff off-screen, and
            the same box takes the sheet's push-back: 60 of overhang is more than the 4% ever needs,
            so no edge of the conversation comes into view. The blur is divided by that scale, so
            what lands on screen is the measured σ18 either way.
          */}
          <div ref={blur} data-slot="details-blur" className="absolute"
            style={{ inset: -60, background: "var(--ios-dt-page)", scale: String(iosDetailsMotion.backdropScale), filter: `blur(${(iosDetailsMotion.blur / iosDetailsMotion.backdropScale).toFixed(3)}px) saturate(var(--ios-dt-saturate))` }}>
            <div className="absolute" style={{ inset: 60 }}>{backdrop}</div>
          </div>
          <div ref={scrim} data-slot="details-scrim" className="absolute inset-0" style={{ background: "var(--ios-dt-scrim)" }} />
        </div>
      )}

      {/* At rest the wrapper carries no transform: a transform node makes Chrome snap descendants to
          whole CSS px, and the entrance is cancelled the moment it lands for exactly that reason. */}
      <div ref={content} data-slot="details-content" className="absolute inset-0"
        style={closing ? { pointerEvents: "none" } : undefined}>
        {actions.map((action, index) => (
          <GlassCircle key={action.id} size={54} data-slot="action" data-action={action.id} aria-label={action.label}
            aria-disabled={action.disabled || undefined} onClick={action.disabled ? undefined : action.onPress}
            style={{ ...subpixel(195.6667), left: 100 + index * 74, color: action.disabled ? "var(--ios-dt-glyph-off)" : "var(--ios-dt-glyph)", mixBlendMode: action.disabled ? "var(--ios-dt-glyph-blend)" as CSSProperties["mixBlendMode"] : undefined }}>
            <ActionGlyph icon={action.icon} />
          </GlassCircle>
        ))}

        {/* The cells scroll; the header above them does not, it collapses. With only the measured
            stack the page is shorter than the screen, so there is nothing to scroll and nothing to
            collapse, and the frame is the capture's. */}
        <div ref={scroller} data-slot="details-scroll" className="absolute inset-0" onScroll={onScroll}
          style={{ overflowY: scroll === undefined ? "auto" : "hidden", overscrollBehavior: "contain" }}>
          <div data-slot="details-page" className="relative" style={{ height: pageHeight }}>{groups}</div>
        </div>

        {collapsing && (
          // The nav bar's own glass, under the name once the header has collapsed into it: measured
          // fill, rim and shadow from `ios-nav-bar.tsx`. Its width is the name's, so it is only in
          // the tree while the collapse is running.
          <span aria-hidden="true" data-slot="collapsed-pill" className="pointer-events-none absolute" style={{
            top: iosDetailsCollapse.pill.top, height: iosDetailsCollapse.pill.height, borderRadius: iosDetailsCollapse.pill.radius,
            opacity: 0, background: "var(--ios-dt-glass)", boxShadow: "var(--ios-dt-glass-rim), var(--ios-dt-glass-shadow)",
            backdropFilter: `blur(${iosDetailsCollapse.blur}px)`, WebkitBackdropFilter: `blur(${iosDetailsCollapse.blur}px)`,
            ...continuous,
          }} />
        )}

        <div aria-hidden="true" data-slot="avatar" className="absolute flex items-center justify-center overflow-hidden rounded-full text-white"
          style={{ left: 161, top: 62, width: 80, height: 80, fontSize: 37.5, lineHeight: 1, fontWeight: 650, background: "linear-gradient(var(--ios-dt-av-top), var(--ios-dt-av-bottom))" }}>
          {avatar ?? letters}
        </div>

        <h1 id={titleId} data-slot="name" className="absolute m-0 whitespace-nowrap text-center"
          style={{ left: 0, right: 0, top: 146.15, fontSize: 28, lineHeight: "33px", fontWeight: 700, letterSpacing: 0, color: "var(--ios-dt-label)" }}>
          <span ref={nameInk}>{name}</span>
        </h1>

        <GlassCircle size={44} data-slot="back" aria-label="Back" onClick={onBack} style={{ left: 16, top: 62 }}>
          <svg aria-hidden="true" width="44" height="44" viewBox="0 0 44 44" fill="none" stroke="var(--ios-dt-glyph)" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round">
            <path d="M24.8 13.87 16.2 22.17 24.8 30.47" />
          </svg>
        </GlassCircle>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, type ComponentProps, type CSSProperties, type PointerEvent as ReactPointerEvent, type ReactNode, type UIEvent as ReactUIEvent } from "react";
import { cn } from "@/lib/utils";
import { Avatar } from "@/components/imessage/avatar";
import { GroupAvatar } from "@/components/imessage/group-avatar";
import { IosSwitch, iosDetailsCollapse, iosDetailsMorph, iosDetailsMotion, subpixel } from "@/components/imessage/ios-details";

/**
 * iOS 26 **group** conversation details, the screen a group's name pill opens.
 *
 * No capture in `references/` shows a group, so this screen is built from three sources and the
 * comment on every number says which one it is.
 *
 * **A. Measured on `references/ios/captures/details-light.png` / `details-dark.png`** (402×874 @3x),
 * through `ios-details.tsx`, which SPEC's fidelity table records at 0.08% against those frames. The
 * two screens share their whole frame, so these are used unchanged:
 *
 * - Back button Ø44 glass circle at (16, 62); the header photo slot Ø80 at (161, 62), centre (201, 102).
 * - Name 28px/33px bold (Chrome's fit to the measured 26pt ink box y 152.33–177.67), box top 146.15.
 * - Round glass action circles Ø54 with their centres on y 222.667, on a measured 74 pt pitch: three
 *   of them measure x 127 / 201 / 275. Centring an even count about x 201 is a **derivation** from
 *   that pitch, not a reading — see `actionLeft`.
 * - Grouped cells span x 16–386 (370 wide), radius 26 continuous, 20 between groups, first cell top
 *   269.6667. Row text starts 16 inside the cell (x 32); a plain text row is 52 tall; the separator
 *   is a 1 pt hairline on the row boundary, carried the way `ios-details.tsx` carries it.
 * - Cell and button fills: 6% black light / 12% white dark. Blue #0088ff / #0091ff, red #ff383c /
 *   #ff4245, separator #dadadb / #3a3a3c, secondary label #848488 / #98989f, chevron #bdbdbd / #5d5d5d.
 * - The screen sits over the conversation, blurred σ18 under a 49% white / 59% black scrim.
 * - `iosDetailsMotion`, `iosDetailsMorph`, `iosDetailsCollapse`, `IosSwitch` and `subpixel` are
 *   imported from that file rather than restated, so the two screens cannot drift apart.
 *
 * **B. Rendered by ChatKit 26 and measured off that render.** A probe app (`clang -target
 * arm64-apple-ios18.0-simulator`, `dlopen` of `/System/Library/PrivateFrameworks/ChatKit.framework`
 * inside the booted iPhone 17 Pro simulator — the same 402×874 @3x geometry as the captures) builds
 * the real cells, lays them out at the measured 370 cell width, dumps every frame, and is
 * screenshotted so the ink can be measured with `scripts/measure/px.py`. What it returned:
 *
 * | Value | Where it comes from |
 * |---|---|
 * | The header photo is the **Snowglobe** stack, not the pancake | A `CKAvatarView` given three contacts and a Ø80 frame draws faces at x 9.667–47.667 / y 32.333–61.333 / x 22.667–46.333, which is `group-avatar.tsx`'s `snowglobeSlots(3)` scaled to 80 to within a third of a point. `CKDetailsAvatarPancakeView` — the lozenge this file used to draw — is a *different* view: `CKDetailsGroupHeaderCell._avatarView`, 41 tall, with `configureCellIconForCollapsedState:`. The details header's photo is `CKGroupPhotoCell._groupView`. |
 * | Group photo ground disc | The Ø80 `CKAvatarView` paints a full-diameter disc behind the faces: measured #f4f5f5 over white and #1f1f20 over black. Light is exactly `+[UIColor quaternarySystemFillColor]` rgba(116,116,128,0.08); the dark alpha is fitted to the measured composite (quaternary's own 0.18 lands 10/255 too dark). |
 * | Participant row 64 tall, avatar Ø37, 12 to the name | `+[CKDetailsContactsStandardTableViewCell preferredHeight]` = 64 and the rendered cell: avatar Ø37 at x 8 y 13.333, name label at x 57 = 8 + 37 + 12. |
 * | Participant name 17 **semibold**, full label colour | The rendered `CKDetailsContactsTableViewCell.nameLabel` is `.SFUI-Semibold 17.0` at rgba(0,0,0,1) — so `detailsContactCellTitleColor`'s 84.71% is not what the cell paints. |
 * | Participant separator inset = the name column | The rendered cell's own hairline starts at x 57, the name column, and runs to the cell's trailing edge. Here that is 16 + 37 + 12 = **65**. |
 * | Add row 44 tall, button Ø37, glyph 13.667 square on a 1.444 stroke | `+[CKDetailsAddMemberStandardCell preferredHeight]` = 44; the rendered circle measures Ø37.000 at x 8 y 3.333 and its plus measures 13.6667 × 13.6667 pt of ink with a 4.33 device-px (1.4444 pt) stroke. |
 * | Add button fill | The rendered circle is #efeff0 over white and #323236 over the cell's own #1c1c1e in dark: both are exactly `-[CKUITheme detailsAddButtonBackgroundColor]` rgba(118,118,128,0.12 / 0.24). |
 * | "Add Contact" | `ADD_CONTACT` in ChatKit's en loctable, and the string the rendered cell actually shows. (`ADD_MEMBER` "Add Member" also exists and is exported for the callers that want it.) |
 * | Group count row 22 | `+[CKDetailsGroupCountCell preferredHeight]` = 22, `DETAILS_VIEW_GROUP_COUNT_TEXT` "%lu PEOPLE" / "%lu PERSON". |
 * | Show-all row 44 | `+[CKDetailsShowMoreContactsCell preferredHeight]` = 44 — native truncates a long member list. ChatKit has no string of its own for that row, so `SEARCH_SHOW_MORE` "See All" stands in. |
 * | Two action buttons, not three | `CKDetailsGroupNameCell` carries exactly `_phoneButton` and `_facetimeVideoButton`; there is no mail button on a group. |
 * | Copy | `ChatKit.loctable` (en), verbatim in `groupDetailsCopy`. |
 *
 * **C. UNMEASURED**, and marked as such where it is used:
 *
 * - Every duration: the presentation and the header collapse are `ios-details.tsx`'s, whose own
 *   header already records them as unmeasured.
 * - The shared-content cells (photos grid, links, attachments). They are the sibling screen's, built
 *   the same way and placed where the sibling places them — after Hide Alerts, above the destructive
 *   row — so with none of them present this screen reproduces the measured cell stack exactly.
 * - The 110 photo tile: `(370 − 2×16 − 2×4)/3`. The 4 gap and the radius 12 are measured
 *   (`photo-picker-light.png`, SPEC line 164); three-across inside the measured 16 inset is not.
 *   `-[CKUIBehaviorPhone searchPhotosInterItemSpacingDetailsView]` = 1.5 and
