   * on the panel for why the shape gives way to sub-pixel edges here.
   */
  topRadius: 39,
  bottomRadius: 57.5833,
  roundTopRadius: 36.1667,
  roundBottomRadius: 53.5,
  columns: 3,
  gap: 1.6207,
