                <svg aria-hidden="true" width={10} height={10} viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth={1.6} strokeLinecap="round">
                  <path d="M1.5 1.5 8.5 8.5M8.5 1.5 1.5 8.5" />
