const font = '-apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro", "Helvetica Neue", Helvetica, Arial, sans-serif';

/**
 * Light values are the conversation list's measured tokens; dark values are its measured dark set.
 * `--ios-search-field-fill` is the pill's own composited interior, measured #ffffff in
 * `search-active-light.png` and #191919 in `search-noresults-dark.png`; the clear button's cross is
 * knocked out of the disc in exactly that colour. The balloon fills defer to the kit's palette
 * (`tokens.ts`, applied by the shell as `--im-*`) so the blue stays one screen-space gradient rather
 * than a second copy of the same two endpoints.
 */
const vars =
  "[--ios-search-bg:#ffffff] [--ios-search-label:#000000] [--ios-search-secondary:#8a8a8e] [--ios-search-chevron:#c5c5c7] [--ios-search-separator:#e8e8e8] " +
  "[--ios-search-glass:rgba(255,255,255,0.9)] [--ios-search-rim:none] [--ios-search-shadow:0_6px_36px_4px_rgba(0,0,0,0.065)] [--ios-search-shadow-round:0_5px_20px_6px_rgba(0,0,0,0.055)] " +
  "[--ios-search-field:#8a8a8e] [--ios-search-field-fill:#ffffff] [--ios-search-glyph:#1a1919] " +
  "[--ios-search-tint:#0088ff] [--ios-search-incoming:#e9e9eb] [--ios-search-incoming-text:#000000] [--ios-search-tile:#e9e9eb] " +
  "dark:[--ios-search-bg:#000000] dark:[--ios-search-label:#ffffff] dark:[--ios-search-secondary:#8d8d93] dark:[--ios-search-chevron:#464649] dark:[--ios-search-separator:#2a2a2c] " +
  "dark:[--ios-search-glass:rgba(28,28,28,0.9)] dark:[--ios-search-rim:inset_0_0_0_1px_rgba(255,255,255,0.09)] dark:[--ios-search-shadow:none] dark:[--ios-search-shadow-round:none] " +
  "dark:[--ios-search-field:#97979d] dark:[--ios-search-field-fill:#191919] dark:[--ios-search-glyph:#f4f3f4] " +
  "dark:[--ios-search-tint:#0091ff] dark:[--ios-search-incoming:#262629] dark:[--ios-search-incoming-text:#ffffff] dark:[--ios-search-tile:#1c1c1e]";

const clamp01 = (value: number) => Math.max(0, Math.min(1, value));

/**
 * The measured tables again, read straight rather than played, so the very first committed frame is
 * already the frame the timeline would draw. Without this the server renders the surface at its base
 * opacity, the screen paints finished, and the animation snaps it back several frames later - which is
 * exactly the flash this screen used to open with.
 */
function sampleTrack<K extends string>(frames: ReadonlyArray<{ offset: number } & Record<K, number>>, key: K, at: number): number {
  const t = clamp01(at);
  for (let i = 1; i < frames.length; i++) {
    const previous = frames[i - 1];
    const next = frames[i];
    if (t > next.offset) continue;
    const span = next.offset - previous.offset;
    const fraction = span === 0 ? 1 : (t - previous.offset) / span;
    return previous[key] + (next[key] - previous[key]) * fraction;
  }
  return frames[frames.length - 1][key];
}

/** `useLayoutEffect` on the client so a posed frame is committed before the browser paints it. */
const useBeforePaint = typeof window === "undefined" ? useEffect : useLayoutEffect;

function reducedMotion() {
  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;
}

function initialsOf(name: string): string {
  return name.trim().split(/\s+/).slice(0, 2).map(part => part[0] ?? "").join("").toUpperCase();
}

/**
 * Where the query lands in a piece of text. Falls back to each word when the whole phrase misses, and
 * merges overlaps so the renderer never has to drop a range it cannot draw.
 */
export function matchRanges(text: string, query: string): Array<[number, number]> {
  const needle = query.trim().toLowerCase();
  if (!needle) return [];
  const haystack = text.toLowerCase();
  const find = (term: string) => {
    const found: Array<[number, number]> = [];
    for (let at = haystack.indexOf(term); at !== -1; at = haystack.indexOf(term, at + term.length)) found.push([at, at + term.length]);
    return found;
  };
  const whole = find(needle);
  const raw = whole.length > 0 ? whole : needle.split(/\s+/).filter(Boolean).flatMap(find);
  const sorted = raw.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  const merged: Array<[number, number]> = [];
  for (const [start, end] of sorted) {
    const last = merged[merged.length - 1];
    if (last && start <= last[1]) last[1] = Math.max(last[1], end);
    else merged.push([start, end]);
  }
  return merged;
}

/**
 * ChatKit's `ck_trimmedStringWithPreferredLength:anchoredAroundSubstring:`: a snippet longer than
 * `max` is cut down to a window centred on the match, with an ellipsis on whichever side was cut.
 * This is native's *pre*-trim at 200 characters; it is not what keeps the match on screen, because a
 * one-line balloon shows about thirty. `Snippet` does that part.
 */
export function trimAroundMatch(text: string, query: string, max = iosSearchMetrics.message.maxSummaryLength): string {
  if (text.length <= max) return text;
  const first = matchRanges(text, query)[0];
  const anchor = first ? first[0] : 0;
  const start = Math.max(0, Math.min(text.length - max, anchor - Math.floor((max - (first ? first[1] - first[0] : 0)) / 2)));
  const end = Math.min(text.length, start + max);
  return `${start > 0 ? "…" : ""}${text.slice(start, end).trim()}${end < text.length ? "…" : ""}`;
}

/** Splits text into the run before the first match, the match, and the run after it. */
export function splitAroundMatch(text: string, query: string): { before: string; match: string; after: string } {
  const first = matchRanges(text, query)[0];
  if (!first) return { before: text, match: "", after: "" };
  return { before: text.slice(0, first[0]), match: text.slice(first[0], first[1]), after: text.slice(first[1]) };
}

/**
 * The annotated snippet inside a balloon. Same font throughout, only the colour changes, which is
 * what `-[CKMessageSearchResultCell _annotatedResultStringForResult:searchText:]` does.
 *
 * The balloon is one line and the framework's 200-character pre-trim leaves the match well past its
 * right edge, so the visible window has to be anchored on the match too. Three flex children do that
 * without measuring anything: the run before the match may shrink and truncates **at its start**
 * (`direction: rtl` with `unicode-bidi: plaintext`, so Latin text still reads left to right but the
 * ellipsis lands on the left), the match itself never shrinks, and the run after it truncates at its
 * end as usual.
 */
function Snippet({ text, query, match }: { text: string; query: string; match: string }) {
  const parts = splitAroundMatch(text, query);
  // `white-space: pre` on both runs, because each flex item starts its own line box and would
  // otherwise drop the space that sits against the match.
  const run: CSSProperties = { whiteSpace: "pre", overflow: "hidden", textOverflow: "ellipsis", minWidth: 0, flexShrink: 1 };
  if (!parts.match) return <span style={run}>{text}</span>;
  return (
    <>
      {parts.before && (
        <span data-slot="before" style={{ ...run, direction: "rtl" }}>
          {/* The run reads left to right inside a right-to-left box, so the ellipsis lands at its
              start; the isolate keeps the bidi algorithm from moving the run's own edge punctuation. */}
          <bdi dir="ltr">{parts.before}</bdi>
        </span>
      )}
      <span data-slot="match" className="shrink-0 whitespace-pre" style={{ color: match }}>{parts.match}</span>
      {parts.after && <span data-slot="after" style={run}>{parts.after}</span>}
    </>
  );
}

/** The same recolouring for a wrapping label, where every match is annotated and nothing is anchored. */
function Highlight({ text, query, match }: { text: string; query: string; match: string }) {
  const ranges = matchRanges(text, query);
  if (ranges.length === 0) return <>{text}</>;
  const parts: ReactNode[] = [];
  let at = 0;
  ranges.forEach(([start, end], index) => {
    if (start > at) parts.push(text.slice(at, start));
    parts.push(<span key={`${start}-${index}`} data-slot="match" style={{ color: match }}>{text.slice(start, end)}</span>);
    at = end;
  });
  if (at < text.length) parts.push(text.slice(at));
  return <>{parts}</>;
}

/** The measured list chevron, reused byte for byte. */
function Chevron({ style }: { style?: CSSProperties }) {
  return (
    <svg aria-hidden="true" data-slot="chevron" className="absolute" style={style} width="11" height="16" viewBox="-2 -2 11 16" fill="none" stroke="var(--ios-search-chevron)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <path d="M1 1 6 6 1 11" />
    </svg>
  );
}

/** The measured list separator, from x 83 to 386 at the row's bottom edge. Never under a section's last row. */
function RowSeparator() {
  const m = iosSearchMetrics.row;
  return <span aria-hidden="true" data-slot="separator" className="absolute" style={{ left: m.separatorLeft, right: m.separatorRight, bottom: 0, height: 1, transform: "translateY(-0.3333px)", background: "var(--ios-search-separator)" }} />;
}

/** The list's glass, byte for byte: one shadow layer under one fill layer, clipped toward its neighbour. */
function GlassLayers({ round = false, clip }: { round?: boolean; clip?: "left" | "right" }) {
  return (
    <>
      <span aria-hidden="true" className="pointer-events-none absolute inset-0 -z-10 rounded-[inherit]" style={{ boxShadow: round ? "var(--ios-search-shadow-round)" : "var(--ios-search-shadow)", clipPath: clip ? `inset(-60px ${clip === "right" ? "-6px" : "-60px"} -60px ${clip === "left" ? "-6px" : "-60px"})` : undefined }} />
      <span aria-hidden="true" className="pointer-events-none absolute inset-0 rounded-[inherit]" style={{ background: "var(--ios-search-glass)", boxShadow: "var(--ios-search-rim)", backdropFilter: "blur(24px)", WebkitBackdropFilter: "blur(24px)" }} />
    </>
  );
}

function ConversationRow({ result, query, last, onSelect }: { result: IosSearchConversationResult; query: string; last: boolean; onSelect?: () => void }) {
  const m = iosSearchMetrics.row;
  return (
    <button type="button" onClick={onSelect} aria-label={`${result.name}, ${result.time}, ${result.preview}`}
      className="absolute inset-0 w-full text-left focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-blue-500">
      <Avatar aria-hidden="true" size={m.avatar} initials={result.initials ?? initialsOf(result.name)} className="absolute" style={{ left: m.avatarLeft, top: m.avatarTop }} />
      <span aria-hidden="true" data-slot="name" className="absolute truncate" style={{ left: m.textLeft, right: 96, top: m.nameTop, transform: "translateY(0.3333px)", fontSize: m.nameSize, lineHeight: 1, fontWeight: m.nameWeight, letterSpacing: 0, color: "var(--ios-search-label)" }}>
        {result.name}
      </span>
      <span aria-hidden="true" data-slot="time" className="absolute whitespace-nowrap" style={{ right: m.timeRight, top: m.timeTop, transform: "translateY(0.3333px)", fontSize: m.timeSize, lineHeight: 1, letterSpacing: 0, color: "var(--ios-search-secondary)" }}>
        {result.time}
      </span>
      <Chevron style={{ left: m.chevronLeft, top: m.chevronTop, transform: "translateX(0.3333px)" }} />
      {/* Two lines, so a match can sit on either; the balloon's anchoring is not needed and native's
          conversation cell does not do it either. Whether native bolds a conversation match is
          untested: `CKConversationSearchResultEmbeddedCell` takes a separate `annotatedFont`, unlike
          the message cell, and no capture shows one. */}
      <span aria-hidden="true" data-slot="preview" className="absolute overflow-hidden" style={{ left: m.textLeft, right: 34, top: m.previewTop, transform: "translateY(-0.3333px)", fontSize: m.previewSize, lineHeight: `${m.previewLine}px`, letterSpacing: 0, color: "var(--ios-search-secondary)", display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical" } as CSSProperties}>
        <Highlight text={result.preview} query={query} match="var(--ios-search-label)" />
      </span>
      {!last && <RowSeparator />}
    </button>
  );
}

function MessageRow({ result, query, last, height, onSelect }: { result: IosSearchMessageResult; query: string; last: boolean; height: number; onSelect?: () => void }) {
  const row = iosSearchMetrics.row;
  const m = iosSearchMetrics.message;
  const snippet = trimAroundMatch(result.text, query);
  // Every spacing here is a framework value; the balloon's own vertical padding is what the row has
  // left once they are taken out, so it is derived rather than invented.
  const balloonTop = m.topSpacing + m.labelLine + m.senderToBalloon;
  const balloonHeight = height - balloonTop - m.bottomSpacing;
  const label = [result.conversation, result.name].filter(Boolean).join(", ");
  return (
    <button type="button" onClick={onSelect} aria-label={`${label}, ${result.time}, ${snippet}`}
      className="absolute inset-0 w-full text-left focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-blue-500">
      {/* Ø28 centred in the measured 26-71 avatar gutter so the text column still starts at x 83. */}
      <Avatar aria-hidden="true" size={m.avatar} initials={result.initials ?? initialsOf(result.name)} className="absolute" style={{ left: row.avatarLeft + (row.avatar - m.avatar) / 2, top: m.topSpacing }} />
      <span aria-hidden="true" data-slot="message-heading" className="absolute flex items-baseline overflow-hidden whitespace-nowrap" style={{ left: row.textLeft, right: row.timeRight + 40, top: m.topSpacing, height: m.labelLine, gap: m.conversationToSender, fontSize: m.labelFontSize, lineHeight: `${m.labelLine}px`, letterSpacing: 0 }}>
        {result.conversation && <span data-slot="conversation" className="shrink-0 truncate" style={{ fontWeight: m.conversationWeight, color: "var(--ios-search-label)" }}>{result.conversation}</span>}
        <span data-slot="sender" className="truncate" style={{ color: "var(--ios-search-secondary)" }}>{result.name}</span>
      </span>
      <span aria-hidden="true" data-slot="time" className="absolute whitespace-nowrap" style={{ right: row.timeRight, top: m.topSpacing, fontSize: m.labelFontSize, lineHeight: `${m.labelLine}px`, letterSpacing: 0, color: "var(--ios-search-secondary)" }}>
        {result.time}
      </span>
      {/*
        The track carries the geometry so the balloon inside it can hug its own text and still stop
        short: an absolutely positioned box cannot take `left`, `right` and a shrink-to-fit width at
        once. The chevron sits at the row's trailing edge and the framework's 12pt balloon-to-chevron
        gap becomes the track's right inset.
        `data-slot="message-bubble"` and the inner `data-slot="bubble"` are what `useBubbleScreenSpace`
        looks for, so an outgoing balloon takes the kit's one screen-space gradient instead of a second
        copy of it squeezed into 34pt.
      */}
      <span aria-hidden="true" data-slot="balloon-track" className="absolute flex items-center"
        style={{ left: row.textLeft, right: iosSearchMetrics.screen.width - row.chevronLeft + m.balloonToChevron, top: balloonTop, height: balloonHeight }}>
        <span data-slot="message-bubble" data-direction={result.fromMe ? "outgoing" : "incoming"} className="flex h-full min-w-0 items-center"
          style={{ maxWidth: `min(100%, ${iosSearchMetrics.screen.width - m.horizontalBalloonMargin}px)` }}>
          <span data-slot="bubble" className="flex h-full min-w-0 items-center overflow-hidden"
            style={{
              paddingLeft: m.balloonPaddingX,
              paddingRight: m.balloonPaddingX,
              borderRadius: Math.min(m.balloonRadius, balloonHeight / 2),
              backgroundColor: result.fromMe ? "var(--im-blue-bottom, #3682f7)" : "var(--ios-search-incoming)",
              backgroundImage: result.fromMe ? "linear-gradient(var(--im-blue-top, #77c7f5), var(--im-blue-bottom, #3682f7))" : undefined,
              backgroundSize: result.fromMe ? "100% var(--im-screen-h, 874px)" : undefined,
              backgroundRepeat: "no-repeat",
              backgroundPosition: result.fromMe ? "0 calc(100% + (var(--im-screen-h, 874px) - var(--bubble-bottom, calc(var(--im-screen-h, 874px) * 0.55))))" : undefined,
              fontSize: m.balloonFontSize,
              lineHeight: `${m.balloonLine}px`,
              letterSpacing: 0,
              color: result.fromMe ? m.fromMeUnannotated : "var(--ios-search-secondary)",
            }}>
            <Snippet text={snippet} query={query} match={result.fromMe ? "#ffffff" : "var(--ios-search-label)"} />
          </span>
        </span>
      </span>
      <Chevron style={{ left: row.chevronLeft, top: balloonTop + balloonHeight / 2 - 8, transform: "translateX(0.3333px)" }} />
      {!last && <RowSeparator />}
    </button>
  );
}

function PhotoTile({ result, onSelect }: { result: IosSearchPhotoResult; onSelect?: () => void }) {
  const m = iosSearchMetrics.photos;
  const size = iosSearchMetrics.cellWidth;
  return (
    <button type="button" onClick={onSelect} aria-label={`Photo from ${result.name}, ${result.time}`}
      className="relative block shrink-0 overflow-hidden focus-visible:outline-2 focus-visible:outline-blue-500"
      style={{ width: size, height: size, borderRadius: m.radius, background: "var(--ios-search-tile)" }}>
      {result.src && (
        // eslint-disable-next-line @next/next/no-img-element -- registry components stay framework-neutral
        <img src={result.src} alt="" className="size-full object-cover" draggable={false} />
      )}
    </button>
  );
}

/**
 * `CKLinkSearchResultCell` hosts an `LPLinkView`, whose small form is one image with a caption bar
 * over its foot. The card is `searchCellPreferredWidth` scaled by the framework's own fractional
 * scales: 192 x 136.
 */
function LinkCard({ result, query, onSelect }: { result: IosSearchLinkResult; query: string; onSelect?: () => void }) {
  const m = iosSearchMetrics.links;
  const width = iosSearchMetrics.cellWidth * m.widthScale;
  const height = iosSearchMetrics.cellWidth * m.heightScale;
  return (
    <button type="button" onClick={onSelect} aria-label={`${result.title}, ${result.domain}, ${result.time}`}
      className="relative block shrink-0 overflow-hidden text-left focus-visible:outline-2 focus-visible:outline-blue-500"
      style={{ width, height, borderRadius: m.radius, background: "var(--ios-search-tile)" }}>
      {result.src && (
        // eslint-disable-next-line @next/next/no-img-element -- registry components stay framework-neutral
        <img src={result.src} alt="" className="absolute inset-0 size-full object-cover" draggable={false} />
      )}
      <span aria-hidden="true" className="absolute inset-x-0 bottom-0 flex flex-col justify-center" style={{ height: m.captionHeight, padding: `0 ${m.captionPadding}px`, background: "var(--ios-search-glass)", backdropFilter: "blur(24px)", WebkitBackdropFilter: "blur(24px)" }}>
        <span className="block truncate" style={{ fontSize: m.labelFontSize, lineHeight: `${m.labelLine}px`, fontWeight: 600, letterSpacing: 0, color: "var(--ios-search-label)" }}>
          <Highlight text={result.title} query={query} match="var(--ios-search-tint)" />
        </span>
        <span className="block truncate" style={{ fontSize: m.labelFontSize, lineHeight: `${m.labelLine}px`, letterSpacing: 0, color: "var(--ios-search-secondary)" }}>
          {result.domain}
        </span>
      </span>
    </button>
  );
}

function DocumentCard({ result, query, onSelect }: { result: IosSearchDocumentResult; query: string; onSelect?: () => void }) {
  const m = iosSearchMetrics.documents;
  const size = iosSearchMetrics.cellWidth;
  return (
    <button type="button" onClick={onSelect} aria-label={`${result.title}, ${result.time}`}
      className="relative block shrink-0 text-left focus-visible:outline-2 focus-visible:outline-blue-500" style={{ width: size }}>
      <span aria-hidden="true" className="block overflow-hidden" style={{ height: size, borderRadius: m.radius, background: "var(--ios-search-tile)" }}>
        {result.src && (
          // eslint-disable-next-line @next/next/no-img-element -- registry components stay framework-neutral
          <img src={result.src} alt="" className="size-full object-cover" draggable={false} />
        )}
      </span>
      <span aria-hidden="true" className="block truncate" style={{ marginTop: m.titleTop, fontSize: m.labelFontSize, lineHeight: `${m.labelLine}px`, fontWeight: 600, letterSpacing: 0, color: "var(--ios-search-label)" }}>
        <Highlight text={result.title} query={query} match="var(--ios-search-tint)" />
      </span>
      <span aria-hidden="true" className="block truncate" style={{ marginTop: m.dateTop, fontSize: m.labelFontSize, lineHeight: `${m.labelLine}px`, letterSpacing: 0, color: "var(--ios-search-secondary)" }}>
        {result.time}
      </span>
    </button>
  );
}

function SectionHeader({ id, title, kind, showSeeAll, onSeeAll }: { id: string; title: string; kind: IosSearchSectionKind; showSeeAll: boolean; onSeeAll?: (kind: IosSearchSectionKind) => void }) {
  const m = iosSearchMetrics.header;
  return (
    <div data-slot="section-header" className="sticky top-0 z-10 flex items-center justify-between gap-3" style={{ height: m.height, paddingLeft: m.margin, paddingRight: m.margin + iosSearchMetrics.details.seeAllTrailingMargin, background: "var(--ios-search-bg)" }}>
      <h2 id={id} className="m-0 min-w-0 truncate" style={{ fontSize: m.fontSize, lineHeight: `${m.lineHeight}px`, fontWeight: m.weight, letterSpacing: 0, color: "var(--ios-search-label)" }}>
        {title}
      </h2>
      {showSeeAll && onSeeAll && (
        <button type="button" data-slot="see-all" onClick={() => onSeeAll(kind)} aria-label={`${iosSearchStrings.seeAll} ${title}`}
          className="shrink-0 rounded focus-visible:outline-2 focus-visible:outline-blue-500"
          style={{ fontSize: m.buttonFontSize, lineHeight: `${m.buttonLineHeight}px`, letterSpacing: 0, color: "var(--ios-search-tint)" }}>
          {iosSearchStrings.seeAll}
        </button>
      )}
    </div>
  );
}

/**
 * The magnifier UIKit draws above "No Results", measured off `search-noresults-dark.png`: the ink box
 * is 45.3333 x 46.0; the ring's outer diameter is 37.3333 with a 4.0 stroke, so its centre line has
 * radius 16.6667 about (18.6667, 18.6667) inside that box; the handle is a 45° stroke 5.45 wide
 * (a horizontal cut through it measures 7.7) whose round cap ends the ink at the box's corner.
 */
function EmptyGlyph() {
  const m = iosSearchMetrics.empty;
  return (
    <svg aria-hidden="true" data-slot="empty-glyph" width={m.glyph} height={m.glyphHeight} viewBox={`0 0 ${m.glyph} ${m.glyphHeight}`} fill="none" stroke="var(--ios-search-secondary)" strokeLinecap="round">
      <circle cx="18.6667" cy="18.6667" r="16.6667" strokeWidth="4" />
      <path d="M30.46 30.45 43.4 44.07" strokeWidth="5.45" />
    </svg>
  );
}

export function IosSearch({
  query: queryProp,
  defaultQuery = "",
  onQueryChange,
  sections = [],
  onSelect,
  onSeeAll,
  onCancel,
  open = true,
  onExited,
  progress,
  topInset = 54,
  listRef,
  maxResults = iosSearchMetrics.maxResults,
  displayScale = 3,
  placeholder = iosSearchStrings.placeholder,
  closeLabel = iosSearchStrings.close,
  emptyState = null,
  noResultsTitle = iosSearchStrings.noResults,
  noResultsDetail = iosSearchStrings.noResultsDetail,
  className,
  style,
  ...props
}: IosSearchProps) {
  const m = iosSearchMetrics;
  const id = useId();
  const [internalQuery, setInternalQuery] = useState(defaultQuery);
  const query = queryProp ?? internalQuery;
  const setQuery = (next: string) => {
    if (queryProp === undefined) setInternalQuery(next);
    onQueryChange?.(next);
  };

  const root = useRef<HTMLDivElement>(null);
  const surface = useRef<HTMLDivElement>(null);
  const results = useRef<HTMLDivElement>(null);
  const composeGlyph = useRef<SVGSVGElement>(null);
  const closeGlyph = useRef<SVGSVGElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const exited = useRef(false);
  // Kept in a ref so a caller passing a fresh closure does not restart the timeline: an inline arrow
  // has a new identity on every render, and a dependency on it would tear a finished exit down and
  // start it again from the top.
  const exitedCallback = useRef(onExited);
  useEffect(() => {
    exitedCallback.current = onExited;
  });

  // An outgoing balloon is filled by the kit's one screen-space gradient, so it needs the same
  // `--bubble-bottom` bookkeeping every other bubble gets, against this screen's own frame.
  useBubbleScreenSpace(results, root);

  const rowHeight = iosSearchRowHeight(displayScale);
  const fieldTop = m.screen.height - m.field.bottomInset - m.field.height;
  const resultsTop = topInset + m.resultsTopPadding;

  // Which table is playing, and where it starts, both derived during render: the closing direction is
  // read off `open` (never off an effect, which would miss the exit's frames), and the surface carries
  // its own first frame inline so the server and the first client paint already draw it.
  const closing = !open;
  const phase = closing ? iosSearchMotion.close : iosSearchMotion.open;
  const posed = progress === undefined ? 0 : clamp01(progress);
  const surfaceOpacity = sampleTrack(phase.surface, "opacity", posed);
  // The same two glyph ramps the timeline plays, read at `posed`, so whichever glyph belongs to this
  // frame is already the one the first paint shows.
  const { out, in: back } = iosSearchMotion.glyph;
  const leavingOpacity = posed >= out ? 0 : 1 - posed / out;
  const arrivingOpacity = posed <= out ? 0 : posed >= back ? 1 : (posed - out) / (back - out);
  const composeOpacity = closing ? arrivingOpacity : leavingOpacity;
  const closeOpacity = closing ? leavingOpacity : arrivingOpacity;

  /** Escape leaves search, wherever focus happens to be. */
  useEffect(() => {
    if (!open || !onCancel) return;
    const onKey = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      onCancel();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, onCancel]);

  /** Opening for real takes the caret; a scrubbed frame must not, or the harness moves focus. */
  useEffect(() => {
    if (!open || progress !== undefined) return;
    input.current?.focus({ preventScroll: true });
  }, [open, progress]);

  /**
   * One timeline over the surface, the two glyphs in the trailing circle and — when the caller hands
   * it over — the conversation list's scrolling layer. Opening and closing run **different measured
   * keyframe tables**, because the recordings say they are different animations: the open is a 267 ms
   * symmetric fade with an accelerating rise, the close a 292 ms ease-in-out fall that begins with the
   * surface already gone. The direction is read off `open` during render rather than in an effect that
   * would skip the exit's frames.
   */
  useBeforePaint(() => {
    if (open) exited.current = false;
    const duration = phase.duration;
    const finish = () => {
      if (exited.current) return;
      exited.current = true;
      exitedCallback.current?.();
    };
    // The compose glyph leaves over the first 28.1% and the ✕ arrives between 28.1% and 51.3%, which
    // is where the recording's ink bottoms out and peaks. Closing plays the same handover the other
    // way round rather than time-reversing it, so both directions start with the glyph that is there.
    const leaves: Keyframe[] = [{ opacity: 1, offset: 0 }, { opacity: 0, offset: iosSearchMotion.glyph.out }, { opacity: 0, offset: 1 }];
    const arrives: Keyframe[] = [{ opacity: 0, offset: 0 }, { opacity: 0, offset: iosSearchMotion.glyph.out }, { opacity: 1, offset: iosSearchMotion.glyph.in }, { opacity: 1, offset: 1 }];
    const tracks: Array<[Element | null, Keyframe[]]> = [
      [surface.current, phase.surface.map(frame => ({ opacity: frame.opacity, offset: frame.offset }))],
      [listRef?.current ?? null, phase.list.map(frame => ({ transform: `translateY(${frame.translate}px)`, offset: frame.offset }))],
      [composeGlyph.current, closing ? arrives : leaves],
      [closeGlyph.current, closing ? leaves : arrives],
    ];
    const animations = tracks
      .filter((track): track is [Element, Keyframe[]] => track[0] !== null)
      .map(([node, frames]) => node.animate(frames, { duration, easing: "linear", fill: "both" }));
    const stop = () => { for (const animation of animations) animation.cancel(); };
    const seek = (to: number) => {
      for (const animation of animations) {
        animation.pause();
        animation.currentTime = to;
      }
    };
    // Scrubbing is inspection, not a dismissal: a seeked frame poses the screen and reports nothing.
    if (progress !== undefined) {
      seek(clamp01(progress) * duration);
      return stop;
    }
    // `prefers-reduced-motion` gets the last frame rather than no animation at all, so the same one
    // timeline still owns every value and nothing is left at its authored default.
    if (reducedMotion()) {
      seek(duration);
      if (!closing) return stop;
      const frame = requestAnimationFrame(finish);
      return () => { cancelAnimationFrame(frame); stop(); };
    }
    if (!closing) return stop;
    const first = animations[0];
    first?.addEventListener("finish", finish);
    return () => { first?.removeEventListener("finish", finish); stop(); };
  }, [open, closing, phase, progress, listRef]);

  const typed = query.trim().length > 0;
  const shown = sections.map(section => ({ section, visible: section.results.slice(0, maxResults) })).filter(entry => entry.visible.length > 0);
  const total = sections.reduce((count, section) => count + section.results.length, 0);

  const rowSection = (section: IosSearchSection, visible: IosSearchResult[], headingId: string) => {
    const insets = section.kind === "conversations" ? m.conversationSection : { top: 0, bottom: 0 };
    return (
      <ul role="list" aria-labelledby={headingId} className="relative m-0 list-none p-0"
        style={{ height: visible.length * rowHeight + insets.top + insets.bottom, paddingTop: insets.top }}>
        {visible.map((result, index) => (
          <li key={result.id} role="listitem" className="absolute left-0 right-0" style={{ top: insets.top, height: rowHeight, transform: `translateY(${index * rowHeight}px)` }}>
            {section.kind === "conversations"
              ? <ConversationRow result={result as IosSearchConversationResult} query={query} last={index === visible.length - 1} onSelect={() => onSelect?.(result, section.kind)} />
              : <MessageRow result={result as IosSearchMessageResult} query={query} height={rowHeight} last={index === visible.length - 1} onSelect={() => onSelect?.(result, section.kind)} />}
          </li>
        ))}
      </ul>
    );
  };

  const strip = (gap: number, children: ReactNode, headingId: string) => (
    <ul role="list" aria-labelledby={headingId} className="m-0 flex list-none overflow-x-auto p-0"
      style={{ gap, paddingLeft: m.header.margin, paddingRight: m.header.margin }}>
      {children}
    </ul>
  );

  return (
    <div ref={root} data-slot="ios-search" data-state={open ? "open" : "closed"} className={cn("absolute inset-0 isolate select-none overflow-hidden", vars, className)}
      style={{ fontFamily: font, ...style }} {...props}>
      {/*
        The page under the search, painted at 1 − the list's measured alpha. Native puts this surface
        *behind* the list and fades the list out on top of it; over the same background colour the two
        composites are the same pixels, and this way the list stays a sibling the shell owns.
      */}
      <div ref={surface} data-slot="surface" className="absolute inset-0" style={{ background: "var(--ios-search-bg)", opacity: surfaceOpacity }}>
        <div ref={results} data-slot="results" className="absolute overflow-y-auto"
          style={{ left: 0, right: 0, top: resultsTop, bottom: 0, paddingBottom: m.screen.height - fieldTop + m.resultsTopPadding }}>
          {!typed && emptyState}
          {typed && total === 0 && (
            // Centred in the results area, which the measured ink centre (431.0) matches to a point
            // against the area's own centre (430.0) between `resultsTop` and the bar.
            <div data-slot="no-results" role="status" className="flex flex-col items-center px-8 text-center"
              style={{ height: fieldTop - resultsTop, justifyContent: "center", transform: `translateY(${m.empty.blockNudge}px)` }}>
              <EmptyGlyph />
              <p className="m-0" style={{ marginTop: m.empty.glyphToTitle, fontSize: m.empty.titleFontSize, lineHeight: 1, fontWeight: m.empty.titleWeight, letterSpacing: 0, color: "var(--ios-search-label)" }}>{noResultsTitle}</p>
              {noResultsDetail && <p className="m-0" style={{ marginTop: m.empty.titleToSubtitle, fontSize: m.empty.subtitleFontSize, lineHeight: 1.2, letterSpacing: 0, color: "var(--ios-search-secondary)" }}>{noResultsDetail}</p>}
            </div>
          )}
          {typed && shown.map(({ section, visible }) => {
            const title = section.title ?? iosSearchSectionTitles[section.kind];
            const headingId = `${id}-${section.kind}`;
            const seeAll = section.results.length > visible.length;
            return (
              <section key={section.kind} data-slot="section" data-kind={section.kind} aria-labelledby={headingId} className="relative" style={{ paddingBottom: m.sectionGap }}>
                <SectionHeader id={headingId} title={title} kind={section.kind} showSeeAll={seeAll} onSeeAll={onSeeAll} />
                {/* `searchResultsTitleHeaderBottomPadding` is the gap under the title header, which is
                    where its name puts it; it used to be applied under the strip instead. */}
                <div style={{ paddingTop: m.header.bottomPadding }}>
                  {(section.kind === "conversations" || section.kind === "messages") && rowSection(section, visible, headingId)}
                  {section.kind === "photos" && strip(m.photos.gap, visible.map(result => (
                    <li key={result.id} role="listitem" className="shrink-0">
                      <PhotoTile result={result as IosSearchPhotoResult} onSelect={() => onSelect?.(result, section.kind)} />
                    </li>
                  )), headingId)}
                  {section.kind === "links" && strip(m.links.gap, visible.map(result => (
                    <li key={result.id} role="listitem" className="shrink-0">
                      <LinkCard result={result as IosSearchLinkResult} query={query} onSelect={() => onSelect?.(result, section.kind)} />
                    </li>
                  )), headingId)}
                  {section.kind === "documents" && strip(m.documents.gap, visible.map(result => (
                    <li key={result.id} role="listitem" className="shrink-0">
                      <DocumentCard result={result as IosSearchDocumentResult} query={query} onSelect={() => onSelect?.(result, section.kind)} />
                    </li>
                  )), headingId)}
                </div>
              </section>
            );
          })}
        </div>
      </div>

      {/* The bar never moves, never resizes and is the list's own bar: same 28 insets, same 48 height,
          same 12pt gap, same glass. Only the trailing circle's glyph and the pill's own right-hand
          control change. */}
      <div data-slot="field-row" role="search" className="absolute z-20 flex items-end"
        style={{ left: m.field.inset, right: m.field.inset, bottom: m.field.bottomInset, height: m.field.height }}>
        <div data-slot="field" className="relative h-full min-w-0 flex-1 rounded-full">
          <GlassLayers clip="right" />
          <svg aria-hidden="true" className="absolute" style={{ left: m.field.glyphLeft, top: m.field.glyphTop }} width="18.3333" height="18.6667" viewBox="-1 -1 18.3333 18.6667" fill="none" stroke="var(--ios-search-field)" strokeLinecap="round">
            <circle cx="6.745" cy="7.219" r="5.883" strokeWidth="1.725" />
            <path d="M11.4 12.01 15.17 15.78" strokeWidth="2.467" />
          </svg>
          {!typed && (
            <span aria-hidden="true" data-slot="placeholder" className="absolute" style={{ left: m.field.textLeft, top: m.field.textTop, transform: "translateY(0.3333px)", fontSize: 17, lineHeight: 1, fontWeight: 500, letterSpacing: 0, color: "var(--ios-search-field)" }}>
              {placeholder}
            </span>
          )}
          {/* The caret measures 2.0 x 22.0; Chrome draws a 1px caret and its width cannot be set, so the
              input carries the measured 22pt line box and the colour, and the extra point of width is a
              known miss. */}
          <input
            ref={input}
            type="search"
            autoComplete="off"
            autoCorrect="off"
            spellCheck={false}
            enterKeyHint="search"
            aria-label={placeholder}
            value={query}
            onChange={event => setQuery(event.target.value)}
            className="absolute border-0 bg-transparent p-0 outline-none select-text [&::-webkit-search-cancel-button]:appearance-none"
            style={{
              left: m.field.textLeft,
              right: m.field.clearRight + m.field.clearSize + 8,
              top: m.field.caretTop,
              height: m.field.caretHeight,
              fontFamily: font,
              fontSize: 17,
              lineHeight: `${m.field.caretHeight}px`,
              // Measured: the typed "Detail" and the "Search" placeholder have the same 5-device-pixel
              // stems at 3x, so typed text is the placeholder's weight, in the label colour.
              fontWeight: 500,
              letterSpacing: 0,
              color: "var(--ios-search-label)",
              caretColor: "var(--ios-search-tint)",
            }}
          />
          {typed && (
            <button type="button" data-slot="clear" aria-label="Clear search" onClick={() => { setQuery(""); input.current?.focus(); }}
              className="absolute flex items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-blue-500"
              style={{ right: m.field.clearRight, top: m.field.clearTop, width: m.field.clearSize, height: m.field.clearSize, background: "var(--ios-search-field)" }}>
              <svg aria-hidden="true" width={m.field.clearSize} height={m.field.clearSize} viewBox="0 0 17 17" fill="none" stroke="var(--ios-search-field-fill)" strokeWidth={m.field.clearCross} strokeLinecap="round">
                <path d="M5.5 5.5 11.5 11.5M11.5 5.5 5.5 11.5" />
              </svg>
            </button>
          )}
          {!typed && (
            <span aria-hidden="true" data-slot="mic" className="absolute" style={{ right: m.field.micRight, top: m.field.micTop, color: "var(--ios-search-field)", display: "flex" }}>
              <IosMicIcon width={m.field.micWidth} height={m.field.micHeight} />
            </span>
          )}
        </div>
        {/* The compose circle in its close state. Both glyphs are drawn so the timeline can crossfade
            them in place, which is what the recording shows the circle doing. */}
        <button type="button" data-slot="close" aria-label={closeLabel} onClick={onCancel}
          className="relative shrink-0 rounded-full focus-visible:outline-2 focus-visible:outline-blue-500"
          style={{ marginLeft: m.field.gap, width: m.field.button, height: m.field.button }}>
          <GlassLayers round clip="left" />
          <svg ref={composeGlyph} aria-hidden="true" data-slot="compose-glyph" className="absolute" style={{ left: 14, top: 13, opacity: composeOpacity }} width="21.3333" height="24" viewBox="0 -2.3333 21.3333 24" fill="none" stroke="var(--ios-search-glyph)" strokeLinecap="round" strokeLinejoin="round">
            <path d="M15 0.9167H4.1167A3.2 3.2 0 0 0 0.9167 4.1167V14.8833A3.2 3.2 0 0 0 4.1167 18.0833H14.8833A3.2 3.2 0 0 0 18.0833 14.8833V4" strokeWidth="1.8333" />
            <path d="M8.427 10.623 17.45 1.6" strokeWidth="2.1" />
            <circle cx="20" cy="-1" r="0.6" strokeWidth="1.4" />
          </svg>
          <svg ref={closeGlyph} aria-hidden="true" data-slot="close-glyph" className="absolute" style={{ left: m.field.closeGlyphLeft, top: m.field.closeGlyphTop, opacity: closeOpacity }} width={m.field.closeGlyph} height={m.field.closeGlyph} viewBox="0 0 17 17" fill="none" stroke="var(--ios-search-glyph)" strokeWidth={m.field.closeStroke} strokeLinecap="round">
            <path d="M1 1 16 16M16 1 1 16" />
          </svg>
        </button>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState, type ComponentProps, type KeyboardEvent, type PointerEvent, type ReactNode } from "react";
import { cn } from "@/lib/utils";

/**
 * "Swipe left to reveal times", measured from `references/ios/captures/swipe-timestamps-light.png`
 * (402×874 @3x).
 *
 * - Every bubble shifts left by exactly 58 (the last one's body right edge goes 386 → 328).
 * - The per-message time is 11pt secondary (#8a8a8e light / #8d8d93 dark), right-aligned with its
 *   ink ending at x 385, and its ink is centred on the bubble body's centre (measured on all eight
 *   bubbles: 235.17 / 295.5 / 339.83 / 384.17 / 464 / 572.5 / 626.5 / 686.67).
 * - iOS formats the time with a narrow no-break space before AM/PM.
 *
 * The drag rubber-bands past full reveal and past zero, and releasing runs a ~300 ms spring
 * (ζ 0.9, ω 20 rad/s). `prefers-reduced-motion` snaps instead. Keyboard users get ArrowLeft /
 * ArrowRight (and Enter/Space to toggle) on the element the hook's `handlers` are spread onto.
 */

const font = "-apple-system, BlinkMacSystemFont, sans-serif";

/** Measured reveal geometry, in points. `timeInset` is from the screen's trailing edge. */
/** `baselineNudge` corrects Chrome's baseline, which sits two thirds of a point below native's. */
export const swipeTimesMetrics = { distance: 58, timeInset: 16, fontSize: 11, lineHeight: 13, letterSpacing: 0.1, baselineNudge: -0.6667 } as const;

export type SwipeToRevealOptions = {
  /** How far the bubbles travel at full reveal. */
  distance?: number;
  /** Controlled 0..1. When set, dragging is disabled and the value is used verbatim. */
  progress?: number;
  /** Fraction of `distance` past which a release settles open. */
  threshold?: number;
  onChange?: (open: boolean) => void;
};

export type SwipeToRevealTimes = {
  /** 0 = hidden, 1 = fully revealed. May exceed 1 slightly while rubber-banding. */
  progress: number;
  /** Signed px shift for the bubble column (negative moves left). */
  offset: number;
  open: boolean;
  setOpen: (next: boolean) => void;
  handlers: {
    onPointerDown: (event: PointerEvent<HTMLElement>) => void;
    onPointerMove: (event: PointerEvent<HTMLElement>) => void;
    onPointerUp: (event: PointerEvent<HTMLElement>) => void;
    onPointerCancel: (event: PointerEvent<HTMLElement>) => void;
    onKeyDown: (event: KeyboardEvent<HTMLElement>) => void;
    tabIndex: number;
    role: string;
    "aria-label": string;
    style: { touchAction: "pan-y" };
  };
};

/** Rubber band: full travel inside [0, 1], a quarter of it outside. */
function band(raw: number) {
  if (raw < 0) return raw * 0.25;
  if (raw > 1) return 1 + (raw - 1) * 0.25;
  return raw;
}

export function useSwipeToRevealTimes({ distance = swipeTimesMetrics.distance, progress: controlled, threshold = 0.4, onChange }: SwipeToRevealOptions = {}): SwipeToRevealTimes {
  const [value, setValue] = useState(0);
  const current = useRef(0);
  const drag = useRef<{ id: number; startX: number; base: number; lastX: number; time: number; velocity: number } | null>(null);
  const spring = useRef({ raf: 0, target: 0, velocity: 0, last: 0 });

  const write = useCallback((next: number) => { current.current = next; setValue(next); }, []);
  const stop = useCallback(() => { cancelAnimationFrame(spring.current.raf); spring.current.raf = 0; }, []);
  useEffect(() => stop, [stop]);

  const settle = useCallback((target: number, velocity: number) => {
    stop();
    if (typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches) { write(target); return; }
    const s = spring.current;
    s.target = target; s.velocity = velocity; s.last = performance.now();
    const step = (now: number) => {
      const dt = Math.min(0.032, (now - s.last) / 1000);
      s.last = now;
      // ζ 0.9, ω 20 rad/s: about 300 ms to rest with no visible overshoot.
      s.velocity += (400 * (s.target - current.current) - 36 * s.velocity) * dt;
      const next = current.current + s.velocity * dt;
      if (Math.abs(s.target - next) < 0.0008 && Math.abs(s.velocity) < 0.01) { write(s.target); s.raf = 0; return; }
      write(next);
      s.raf = requestAnimationFrame(step);
    };
    s.raf = requestAnimationFrame(step);
  }, [stop, write]);

  const setOpen = useCallback((next: boolean) => { settle(next ? 1 : 0, 0); onChange?.(next); }, [settle, onChange]);

  const locked = controlled !== undefined;
  const progress = locked ? controlled : value;

  const handlers: SwipeToRevealTimes["handlers"] = {
    tabIndex: 0,
    role: "group",
    "aria-label": "Conversation. Swipe left, or press the left arrow key, to show message times.",
    style: { touchAction: "pan-y" },
    onPointerDown(event) {
      if (locked || event.button !== 0) return;
      stop();
      drag.current = { id: event.pointerId, startX: event.clientX, base: current.current, lastX: event.clientX, time: performance.now(), velocity: 0 };
      event.currentTarget.setPointerCapture?.(event.pointerId);
    },
    onPointerMove(event) {
      const d = drag.current;
      if (!d || d.id !== event.pointerId) return;
      const now = performance.now();
      const dt = Math.max(1, now - d.time);
      d.velocity = ((d.lastX - event.clientX) / distance / dt) * 1000;
      d.lastX = event.clientX; d.time = now;
      write(band(d.base + (d.startX - event.clientX) / distance));
    },
    onPointerUp(event) {
      const d = drag.current;
      if (!d || d.id !== event.pointerId) return;
      drag.current = null;
      event.currentTarget.releasePointerCapture?.(event.pointerId);
      const next = current.current + d.velocity * 0.12 > threshold;
      settle(next ? 1 : 0, d.velocity);
      onChange?.(next);
    },
    onPointerCancel(event) {
      const d = drag.current;
      if (!d || d.id !== event.pointerId) return;
      drag.current = null;
      settle(0, 0);
      onChange?.(false);
    },
    onKeyDown(event) {
      if (locked) return;
      if (event.key === "ArrowLeft") { event.preventDefault(); setOpen(true); }
      else if (event.key === "ArrowRight" || event.key === "Escape") { event.preventDefault(); setOpen(false); }
      else if (event.key === "Enter" || event.key === " ") { event.preventDefault(); setOpen(progress < 0.5); }
    },
  };

  return { progress, offset: -progress * distance, open: progress > 0.5, setOpen, handlers };
}

export type SwipeTimesProps = Omit<ComponentProps<"div">, "children"> & {
  /** Already formatted, e.g. "1:25 AM" with a narrow no-break space. */
  time: ReactNode;
  /** 0..1 from `useSwipeToRevealTimes`. */
  progress?: number;
  distance?: number;
  /** Ink inset from the container's trailing edge. */
  timeInset?: number;
  children: ReactNode;
};

/**
 * One message row of the reveal: shifts its message left and slides the time in from the trailing
 * edge, vertically centred on the bubble body. Clip the scrolling container: at rest the time column
 * sits one full `distance` off-screen.
 */
export function SwipeTimes({ time, progress = 0, distance = swipeTimesMetrics.distance, timeInset = swipeTimesMetrics.timeInset, className, style, children, ...props }: SwipeTimesProps) {
  const t = Math.max(0, progress);
  const row = useRef<HTMLDivElement>(null);
  // Native centres the time on the bubble *body*, not on the row: a reaction balloon or a status
  // line grows the row without moving the body, and the time stays put.
  useLayoutEffect(() => {
    const root = row.current;
    if (!root) return;
    const measure = () => {
      const body = root.querySelector<HTMLElement>('[data-slot="bubble"], [data-slot="emoji"]');
      const box = root.getBoundingClientRect();
      const centre = body ? body.getBoundingClientRect().top + body.getBoundingClientRect().height / 2 - box.top : box.height / 2;
      root.style.setProperty("--swipe-centre", `${centre.toFixed(2)}px`);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    document.fonts?.ready.then(measure).catch(() => {});
    return () => observer.disconnect();
  }, [children, time]);
  return (
    <div ref={row} data-slot="swipe-times" data-progress={t.toFixed(3)}
      className={cn("relative w-full [--ios-sw-secondary:#8a8a8e] dark:[--ios-sw-secondary:#8d8d93]", className)}
      style={{ fontFamily: font, ...style }} {...props}>
      <div data-slot="swipe-content" style={{ transform: `translateX(${(-t * distance).toFixed(2)}px)`, willChange: "transform" }}>{children}</div>
      <span data-slot="time" aria-hidden={t < 0.5 || undefined} className="pointer-events-none absolute whitespace-nowrap text-right"
        style={{
          // The column travels with the bubbles: it starts one full `distance` off the trailing edge.
          right: timeInset, top: "var(--swipe-centre, 50%)",
          transform: `translate(${((1 - Math.min(1, t)) * distance).toFixed(2)}px, calc(-50% + ${swipeTimesMetrics.baselineNudge}px))`,
          fontSize: swipeTimesMetrics.fontSize, lineHeight: `${swipeTimesMetrics.lineHeight}px`, letterSpacing: swipeTimesMetrics.letterSpacing,
          color: "var(--ios-sw-secondary)", opacity: Math.max(0, Math.min(1, t * 4)),
        }}>
        {time}
      </span>
    </div>
  );
}

"use client";

import type { ComponentProps, ReactNode } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";

/**
 * In-conversation notices.
 *
 * **Unknown sender** — measured from `references/ios/captures/incoming-light.png` / `-dark.png`
 * (402×874 @3x): centred secondary text whose ink runs 721.33–731.67 on line 1 and 734.67–745 on
 * line 2 (ascender 8.33, x-height 6.0 → 11pt, 13.33 pitch), colour #8a8a8e / #8d8d93. Line 1's ink
 * spans x 22.67–379 and line 2 ("be spam.") x 177–224, so the paragraph is centred on x 201 and
 * wraps inside the 370pt content width. The last bubble body ends at 702.67, 16 above the text box.
 * The "Report Spam" pill is 91 × 22.33 centred on (200.83, 766.83) — a capsule filled with the
 * incoming gray (#e9e9eb / #262629) carrying a 69pt-wide #0088ff / #0091ff label.
 *
 * **Not delivered** — measured from `references/macos/captures/attachment-not-delivered-dark-2x.png`
 * (960×640 @2x): a Ø17 red ring badge (#eb534e) centred 9.5 past the bubble's trailing edge, on the
 * body's vertical centre, plus "Not Delivered" in the same 10pt semibold slot "Delivered" uses,
 * right-aligned 16.5 inside the badge's trailing edge. iOS scales that to the 11pt status world.
 */

const font = "-apple-system, BlinkMacSystemFont, sans-serif";

const noticeVars =
  "[--ios-nt-secondary:#8a8a8e] [--ios-nt-pill:#e9e9eb] [--ios-nt-link:#0088ff] " +
  "dark:[--ios-nt-secondary:#8d8d93] dark:[--ios-nt-pill:#262629] dark:[--ios-nt-link:#0091ff]";

/** Measured notice geometry, in points. */
export const unknownSenderMetrics = {
  fontSize: 11, lineHeight: 13.3333, contentWidth: 370, topGap: 16,
  pillWidth: 91, pillHeight: 22.3333, pillGap: 10.3333, pillFontSize: 11, letterSpacing: 0.1,
  /**
   * Centring a 91 wide pill in the 370 wide content column puts its left edge on 155.5, half a
   * point off the device grid at 3x. Native rounds that painted edge down to the pixel below and
   * fills x 466–738 of the capture (155.33–246.33); Blink rounds the whole background box up to
   * 156 instead. Snapping happens before the transform, so two thirds of a point here lands the
   * composited capsule back on the capture's edges. It is a rasterising correction for the
   * measured 370 column, not a layout offset.
   */
  pillNudgeX: -0.6667,
} as const;

export type UnknownSenderNoticeProps = Omit<ComponentProps<"div">, "children" | "title"> & {
  /** The grey paragraph. Defaults to the exact string iOS shows. */
  message?: ReactNode;
  /** Omit to hide the button. */
  action?: string;
  onAction?: () => void;
  /** Space above the paragraph, from the previous bubble's body bottom. */
  topGap?: number;
};

export function UnknownSenderNotice({
  message = "If you did not expect this message from an unknown sender, it may be spam.",
  action = "Report Spam", onAction, topGap = unknownSenderMetrics.topGap, className, style, ...props
}: UnknownSenderNoticeProps) {
  const m = unknownSenderMetrics;
  return (
    <div data-slot="unknown-sender-notice" role="note"
      className={cn("flex w-full select-none flex-col items-center", noticeVars, className)}
      style={{ fontFamily: font, paddingTop: topGap, ...style }} {...props}>
      <p data-slot="notice-text" className="m-0 text-center"
        style={{ maxWidth: m.contentWidth, fontSize: m.fontSize, lineHeight: `${m.lineHeight}px`, letterSpacing: m.letterSpacing, color: "var(--ios-nt-secondary)" }}>
        {message}
      </p>
      {action && (
        <button type="button" data-slot="notice-action" onClick={onAction}
          className="relative flex items-center justify-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#0088ff]"
          style={{
            marginTop: m.pillGap, width: m.pillWidth, height: m.pillHeight, borderRadius: m.pillHeight / 2,
            color: "var(--ios-nt-link)",
            fontSize: m.pillFontSize, lineHeight: `${m.pillHeight}px`, fontWeight: 600, letterSpacing: 0,
          }}>
          {/* The fill carries `pillNudgeX`; the label must not, since its own ink already lands on the capture. */}
          <span aria-hidden="true" data-slot="notice-action-fill" className="absolute inset-0"
            style={{ borderRadius: m.pillHeight / 2, background: "var(--ios-nt-pill)", transform: `translateX(${m.pillNudgeX}px)` }} />
          {/* Chrome's baseline sits two thirds of a point below native's in this line box. */}
          <span className="relative" style={{ transform: "translateY(-0.6667px)" }}>{action}</span>
        </button>
      )}
    </div>
  );
}

/** Status typography per platform, matching `bubbleMetrics` so the label lands where "Delivered" would. */
const statusStyle: Record<Platform, { fontSize: number; lineHeight: number; letterSpacing: number; gap: number; inset: number; badge: number; badgeGap: number }> = {
  ios: { fontSize: 11, lineHeight: 13, letterSpacing: -0.25, gap: 4.65, inset: 19.3, badge: 18, badgeGap: 8 },
  macos: { fontSize: 10, lineHeight: 12, letterSpacing: -0.45, gap: 4, inset: 16.5, badge: 17, badgeGap: 9.5 },
};

export type FailedSendBadgeProps = Omit<ComponentProps<"button">, "children"> & {
  size?: number;
  platform?: Platform;
  label?: string;
};

/** The red (!) ring that sits beside a message that failed to send. */
export function FailedSendBadge({ size, platform: platformProp, label = "Message not delivered. Try again.", className, style, ...props }: FailedSendBadgeProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const d = size ?? statusStyle[platform].badge;
  return (
    <button type="button" data-slot="failed-send-badge" aria-label={label} title={label}
      className={cn("inline-flex shrink-0 items-center justify-center rounded-full align-middle focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#eb534e]", className)}
      style={{ width: d, height: d, ...style }} {...props}>
      <svg aria-hidden="true" width={d} height={d} viewBox="0 0 17 17" fill="none" stroke="#eb534e" strokeWidth="1.15" strokeLinecap="round">
        <circle cx="8.5" cy="8.5" r="7.9" />
        <path d="M8.5 4.3v5.1" />
        <path d="M8.5 12.35v0.05" strokeWidth="1.5" />
      </svg>
    </button>
  );
}

export type NotDeliveredProps = Omit<ComponentProps<"div">, "children"> & {
  label?: string;
  platform?: Platform;
  /** Trailing inset of the label's ink. Defaults to the platform's "Delivered" inset. */
  inset?: number;
};

/**
 * The red status line that replaces "Delivered". Drop it in the same slot: it uses the platform's
 * status typography so the ink lands on the measured baseline.
 */
export function NotDelivered({ label = "Not Delivered", platform: platformProp, inset, className, style, ...props }: NotDeliveredProps) {
  const contextPlatform = usePlatform();
  const platform = platformProp ?? contextPlatform;
  const s = statusStyle[platform];
  return (
    <div data-slot="not-delivered" className={cn("select-none text-right", className)}
      style={{
        fontFamily: font, fontSize: s.fontSize, lineHeight: `${s.lineHeight}px`, fontWeight: 600,
        letterSpacing: s.letterSpacing, marginTop: s.gap, paddingInlineEnd: inset ?? s.inset, color: "#eb534e", ...style,
      }} {...props}>
      {label}
    </div>
  );
}

"use client";

import { useLayoutEffect, useRef, type ComponentProps, type CSSProperties } from "react";
import { cn } from "@/lib/utils";
import { Avatar, type AvatarProps } from "@/components/imessage/avatar";

/**
 * The two avatar surfaces a group conversation has and a one-to-one does not: the stacked group
 * photo, and the small per-sender photo beside an incoming bubble.
 *
 * ## Where the numbers come from
 *
 * **A capture now exists.** Nothing in `references/ios/captures` or `references/macos/captures` shows
 * a group conversation — `grouped-light.png` is message *grouping* in a two-person thread and
 * `details-light.png` is a one-to-one details screen. So this surface was captured on purpose:
 * `references/group-avatar/snowglobe-light.png` and `snowglobe-dark.png` are
 * `xcrun simctl io booted screenshot` of the iPhone 17 Pro simulator (1206x2622 = 402x874 pt at 3x,
 * the repo's iOS capture geometry) running a small app that dlopens the runtime's own
 * ChatKit/ContactsUICore and lays out real `CKAvatarView`s over `CNMutableContact` fixtures. Every
 * circle in those two PNGs is drawn by Apple's code, in a live window, with a live blur. See
 * `references/group-avatar.md` for the layout and how to re-take them.
 *
 * The frames and diameters below are read straight out of the frameworks with a Mac Catalyst probe
 * (`clang -target arm64-apple-ios26.0-macabi`, `-[UIDevice userInterfaceIdiom]` swizzled to the idiom
 * being asked about, then `dlopen`), and cross-checked against those captures.
 *
 * ## The stack
 *
 * A group photo is not a ChatKit drawing at all: `CKAvatarView` is a `CNAvatarView` subclass, and
 * ContactsUICore lays the faces out through
 * `+[CNUIAvatarLayoutManager layoutConfigurationsForType:withItemCount:]`. Type 2 is
 * `SnowglobeAvatarLayoutConfigurations`, the one a group photo uses; type 3 is
 * `SnowglobeGroupTypingIndicatorAvatarLayoutConfigurations`, the same circles in a different order.
 * Each entry is a `CNUIAvatarLayoutItemConfiguration` carrying `x`, `y`, `size` and `baseSize`, and
 * `-itemFrameInContainingBounds:isRTL:` turns one into a frame:
 *
 * ```
 * s = bounds.width / baseSize          baseSize is 88 for every Snowglobe entry
 * d = size * s
 * frame = (bounds.midX + x*s - d/2, bounds.midY + y*s - d/2, d, d)
 * ```
 *
 * `snowglobeStack` is that table verbatim. One participant fills the circle; two and three have their
 * own rows; four, five and six add a slot to the three-face row; seven re-lays the whole set.
 * `+[CNUIAvatarLayoutManager maxAvatarCountForType:]` answers 10, but asking for 8, 9, 10 or 11
 * returns the same seven entries, so an eighth participant is simply not drawn.
 *
 * **The faces never touch.** The previous version of this file claimed "there is no ring, cut-out or
 * hairline between the faces — they simply overlap". They do not overlap: the table leaves a gap, and
 * that gap *is* the ring you see. Minimum centre-to-centre clearance, computed from the table and
 * confirmed in the capture (`snowglobeClearance`, in base-88 units): 1.598 for two faces, 2.446 for
 * three, 2.040 for four through six, 2.071 for seven — 1.09 / 1.67 / 1.39 / 1.41 pt once scaled to
 * Ø60. Whatever is behind the stack shows through that gap, and nothing strokes it.
 *
 * **The largest face is at the back, not the front.** A live `CKAvatarView` builds a
 * `ContactsUICore.SnowglobeUIView` holding one `ContactsUICore.AvatarUIView` per person, added in
 * table order with `zPosition` 0 on every one — so the first (largest) entry is the first subview and
 * paints first. (`-[CNUIAvatarLayoutItemConfiguration updateLayer:inBounds:atIndex:isRTL:layoutType:]`
 * does set `zPosition` to `-index`, but that path is not the one a group photo runs.) The previous
 * version asserted the opposite; it never showed because the faces do not overlap. This component
 * paints in table order with no `z-index`, which is the native order.
 *
 * **The frosted plate is real, and it is a circle.** `SnowglobeUIView` inserts a `UIVisualEffectView`
 * as subview 0, filling the box, behind every face, with `UIBlurEffect material=20` —
 * `.systemThinMaterial` (`+[UIBlurEffect effectWithStyle:]` reports material 20 for
 * `systemThinMaterial` and its Light/Dark siblings). The view's frame is square, but it is masked to a
 * circle: traced in `snowglobe-light.png` with `scripts/measure/outline.py` the plate is 60.00 x 60.00
 * pt with a ~29.5 pt radius on all four corners, i.e. a full-box disc. It is present only for two or
 * more faces — one contact skips `SnowglobeUIView` entirely and gets a bare `AvatarUIView`.
 * `groupAvatarPlate` is the material measured over five backgrounds in both appearances.
 *
 * **RTL** mirrors x about the centre and nothing else, so the whole stack is expressible as
 * `inset-inline-start`: a face at physical `left` L in a box of S with diameter d lands at `S - L - d`
 * in RTL, which is exactly what `inset-inline-start: L` does. This component therefore inherits the
 * document direction for free; `rtl` only stamps `dir` when a caller forces it.
 *
 * ## Sizes, per behaviour object
 *
 * `-[CKUIBehavior* groupAvatarViewSize]` is 60 x 60 on Phone, Pad and Mac alike — the nav-bar avatar's
 * Ø60 in `conv3-light.png`. The list rows are a different constant:
 * `conversationListContactImageDiameter` is 45 on Phone and Pad (SPEC's Ø45 iOS list rows) and 40 on
 * Mac (SPEC's Ø40 sidebar rows and Ø40 header avatar). See `groupAvatarMetrics`.
 *
 * The iOS **details** header is not this stack. `CKDetailsAvatarPancakeView` — diameter 37, cut-out
 * 41, overlap 13.5, widths 58 and 72 for two and three, all still on the behaviour object as
 * `detailsAvatar*` / `detailsAvatarPancakeView*` — is a row of overlapping heads with knockouts, and
 * `group-details.tsx` already draws it. (`registry.json` says this component covers "the details
 * header"; it does not, and that line wants correcting.)
 *
 * ## The per-sender avatar
 *
 * `+[CKChatItemLayoutUtilities avatarSupplementaryItemForChatItem:layoutEnvironment:]` returns an
 * `NSCollectionLayoutSupplementaryItem` of `.absolute(d) x .absolute(d)` at `zIndex` 1, anchored with
 * `[NSCollectionLayoutAnchor layoutAnchorWithEdges:6 absoluteOffset:(-d, 0)]`. Edges 6 is
 * `NSDirectionalRectEdge.leading | .bottom`, so the avatar hangs off the balloon's leading edge with
 * its **bottom flush to the balloon's bottom** — which is why a cluster carries one avatar, on its
 * last (tailed) bubble. `d` is not hardcoded: running the same call under each idiom returns 32 / 34 /
 * 28, i.e. `-[CKUIBehavior* transcriptContactImageDiameter]`, and
 * `-[CKTranscriptAvatarSupplementaryView initWithFrame:]` builds its `CKAvatarView` at exactly
 * `(0, 0, d, d)` with no inset whatever frame the view is given. `contactPhotoBalloonMargin` is 7 on
 * all three; the leading gutter an incoming row gives up is `d + 7` = **39 / 41 / 35**.
 *
 * The group typing indicator uses a bigger face: `transcriptGroupTypingContactImageDiameter`, 44 / 48
 * / 42. `typing-indicator.tsx` does not draw one yet; the constant is here so it can.
 *
 * ## Motion
 *
 * When a new message joins an incoming cluster the avatar hands off to the new last bubble, riding the
 * transcript's insert animation: `-[CKUIBehavior* scrollInNewMessageAnimationDuration]` is **0.300 s**
 * on all three idioms. `SenderAvatar` plays that as a FLIP on the Web Animations API so the harness can
 * seek it with `progress`. The easing is **unmeasured** — no recording in `references/` contains a
 * group transcript — so it uses `ease-in-out`, UIView's default, and says so in `senderAvatarMotion`.
 *
 * @see references/group-avatar.md
 */

/** One face in the stack. Same shape `avatar.tsx` takes, plus the name used for the composed label. */
export type GroupParticipant = { name?: string; initials?: string; src?: string };

/** `{ x, y, diameter }` in the Snowglobe table's own 88-point box, centre-relative. */
export type StackSlot = { x: number; y: number; diameter: number };

/** The base box every Snowglobe configuration is expressed in (`CNUIAvatarLayoutItemConfiguration.baseSize`). */
export const snowglobeBaseSize = 88;

/** Most faces the table will draw. Participants past this many are not shown. */
export const snowglobeMaxFaces = 7;

/**
 * `SnowglobeAvatarLayoutConfigurations`, read back from
 * `+[CNUIAvatarLayoutManager layoutConfigurationsForType:2 withItemCount:n]`.
 * Index 0 is the first entry the framework returns: the largest face, and the first subview added, so
 * it is at the **back** of the paint order.
 */
export const snowglobeStack: readonly (readonly StackSlot[])[] = [
  [{ x: 0, y: 0, diameter: 88 }],
  [{ x: -10.5, y: -10.5, diameter: 48 }, { x: 17.5, y: 17.5, diameter: 28 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }, { x: 20, y: -20.5, diameter: 20 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }, { x: 20, y: -20.5, diameter: 20 }, { x: -27.5, y: 14, diameter: 14 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }, { x: 20, y: -20.5, diameter: 20 }, { x: -27.5, y: 14, diameter: 14 }, { x: 7.5, y: -32.5, diameter: 10 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 19.5, y: 11.5, diameter: 30 }, { x: 21.5, y: -16.5, diameter: 22 }, { x: -21, y: 19.5, diameter: 20 }, { x: 2, y: 30, diameter: 15 }, { x: -3, y: 15, diameter: 11 }, { x: 9, y: -31.5, diameter: 10 }],
];

/**
 * `SnowglobeGroupTypingIndicatorAvatarLayoutConfigurations`, layout type 3. The same circles as
 * `snowglobeStack` in a different order: four onwards puts the small top-right slot second, and seven
 * is a full reshuffle. Read back the same way, at `withItemCount:` 1 through 7.
 */
export const snowglobeTypingStack: readonly (readonly StackSlot[])[] = [
  [{ x: 0, y: 0, diameter: 88 }],
  [{ x: -10.5, y: -10.5, diameter: 48 }, { x: 17.5, y: 17.5, diameter: 28 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 20, y: -20.5, diameter: 20 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 20, y: -20.5, diameter: 20 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }, { x: -27.5, y: 14, diameter: 14 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 7.5, y: -32.5, diameter: 10 }, { x: 20, y: -20.5, diameter: 20 }, { x: 21.5, y: 7.5, diameter: 32 }, { x: -6, y: 23.5, diameter: 26 }, { x: -27.5, y: 14, diameter: 14 }],
  [{ x: -12.5, y: -12.5, diameter: 42 }, { x: 9, y: -31.5, diameter: 10 }, { x: 21.5, y: -16.5, diameter: 22 }, { x: 19.5, y: 11.5, diameter: 30 }, { x: 2, y: 30, diameter: 15 }, { x: -3, y: 15, diameter: 11 }, { x: -21, y: 19.5, diameter: 20 }],
];

/**
 * Smallest gap between any two faces, in base-88 units, one entry per row of `snowglobeStack`. Every
 * value is positive: the stack has clearance everywhere, so the "ring" between the faces is the
 * background showing through and not a stroke. `NaN` for the single-face row, which has no pair.
 * Multiply by `size / 88` for a real diameter (Ø60 → 1.0895, 1.6678, 1.3910, 1.3910, 1.3910, 1.4123).
 */
export const snowglobeClearance: readonly number[] = [NaN, 1.598, 2.4462, 2.0401, 2.0401, 2.0401, 2.0713];

/**
 * The table row for `count` faces. One through seven map to their own row; anything larger gets the
 * seven-face row, as the framework does; zero and negatives clamp up to the single-face row, which is
 * what `GroupAvatar` draws while a conversation is still loading.
 */
export function snowglobeSlots(count: number, layout: "photo" | "typing" = "photo"): readonly StackSlot[] {
  const table = layout === "typing" ? snowglobeTypingStack : snowglobeStack;
  return table[Math.min(Math.max(count, 1), snowglobeMaxFaces) - 1];
}

/**
 * One slot's box inside a circle of `size`, in CSS px, as `-itemFrameInContainingBounds:isRTL:`
 * computes it. `left` is the physical left edge; pass `rtl` to mirror it the way `isRTL:YES` does.
 * `GroupAvatar` instead spends the LTR value as `inset-inline-start`, which mirrors identically and
 * inherits the document direction — see `snowglobeFrame(slot, size, true).left === size - ltr - d`.
 */
export function snowglobeFrame(slot: StackSlot, size: number, rtl = false): { left: number; top: number; size: number } {
  const scale = size / snowglobeBaseSize;
  const face = slot.diameter * scale;
  const x = (rtl ? -slot.x : slot.x) * scale;
  return { left: size / 2 + x - face / 2, top: size / 2 + slot.y * scale - face / 2, size: face };
}

/**
 * Group-photo diameters, per behaviour object. `groupAvatar` is `groupAvatarViewSize` (the nav bar and
 * the macOS header slot); `conversationList` is `conversationListContactImageDiameter` (the iOS list
 * rows and the macOS sidebar rows). Read off `CKUIBehaviorPhone` / `Pad` / `Mac` directly.
 */
export const groupAvatarMetrics = {
  phone: { groupAvatar: 60, conversationList: 45 },
  pad: { groupAvatar: 60, conversationList: 45 },
  mac: { groupAvatar: 60, conversationList: 40 },
} as const;

/** `-[CKUIBehavior groupAvatarViewSize]`, 60 x 60 on every idiom. */
export const groupAvatarSize = groupAvatarMetrics.phone.groupAvatar;

/**
 * The frosted disc behind the faces, `UIBlurEffect(.systemThinMaterial)`, measured off two live
 * simulator renders: `references/group-avatar/snowglobe-{light,dark}.png` (the plate under a real
 * stack, 762 clean samples per cell) and `material-swatches-{light,dark}.png` (a bare
 * `UIVisualEffectView` over the same flats). The two agree to under 1/255 everywhere.
 */
export const groupAvatarPlate: readonly { background: string; light: string; dark: string }[] = [
  { background: "#ffffff", light: "#f4f4f5", dark: "#7d7d7d" },
  { background: "#000000", light: "#8d8e8e", dark: "#1f1f1f" },
  { background: "#3478f6", light: "#a2c7ff", dark: "#264a8f" },
  { background: "#e9e9eb", light: "#ededee", dark: "#737373" },
  { background: "#1c1c1e", light: "#9d9d9e", dark: "#2a2a2a" },
];

/**
 * A translucent fill that reproduces the plate over an arbitrary background, fitted to the two
 * achromatic ends of `groupAvatarPlate` (#ffffff and #000000, which it hits exactly). Residuals
 * against the other measured rows: 1.2/255 on #e9e9eb and 4.0/255 on #1c1c1e in light, 1.7 and 0.9 in
 * dark. Over #3478f6 it misses by up to 14/255 (light) and 22/255 (dark) in the blue channel, because
 * the material also lifts saturation and a flat overlay cannot; a surface that knows it is drawing on
 * the selection blue should set `--im-ga-plate` to that row's measured colour instead.
 */
export const groupAvatarPlateFit = { light: "rgba(237, 237, 237, 0.596)", dark: "rgba(49, 49, 49, 0.632)" } as const;

export type GroupAvatarProps = Omit<ComponentProps<"span">, "children"> & {
  /** Circle diameter. Defaults to the framework's 60; see `groupAvatarMetrics` for the list sizes. */
  size?: number;
  /** The people in the conversation, in the order the stack should draw them. */
  participants: readonly GroupParticipant[];
  /** Accessible name; falls back to the participants' names. */
  name?: string;
  /**
   * Mirror the stack the way `isRTL:YES` does. Left undefined the stack follows the document
   * direction on its own (the faces are placed with `inset-inline-start`); passing a boolean stamps
   * `dir` on the host to force it.
   */
  rtl?: boolean;
  /** `"typing"` uses the group typing indicator's ordering of the same circles. */
  layout?: "photo" | "typing";
  /**
   * The frosted disc behind the faces. Defaults to `--im-ga-plate`, which the component seeds with
   * `groupAvatarPlateFit`; pass a colour to pin it (e.g. a measured `groupAvatarPlate` row over a
   * selected sidebar row) or `false` to leave it out. Never drawn for fewer than two faces, because
   * one contact skips `SnowglobeUIView` natively.
   */
  plate?: string | false;
};

/**
 * `avatar.tsx` declares `--av-top` / `--av-bottom` inline and then tries to override them with a
 * `dark:` class, which an inline declaration always beats — so an `Avatar` rendered through this file
 * would keep the light gradient in dark mode. Its `style` prop is spread last, so handing it the pair
 * as `var()` references with the light values as fallbacks restores the switch without touching that
 * file, and keeps working if it is fixed there.
 *
 * Both pairs re-measured off `references/group-avatar/snowglobe-{light,dark}.png`: fitting a straight
 * line down the Ø60 single-face circle (116 rows, glyph pixels dropped) returns #a9c2e1 -> #747fb9 in
 * light and #575368 -> #302649 in dark, max residual 0.89 and 0.78 of 255 — the same four values
 * `avatar.tsx` records, from a capture it has never been diffed against.
 */
const faceGradient = { "--av-top": "var(--im-ga-face-top, #a9c2e1)", "--av-bottom": "var(--im-ga-face-bottom, #747fb9)" } as CSSProperties;
const faceGradientDark = "dark:[--im-ga-face-top:#575368] dark:[--im-ga-face-bottom:#302649]";

/** "Alex Morgan, Jamie Chen and Sam Rivera", or "3 people" when nobody is named. */
function participantsLabel(participants: readonly GroupParticipant[]): string {
  const named = participants.map(person => person.name ?? person.initials).filter((value): value is string => Boolean(value));
  if (!named.length) return participants.length ? (participants.length === 1 ? "1 person" : `${participants.length} people`) : "Group";
  if (named.length === 1) return named[0];
  return `${named.slice(0, -1).join(", ")} and ${named[named.length - 1]}`;
}

/**
 * A group conversation's photo: the participants' faces laid out by the Snowglobe table over the
 * material plate. Draws at most seven faces, as the framework does, largest first and so furthest
 * back.
 */
export function GroupAvatar({ size = groupAvatarSize, participants, name, rtl, layout = "photo", plate, className, style, ...props }: GroupAvatarProps) {
  const faces = participants.slice(0, snowglobeMaxFaces);
  const slots = snowglobeSlots(faces.length || 1, layout);
  const label = name ?? participantsLabel(participants);
  // The light fill rides in as the `var()` fallback rather than a declaration, so the dark class and
  // any `--im-ga-plate` a surface sets on an ancestor both win without a specificity fight.
  const plateFill = typeof plate === "string" ? plate : `var(--im-ga-plate, ${groupAvatarPlateFit.light})`;
  return (
    <span
      data-slot="group-avatar"
      data-size={size}
      data-count={participants.length}
      data-faces={faces.length || 1}
      data-truncated={participants.length > snowglobeMaxFaces ? "" : undefined}
      role="img"
      aria-label={label}
      dir={rtl === undefined ? undefined : rtl ? "rtl" : "ltr"}
      className={cn("relative inline-block shrink-0 select-none align-middle dark:[--im-ga-plate:rgba(49,49,49,0.632)]", faceGradientDark, className)}
      style={{ width: size, height: size, ...style }}
      {...props}
    >
      {/* `SnowglobeUIView`'s UIVisualEffectView: the whole box, masked to a disc, behind every face.
          Absent for one contact, which never builds a SnowglobeUIView at all. */}
      {slots.length > 1 && plate !== false && (
        <span data-slot="group-avatar-plate" aria-hidden="true" className="absolute inset-0 rounded-full" style={{ background: plateFill }} />
      )}
      {/* An empty group still draws one circle, so the surface never collapses while a conversation loads. */}
      {(faces.length ? faces : [{} as GroupParticipant]).map((person, index) => {
        const frame = snowglobeFrame(slots[index], size);
        // Table order, no z-index: the framework adds the largest face first, so it paints first.
        const layer: CSSProperties = { position: "absolute", insetInlineStart: frame.left, top: frame.top, ...faceGradient };
        const avatar: AvatarProps = { size: frame.size, initials: person.initials, src: person.src, name: person.name };
        return <Avatar key={index} {...avatar} aria-hidden="true" role={undefined} style={layer} />;
      })}
    </span>
  );
}

/** Which behaviour object a surface reads its transcript diameters from. */
export type SenderAvatarPlatform = "phone" | "pad" | "mac";

/**
 * The avatar beside an incoming bubble in a group, per behaviour object. `gutter` is
 * `transcriptContactImageDiameter + contactPhotoBalloonMargin`: the diameter, the margin and the
 * `(-d, 0)` supplementary anchor are each read directly from the frameworks, and the sum is the
 * leading inset the transcript cells spend on the pair.
 */
export const senderAvatarMetricsFor: Record<SenderAvatarPlatform, { diameter: number; balloonMargin: number; gutter: number; typingDiameter: number }> = {
  /** `CKUIBehaviorPhone`: 32 / 7 / 44. */
  phone: { diameter: 32, balloonMargin: 7, gutter: 39, typingDiameter: 44 },
  /** `CKUIBehaviorPad`: 34 / 7 / 48. */
  pad: { diameter: 34, balloonMargin: 7, gutter: 41, typingDiameter: 48 },
  /** `CKUIBehaviorMac`: 28 / 7 / 42. The macOS pane's gutter is 35, not the phone's 39. */
  mac: { diameter: 28, balloonMargin: 7, gutter: 35, typingDiameter: 42 },
};

/**
 * The Phone numbers, kept as a bare export because that is what this file used to ship. Prefer
 * `senderAvatarMetricsFor` — a macOS transcript is 28/35, not 32/39.
 */
export const senderAvatarMetrics = senderAvatarMetricsFor.phone;

/** Maps `platform.tsx`'s two-value platform onto a behaviour object. */
export function senderAvatarMetricsForPlatform(platform: "ios" | "macos") {
  return platform === "macos" ? senderAvatarMetricsFor.mac : senderAvatarMetricsFor.phone;
}

/**
 * The hand-off: when a new message joins an incoming cluster the avatar moves to the new last bubble
 * on the transcript's insert animation, `-[CKUIBehavior* scrollInNewMessageAnimationDuration]` =
 * 0.300 s (identical on Phone, Pad and Mac).
 *
 * `easing` is **unmeasured** — nothing in `references/` records a group transcript, so there is no
 * curve to fit. `ease-in-out` is UIView's default for a plain `animateWithDuration:`; treat it as a
 * placeholder, not a reading.
 */
export const senderAvatarMotion = { handoff: 300, easing: "ease-in-out" } as const;

/**
 * Where an element sits inside its scroll container, so a hand-off measures the same before and after
 * the list scrolls. Falls back to page coordinates when nothing above it scrolls.
 */
function anchorPoint(el: HTMLElement): { left: number; top: number } {
  const rect = el.getBoundingClientRect();
  for (let node = el.parentElement; node; node = node.parentElement) {
    const overflow = getComputedStyle(node).overflowY;
    if (overflow === "auto" || overflow === "scroll") {
      const box = node.getBoundingClientRect();
      return { left: rect.left - box.left + node.scrollLeft, top: rect.top - box.top + node.scrollTop };
    }
  }
  return { left: rect.left + window.scrollX, top: rect.top + window.scrollY };
}

/** The last settled position of every live hand-off key, ref-counted so a move survives the remount. */
const handoffPositions = new Map<string, { left: number; top: number; users: number }>();

function prefersReducedMotion(): boolean {
  return typeof window !== "undefined" && typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

export type SenderAvatarProps = Omit<ComponentProps<"span">, "children"> & {
  /** The sender's name, used as the accessible label. */
  name?: string;
  initials?: string;
  src?: string;
  /** Which behaviour object's diameters to use. Defaults to the phone's. */
  platform?: "ios" | "macos";
  /** Diameter. Defaults to the platform's `transcriptContactImageDiameter`. */
  size?: number;
  /** `"typing"` swaps in `transcriptGroupTypingContactImageDiameter`. */
  variant?: "message" | "typing";
  /**
   * Identifies the cluster this avatar belongs to. When an avatar with the same key reappears at a
   * new position — the cluster grew a bubble and the avatar moved to it — it slides from where it
   * was. Leave it off to place the avatar without any motion.
   */
  handoffKey?: string;
  /** Play the hand-off from this offset instead of a measured one. For the lab and the harness. */
  handoffFrom?: { dx?: number; dy: number };
  /** 0..1 seeks the hand-off instead of playing it. */
  progress?: number;
  /**
   * Position the avatar in the row's leading gutter, bottom-aligned with the balloon, the way
   * `avatarSupplementaryItemForChatItem:` anchors it. Needs a positioned row that reserves `gutter`
   * of leading padding. Pass `false` to lay it out yourself.
   */
  anchored?: boolean;
};

/**
 * The photo beside an incoming bubble in a group: one per cluster, on the last (tailed) bubble,
 * bottom flush with the balloon and hanging its own diameter off the balloon's leading edge.
 *
 * The row it sits in has to be `position: relative` and give up `gutter` of `padding-inline-start`;
 * this element then takes the leading edge and the bottom of that box. See the file docstring for the
 * supplementary-item anchor those two rules come from.
 */
export function SenderAvatar({
  name, initials, src, platform = "ios", variant = "message", size, handoffKey, handoffFrom, progress, anchored = true, className, style, ...props
}: SenderAvatarProps) {
  const metrics = senderAvatarMetricsForPlatform(platform);
  const diameter = size ?? (variant === "typing" ? metrics.typingDiameter : metrics.diameter);
  const host = useRef<HTMLSpanElement>(null);
  const animation = useRef<Animation | null>(null);
  const forcedDx = handoffFrom ? handoffFrom.dx ?? 0 : undefined;
  const forcedDy = handoffFrom?.dy;

  useLayoutEffect(() => {
    const el = host.current;
    if (!el) return;
    // Measure where this avatar rests, with any in-flight slide removed first.
    animation.current?.cancel();
    animation.current = null;
    const at = anchorPoint(el);
    const previous = handoffKey ? handoffPositions.get(handoffKey) : undefined;
    const delta = forcedDy !== undefined
      ? { dx: forcedDx ?? 0, dy: forcedDy }
      : previous
        ? { dx: previous.left - at.left, dy: previous.top - at.top }
        : null;
    if (handoffKey) handoffPositions.set(handoffKey, { left: at.left, top: at.top, users: (previous?.users ?? 0) + 1 });
    if (delta && (delta.dx !== 0 || delta.dy !== 0) && !prefersReducedMotion() && typeof el.animate === "function") {
      const run = el.animate(
        [{ transform: `translate(${delta.dx}px, ${delta.dy}px)` }, { transform: "translate(0px, 0px)" }],
        { duration: senderAvatarMotion.handoff, easing: senderAvatarMotion.easing, fill: "both" },
      );
      animation.current = run;
      // Drop the forwards fill once it lands, so a settled avatar carries no transform (and so no
      // stacking context) into the next hand-off. A seeked animation is paused and never resolves.
      run.finished.then(() => run.cancel()).catch(() => undefined);
    }
    return () => {
      if (!handoffKey) return;
      const entry = handoffPositions.get(handoffKey);
      if (!entry) return;
      entry.users -= 1;
      // React unmounts before it mounts the moved node, so let the new instance claim the key first.
      queueMicrotask(() => {
        const live = handoffPositions.get(handoffKey);
        if (live && live.users <= 0) handoffPositions.delete(handoffKey);
      });
    };
  }, [handoffKey, forcedDx, forcedDy]);

  // Seeks in a second layout effect, after the one above has built the animation and before paint, so
  // a scrubbed hand-off never shows a played frame and re-scrubbing never restarts it.
  useLayoutEffect(() => {
    const run = animation.current;
    if (!run || progress === undefined) return;
    run.pause();
    run.currentTime = Math.min(Math.max(progress, 0), 1) * senderAvatarMotion.handoff;
  }, [progress, handoffKey, forcedDx, forcedDy]);

  return (
    <span
      ref={host}
      data-slot="sender-avatar"
      className={cn("block", anchored && "absolute bottom-0 start-0", faceGradientDark, className)}
      style={{ width: diameter, height: diameter, ...style }}
      {...props}
    >
      <Avatar size={diameter} initials={initials} src={src} name={name} style={faceGradient} />
    </span>
  );
}

"use client";

import { useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore, type ComponentProps, type CSSProperties } from "react";
import { cn } from "@/lib/utils";
import { usePlatform, type Platform } from "@/components/imessage/platform";
import { fontStack } from "@/components/imessage/tokens";

/**
 * Recording a voice message: the composer's field becomes a row carrying a live waveform, a running
 * timer and a stop button; stopping swaps the stop for a play control, a duration pill with a `+`,
 * and a send pill.
 *
 * ## Where these numbers come from
 *
 * **No capture in `references/` holds this screen on either platform**, so every geometric number
 * below was read out of ChatKit — the framework both Messages apps run on — by a Mac Catalyst probe
 * whose full source is committed in `references/audio-recorder.md` and whose readings are tabulated
 * in `references/SPEC.md` ("Audio recorder"). The probe dlopens
 * `/System/iOSSupport/System/Library/PrivateFrameworks/ChatKit.framework/ChatKit`, swizzles
 * `-[UIDevice userInterfaceIdiom]` so `+[CKUIBehavior sharedBehaviors]` vends the Phone or the Mac
 * behaviour, stubs `+[IMService iMessageService]` (which the view's initialiser force-unwraps), then
 * **builds the real view**: `-[CKAudioMessageRecordingView initWithFrame:service:]`, feeds it known
 * intensities through `-addToWaveformWithIntensity:`, walks `-setState:` 0 to 3 and reads every
 * subview's frame, colour, radius, font and symbol image back. The frames below are the frames
 * Messages lays out.
 *
 * ChatKit's `-setState:` has four states; three of them are this component's:
 * 1 `recording`, 2 `stopped`, 3 `playing` (0 is the empty pose before recording starts).
 *
 * ### The row
 *
 * `-[CKAudioMessageRecordingView sizeThatFits:]` returns **52** tall on Phone and **49** on Mac.
 * Every child is centred in it, and — this reproduces all twelve measured child frames exactly —
 * **each child's leading or trailing inset equals its own vertical inset**, `(rowHeight - size) / 2`:
 * the 34/31 circles sit 9 in, the 30 x 22 send pill 15 in on Phone and 13.5 on Mac. Every gap
 * between neighbours is `audioRecordingViewDurationSpacing` **12**, except the waveform's leading
 * inset while recording, which is `audioRecordingViewButtonSpacing` **16** (there is no play button
 * to sit beside). Those two rules close on 294 and on 530 in all three states:
 *
 * | | leading | waveform | trailing chain |
 * |---|---|---|---|
 * | iOS recording | 16 | 181.5 | 12 + timer 29.5 + 12 + stop 34 + 9 |
 * | iOS stopped | 9 + play 34 + 12 | 109 | 12 + append 61 + 12 + send 30 + 15 |
 * | iOS playing | 9 + play 34 + 12 | 140.5 | 12 + timer 29.5 + 12 + send 30 + 15 |
 * | macOS recording | 16 | 415 | 12 + timer 35 + 12 + stop 31 + 9 |
 * | macOS stopped | 9 + play 31 + 12 | 348 | 12 + append 62.5 + 12 + send 30 + 13.5 |
 * | macOS playing | 9 + play 31 + 12 | 375.5 | 12 + timer 35 + 12 + send 30 + 13.5 |
 *
 * The waveform view is **0.75 of the row** — 39 in the 52 (which is `audioWaveformViewHeight`) and
 * 36.75 in the 49 — and is vertically centred, top 6.5 / 6.125.
 *
 * ### The waveform
 *
 * Bars are `waveformPowerLevelWidth` **2** wide with a radius of 1, `audioWaveformGapWidth` **2**
 * apart, so the pitch is 4; they are vertically centred and the strip is anchored to the box's
 * trailing edge, which leaves `width - 2 - (count - 1) * 4` empty at the leading edge (3 of hole in
 * a 109 box: measured, not a bug).
 *
 * **`height = level² × waveformViewHeight`, floored at `minimumWaveformHeight` 4.** Feeding the view
 * a ramp and reading the segments back: 0.3333 → 4.3333, 0.4 → 6.24, 0.4444 → 7.7037, 0.5 → 9.75,
 * 0.6 → 14.04, 0.6667 → 17.3334, 0.75 → 21.9375, 0.8 → 24.96, 0.9 → 31.59, 1 → 39 — every one of
 * them exactly `level² × 39`, and everything below 0.3203 clamped to 4. It scales to the **view**
 * height 39, not to `audioWaveformHeight` 35; a full-scale bar fills the box edge to edge.
 *
 * While recording, the newest bars ramp in: a bar `k` segments back from the leading edge is scaled
 * by **`min(1, sqrt(k / 4))`**, measured to five decimals at k = 0, 1, 2, 3, 4 (0, 0.5, 0.70711,
 * 0.86603, 1), with the k = 0 bar additionally at opacity 0. Bars ahead of the take are drawn at the
 * minimum height and half opacity, which is the track the wave is written onto.
 *
 * Once stopped, the take is resampled up to the bars that fit by **nearest neighbour**, bar `j`
 * taking level `floor(j × n / count)` — 5 levels in a 27-bar box measured as runs of 6, 5, 6, 5, 5.
 * The played part is **`max(1, floor(fraction × count))`** bars, checked at nine positions.
 *
 * ### Colours, resolved with `-resolvedColorWithTraitCollection:` in both styles
 *
 * - recording bars and timer ink `#FF383C` light / `#FF4245` dark, at full opacity, over a track of
 *   the same colour at 0.5;
 * - stopped and playing bars `rgba(0, 0, 0, 0.498)` / `rgba(255, 255, 255, 0.549)`, the part not yet
 *   played at 0.5 of that;
 * - play button fill `rgba(118, 118, 128, 0.12)` light and **0.24 dark** (the framework's own
 *   `UIBackgroundConfiguration`, read per trait), glyph `rgba(0, 0, 0, 0.847)` / `rgba(255, 255, 255, 0.847)`;
 * - stop button fill `rgba(255, 56, 60, 0.19)` in **both** styles, glyph the red above;
 * - the stopped duration pill `rgba(116, 116, 128, 0.08)` in both styles with 84.7% label ink; while
 *   recording and while playing the same pill has **no fill at all**;
 * - send `#0088ff` with a white arrow;
 * - the cancel button's `xmark` at 84.7% label ink over glass.
 *
 * ### Glyphs
 *
 * Each is the framework's own symbol image, rasterised at 8x and measured for its ink box and its
 * coverage, and the outlines below are fitted to both:
 *
 * | control | symbol | ink | coverage |
 * |---|---|---|---|
 * | stop | `stop.fill` 17 regular | 14 x 14 | 180.3853 |
 * | play | `play.fill` 17 regular | 12.5 x 14 | 101.8686 |
 * | pause | `pause.fill` 17 regular | 10.5 x 14 | 110.7490 |
 * | append | `plus` 17 regular | 14 x 14 | 37.4529 |
 * | send | `arrow.up` 17 **bold** | 13.5 x 16 | 68.9608 |
 * | cancel | `xmark` **16 medium** | 13 x 13 | 55.3471 |
 *
 * The send arrow's stem measures **2.4098** of stroke, which is the same weight `conv3-light.png`
 * gives the composer's own send pill (2.41 measured there) — but it is not the same drawing: the
 * composer's is a 38 x 28 pill and this is a 30 x 22 one, so the arrow is smaller here.
 *
 * The `xmark` is the one place the two fits disagree: its rows integrate to 4.9588 of ink, i.e.
 * 1.7532 of stroke at 45 degrees, while its total coverage wants 1.68. The 1.68 is drawn, because
 * total coverage is the more robust measure and is what this repo fits elsewhere.
 *
 * ## What is *not* from the framework
 *
 * - **Where the surface sits in the composer.** ChatKit's own
 *   `entryViewLeftInsetForRecordedAudioCancelButton` is 8.5 on both idioms, which is neither the
 *   iOS composer's measured 28 nor the macOS `+`'s measured 9, so its frame of reference could not
 *   be established and it is not used. Instead the cancel circle is centred on the **measured**
 *   centre of the `+` it replaces (iOS x 48, `SPEC.md`; macOS pane x 24) and the row takes the
 *   **measured** field box (iOS x 80–374, macOS pane x 49–579). Both rest their bottom edge on the
 *   composer's measured baseline (iOS y 846, macOS pane y 629), because every other element of both
 *   composers is bottom-aligned there. The row is taller than the field it replaces, so it grows
 *   upward. Derived from measurements, but not itself measured.
 * - **The row's corner radius.** UNMEASURED: `-[CKAudioMessageRecordingView cornerRadius]` is 0
 *   until the entry view sets it, and nothing in the framework stores what it sets. Drawn as a
 *   capsule (half the row's height), because both composer fields are capsules at one line.
 * - **The row's fill, rim and shadow.** Copied from the two composer files, which measured them, so
 *   that this stays a registry item with no dependency on either.
 * - **The entrance and the exit.** UNMEASURED. 260 / 200 ms on the iOS effects screen's measured
 *   `cubic-bezier(0.32, 0.72, 0, 1)`; a reuse, not a measurement of this surface.
 * - **The spring's frequency.** `stateChangeAnimationDuration` 0.6 and `stateChangeSpringDamping`
 *   0.86 are the view's own Swift ivars, read at their offsets; the frequency UIKit derives from
 *   that pair is not stored anywhere, so `springEasing` samples the spring whose envelope has
 *   decayed to 0.1% at 0.6 s. A fit.
 * - **The slide between segments.** ChatKit lays every bar on a 4 pt grid, so its model steps 4 pt
 *   twelve times a second; whether its display link interpolates between those frames cannot be read
 *   from a view that never runs. This slides the strip by `4 × frac(t / segment)`, which is the
 *   smallest continuous interpolation of the measured layout and is exactly ChatKit's frame at every
 *   whole segment.
 *
 * Every animation is seekable rather than merely playable: the slide is one Web Animations timeline
 * whose offset is linear in time, the state change takes `transition={{ from, progress }}` the way
 * `MacComposer` takes `grow`, and `progress` seeks the entrance and the exit to a frame rather than
 * jumping them to the end. `prefers-reduced-motion` builds no timeline at all and poses the row.
 */
export const audioRecorderMetrics = {
  /** ChatKit's, read per idiom. Points equal CSS px. */
  ios: {
    /** `-[CKAudioMessageRecordingView sizeThatFits:]`, Phone idiom, with a take in it. */
    rowHeight: 52,
    /** UNMEASURED: the entry view sets the row's radius and does not store it. A capsule. */
    rowRadius: 26,
    /** The play and stop circles. */
    button: 34,
    /** `CKGlassSendButton`. */
    send: { width: 30, height: 22, radius: 11 },
    /** `ChatKit.AudioMessageRecordingAppendButton` while recording and while playing. */
    timer: { width: 29.5, height: 16, radius: 8, fontSize: 13 },
    /**
     * The same button once stopped, where the whole pill is the control that appends to the take.
     * `glyph` is the framework's own image box for the `plus`; `ink` is what the symbol's 14 x 14 of
     * ink becomes once scaled into it.
     */
    append: { width: 61, height: 26, radius: 13, labelLeft: 21.5, glyph: { left: 7, top: 8, width: 11.5, height: 10.5, inkWidth: 8.944, inkHeight: 9.188 } },
    /** `CKGlassCancelAudioRecordingButton` `-sizeThatFits:`, radius 20.5, i.e. a circle. */
    cancel: 41,
    /**
     * Not ChatKit: the measured iOS composer (`SPEC.md`, `ios-composer.tsx`). The field's box, the
     * `+`'s centre and the composer's bottom margin on a 402-wide screen.
     */
    composer: { fieldLeft: 80, fieldWidth: 294, leadingCentre: 48, bottom: 28 },
  },
  macos: {
    rowHeight: 49,
    /** UNMEASURED, as above. */
